local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Người giữ gìn, cho tôi hỏi khi nào tôi có thể tham quan nghĩa trang của học viện không? Những linh hồn vĩ đại đang chôn cất ở đó nhất định sẽ mang lại cho tôi cảm hứng khác thường! Hãy yên tâm, tôi đảm bảo sẽ không đào xác ra để ngắm gần nữa..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Câu chuyện bên lề: Về Người mẫu"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Chờ đã! Tôi vừa nghĩ ra một cách thể hiện mới, chắc chắn sẽ làm kinh ngạc cả giới hội họa!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Tôi chính là ánh sáng và bóng tối, tôi chính là màu sắc, tôi... chính là hội họa!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Sụt…… Một màu sắc tôi chưa từng thấy, tỏa sáng trong thế giới linh hồn của bạn…… Đó rốt cuộc là gì……"
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_100338_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Màu đen tuyệt vời biết bao! Tôi đã từng thu thập nhiều chất phân rã để vẽ tranh, cuối cùng những tác phẩm đó đều biến mất. Màu sắc đến từ vũ trụ nguyên thủy, tất cả các bức tranh đều bị nuốt chửng, không ai nhớ đến…… Không phải càng tuyệt hơn sao?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Để tôi lại gần một chút... cho tôi nhìn thêm một chút! Những ánh sáng, những sắc màu, những tư thái này... so với chúng, những thứ tôi đã vẽ trước đây chỉ là một đống giấy vụn..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_100340_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Dulserain luôn kể cho tôi nghe món ăn của anh ta có cảm giác nghệ thuật thế nào, bảo tôi xem, việc ăn uống và nghệ thuật hoàn toàn không liên quan! Không những phải tốn thời gian quý báu để xử lý những xác chết phức tạp, cuối cùng tạo ra được món ăn hoàn mỹ về cả hình và vị, còn phải gặm nhấm, nuốt chửng! Điều này thật sự là một tội ác đối với nghệ thuật!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh…"},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Người mẫu tồi tệ..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Không được không được, lại là một tác phẩm tồi tệ... phải đi đâu tìm cảm hứng đây. Nghĩa trang? Hoặc trường xử án..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Mặc dù tôi thấy rằng hình thức nghệ thuật điêu khắc này có phần cứng nhắc và cũ kỹ, nhưng nghệ sĩ điêu khắc tên Sanga, chiếc dao chạm khắc của cô có thể mang lại sức biểu đạt vượt xa những gì hình thức nghệ thuật này có thể mang"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Đàm thoại: Về Sanga"
  },
  Voice_100345_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"sơn\" sẽ mở khóa"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Bạn có thấy bức tranh này không, người giữ gìn? Đây là chân dung tôi vẽ cho bạn. Hãy nhìn xem dáng vẻ bạn đang gặm xác chết thật quyến rũ! Tôi biết, không phải ai cũng có thể hiểu tác phẩm của tôi, nhưng cái vẻ đẹp điên cuồng mà bức tranh này truyền tải, bạn chắc chắn đã tiếp xúc rồi đúng không?! Đối với tôi, điều đó đã đủ rồi, hoàn toàn đủ rồi......"
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_100346_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Ngài vừa nói muốn mua bức tranh này... thật sao?! Cảm ơn, Người giữ gìn! Rất ít con người có thể thưởng thức những thứ này..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_100347_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Người giữ gìn, gần đây bạn còn có thời gian đến làm người mẫu cho tôi không? So với hình ảnh tôi thấy trên bạn lần trước, những người mẫu khác hoàn toàn đang lãng phí thời gian của tôi..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Chứng kiến sự tái sinh trong tác phẩm này!"
  },
  Voice_100349_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_100350_AwakerVoiceContent = {
    Text = "Hãy nhìn những đường nét sống động này!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Tôi có linh cảm, những thứ được tạo ra từ cây bút này sẽ khiến mọi người phải kinh ngạc!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Một màu sắc mới lạ…… Tôi sẽ bôi nó ở vị trí thích hợp nhất!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Nơi đây thật sự là một nơi tuyệt vời để bùng nổ cảm hứng! Tôi đã có một vài ý tưởng mới, người giữ gìn, gần đây ông có rảnh để tham quan phòng tranh của tôi không? Đến đi, đến đi!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_100353_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Đúng rồi, đúng rồi! Chiến thắng được tưới mát bởi máu! Một bố cục tuyệt vời biết bao!"
