  Voice_100355_AwakerVoiceContent = {Text = "Ugh…"},
  Voice_100355_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Xin mời ngồi, người giữ gìn. Làm người mẫu cho tôi là một công việc khó khăn. Xin hãy yên tâm, tôi chắc chắn sẽ tạo ra một tác phẩm tuyệt vời cho bạn."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_100356_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Một nghệ sĩ, trong mắt chỉ nên có tác phẩm chính mình, không để ý đến ánh nhìn của người khác, nhưng tôi không làm được... từ ngày đầu tiên nắm lấy cọ vẽ, tôi đã hy vọng có thể mang lại vẻ đẹp thật sự cho mọi người."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_100357_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Nơi này khiến tôi nhớ lại những ngày tháng ở học viện hội họa trước đây. Mặc dù giáo sư và các bạn học phần lớn đều là những kẻ hoàn toàn không hiểu về nghệ thuật, nhưng luôn có một hai người có hiểu biết, có thể nhìn thấy vẻ đẹp mà tôi thấy từ các tác phẩm của tôi."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Buổi biểu diễn hoang dã này sẽ va chạm tạo ra nghệ thuật điên cuồng gì đây?!"
