  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Bảng màu của tôi!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "Đau đớn cũng là nghệ thuật..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Tôi đã thấy nó…… Mắt mù ẩn sâu dưới vực thẳm, hình ảnh cuối cùng của vũ trụ…… Xin hãy chờ một chút, người giữ gìn, chúng ta sắp hoàn thành nó rồi!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_100362_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Cây cọ của tôi, được làm từ xương chân của tôi. Bảng màu, những sắc màu này tôi đã thu thập ở nghĩa trang của hai mươi thành phố... và cả tấm vải da quý giá của tôi nữa! Người giữ gìn, làm ơn hãy mang những thứ này, hãy vẽ cho tôi một bức chân dung nhé! Không không không, bạn không cần có kỹ năng vẽ gì... Tôi tin rằng, khi sự cộng hưởng tinh thần này được hiển lộ trên bức vải, chắc chắn đó sẽ là một tác phẩm đẹp đẽ mà tôi chưa từng tưởng tượng đến...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_100363_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Tôi chính là ánh sáng và bóng tối, tôi chính là màu sắc, tôi... chính là hội họa!"
  },
  Voice_100364_AwakerVoiceTitle = {
