  Voice_100365_AwakerVoiceContent = {
    Text = "Hãy thử màu này!"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_100366_AwakerVoiceContent = {
    Text = "Bản chất của nghệ thuật chính là sự điên cuồng...!"
  },
  Voice_100366_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_100367_AwakerVoiceContent = {
    Text = "Ý ngài là, lần tới có thể thử chụp cận cảnh phần này trong tác phẩm không? Ơ... tôi thật sự chưa từng nghĩ đến! Thật là một ý tưởng xuất chúng!"
