  },
  Voice_100368_AwakerVoiceContent = {
    Text = "Cẩn thận!"
  },
  Voice_100368_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "Bản chất của nghệ thuật chính là sự điên cuồng...!"
  },
  Voice_100369_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_100370_AwakerVoiceContent = {
    Text = "Bảng màu của tôi!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Ôi! Khung hàm mượt mà, đôi mắt sáng, thân hình hoàn hảo, và, và cả thế giới linh hồn rộng lớn như bầu trời sao…… Tôi là họa sĩ Pikman, có thể mời bạn trở thành người mẫu của tôi không?"
  },
  Voice_100371_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_100372_AwakerVoiceContent = {
    Text = "Triết lý nghệ thuật mà tôi tôn thờ là điên rồ, bất an, âm nhạc của Hameln thì hoàn toàn khác, nghiêm túc như những bia mộ tẻ nhạt. Nhưng không biết tại sao, tôi luôn thấy trong những nốt nhạc gọn gàng đó, sự hỗn loạn mãnh liệt nhất ở sâu trong vũ trụ..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Câu chuyện bên lề: Về Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Hamlin\""
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Hãy nhìn, người giữ gìn! Cảnh tượng điên cuồng vĩnh cửu trên bức vải, thật cuốn hút, thật tuyệt vọng! Những gì nở rộ trong cơn điên cuồng và đau đớn tuyệt đối mới chính là nghệ thuật......"
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_100373_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! Xin, xin lỗi, người giữ gìn…… Tôi đã nhìn thấy một cảnh tượng chưa từng có trên người bạn…… Kinh khủng hơn cả vực thẳm, quyến rũ hơn cả vực thẳm……"
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_100374_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Thật không hiểu, nếu nhân loại có cơ hội, sao không trở thành một thây ma? Cái vẻ đẹp điên cuồng đầy máu me này, chẳng phải thú vị hơn nhiều so với việc làm một con người không có đam mê trong căn biệt thự sao?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Trừng phạt tội ác!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Trừng phạt tội ác!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Tôi thừa nhận khả năng ăn cắp của cô ấy có phần xuất sắc, nhưng tiểu thư không cần phải dùng những thủ đoạn đê tiện như vậy, những thứ tôi muốn, mọi người có thể\"tự nguyện\" cho tôi mà không phải dùng đến vấn đề này sao?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_117791_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Ha ha ha, của tôi, của tôi, tất cả kẹo của Mythag đều là của tôi! Còn chờ gì nữa, cùng theo mụ phù thủy này đi, ngay bây giờ chuẩn bị đi chinh phục tiệm kẹo toàn bộ Londinium nhé!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_117792_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Không cho à? Vậy thì mụ phù thủy này sẽ hành động thật sự!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Ngài hỏi làm sao những chiếc kẹo này có nhân bên trong, hoàn toàn không tìm thấy khe hở hay lỗ kim nào cả, thật mong muốn người phát minh ra những chiếc kẹo này cũng đến làm việc ở nhà hàng Mythag, mỗi ngày đều sáng chế cho tiểu thư này một món tráng miệng mới!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Ngài đã chọc giận Nữ phù thủy!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Trước đây tôi luôn cảm thấy kẹo thì quá giản dị và không được thanh lịch so với bánh kem, giờ đây nhận ra, tôi đã đánh giá thấp những món nhỏ xinh trong giấy màu sắc sặc sỡ ấy. Đặc biệt là so với bánh kem, kẹo có thời hạn sử dụng lâu hơn nhiều, muốn tích trữ bao nhiêu cũng không sợ bị hỏng, thật muốn chất đầy cả ngôi nhà!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Ngài tìm thấy một loại kẹo mới? Hãy cho tôi xem... cái gì thế, cái nhẫn kẹo này nhìn thật hài hước, sao lại có chiếc nhẫn lớn như vậy? Đợi đã, ý ngài tặng nhẫn cho tôi là sao? Nói rõ cho tôi biết đi!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_117797_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Nghe nói bên cạnh mụ phù thủy thường có một con mèo đen bí ẩn, chọn con mèo hoang trong trường thật sự là quá mất mặt, quyết định rồi, để cậu đội vòng tai mèo, làm con mèo đen nhỏ của tôi nhé."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_117798_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Kháng cự thì không có tác dụng."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_117800_AwakerVoiceContent = {
    Text = "Hơi hơi hơi!"
  },
  Voice_117800_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Trên thế giới này có thật sự tồn tại phù thủy không? Họ sống một mình trong những cánh rừng không có bóng người, ai sẽ nấu ăn, giặt giũ, chuẩn bị bánh ngọt cho họ? Nếu không ăn được trà chiều, thì cuộc sống như vậy còn ý nghĩa gì nữa, nghĩ đến mà đã không chịu được."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_117801_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "Mụ phù thủy đến rồi!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "Ngài vẫn còn chocolate trong tay? Tuyệt quá, hãy đưa cho tôi tất cả. Có chuyện gì vậy? Đồ của ngài chính là đồ của tôi, không phải là lẽ đương nhiên hay sao?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_117803_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Ngài hỏi tôi thích loại kẹo nào nhất? Để tôi nghĩ xem, kẹo hạt phỉ có vị rất thơm, chocolate caramel cũng rất ngon, kẹo dẻo rau câu dâu tây, kẹo dẻo nho có vị rất thú vị, còn có loại kẹo mạch nha có thể kéo dài rất dài, màu sắc giống như mật ong... không được, không thể chọn ra, mỗi loại kẹo đều có đặc trưng riêng của nó, mà giỏ bí ngô chính là có nhiều mà thôi, tôi sẽ lấy hết tất cả!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_117804_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Mục tiêu cuộc sống của tôi hiện tại là ăn hết tất cả các loại kẹo trên thế giới, chỉ cần nghĩ đến việc vẫn còn rất nhiều loại kẹo vô số đang chờ đợi tôi, tôi đã tràn đầy động lực để thức dậy mỗi ngày. Bạn nói bánh kem? Bánh kem là một mục tiêu sống nữa của tôi."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_117805_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Đừng nhìn vẻ bề ngoài của ngài như trẻ con, thực ra tuổi tác của ngài đã đủ lớn để chôn xuống đất rồi, đừng nói đến kẹo, ngay cả bất cứ thứ gì mà người sống thích cũng không làm ngài hứng thú. Vậy nên, món kẹo sẽ gửi cho ngài, tốt hơn hết là hãy tặng hết cho tôi, tôi chính là người sẽ không bao giờ làm chúng thất vọng."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về tulô"
  },
  Voice_117806_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Nếu tôi trở thành phù thủy, tôi nhất định phải trở thành phù thủy sống trong cung điện sang trọng, cung điện phải lộn xộn, rồi tìm mười đầu bếp giỏi nhất mỗi ngày làm cho tôi những chiếc bánh và kẹo khác nhau… bạn nói thứ đó gọi là công chúa? Thì sao, tôi vẫn có thể làm một phù thủy công chúa mà!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_117807_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Này, chóng chuẩn bị cho tôi nhiều loại kem đánh răng đi, không, tôi không ăn nhiều kẹo đâu, tôi không có sâu răng đâu, chỉ hơi đau một chút khi ngủ vào ban đêm thôi……"
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Lời lẽ rỗi việc · Về kẹo"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Mặc dù quy tắc của nhà hàng Mythag thường khiến người ta không thoải mái, nhưng tay nghề làm món tráng miệng của họ, ừm... coi như tạm chấp nhận đi."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "Trên thế giới này thật sự tồn tại nhiều nơi đen tối, ghê tởm, có thời gian lo lắng về sự hủy diệt của thế giới, không bằng trước đó ăn thêm vài viên kẹo."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Đau quá!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Mặc dù giờ không còn những tấm thảm lông cừu, vòng cổ ngọc trai đen trên biển, hay bộ đồ ngủ satin phương Đông nữa, nhưng hàng ngày thức dậy trong phòng đầy kẹo, chỉ cần với tay là có thể chạm đến giỏ bí ngô đầy ắp, cuộc sống như vậy, có lẽ mới thực sự là hạnh phúc... Này, đừng có cười mỉm mỉm như vậy, vẫn phải phục vụ cô tiểu thư mãi mãi, bạn còn phải cố gắng hơn nữa!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_117812_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Miserable Mythag, dám cản trở tôi lấy kẹo, sao? Vẫn không phải bị tôi ăn vào sao?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Làm gì vậy? Muốn ăn kẹo của tôi à? Hừ hừ, cũng không phải không thể từ bi ban tặng cho bạn, nào, gọi một tiếng nghe thử, thưa phù thủy!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Thế nào có thể gọi là cướp bóc nhỉ? Tôi chỉ đang thi hành quyền lực quý phái của một quý cô mà thôi."
  },
  Voice_117815_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_117816_AwakerVoiceContent = {
    Text = "Lữ khách kẹo công lý đã đến, tất cả kẹo thất lạc đều nên trở về nơi chúng thuộc về!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Thật đáng ghét, thằng keo kiệt, mụ phù thủy sẽ nhớ đến cậu……"
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Tại sao con chuột nhỏ đó có thể thỏa thích lục lọi kẹo, mà tôi thì không? Các ngươi đang chống lại quý cô sao! Thật thiếu tôn trọng!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Không cho à? Vậy thì mụ phù thủy này sẽ hành động thật sự!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Hãy ăn kẹo nhé!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_117821_AwakerVoiceContent = {
    Text = "So với những người phục vụ trong các nhà hàng, bạn vẫn là người hiểu ý nhất, biết đặc biệt chuẩn bị cho tôi một viên kẹo, hãy tiếp tục nhé, người hầu riêng của tôi."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_117821_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Hơi hơi hơi!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "Quá đáng!"
  },
  Voice_117823_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_117824_AwakerVoiceContent = {
    Text = "Cản tôi làm gì? Là một người hầu trung thành của tiểu thư, bạn không nên chủ động giúp tiểu thư cướp hết kẹo… mang đến sao?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Dừng lại, cướp! Tôi khuyên bạn hãy nhận thức một chút, ngoan ngoãn giao hết tất cả kẹo ra đi, nếu không, hừ hừ…"
  },
  Voice_117825_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_117826_AwakerVoiceContent = {
    Text = "Mềm, cứng, giòn, nhẹ, vị sữa, vị trái cây, vị hạt, vị socola… Ồ, làm sao mà trên thế giới này lại có nhiều loại kẹo tôi chưa thử đến vậy? Quyết định rồi, hãy đề nghị với Mythag tổ chức lễ Thánh hàng tuần nhé!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_117827_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_117827_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "Nữ phù thủy vĩ đại chắc chắn sẽ chiến thắng! Thần kẹo đang che chở cho tôi, và tôi, che chở cho tất cả các loại kẹo! Ah ha ha ha!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Kháng cự thì không có tác dụng."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Tất cả kẹo cuối cùng sẽ thuộc về tôi!"
  },
  Voice_117830_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_117831_AwakerVoiceContent = {
    Text = "Cậu bé đó nghe lời đến mức hơi đáng sợ, chỉ cần bạn xin kẹo, cậu ta sẽ cho, thậm chí không để lại một cái cho mình, làm cho người ta còn thấy ngại ngùng... ợ, tôi muốn nói, vì cô ấy thật biết điều, phù thủy nhân từ chắc chắn sẽ để lại một số làm phần thưởng."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lily\""
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Ngài đã chọc giận Nữ phù thủy!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Tôi đã tức giận rồi!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Tất cả kẹo cuối cùng sẽ thuộc về tôi!"
  },
  Voice_117834_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_117835_AwakerVoiceContent = {
    Text = "Ngài nói gì, loại kẹo bông này cũng có thể nướng ăn sao? Hả, nóng hổi và dính dính thì có ngon không? Để tôi nếm thử? Được thôi, tôi sẽ miễn cưỡng thử một miếng, nếu ngài dám đùa với tôi... Ừ?! Cái cảm giác giòn giòn, mềm mềm này, ngon quá!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_117835_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Hư vọng, đảo lộn, đều là số phận!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Hư vọng, đảo lộn, đều là số phận!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Bởi vì đã đối mặt với nỗi kinh hoàng thực sự, nên không sợ hãi con người thật của tôi? Hừ, thật là một câu trả lời khôn khéo, nhưng cũng khiến tôi… càng ngày càng tò mò về bạn."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_123312_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Thế giới trong mắt bạn như thế nào? Những giới hạn kinh dị đó ở đâu? Không, tôi không muốn bạn kể cho tôi, tôi muốn cùng bạn cảm nhận, cảm nhận những điều điên rồ, cái chết, sự kinh dị. Tôi đã quyết định! Trước khi thỏa mãn sự tò mò, tôi sẽ không rời xa bạn."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_123313_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Kẻ điên không kiểm soát? Bạn nói không sai. Ở đây không phải là thế giới của tôi, không có những luật lệ và quy tắc nhàm chán đó... Ở đây, tôi muốn làm gì thì làm, vì vậy Người Giữ Gìn, bạn phải cẩn thận đấy, đừng để bị kẻ điên mất kiểm soát cắn nhé."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_123314_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Vì sức khỏe thể chất và tinh thần của tôi, bạn muốn có một cuộc trò chuyện sâu sắc? Được rồi, hãy bắt đầu nhanh chóng, những chuyện nhàm chán này, bắt đầu sớm thì kết thúc sớm."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_123315_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Tôi chỉ đang giả vờ là người bình thường để trả lời câu hỏi của bạn? À, vẫn bị bạn phát hiện rồi — vậy, bạn đã sẵn sàng để thấy bản chất thật của tôi chưa?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_123316_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Chặt đầu của bạn."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "Mọi người từ trẻ đến già đều thích xem! Lấp lánh☆Lốc xoáy——!!"
  },
  Voice_123771_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_123772_AwakerVoiceContent = {
    Text = "Người đáng lẽ phải ngã không phải là tôi……"
  },
  Voice_123772_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_123773_AwakerVoiceContent = {
    Text = "Tác động bão tố!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Bạn muốn cứu thế giới tàn khốc và méo mó này sao? Thật là một cách chết điên rồ và thú vị — hãy để tôi xem bạn có thể đi xa đến đâu."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Các bé yêu, có muốn thử chiếc rìu của tôi không? Đừng vội, đây rồi..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Người giữ bí mật, hình như tôi thấy ánh sáng, chẳng lẽ lần này…… không biết các đồng nghiệp trong đoàn điều tra thế nào rồi? Nhất định đừng để lại một đống công việc cho tôi, tôi không muốn làm thêm giờ."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_123776_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Thông qua nghi lễ này tôi có thể về nhà? Bạn chắc chứ? Đây là lần thứ mấy thử rồi... Thôi được, dù sao cũng thử xem có hại gì đâu."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_123777_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, quả thật so với những ngày nhàm chán, cuộc sống thăng hoa adrenaline như thế này vẫn phù hợp với tôi hơn!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_123780_AwakerVoiceContent = {
    Text = "Người đáng lẽ phải ngã không phải là tôi……"
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Lấp lánh☆Siêu tân tinh——Phát xạ!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Mọi người từ trẻ đến già đều thích xem! Lấp lánh☆Lốc xoáy——!!"
  },
  Voice_123782_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_123783_AwakerVoiceContent = {
    Text = "Cảm giác hiện tại... giống như đã bước vào trong sương mù. Nói về sương mù, tôi lại nhớ đến những cậu bé trong sương mù đó. Thật đáng tiếc, khi tâm trạng không tốt thì không thể tìm chúng để giải tỏa nữa."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_123783_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Ghét ư? Tôi không nói như vậy, tôi chỉ thật lòng hy vọng rằng những cuộc họp nhàm chán, xã hội và các giá trị phổ quát sẽ biến mất mà thôi."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Chính là như vậy... Tôi có thể cảm nhận được, tôi đang ngày càng gần với \"bản thân thực sự\"."
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "À, thất bại như đã dự đoán. Cuộc sống chính là như vậy, có lúc thăng trầm, quen dần thì sẽ ổn thôi… Nhưng mà, vẫn cảm ơn bạn vì đã thử lần này."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_123786_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "Giống như thảm họa sương mù, tôi cũng không biết gì về Rỗng Rỗng. Đó chính là điều khiến chúng trở nên hấp dẫn, phải không?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mộc Hạ, đoàn điều tra……Ôi không, bây giờ không còn là tiền phong của đoàn điều tra nữa. Vậy thì, tôi sẽ giới thiệu lại về mình — tôi tên là Mộc Hạ, chỉ là một cô gái đáng yêu~"
  },
  Voice_123788_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_123789_AwakerVoiceContent = {
    Text = "Biến đi!"
  },
  Voice_123789_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Nơi này quá gần khu vực cư trú của con người, xung quanh toàn là những người lớn nhàm chán…… Có bao giờ nghĩ đến việc chuyển trường đến những vùng núi rừng hoang vắng không?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_123791_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_123791_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Tôi sắp yêu cảm giác lang thang trong thế giới khác này, cơ thể mạnh mẽ được đánh thức, sự hòa tan đáng sợ và những vị thần chưa biết! Ah, mọi thứ đều là sự thoải mái xa rời xã hội bình thường!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Còn ai nữa không? Tôi đang chơi rất vui——Nhanh lên, ai cho tôi chém thêm một phát nữa."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_123794_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_123794_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Một lần thất bại không thể đại diện cho điều gì... thật là buồn cười. Các cậu hãy rửa sạch cổ chờ tôi nhé!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Có nhiệm vụ? Lần sau không cần chào hỏi, chúng ta đã quen đến mức không cần diễn \"quy trình gặp gỡ xã giao\" nữa."
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Hy sinh bản thân vì người khác, thực sự là một suy nghĩ ngu ngốc và đáng tức giận. Không ai có thể yêu cầu người khác như vậy, ngay cả thần minh cũng không được."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Salvador\""
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Không tệ lắm——"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Cuối cùng cũng không cần phải giả vờ nữa... Tiếp theo, hãy để chúng ta chơi thật vui nhé."
  },
  Voice_123799_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_123800_AwakerVoiceContent = {
    Text = "Nghi lễ vẫn chưa kết thúc sao? Tôi thật sự muốn nhanh chóng trở về để ăn cá hầm Revinlog, trà hạt phỉ Kava nóng hổi, tất nhiên, trà đỏ Ceylon và bánh Andalusia ở đây cũng không tồi."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_123800_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Luôn nâng cao khả năng của tôi, bạn không sợ một ngày nào đó tôi sẽ mất kiểm soát sao... haha, đùa thôi."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Thật ra, tạm thời ở lại thế giới này cũng không tệ. Tôi sẽ ghi nhớ mọi thứ xảy ra ở đây, viết lại và khi trở về sẽ chia sẻ với mọi người bên đó. Ừm, tên gọi sẽ là \"Cuộc phiêu lưu ở thế giới khác của Mộc Hạ\", nghe có vẻ tuyệt đúng không?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_123802_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Tôi thừa nhận cô ấy rất đáng yêu... Ừm, đúng vậy, nhìn cô ấy đuổi bắt và đánh nhau với những con mèo hoang lang thang trong khuôn viên trường thật sự rất đáng yêu."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Lệch lạc: Về Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Mặc dù những lực lượng này không thể đưa tôi trở lại thế giới của mình, nhưng trở nên mạnh mẽ luôn là điều tốt."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Nữ hầu à, tôi cũng đã làm qua, hãy tìm thời gian cho cô ấy xem cách tôi phát triển, chiến đấu bằng máy hút bụi!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Lời nói phiếm: về Gia Lân"
  },
  Voice_123805_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Gia Lân\""
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, quả thật so với những ngày nhàm chán, cuộc sống thăng hoa adrenaline như thế này vẫn phù hợp với tôi hơn!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Đòn chí mạng."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Xếp hàng từng người một."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "Hủy diệt đi!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Đừng nghĩ, đừng làm phiền, nghe mù lòa, tuân theo như người câm, trần gian chỉ là gánh nặng!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Đừng nghĩ, đừng làm phiền, nghe mù lòa, tuân theo như người câm, trần gian chỉ là gánh nặng!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Ngài hỏi họ tại sao trong đầu lại trống rỗng? Ừm, có lẽ là do sinh ra đã như vậy."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Ngừng giận, ngừng oán, mọi thứ đều trở thành hư vô."
  },
  Voice_126949_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_126950_AwakerVoiceContent = {
    Text = "Sự nhiệt tình như vậy sẽ khiến tôi không thể không muốn trêu chọc ngài hơn nữa."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_126951_AwakerVoiceContent = {
    Text = "Ôi trời!"
  },
  Voice_126951_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Ngài đang mong đợi tôi xinh đẹp hơn, hay đáng sợ hơn?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Công chúa sinh ra từ niềm vui, chiếc váy của cô thêu chỉ vàng, làn da giống như ngà voi, hương trầm bay bổng xung quanh cô, ánh mắt lấp lánh khiến người khác mê mẩn."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_126953_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Rất nhanh, cô ấy đã chán ngấy với những trò vui này, các tín đồ của cô chỉ liên tục lặp đi lặp lại cùng một kịch bản, đắm chìm trong tình yêu sinh ra từ dục vọng, hoặc dục vọng sinh ra từ tình yêu, vì mất mát và phản bội mà đau khổ không chịu nổi, sự ngu ngốc của họ khiến cô ấy chán nản, và nước mắt của họ cũng khiến cô ấy chán ngấy."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_126954_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Ánh mắt tiểu nhân của các ngươi thật khiến ta chán ghét."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "Vị đó Bà Đỏ, đã từng gửi cho tôi vài lần thiệp mời salon. \n Hương vị bánh ngọt ngoại quốc cũng khá ngon, nhưng… \n Cô ấy nên nói sớm cho tôi biết, ở trong nhà cô, bánh ngọt và phục vụ không phải là một ý nghĩa."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Sorrel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Sorrel\""
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Không phải là tình yêu sao, vậy tại sao lại sợ hãi khi bị bao vây? Không phải là sự chán ghét sao, vậy tại sao lại rơi lệ khi không thể quay lại? \n À, bây giờ bạn đã sợ bóng dáng của tôi rồi sao, hương thơm của hoa ngọc lan đã trở thành thứ ngọt ngào và tanh tưởi mà bạn không thể hiểu nổi rồi sao?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_126958_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_126959_AwakerVoiceContent = {Text = "Ừm!"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Ôi? Bạn hỏi tôi tại sao họ lại xăm hình đó ở nách? Bạn không thấy điều đó rất thú vị sao?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về sự phì nộn"
  },
  Voice_126961_AwakerVoiceContent = {
    Text = "Ôi trời!"
  },
  Voice_126961_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_126963_AwakerVoiceContent = {
    Text = "So với sự cống hiến của tín đồ, những điều này lại phù hợp với tâm ý của tôi hơn."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Trước tiên là phong thái, sau đó là hình dáng, cho đến khi họ cũng sở hữu một đôi mắt... hoặc nói cách khác, chỉ còn lại một đôi mắt đẹp đẽ, mê hồn—cũng giống như đôi mắt của bản thân tôi."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_126964_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Hôm nay tôi thực sự chán nản, bạn không có điều ước nào cần được thực hiện sao?\nThật đáng tiếc, chỉ vì một số mục đích nhàm chán, có rất nhiều người sẵn sàng vung lưỡi hái, dâng lên tôi máu thịt.\nNhưng nếu là bạn thì…"
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_126965_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Ung Dung Chúng vì sao đi theo bên thiếp, lại vì sao mà thành lập? Câu hỏi thú vị, ngài có từng có người mà cầu mà không được, có nỗi hối hận vì bất lực không?\n\nUhm, nhìn có vẻ là không, thật đáng tiếc.\n\nCái biểu cảm giãy giụa trong tuyệt cảnh ấy, nếu xuất hiện trên gương mặt ngài, nhất định sẽ rất～rất thú vị."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_126966_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "……Nếu ngài còn tiếp tục quá đáng như vậy, thì thiếp sẽ không chỉ dùng tư thái này để đối mặt với ngài đâu."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Câu chuyện của cô ấy, tôi đã gần như quên mất, nhưng đó là một câu chuyện về niềm vui, một câu chuyện về sự tàn bạo, một câu chuyện ban đầu là về sự bỏ rơi và báo ứng, sau đó là về hy sinh và mù theo."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_126968_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Hãy làm vui lòng ta, hãy tự tàn sát trong nỗi đau và sự sợ hãi đi~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "……điều này khiến tôi có chút hứng thú."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Mọi người sẽ nhìn thấy diện mạo của người mà mình yêu quý nhất dưới chiếc quạt của tôi. Tôi đã cho những kẻ yếu đuối này sức mạnh này, trở thành lưỡi dao sắc, để tìm niềm vui từ đó. \n Nhưng có lẽ, tôi chỉ đang nói, có lẽ. \n Nếu bạn sẵn lòng bị mê hoặc bởi điều này, tôi sẽ cảm nhận được niềm hạnh phúc thật sự, vô thượng."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_126971_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Đừng lo lắng, bạn khác với những kẻ tầm thường đó. \n Suỵt, đừng nhìn vào phía sau của ta, đừng bận tâm đến những cái chạm vô hình - hãy nhìn vào đôi mắt của ta."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_126972_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Khẽ cười, các ngươi có dám nhìn thẳng vào diện mạo thật của ta không?"
  },
  Voice_126973_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_126975_AwakerVoiceContent = {Text = "Ồn ào."},
  Voice_126975_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_126976_AwakerVoiceContent = {
    Text = "Sao? Lại đang nhìn chằm chằm vào chiếc quạt của ta, đang say mê sao? \n Ha ha, bất kể bạn muốn nhìn thấy khuôn mặt của ai dưới chiếc quạt, ta sẽ làm hài lòng bạn... Đến đây, lại gần hơn chút đi - \n Ê, không muốn sao? Nói ra những lời lạnh lùng như vậy, nhưng biểu cảm lại rất đáng yêu..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_126976_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Quý vị không mơ quê, muốn tìm kiếm điều gì?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Ngừng giận, ngừng oán, mọi thứ đều trở thành hư vô."
  },
  Voice_126978_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_126979_AwakerVoiceContent = {
    Text = "Không được vô lễ."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_126980_AwakerVoiceContent = {Text = "Ừm!"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "Tôi cũng từng có một cô gái nhỏ xinh đẹp, nhút nhát như vậy. \n Một nụ hoa rực rỡ, tất nhiên phải thêm một chút mũi nhọn, không thể cắm vào bình hoa."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lily\""
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "Học viện đã kiên quyết từ chối đơn xin làm việc của tôi tại phòng tư vấn tâm lý, thật kỳ lạ, rốt cuộc có điều gì không ổn?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Tất cả rồi sẽ trở về Hư vô, sao không cùng tôi tìm chút niềm vui? \n Xin hãy yên tâm, nếu một ngày nào đó bạn không thể chống cự, tôi sẽ không để Ngài lấy đi bạn trước."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "Nhàm chán."
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "Ngài thật là một người kỳ diệu, trong thế giới sắp phải diệt vong này, lại bận rộn với nhiều chuyện bên ngoài như vậy. \n Khiến tôi cũng không thể không cảm thấy hứng thú."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_126985_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Đừng lại gần!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Tôi là chúa tể Không mơ quê, Tuần. Nếu trong lòng bạn có người muốn gặp nhưng không thể gặp, tôi sẵn lòng mở quạt, cho bạn một cái nhìn."
  },
  Voice_126988_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_127088_AwakerVoiceContent = {
    Text = "Tất cả các con non của sinh vật đều rất phiền phức. \n Nhỏ bé, mềm mại, ồn ào, vô tình khiến mọi thứ xung quanh xoay vòng. Tôi thích sự ồn ào, nhưng thực sự không thích loại ồn ào này, mong bạn hãy để chúng xa một chút."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Tiểu hoa nhài của ta, đứa bé ngoan của ta, ta ngọt như mật khi ở trong trò chơi gia đình~\nÀ, một vài lời nói lăng nhăng khi tâm trạng tốt, bạn không cần phải lo lắng."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "Trong truyền thuyết về Quốc gia Phàn Long, chim công là một loài thú dữ đẹp đẽ và kiêu sa. \n Đẹp đẽ nhưng độc ác, nghe thôi đã khiến người ta rùng mình, nếu xấu xí nhưng lại tốt bụng thì có phần nhàm chán."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Ăn hết ăn hết, ăn tất cả đi"
  },
  Voice_129651_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_129652_AwakerVoiceContent = {Text = "Ọc ọc~"},
  Voice_129652_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Viên than nhỏ, tôi, ăn cơm, cùng nhau? Cùng nhau!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_129653_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Mosk! Rất mạnh!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Hố sâu! Xoáy! Hủy diệt! Tất cả—— biến thành Vortex đi!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Đau!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Đừng chạm vào tôi, đừng! Đừng chạm vào tôi, hỏng rồi!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_129657_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Vỏ ốc, lấp lánh! Lấp lánh, đẹp, tặng bạn!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_129658_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Lạnh băng, đáng sợ, Mosk, trốn đi!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về đóa"
  },
  Voice_129659_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"đóa\""
  },
  Voice_129660_AwakerVoiceContent = {Text = "Á hô!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Săn bắn, đáng ghét! Hỏng rồi! Mosk, đánh chúng, hỏng rồi!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "Vui quá! Lần sau! Còn muốn nữa!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_129662_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Vuốt ve, được rồi! Mosk, bạn, vuốt ve!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Không, đừng! Viên than nhỏ, Mosk, bảo vệ!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Lại một lần nữa? Lại một lần nữa!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hì hì, Mosk, muốn chơi!"
  },
  Voice_129666_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_129667_AwakerVoiceContent = {
    Text = "Sóng lớn đến rồi!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_129668_AwakerVoiceContent = {Text = "Mất!"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Đau!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Ôi!"},
  Voice_129670_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_129671_AwakerVoiceContent = {
    Text = "Lễ nghi?! Đưa tôi cùng đi!"
