  },
  Voice_129682_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_129683_AwakerVoiceContent = {
    Text = "Nautilus, Nốtira, Viên than nhỏ! Sáng lấp lánh!"
  },
  Voice_129683_AwakerVoiceTitle = {
