  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nốtira, muốn gặp. Eh, Nốtira, Mosk, Mosk!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Nốtira"
  },
  Voice_129693_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Nốtira\""
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Đã trở nên mạnh hơn!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Tôi! Mosk! Xin chào!"
  },
  Voice_129695_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_130511_AwakerVoiceContent = {Text = "Hô——"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Kỹ năng·II·Nạp đạn ba"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "Sai lầm sẽ được sửa chữa."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "Bi kịch mà ngài thấy, chẳng qua là một thoáng trong muôn vàn khả năng. Vén màn số mệnh, ta nhìn thấy sân khấu tối đen kia. Đèn tắt, người tản, vạn tượng quy về vực thẳm hỗn mang. Tuy nhiên... tất cả chưa phải hồi kết. Ý chí của ta vẫn còn, đủ để chống đỡ cuộc khổ dịch vô vọng này, chờ đợi tia huy quang kế tiếp thắp sáng."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Số phận của người đời đều do sợi tơ dẫn dắt… Nhưng số phận của ngài, lại là kịch bản mà tôi không thể đọc hiểu. Tôi mong chờ, ngài sẽ mang đến cho thế giới này màn ứng tấu xuất sắc như thế nào?"
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Con rối chính, hãy bước lên sân khấu thuộc về ngươi."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Ừm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Phàm là quá khứ, đều là khúc dạo đầu. Trang mới của ngài và ta, đang chờ ngài viết nên, Người Giữ Bí Mật."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_133725_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Nếu ngài yêu thích hài kịch, \"Giấc Mộng Đêm Hè\" là một lựa chọn tuyệt vời. Ta đặc biệt yêu thích những lời mê sảng xảo quyệt của Puck, trong tiếng cười đùa của tinh linh, luôn ẩn giấu mật ngữ mà số mệnh vô tình tiết lộ."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_133726_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Thuận theo đây."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_133728_AwakerVoiceContent = {
    Text = "Guồng xe sợi, tại đây quay."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Hỡi tù nhân bi ai của số mệnh, hãy lĩnh nhận phán quyết đã định sẵn cho ngươi."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Dẫu là người quan sát thấu tỏ vạn tượng, cũng chẳng qua là kẻ diễn vụng về trong kịch bản của chính mình. Nắm giữ lưới định mệnh, nhưng rốt cuộc vẫn bị sợi tơ trói buộc. Trong cảnh ngộ đã định sẵn này, chúng tôi bước trên những con đường khác nhau, nhưng đều chưa bao giờ từ bỏ những cuộc truy tìm vô vọng ấy. Dù ngu muội hay si cuồng, tôi là vậy, cô ấy cũng thế."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Nhàn đàm: Về Tavi"
  },
  Voice_133730_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Tà Vy\", tính năng sẽ được mở khóa"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Bước ngoặt bất ngờ?"
  },
  Voice_133731_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_133732_AwakerVoiceContent = {
    Text = "Đa tạ ngài đã đồng hành suốt những lần màn mở màn khép. Tương lai, ta nhất định không phụ kỳ vọng, dâng lên ngài những đêm kịch nghệ lay động lòng người hơn nữa."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_133732_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Ca giả tài năng thiên phú đến vậy, giọng hát trời ban, trong trẻo mà nồng cháy, tựa như vọng ra từ tiếng nói của định mệnh... Nếu có thể mời đến nhà hát của tôi, chắc hẳn ngay cả những khán giả khó tính nhất cũng sẽ phải kinh ngạc."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Nhàn đàm: Về Tinkter"
  },
  Voice_133733_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"tinkerer\""
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Ngài và ta, hai sợi tơ số mệnh không thể nhìn rõ ấy, đã sớm quấn chặt lấy nhau, không phân ngươi ta, dệt thành lồng giam và con đường. Ta không thể nhìn rõ biên giới của lồng giam, cũng không thể nhìn rõ điểm cuối con đường. Đây chính là phần mê hoặc nhất trong câu chuyện này."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_133734_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Sợi tơ vận mệnh, đã buông xuống."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Cô ấy thường đến nhà hát của tôi ngồi xem... Nhưng tôi biết, cô ấy không đến vì vở kịch, mà mượn sân khấu này để phản chiếu phong cách của chính mình. Thế nhưng diễn xuất tinh tế đến vậy, nếu chỉ làm khán giả thì thật đáng tiếc. Nó lẽ ra phải tỏa sáng dưới ánh đèn sân khấu, chứ không phải ẩn mình trong bóng tối của hàng ghế khán giả."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Sorrel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Sorrel\""
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Tôi từng nghe anh ấy biểu diễn, giai điệu tuyệt mỹ ấy khiến linh hồn người ta rung động... Có lẽ, nên mời anh ấy phổ một bản giao hưởng định mệnh cho vở kịch mới của tôi?"
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Câu chuyện bên lề: Về Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Hamlin\""
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Thêm một câu chuyện viên mãn, hạ màn."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Lưới vận mệnh vô tận, ta đã nhìn thấy toàn cảnh."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Nếu ngài cho phép... ta muốn dệt nên một màn kịch đôi chỉ thuộc về ngài và ta. Không cần khán giả, chẳng cần tập dượt... Ta chỉ mong chờ, khi ngài đứng dưới ánh sáng, sợi tơ mà ta không thể nhìn rõ ấy, sẽ có những nhịp rung động đáng kinh ngạc đến nhường nào."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_133740_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Vũ công bất hạnh ơi, tôi đã chứng kiến bước nhảy của cô ấy. Đó là vẻ đẹp tiến sát đến hủy diệt, mỗi vòng xoay đều bùng lên ngọn lửa xanh, cố thiêu đốt sợi dây định mệnh, nhưng đáng tiếc cuối cùng vẫn bị những sợi tơ ấy cắt xé thành bức tranh bi thương diễm lệ nhất. Nếu có cơ hội, tôi nguyện viết cho cô ấy một vở vũ kịch chỉ thuộc về riêng cô ấy."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Nhàn đàm: Về Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Giải khóa sau khi nhận được thân thể được đánh thức \"Liz\""
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Nơi đây dệt nên, nơi đây cân nhắc, nơi đây phán quyết."
  },
  Voice_133742_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_133743_AwakerVoiceContent = {
    Text = "Hãy lắng xuống……"
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Thêm một sợi tơ, đã rõ ràng."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Màn nhung đã mở rộng vì ngài, kịch bản số mệnh đang chờ khai màn. Hãy cho ta biết, ngài muốn bước vào quỹ đạo định mệnh nào? Là hồi kết bi thương, hay khúc dạo đầu hoan hỉ?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_133745_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Ta quả thực đắm chìm trong công việc dệt tơ ngày qua ngày... Trong nhịp kéo tơ lặp lại và tĩnh lặng, dự kiến khởi đầu và kết thúc của muôn vàn câu chuyện, bàng quan mọi số mệnh hạ màn, tựa như đã siêu thoát ngoài vòng số mệnh. Nhưng lưới trời số mệnh không thể né tránh, chỉ đứng ngoài bàng quan rốt cuộc vẫn cô liêu. Thế là, ta bước vào nhà hát, trong vai diễn, nếm trải những bi hoan mà chính tay ta dệt nên nhưng chưa từng trải qua."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh…"},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Hừ……"},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Nơi đây dệt nên, nơi đây cân nhắc, nơi đây phán quyết."
  },
  Voice_133749_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_133750_AwakerVoiceContent = {
    Text = "Lời thì thầm của vận mệnh, đã gần hơn rồi."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Nhà hát vừa dàn dựng một vở hài kịch lãng mạn, ta đã giữ sẵn một chỗ trống cho ngài tại hàng ghế của số mệnh. Ta sẽ trong mỗi đêm dài số mệnh đan xen, lặng lẽ chờ đợi ánh sao tương phùng cùng ngài."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_133751_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "Chấp niệm đến vậy trong việc gảy lên sợi tơ số mệnh... Ngài, cũng muốn nhìn thấy chương truyện thuộc về chính mình sao?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Tương lai đã đến."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Nếu ngài muốn bước vào điện đường bi kịch, xin cho phép ta dâng lên \"Antigone\". Giữa cuộc đối đầu của luật thần và trần thế, mỗi bước nàng đều giẫm lên sợi tơ do số mệnh dệt nên, cho đến khi bước vào bóng tối thâm u của lăng mộ đá. Chính vì xiềng xích ấy không thể thoát khỏi, ý chí bùng phát từ thân hình nhỏ bé của nàng mới rực cháy như ngọn lửa cô độc giữa đêm trường."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_133754_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Từ kết cục vô định, không thoát khỏi lưới nhân quả……"
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Trên sợi tơ, ta thấy muôn vàn sắc màu cầu vồng lưu chuyển — nó nối liền lưới trời vô tận, trải rộng thế giới vô biên, mở ra vô hạn khả năng, cuối cùng dệt nên hoa văn tráng lệ rực rỡ nhất thế gian. Bất kể thần minh hay phàm nhân, anh hùng hay ác nhân, đều bị sợi tơ mảnh mai ấy thao túng, dưới ánh mắt số mệnh nghĩa vô phản cố lao về kết cục thuộc về mình."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Ta vốn tưởng trên đời không còn lựa chọn nào có thể khiến ta kinh ngạc... Gu thưởng thức kịch nghệ của ngài, thật khiến ta ấn tượng sâu sắc."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_133757_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Sợi tơ số mệnh luôn kết nối trong bóng tối... Ngài đã chạm vào sợi tơ này, cũng chạm động đến ta."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_133758_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Tôi luôn không muốn xem những vở kịch mẫu nhàm chán không thay đổi. Ý nghĩa của việc bước vào nhà hát, vốn nằm ở chỗ được trải nghiệm trực tiếp buổi diễn không thể tái tạo. Nếu mỗi buổi diễn chỉ là sự lặp lại máy móc, thì sân khấu sẽ trở thành chiếc lồng tinh xảo, còn việc xem kịch cũng chẳng khác nào cuộc hành hương mệt mỏi đến một kết cục đã biết trước. Buổi diễn như vậy, dù hoa lệ đến đâu, cũng đã mất đi linh hồn. Ngài nghĩ sao về điều này?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Sợi tơ số mệnh vốn luân chuyển có trật tự trong lòng bàn tay ta... Cho đến khi ngài xuất hiện, khiến quỹ đạo của chúng gợn lên những làn sóng chưa từng dự liệu."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_133760_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Hỡi tù nhân bi ai của số mệnh, hãy lĩnh nhận phán quyết đã định sẵn cho ngươi."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Ta giữa muôn vàn sợi tơ vô tận, dệt nên quỹ đạo duy nhất."
  },
  Voice_133762_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_133763_AwakerVoiceContent = {
    Text = "Trên sân khấu vận mệnh, chúng sinh trong nhân quả của mình lặng lẽ chờ đợi lên sàn diễn, vạn nỗi bi hoan trong tiếng bánh răng quay mà lặng lẽ thành chương…… Màn đã mở, Người Giữ Bí Mật, câu chuyện giữa bạn và tôi, từ đây sẽ bắt đầu."
  },
  Voice_133763_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_133764_AwakerVoiceContent = {
    Text = "Phân tranh đã đến, ngài muốn đóng vai anh hùng phá lưới, hay vai phụ thuận theo số mệnh?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Sự phản kháng vô ích."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Cảm ơn. Tôi sẽ trân trọng món quà này."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Đã học rất nhiều về cấu trúc của Giác Tỉnh Thể, giờ cũng đã xứng đáng là chuyên gia rồi đó. Nhưng thứ gọi là \"Linh Tính\" trong Ngân Tâm, vẫn hơi không hiểu lắm nhỉ……"
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_139866_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Đây chính là, khởi đầu của thế giới mới……"
  },
  Voice_139867_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_139868_AwakerVoiceContent = {
    Text = "Tớ có thể làm được những việc như vậy đó. Tái tổ hợp cơ thể sinh vật khác nè, điều chỉnh nè……"
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_139868_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Nên điều chỉnh chỗ nào và như thế nào, mỗi loài sinh vật đều khác nhau, nên không chịu khó học hành thì không được đâu nhé."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_139869_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Không sợ sao, hình dạng của tôi? Ê, hơi nhàm chán nhỉ……"
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Sẽ không để ai cản trở chúng ta đâu"
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Tôi đã sẵn sàng rồi đây."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Sinh vật thật sự đầy đa dạng nhỉ. Muốn tìm hiểu thêm nữa!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Cậu muốn chơi cùng Saya không?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_139876_AwakerVoiceContent = {Text = "A!"},
  Voice_139876_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_139877_AwakerVoiceContent = {
    Text = "Đây chính là, khởi đầu của thế giới mới……"
  },
  Voice_139877_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_139878_AwakerVoiceContent = {
    Text = "Ăn no rồi, cảm ơn đã chiêu đãi!"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Thủ Mật Nhân, cậu đã từng yêu ai, nhớ nhung ai chưa?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_139880_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Eek!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "Có phải đây không?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Vất vả rồi! Có thu hoạch gì tốt không?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Sau khi thực hiện nhiều kiểm chứng khác nhau, đại thể đã hiểu rồi đó. \"Linh Tính\" mà mỗi Giác Tỉnh Thể sở hữu là hoàn toàn khác nhau. Và rồi, Linh Tính trong Ngân Tâm của tớ dường như là \"Tình Yêu\" đấy."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_139884_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Thế nào, giật mình chưa?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Đây là món quà cuối cùng dành cho cậu."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "\"Trên một ngôi sao nào đó trong số những ngôi sao này, bông hoa của tôi đang nở rộ...\"Đã nói như vậy đấy.\nHình như cậu cũng từng nói điều tương tự nhỉ."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_139887_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Thứ gọi là \"Ngân Tâm\" này, dường như kết nối với một ý chí rất xa xôi. Thật kỳ diệu nhỉ……"
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_139888_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Đây là món quà cuối cùng dành cho cậu."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Á!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Hoàng tử bé nói rằng, chính sự chăm sóc của cậu ấy dành cho bông hồng đã khiến nó trở nên khác biệt…… Cậu cũng nghĩ vậy sao?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_139892_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Hôm qua, tớ thấy một cuốn sách tên là\"Hoàng Tử Bé\" trong tủ sách của Lily. Tớ đã mượn nó rồi. Cậu có muốn đọc cùng tớ không?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_139893_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Ừm, cũng đã nghiên cứu cấu trúc của Ngân Tâm rồi, dần dần có nhận thức về đại thể của Giác Tỉnh Thể rồi đó."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_139895_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Á!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_139897_AwakerVoiceContent = {Text = "Hây da!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Mong được chỉ giáo nhiều!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Xin chào!……Nói vậy có đúng không?\nTôi là Saya. Ừm……xin hãy chỉ giáo—"
  },
  Voice_139900_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_139901_AwakerVoiceContent = {
    Text = "Có một loài hoa gọi là bồ công anh, sẽ để hạt giống bay theo gió trôi dạt đi. Những hạt giống lông tơ mềm mại được gió mang đi, rời xa quê hương thật xa thật xa, có lẽ sẽ rơi xuống sa mạc không có một cọng cỏ nào. Lúc đó, hạt giống nhỏ bé ấy sẽ nghĩ gì nhỉ……"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_139901_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Dù làm bao nhiêu lần cũng rất thú vị!"
  },
  Voice_139902_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_139903_AwakerVoiceContent = {Text = "Hây——"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_139906_AwakerVoiceContent = {
    Text = "Nguy hiể——"
  },
  Voice_139906_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Siêu thích đồ ăn ngon! Cũng thích những người dịu dàng với Saya. Được đối xử dịu dàng thì thật sự rất vui——"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Đó là người đã đánh thức tôi sao? Tổng cảm giác thật rạng rỡ nhỉ…… Ừm~ Vậy, cậu đã giúp cô ấy tìm được chị gái chưa?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Nhàn đàm: Về Tinkter"
  },
  Voice_140534_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"tinkerer\""
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Mỗi khi Saya muốn độc chiếm Thủ Mật Nhân, lại có rất nhiều người kỳ quặc bu lại. Vẫn thích lúc ở trong Mật Cảnh hơn——"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Thì ra là vậy. Hiểu rồi!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Thủ Mật Nhân, Liên Kết, Hoán Tỉnh Thể, là mối quan hệ cậu đã nói cho tôi biết đúng không. Có thể cảm nhận được linh hồn hai người liên kết với nhau…… Thông qua sợi tơ bạc? Đại loại vậy, ừm—— tổng cảm giác mọi thứ đều khó hiểu quá……"
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Dùng máu thịt để vận chuyển hạt giống? Ừm~ Thì ra là vậy. Hơi hứng thú với con cừu của cô ấy đấy."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Thais"
  },
  Voice_140538_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Thái Di Sơ\""
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Một mối nguy nào đó đe dọa thế giới này, bóng tối có thể dẫn đến sự diệt vong của tồn tại, đúng không? Tôi biết mà. Đã nghe rất nhiều từ Giáo sư Doyle rồi."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Không thích người thô bạo. Khiến người ta cảm thấy khó chịu……"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Chủng tộc của cô ấy, hình như cũng dựa vào việc cướp đoạt các chủng quần khác để có được cơ hội sinh sôi trên hành tinh mới đấy. Ừm~ Thì ra là vậy……"
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Tán gẫu: Về Winkor"
  },
  Voice_140541_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Đứa trẻ ngoan."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Ơ!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt·số ba"
  },
  Voice_141965_AwakerVoiceContent = {Text = "Ừm!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Bị đánh·Năm"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Thật đáng tiếc, khi bạn thay đổi ý định, bạn biết phải tìm ta ở đâu."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_143501_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "Đáng ghét..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Da thịt, cơ bắp, thần kinh, xương cốt, tất cả chúng đều sẽ được tái cấu trúc, lại lành lặn khỏe mạnh, lại tràn đầy sức sống."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_143503_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Trước biển cả, không có kẻ thù nào là bất khả chiến bại!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Yến tiệc, Săn lùng, che chở?\nHãy cầu nguyện với ta, những làn nước biển cổ xưa nhất sẽ nói cho ngươi biết tên ta.\nTa là chúa tể vực thẳm, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_143506_AwakerVoiceContent = {
    Text = "Hehe, nhớ những tháng ngày tại Epoyanth sao…\nNó vẫn ở trong thân xác này, luôn chào đón bạn trở về bất cứ lúc nào."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Dù ta không làm vậy, nhưng nếu một ngày nào đó ngươi nghe thấy tiếng nước biển và tiếng vỗ cánh trong tai, đừng lo lắng, đó là hiện tượng bình thường."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Dâng hiến giác quan của ngươi, mãi mãi sám hối trong vực thẳm!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Ta thích những người trẻ tràn đầy sức sống, tiếc thay, Misaque kiểm soát việc cuồng hoan quá nghiêm ngặt, thậm chí không có nổi một trường săn bắn tử tế.\nHơn nữa, Bên trong còn có thứ bẩn thỉu kia dám công khai nghênh ngang, thậm chí còn mang danh hiệu giáo sư."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_143511_AwakerVoiceContent = {
    Text = "Ta đã làm bao nhiêu thứ như vậy, bạn thậm chí không chịu gọi ta một tiếng cậu, thật đau đầu quá."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Đừng vội vàng, bóng tối nơi sâu thẳm nhất của biển tất sẽ Nuốt chửng các ngươi."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Quỳ xuống, trở thành dưỡng chất cho Epoyanth."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt·số ba"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Còn về sự tồn tại đã chọn ta… Chỉ có thể nói vừa thân thiện lại vừa tàn ác.\nRơi xuống đâu hoàn toàn tùy tâm trạng, chắc chắn sẽ cứu bạn thoát khỏi hiểm cảnh, còn nơi đó có phải là một hiểm cảnh khác hay không, thì không phải là điều \"chuyến đi\" lần này cần phải suy nghĩ.\nThật thú vị làm sao, thật khó đoán làm sao, ta đang cân nhắc tiếp nối truyền thống này."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_143515_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Ta và Epoyanth tồn tại một mối liên hệ đặc biệt, hay nói đúng hơn, ta chính là Epoyanth, Epoyanth được duy trì bởi ta, tồn tại thông qua thân xác của ta."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Epoyanth"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Ngẩng đầu lên, để lộ cổ họng của ngươi ra."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Xóa bỏ ký ức, xóa bỏ sự tồn tại. Thật quen thuộc… bạn hiểu ý ta, dù nguồn gốc khác nhau, nhưng có vẻ Chúng luôn sinh sôi từ nơi không có ánh sáng."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Các ngươi không nên ngu ngốc đến mức xâm phạm uy nghiêm của ta."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Quá yếu!"
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "Tại Epoyanth, cuộc cuồng hoan sẽ không bao giờ dừng lại, kẻ thù của Epoyanth cũng sẽ mãi mãi không được yên nghỉ."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_143521_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "À, ta cảm nhận được sự run rẩy của bạn, nhưng điều đó hoàn toàn không cần thiết, người bạn trẻ của ta.\nHãy chấp nhận nỗi Sợ hãi về sự tầm thường và bị bào mòn, nhìn vào ta, bạn sẽ hiểu rằng bạn luôn có một lựa chọn khác."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_143522_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Đúng vậy, ta biết thảm họa đó không phải do hắn trực tiếp chỉ đạo, chỉ là sự tình cờ trong lúc mua vui, nhưng điều này rõ ràng chỉ khiến ta càng muốn giết hắn hơn.\nĐám sương đen đó tốt nhất đừng đi một mình, cũng đừng để ta bắt được."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Những Người cá nhớp nhúa đó không phải bạn bè của ta, mà là kẻ thù của ta. Ngạc nhiên lắm sao? biển vốn dĩ không thuộc về chúng."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_143524_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Mãi mãi, lưu lại nơi đây!"
  },
  Voice_143525_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_143526_AwakerVoiceContent = {
    Text = "Chuẩn bị chưa, những con mồi!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "Linh tính sinh ra thân xác mới, thân xác được lấp đầy bởi những tri thức vô nghĩa, rồi những cá thể xinh đẹp linh hoạt ấy sẽ mãi mãi tụ hội tại một nơi.\nCòn nhớ ta đã nói không, nơi sâu thẳm nhất của biển dung chứa tất cả… giữ lại tất cả."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_143527_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Ác mộng, hãy chặn chúng lại."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Hy vọng những sinh vật nhỏ bé này sẽ không ăn hết của ngươi, ngươi biết đấy, nuôi cả một đại gia đình thực sự không phải chuyện dễ dàng."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Từ rất rất lâu về trước, trước khi lục địa nổi lên khỏi biển, hành tinh này đã hồi sinh một số linh tính đặc biệt. Mạnh mẽ, uy nghiêm, không thể Dòm Ngó.\nChúng không thể được định nghĩa là thù địch hay thân thiện, con người cũng như vô số sinh linh trong quá khứ, đối với Chúng mà nói chẳng đáng kể, sẽ bị phủi đi như bụi, cũng sẽ được bảo vệ cùng với lãnh thổ."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_143530_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Chỉ có sự già nua mới là cuộc phiêu lưu bạn cần một mình đối mặt, người bạn tốt nhất và kẻ thù khó chịu nhất của bạn, ánh đèn của Epoyanth sẽ xua đuổi nó đi hoàn toàn… Chỉ là những ký ức không đáng kể, bạn không cần để chúng neo giữ mình."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_143531_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Hãy từ bỏ ảo tưởng Thoát khỏi nơi này."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Ngươi sẽ hóa thành tro bụi trắng xám."
  },
  Voice_143533_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_143534_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_143534_AwakerVoiceTitle = {Text = "Đánh"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Thật thông minh đấy, cậu bé, Tín đồ của những quái vật ngoại lai luôn ngu ngốc đến mức ném xác xuống biển, điều đó không được tính là quà tặng, phải không?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Ngươi đã bị nhắm vào rồi."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Dù không muốn thừa nhận, đôi khi rất hiếm hoi, ta sẽ cảm thấy sự già nua không phải là thứ duy nhất mà thời gian mang lại, mà chỉ là một biểu tượng.\nVì vậy, ta cho phép nó tồn tại trên người ta. Tất nhiên — chỉ giới hạn ở vẻ bề ngoài."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "cầu nguyện là có hiệu quả đấy, hãy tưởng tượng, dù sâu bọ có xếp thành chữ Leoven trước mặt bạn, bạn cũng sẽ cân nhắc đáp lại yêu cầu của chúng."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_143539_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Hahaha, thôi nào, đừng có biểu cảm như vậy, người bạn nhỏ của ta.\nĐó chỉ là một số truyền thống mà cái gọi là \"thần cũ\" phải tuân theo, còn với bạn, không cần bất kỳ cái giá hay điều kiện nào, ta sẽ mãi mãi đứng về phía bạn."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_143540_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hừ, một quái vật nhỏ cấu kết với quái vật ngoại lai.\nThực ra có đứa ngốc nào đó đặt ta và hắn lên cùng một bệ thờ, thật là sỉ nhục!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về tulô"
  },
  Voice_143554_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Kẻ thù của kẻ thù là bạn bè, nếu có cơ hội, ta không ngại thực hiện một thương vụ tốt là cướp đi món đồ chơi yêu thích nhất của kẻ thù không đội trời chung."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Lắc"
  },
  Voice_143555_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lắc\""
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Ồ? Muốn ra tay với ta ở đây? Ta không ngại."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Thêm nữa, hãy cho ta thêm Sức mạnh!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Ta không thích những người không thuần khiết, vì không thuần khiết thường đồng nghĩa với yếu đuối. Nhưng bạn là một ngoại lệ. Ta từng nghĩ rằng, một người gánh nặng quá nhiều thứ sẽ không thể tiến xa hơn. Thế nhưng con đường bạn bước đi, ngay cả ta cũng cảm thấy kinh ngạc… Có lẽ, một người đi trên con đường khác biệt, mới là đối tượng đáng được bồi dưỡng và thách thức hơn. Bạn có đồng ý không, \"đối thủ\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Cá Voi Lãng Du Tinh Thiên, hãy Nuốt chửng tất cả!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Hãy cảm thấy vinh hạnh vì được làm đối thủ của ta!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Hãy để tinh hải, chứng kiến hủy diệt!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Chưa đủ, vẫn còn xa mới đủ…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Hừ."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hừ."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Ta không quan tâm đến sự tan biến của mọi thứ, nhưng ta sẽ không cho phép nó trở thành chướng ngại vật trên con đường ta theo đuổi sức mạnh."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Chỉ vì sự diệt vong tất yếu sẽ đến mà bắt đầu nghi ngờ ý nghĩa của mọi sự tồn tại… Ta không có hứng thú tham gia vào cuộc tranh luận nhàm chán kiểu trẻ con này. Không cần quan tâm đến hủy diệt, cũng không cần ghi nhớ. Bản thân sức mạnh, chính là ý nghĩa."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Tan chảy · Đóa"
  },
  Voice_146168_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Tan Chảy · Đóa\""
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Trong Đôi Mắt của bạn, ta thấy một ý chí không thuộc về nơi này. Nó không thuần khiết, nhưng đủ kiên cường. Hãy đến đây, chứng minh cho ta thấy, bạn đang dựa vào Sức mạnh và khát vọng nào mà đứng trước mặt ta."
  },
  Voice_146169_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Hãy cảm thấy vinh hạnh vì được làm đối thủ của ta!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Hơi thở của Hỗn Mang, lâu lắm rồi mới gặp lại… Kể từ khoảnh khắc ta được sinh ra từ Hư vô này, thứ ta theo đuổi, chưa bao giờ thay đổi."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_146172_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Muốn thách thức ta? Ta trân trọng sự dũng cảm của bạn, và cũng sẵn lòng ban cho bạn vinh dự được thua trận. Đây là sự tôn trọng của ta dành cho \"Người Giữ Gìn Misaque\"."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_146173_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Một không tưởng giả tạo, chật ních những kẻ yếu đuối, hèn nhát và tự lừa dối bản thân. Nhưng không sao, nơi đây có thể mang đến cho ta những kẻ thù hưng phấn nhất, thế là đủ rồi."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Rõ ràng sở hữu sức mạnh hùng hậu, thế mà vì sợ hãi, tội lỗi và mệt mỏi, lại giam cầm tài năng của mình trong giấc mơ dài dằng dặc bên trong, thật lãng phí."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về tulô"
  },
  Voice_146175_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Không đáng một đòn."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Phong ấn đã Thông ra đôi chút… Sức mạnh từ sâu thẳm tinh hải đang trào dâng. Ta đã lâu lắm rồi không cảm nhận được cảm giác này…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_146177_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Cá Voi Lãng Du Tinh Thiên, hãy Nuốt chửng tất cả!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Thỏa mãn."
  },
  Voice_146179_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_146180_AwakerVoiceContent = {
    Text = "Ta đã lang thang giữa biển sao vô số năm, tự tay đẩy những kẻ tự xưng mạnh mẽ xuống vực thẳm. Bạn có điểm đặc biệt của riêng mình, nhưng nếu muốn sánh vai cùng ta, trước tiên hãy học cách ngẩng đầu trước mặt ta. Kẻ đồng hành hèn nhát, ta không cần."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_146180_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Dũng cảm, hèn nhát, kiên cường, mong manh… Hừ, không, ta không quan tâm đối thủ là người như thế nào. Dù là kiểu người nào, chỉ cần là một đối thủ có thực lực, là đủ để ta cảm thấy vui vẻ."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Yếu đuối. Trên đời này có vô số thứ đáng ghê tởm, nhưng yếu đuối mới là tội lỗi nguyên thủy đáng khinh nhất. Mỗi người đều mang theo kiếm đến với thế giới này, không ai có quyền buông tay trước khi đến đích, bước lên chiến trường định mệnh với tâm niệm thất bại. Đó là sự xúc phạm đối với đối thủ, cũng là sự xúc phạm đối với chính mình."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Tinh Hài đã mục ruỗng, hãy Tỉnh giấc —"
  },
  Voice_146183_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_146184_AwakerVoiceContent = {
    Text = "Hừ… Một đối thủ thú vị. Lần sau, ta sẽ không còn nương tay nữa."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Xương cốt ta đang rung động vì hân hoan… Những nỗ lực bạn đã bỏ ra, ta đã thấy tất cả. Đây là bằng chứng cho thấy bạn xứng đáng đứng bên cạnh ta, Người Giữ Gìn."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_146185_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Hừ… Bạn nhìn thấu rất rõ, Người Giữ Gìn. Xiềng xích của Sức mạnh, vốn dĩ là để bị đập tan!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_146186_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Ừm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Ừm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Ngay phía trước… Điểm cuối của sức mạnh mà ta đã theo đuổi cả đời… Người đã đi theo ta suốt chặng đường, dẫn dắt ta đến đây, chính là bạn. Ta rất mong chờ được cùng bạn chứng kiến ngày tận cùng đó!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_146189_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Có lẽ những lời trước đây của ta hơi quá bốc đồng… Tốc độ tăng trưởng của bạn, cùng với những sức mạnh tiềm ẩn trong người bạn, đều khiến ta bất ngờ đôi chút. Ta đã chứng kiến quá nhiều sinh lực bị sự diệt vong nuốt chửng theo năm tháng, nhưng bạn… quả thực khác thường. Ta rất muốn biết, bí mật của những sức mạnh trong người bạn, rốt cuộc đến từ đâu?"
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_146190_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Cổng địa ngục, hãy mở ra trước mặt ta!"
  },
  Voice_146192_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_146193_AwakerVoiceContent = {
    Text = "Ồ, ta đã thấy rồi… Điểm cuối của sức mạnh, chưa bao giờ tồn tại… Thử thách thực sự, giờ mới thực sự mở ra trước mắt ta! Chính bạn đã đưa ta đến đây, giúp ta nhìn thấy tất cả mọi thứ. Chẳng bao lâu nữa, ta sẽ mang đến trước mặt bạn một chiến binh hoàn hảo hơn. Hy vọng lúc đó, ta cũng có thể thấy một bạn hoàn hảo hơn, \"đối thủ\" của ta."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_146193_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Trò vặt."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "Sức mạnh đang sôi sục trong tủy xương!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Nuốt chửng tất cả!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Nhân từ, yếu đuối, mê muội… Đôi mắt bạn chứa đầy tạp chất. Một người không đủ thuần khiết, sẽ không bao giờ hiểu được sức mạnh là gì."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_146197_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Sức mạnh thực sự, chưa bao giờ liên quan đến trả thù hay bảo vệ. Sức mạnh Chỉ là sức mạnh, cái tôi kia chưa bao giờ \"thực sự\" hiểu được đạo lý này. Đó chính là căn nguyên khiến cô ấy không đủ mạnh mẽ."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về lơ-tan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lơ-tan\""
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Hãy nghe kỹ, ta chỉ nói một lần:\nTa, lơ-tan, xác nhận bạn là đối thủ xứng đáng để đợi.\nTrước khi bạn đạt đến đỉnh cao, ta sẽ là thanh kiếm đáng tin cậy nhất của bạn. Lời hứa và sự trung thành của ta không liên quan đến cảm xúc. Bạn là đối thủ mang lại cho ta nhiều niềm vui nhất, ta tuyệt đối sẽ không để bạn ngã xuống trên con đường."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_146199_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Hãy đến đây, giết ta, hoặc, bị ta giết chết."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Cổng địa ngục, hãy mở ra trước mặt ta!"
  },
  Voice_146201_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_146521_AwakerVoiceContent = {
    Text = "Nơi lưỡi xương chỉ đến, vạn vật tan vỡ!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Sức mạnh… vô tận không cùng!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_147493_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(một đoạn hát khàn khàn)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Khán giả, cần thêm nhiều khán giả……"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Cát…… sa mạc trắng…… nơi này rất nguy hiểm, nhanh lên, hãy rời khỏi đây cùng tôi."
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_147496_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Tôi còn nhớ bản đồ của ngôi nhà mới, đều màu sắc rực rỡ, rất đẹp. Đây là nơi chúng ta nên đến. Chúng ta có thể hát, chúng ta có thể có được hạnh phúc."
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_147498_AwakerVoiceContent = {Text = "À"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_147499_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hả…?"},
  Voice_147500_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_147501_AwakerVoiceContent = {
    Text = "Đó là……Tiếng của Tinh Không……"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Bạn lại đến đây à. Như trước kia, ngồi bên cạnh tôi và cùng nhau chờ đợi đi. Chờ đợi cái gì...? Chờ đợi, chính là chờ đợi mà."
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Buổi tổng duyệt hoàn hảo, tôi đã hoàn toàn sẵn sàng cho sân khấu rồi!"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_147503_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_147504_AwakerVoiceContent = {
    Text = "Hãy rơi xuống."
  },
  Voice_147504_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "Dâng tặng cho sự hoang tàn và cái chết."
  },
  Voice_147505_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_147506_AwakerVoiceContent = {
    Text = "Tôi không phải là kẻ điên, và cũng chưa bao giờ cảm thấy buồn bã. Xin đừng tin vào những tin đồn vô lý."
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Lạ thật, họ có vẻ rất sợ hãi trước giọng hát của tôi"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_147508_AwakerVoiceContent = {
    Text = "Suỵt……"
  },
  Voice_147508_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Thật là bộ trang phục biểu diễn đẹp, lấp lánh……"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_147509_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Vẻ đẹp từ ánh sao vẫn còn đây."
  },
  Voice_147511_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_147512_AwakerVoiceContent = {
    Text = "Hãy hát đi."
  },
  Voice_147512_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_147513_AwakerVoiceContent = {
    Text = "Đào tạo phát âm đúng…? Nhưng tôi rất hài lòng với giọng nói hiện tại của mình."
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_147513_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Có vẻ giọng nói đã thay đổi một chút……"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_147515_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Thế nào, giọng hát của tôi có hay không?"
  },
  Voice_147516_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_147517_AwakerVoiceContent = {
    Text = "Ngủ ngon nhé……"
  },
  Voice_147517_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_147519_AwakerVoiceContent = {
    Text = "Được rồi."
  },
  Voice_147519_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_147520_AwakerVoiceContent = {Text = "À"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Cảm ơn… Tôi có nên nói cảm ơn không?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_147522_AwakerVoiceContent = {Text = "Haiz……"},
  Voice_147522_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_147523_AwakerVoiceContent = {
    Text = "Hãy tỏa sáng thật rực rỡ!"
  },
  Voice_147523_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_147524_AwakerVoiceContent = {
    Text = "Cảm giác đã lâu không có……Cuối cùng cũng trở lại sân khấu. Cảm ơn bạn, Người Giữ Gìn."
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_147524_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Xin lỗi đã làm phiền… Bạn có thể giúp tôi xuống khỏi cây không? Tôi không nhớ tại sao mình lại leo lên đó, có lẽ là vì những đám mây trên đầu khiến tôi cảm thấy hơi hoài niệm…"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Dân tộc tôi chưa bao giờ rời bỏ tôi, họ chỉ đi đến những nơi xa lắm."
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về tộc nhân"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "Bạn có nghe thấy không?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Ồ."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Bạn luôn lảng vảng quanh tôi… Tôi hiểu rồi, bạn chắc hẳn là fan của tôi, đúng không?"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_147529_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "Lala lala~ gì vậy, đây có thảm họa hủy diệt không? À… thì tôi phải chải tóc cho đẹp, còn phải đi tìm chị ấy…"
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Suỵt… đừng nói chuyện, có kẻ xấu đến rồi. Họ muốn bắt tôi và chị gái, còn không cho chúng tôi lên tàu…"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Lời nhàn rỗi·liên quan đến an toàn"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_147532_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Khi tôi tỉnh dậy, hành tinh đang hủy diệt. Tôi thấy bầu trời đêm bong tróc từng mảng, thế giới trở thành một tấm vải bị gió lớn thổi vào, trước tiên là biến dạng, sau đó bị xé toạc, rồi tan vỡ."
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_147533_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Đây là poster chữ ký của tôi, ông Pickman đã vẽ cho tôi. Tôi trao tặng nó cho bạn."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Lời đùa · Về Phiệt"
  },
  Voice_147534_UnlockDesc = {
    Text = "Nhận thân thể được đánh thức \"Fiynt\"để mở khóa"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Ừm ừm? Tò mò lắm sao? Kho báu của giáo mẫu, không thể tùy tiện cho người ngoài xem đâu nhé. Nếu muốn biết bên trong chứa đầy những gì, chi bằng ngay bây giờ hãy gia nhập Giáo Phái Tiên Nữ đi, hí hí?"
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Ngươi không tin kết luận của Caraboo? Hu hu, quả nhiên khó qua mắt người ta… Thực ra ta là con ngoài giá thú của Bohemond VI công quốc @1, ẩn danh lưu lạc chốn nhân gian, vì để tránh sự truy đuổi của quân thù mới giả xưng là tiên nữ… Ta đã nói cho ngươi biết bí mật quan trọng nhất rồi, ngươi không thể không tin ta chứ?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_149668_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_149669_AwakerVoiceContent = {
    Text = "Đau quá đau~"
  },
  Voice_149669_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_149670_AwakerVoiceContent = {
    Text = "Ăn kẹo nhiều quá? Không không không, đây là bí quyết để giáo mẫu luôn giữ nụ cười đấy, không thể vì chuyện nhỏ như sâu răng mà dừng lại được chứ? ~~"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Nào, đến đứng bên ta đây. Sao? Mọi người cùng nhau chia tế phẩm ăn chung? … Thôi được, nếu đây là quy tắc của Misaque… thì ta… ta hoàn toàn không có ý kiến gì phản đối cả, nào, mọi người cùng vui vẻ nào!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_149671_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Ôi chà, thật là chú cừu non thành kính nhỉ."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Thêm một chút nữa, tiên nữ mới ban phước cho ngươi đấy?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Các ngươi còn non lắm~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Lễ thờ phụng lần này long trọng hơn mọi lần, số lượng tế phẩm cũng nhiều hơn… Ôi trời, tất nhiên không phải người làm tế vật rồi, ta là tiên nữ hiền lành, sẽ không làm hại ai đâu~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_149676_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Người giữ bí mật, ngài đã sẵn sàng nghe lời thật lòng của Caraboo chưa?\nCaraboo đến từ đâu, thực ra chẳng quan trọng gì cả. Điều quan trọng là, ngài là món quà quý giá nhất mà trời ban cho ta, Caraboo đã quyết định sẽ mãi mãi, mãi mãi ở bên cạnh vị quý nhân là ngài.\nNgài cho rằng đây cũng là một phần của trò lừa, để ngài không truy cứu nữa? Hí hí, ngài đoán xem?\nDù sao đi nữa, như phần thưởng cho việc nói ra lời thật lòng, ngài có thể cho Caraboo một viên kẹo dẻo vị táo không?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_149677_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hí hí~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Không sao, lần sau hãy tập trung bảo vệ tiên nữ, sẽ không thất bại nữa đâu~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Đừng hòng lừa ta!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Ôi chao, nhiều cống phẩm thế này… Khặc, hừ hừ, làm tốt lắm, xứng đáng được khen thưởng! Nào, tiên nữ ban cho ngươi một nụ hôn tiên nữ! Nghĩ gì vậy, tất nhiên là lên trán rồi!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_149683_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Cảm ơn sự cúng dường của các tín đồ! Giáo mẫu thấu hiểu lòng người sẽ cho tạc một bức tượng vàng ròng thờ ngài trong thần điện. Ôi chà, để bức tượng đó thể hiện được dáng vẻ lạnh lùng thanh tú của ngài, còn phải tìm kiếm thêm nhiều thứ nữa~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_149684_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Ngươi? … Ngươi là một thành viên chưa giác ngộ của giáo hội chúng ta, Caraboo sẽ kiên nhẫn chờ đến ngày ngươi nhận ra chân lý của thế giới. Đến lúc đó, nhớ dâng lên giáo chủ thân xác, lòng trung thành và tài sản của ngươi nhé, hí hí."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Những thứ trong danh sách… đã tập hợp đủ rồi sao? Tài lực của Misaque thật sâu không thể đo được… Biết vậy ta đã… hm hm? Ta đang lẩm bẩm gì vậy? Chỉ là đang cảm ơn sự hào phóng của Chúa tước Dexter thôi, hí hí~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_149686_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Thứ ghét nhất? Tất nhiên là những tên phù thủy không có tinh thần hợp đồng rồi. Có một bí mật nói nhỏ cho ngươi nghe, thực ra tất cả phù thủy đều là kẻ lừa đảo, mọi lời tiên tri và lời nguyền của chúng đều nhằm lừa ngươi thành kẻ trắng tay! Còn cách phòng tránh… chỉ cần để tiền của ngươi được hưởng phước lành của tiên nữ là xong!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Lần đầu gặp mặt, ta là nàng tiên xanh xao đến từ phương xa, có muốn tìm hiểu không? Phước lành của tiên nữ có cường độ khác nhau tùy theo mức hội phí đấy, hí hí~"
  },
  Voice_149688_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_149689_AwakerVoiceContent = {
    Text = "Trong các nghi lễ thờ phụng trước đây, ngoài quy trình bảy lần lễ bái và ba lần tuyên thệ, các tín đồ còn đặc biệt xây dựng thần điện mới và dâng lên những lễ vật phong phú cho ta. Đây là danh sách!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_149689_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Hãy đến đây, chôn vùi những thứ muốn từ bỏ vào trong tuyết sâu…"
  },
  Voice_149690_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_149691_AwakerVoiceContent = {
    Text = "Ta nghe nói ngươi đang tìm hiểu về xuất thân của ta, hí hí, đó là bí mật của giáo mẫu đấy. Tuy nhiên, nếu ngươi nhất quyết muốn điều tra, trong Giáo Phái Tiên Nữ có lưu giữ cuốn tiểu sử do chính ta chấp bút, chỉ cần nộp một trăm nghìn bạc tâm là có thể đọc được, muốn thử không?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_149691_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Tốt lắm, ở đây có rất nhiều đứa trẻ đáng yêu và khoản trợ cấp sinh hoạt hào phóng đến mức kinh ngạc. Có họ, sớm muộn gì ta cũng tích đủ tiền lộ phí để đến phương Đông…"
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Nhớ tôn thờ giáo mẫu nhé, hí hí."
  },
  Voice_149693_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_149694_AwakerVoiceContent = {
    Text = "Xin lỗi nhé, lãnh địa của tiên nữ rất thiêng liêng, không tiếp đón người sói kỳ lạ… Cái gì không khí có mùi nói dối, chắc là mũi cậu ta bị trục trặc thôi?"
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Trò chuyện: Về Lắc"
  },
  Voice_149694_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lắc\""
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Ơ, có người nói ta là tiên nữ giả… bị lật tẩy rồi, hí hí. Ta biết ngươi sẽ không để ý đâu, đúng không?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về tin đồn"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Ừm, ngon quá~"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_149697_AwakerVoiceContent = {
    Text = "Hãy yên tâm~"
  },
  Voice_149697_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Những chú cừu lạc lối, tiên nữ đây đến rửa sạch tội lỗi cho các ngươi, hí~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Vẫn chưa bỏ cuộc sao? Thôi được, để Caraboo tự nói cho ngươi nghe vậy. Thực ra Caraboo là con gái của nữ thần Umapati, vị thần cai quản ngọn núi tuyết chọc trời ở phương Đông… Ừm, ngươi nói vị nữ thần đó chỉ có hai con trai không có con gái? Những ghi chép về thần linh luôn có chỗ thiếu sót mà."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_149699_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Xeng xeng~ Ánh hào quang của tiên nữ đã chiếu rọi lên ngươi rồi, xông lên thôi!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Thôi thôi đừng điều tra nữa, được không nào? Để bù đắp cho việc ngoan ngoãn dừng hành động xúc phạm này lại, ta có thể lén chia cho ngươi một nửa số kẹo quý giá nhất đấy. Phải biết rằng, trên chiến trường của đội quân Đông chinh, kẹo ngọt là thứ hiếm có lắm đó."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_149701_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "Phước lành của Caraboo có thể chữa lành mọi bệnh tật trên đời, tất nhiên cũng có thể chữa được loại dịch bệnh đen tối này… Tất nhiên là thật rồi, chỉ cần ngươi đủ thành tâm, đủ tin tưởng vào Caraboo là được, hí hí."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_149703_AwakerVoiceContent = {
    Text = "Ghét quá!"
  },
  Voice_149703_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Hào quang của tiên nữ~"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Bảy lần lễ bái, ba lần tuyên thệ, hãy dùng chúng để đổi lấy sự tha thứ của tiên nữ!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_150079_AwakerVoiceContent = {
    Text = "Hãy cảm nhận đi!"
  },
  Voice_150079_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Ơ, sao Orci lại cho ngài vào được? Chẳng phải đã nói chặn tất cả mọi người lại sao? Ngài là chủ nhân của cậu ta… ? Đứa trẻ không đáng tin cậy thật phiền phức, vì buổi tụ hội lần này ta đã bỏ ra không ít công sức chuẩn bị đấy. Hay là… chia đôi số cúng phẩm nhận được, ngài mở lượng khoan hồng cho ta nhé?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Orci"
  },
  Voice_150104_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Orci\""
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Hãy kết thúc nhanh đi, đừng nán lại trên đường phố."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Anh ta đã gia nhập giáo đoàn trong thời gian tôi đang ngủ say, tôi và anh ta không có nhiều giao lưu. \nTuy nhiên, nghe nói anh ta tự tìm đến. Muốn từ bỏ hình dạng con người, trở thành \"người dấn thân vào biển\" hoàn toàn... hừ, lại thêm một kẻ bị sức mạnh làm mờ mắt."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Kẻ khắc sét"
  },
  Voice_36679_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath chưa bao giờ là một chó con trung thành, thật khó hiểu tại sao Miriam lại coi trọng anh ta như vậy… Nếu không bị xích, người đầu tiên chạy thoát sẽ là anh ta."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Goliath"
  },
  Voice_36680_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Người dấn thân vào biển không phải sinh ra đã như vậy. Để che giấu trong đám đông, nửa đời trước của họ không khác gì con người...\nBạn hãy cẩn thận một chút, biết đâu chủ tiệm bánh yêu thích của bạn cũng là một thành viên của họ đấy?"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Hoài niệm · Về người dấn thân vào biển"
  },
  Voice_36681_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Bài hát thuyền lạc điệu của Hilaster, món cá hầm thịt hun khói khoái khẩu của thuyền trưởng, chiếc chăn bị gió biển làm cho vừa tanh vừa cứng… Dù nguy hiểm và căng thẳng, nhưng những tháng ngày lưu vong trên biển cùng họ, tôi sẽ không bao giờ quên."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về \"Con tàu ma\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Mặc dù mọi người ở trường đều có vẻ rất bận rộn, nhưng…\nNhưng ở đây, có một cảm giác yên bình mà tôi chưa từng trải qua trước đây.\nCảm giác mọi người tụ tập lại vì mục tiêu chung và cùng nhau nỗ lực… hừm, cũng khá tốt đấy."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Đại học Misaque · II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Giường quá cứng, thời tiết quá lạnh, trà chiều thường được pha như nước rửa cỏ... Bản tiểu thư có cả ngàn lý do không thích nơi này. \nTuy nhiên, chỉ vì \"có anh ở đây\", tôi cũng có thể miễn cưỡng ở lại..."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Người Giữ Gìn · III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Cảm ơn, cảm ơn… Hả? Tại sao phải cảm ơn cậu? Điều này… không cần phải nói chứ! Tất nhiên là vì mọi thứ cậu đã làm cho tôi trên biển… \nKhoan đã, sao cậu lại cười? Cậu rõ ràng muốn xem ta lúng túng đúng không!"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Người Giữ Bí Mật · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Tôi từng nghĩ, giữa tôi và cô ấy có tình cảm gia đình……\nNhưng sau khi mọi chuyện xảy ra, tôi mới nhận ra, có lẽ, những chút ấm áp thoáng qua ấy từ đầu đã chỉ là sự tự nguyện một phía của tôi. \nViệc đối xử với cô ấy là chuyện của các người. Chỉ cần đừng để cô ấy đến gần tôi nữa. Như vậy là đủ rồi."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Lời nói phi chính thức · Về Miriam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Thật kỳ lạ… Cảm giác này thật kỳ lạ. \nTrái tim rõ ràng đã ngừng đập, nhưng cơ thể vẫn còn ấm… Này, cậu lại đây sờ tay tôi đi, bảo tôi rằng đây không phải là ảo giác."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về \"thân thể được đánh thức\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 6 để mở khóa"
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Có thể tôi không sinh ra ở Vương quốc Leo, nhưng Đền Thánh chính là nơi tôi nhận được sức sống thứ hai. Như vậy, coi đây là quê hương của mình thì có gì không thể?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về quê hương"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Sau nhiều năm bị đại dịch vô hình hoành hành, cuối cùng Cha Trời đã nghe thấy lời cầu nguyện của ta và ban xuống \"phước lành\" này để chống lại đau khổ. Nó thực sự có thể ban tặng sinh lực, nhưng cũng đòi hỏi cái giá phải trả. \n Là người được chọn, ta đương nhiên nên gánh vác thay cho những ai nhận được ân huệ."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Lời rỗi·về \"phước lành\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Đối với tôi, trạng thái thân thể được đánh thức là ân huệ mà Cha Thiêng Liêng ban cho linh hồn trong vòng tay. Đây là sức sống thứ hai, cũng là cơ hội để bù đắp những tiếc nuối trong quá khứ. \nTôi sẽ noi theo ý Cha Thiêng Liêng, thực hiện trách nhiệm của người đại diện, loại bỏ nhiều hơn nữa nỗi khổ đau."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về \"thân thể được đánh thức\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Xin hãy để tôi một lần nữa bày tỏ lòng biết ơn với bạn, Người Giữ Gìn. Bạn đã tôn trọng ý kiến của tôi và giữ kín thông tin cho hội nghị thẩm tra. Nếu họ can thiệp, e rằng họ sẽ không cho phép tôi tiếp tục phục vụ khu đền thánh."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Người Giữ Gìn · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Mở khóa sau khi hoàn thành Hồ sơ Đặc phái \"Màu của máu\""
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Đứa trẻ đó chân thành, kiên định và tốt bụng, có một linh hồn sáng rực rất hiếm có. Lần cuối tôi gặp một người như thế này, đó đã là từ kiếp trước của tôi rồi."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Chuyện trò·về Orci"
  },
  Voice_45157_UnlockDesc = {
    Text = "Mở khóa sau khi hoàn thành Hồ sơ Đặc phái \"Màu của máu\""
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Mất đi thị giác không có nghĩa là tôi trở nên mù lòa. Cha thần linh đã khiến bóng tối đến với tôi, nhưng cũng giúp tôi có thể nhìn thấy ánh sáng mỏng manh của linh hồn."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về thị giác"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "Lúc đó, dù đã nhận được \"phước lành\", tôi vẫn chỉ là một người bình thường. Có quá nhiều người phải chịu khổ, quá nhiều người cần \"phước lành\". Tôi muốn cứu tất cả họ, nhưng không thành công. \nĐây là điều tiếc nuối lớn nhất của tôi, cũng là nỗi áy náy vĩnh cửu của tôi."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Lần đầu tiên được sống"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Nhiều người trong Giáo Đình cho rằng, \"ngọn lửa trắng\" được đề cập trong《kinh điển》chính là ánh trăng: vị sứ giả xanh xao sẽ xuất hiện từ ánh trăng, dẫn dắt chúng ta thoát khỏi khổ nạn. \nNhưng tôi biết, ngọn lửa thật sự là linh hồn đang cháy trong lòng bạn và tôi."
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Chuyện trò · Liên quan đến \"lửa nhợt nhạt\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "Thực ra, việc giấu thân phận của tôi là ý của Đại Giáo Chủ. Ngài không nói rõ lý do, chỉ căn dặn tôi rằng: nơi thuần khiết nhất cũng có thể tồn tại bóng tối, làm việc thiện cũng cần phải cẩn thận.\nTất nhiên, đối với bạn, tôi hoàn toàn tin tưởng."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về việc giấu danh tính"
  },
  Voice_45161_UnlockDesc = {
    Text = "Mở khóa sau khi hoàn thành Hồ sơ Đặc phái \"Màu của máu\""
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Giọng hát của tôi, có trở thành sự hỗ trợ của ngài không?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Khỉ thật, rõ ràng hắn cũng chỉ là một đứa trẻ, sao mọi người lại tôn trọng hắn như vậy! Hãy đối xử với tiểu thư đây bằng thái độ tương tự, hiểu chưa!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về tulô"
  },
  Voice_4909_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Ê, bạn có biết những thân thể được đánh thức khác thường làm gì không? Đừng hiểu lầm, tôi không muốn kết bạn, chỉ là muốn… đúng vậy, tôi chỉ muốn kiểm tra một chút thôi!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về cuộc sống hàng ngày"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Khốn kiếp khốn kiếp khốn kiếp! Lần sau nhất định phải ném xác họ cho nhện ăn!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Dư âm."},
  Voice_4912_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_4913_AwakerVoiceContent = {
    Text = "Nhịp điệu."
  },
  Voice_4913_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Thử nghiệm táo bạo."
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Không cần vội vàng như vậy… Có gì tôi có thể giúp bạn không…"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Quá táo bạo!"
  },
  Voice_4916_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_4917_AwakerVoiceContent = {
    Text = "(chất vấn với sự hứng thú)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "Tự nhiên đã ban cho tôi điều vô thượng tôn vinh. Bạn thấy điều này rất không giống tôi?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_4919_AwakerVoiceContent = {Text = "Làm gì?"},
  Voice_4919_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Tôi làm khá tốt phải không? Vậy thì, thù lao. —— Sao nào, trên đời này đâu có bữa trưa miễn phí!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Đi đi!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_4922_AwakerVoiceContent = {
    Text = "Cẩn thận!"
  },
  Voice_4922_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Thật là một chiến thắng tuyệt vời… Tôi sẽ ghi nhớ khoảnh khắc này mãi mãi."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Cảm nhận được nguồn không tinh khiết... lại gần thêm một bước với bản thể... Ôi trời ơi! Hãy để ta xé toạc thế giới này!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_4924_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Chúng tôi... đã sẵn sàng. Xin vui lòng ra lệnh, Thủ Bí Nhân."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_4925_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Thưa ngài, ông thật là người tốt. Tiếc thay tôi không có gì để báo đáp ông, tôi chỉ là một kẻ chẳng có ích gì..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_4926_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "... Nữa bước nữa, có thể tách rời hoàn toàn khỏi \"họ(chỉ nữ giới)\" rồi sao?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_4927_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Ể, tôi vẫn còn sống...... Ngài, thật sự sẽ không lấy trộm nội tạng của tôi, bắt tôi đi làm thí nghiệm chứ?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_4928_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Dân tộc bản địa của Wenkel có khả năng xâm nhập vào não bộ sinh vật, ý chí ngoại lai kết hợp với tôi vì vậy mà rất e ngại cô ấy. Tuy nhiên, hiện giờ cô ấy cũng chỉ là một linh hồn đáng thương bị nhốt trong thân xác mà thôi."
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Wenkel"
  },
  Voice_4929_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Tất cả mọi thứ, Ai Jī Sī đều rất thích. Khi mọi người tụ tập quanh bàn ăn để cầu nguyện cũng vậy; khi Người Giữ Gìn ra ngoài làm nhiệm vụ, tất cả mọi người chờ đón ngài trở về chiến thắng cũng vậy… Không khí luôn tràn ngập hương vị hạnh phúc… Liệu tôi như thế này có thật sự xứng đáng tận hưởng những điều tốt đẹp ấy không?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Chìm đi."},
  Voice_4931_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_4932_AwakerVoiceContent = {
    Text = "Hãy nở rộ."
  },
  Voice_4932_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_4933_AwakerVoiceContent = {
    Text = "\"tin tưởng\",\"tuân phục\",\"nô lệ\",\"tình yêu\",\"kính trọng\"... mô đun ngôn ngữ đang được tái tạo và học tập, rất mong Người Giữ Gìn chỉ giáo nhiều hơn."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_4933_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erika hiện đang ở trạng thái chờ, cơ thể sẽ hoàn thành làm mát sau một giờ mười lăm phút, <Del:muốn khởi động thì hãy đổi chỗ bằng trái tim của bạn> có muốn khởi động khẩn cấp không?……đang xác thực quyền hạn……quyền hạn cao nhất của Người Giữ Gìn đã được xác thực xong. Xin chào, Người Giữ Gìn."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_4934_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "Nhiệm vụ điều tra có chỉ số nguy hiểm trung bình là 7, lượng thuốc bổ sung luyện kim tiêu tốn trung bình là 8 chai, thời gian xử lý xác chết trung bình là 10 giờ. \nKết luận: Công việc của Người Giữ Gìn rất nguy hiểm, hãy chú ý an toàn trong quá trình hành động."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_4935_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Đang truy vấn hồ sơ giáo viên: Erika Riefel, giảng viên chuyên ngành Cơ khí và Tự động hóa bạc tâm, đã qua đời — Bạn không muốn kiểm tra cái này sao? Được, đang thực hiện tìm kiếm lại từ khóa \"Erika\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_4936_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Nếu cần tra cứu tài liệu, vui lòng cung cấp tên tệp, chức năng tìm kiếm mờ hiện tạm thời không khả dụng."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_4937_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_4938_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_4938_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_4939_AwakerVoiceContent = {Text = "À"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_4940_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_4940_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_4941_AwakerVoiceContent = {Text = "À"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Sạc đầy, chuẩn bị nổ phá."
  },
  Voice_4942_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_4943_AwakerVoiceContent = {
    Text = "Sạc đầy, chuẩn bị nổ phá."
  },
  Voice_4943_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_4944_AwakerVoiceContent = {
    Text = "Loại chuyện vặt vãnh này, sau này đừng đến quấy rầy thời gian nghỉ ngơi của hoàng nữ nữa."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Tôi sẽ bảo vệ bạn như cách tôi bảo vệ \"tinkerer\"."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Tôi không phải là người quan trọng, chỉ là một giọt nhỏ bé trong số đông tín đồ…… Chỉ cần có thể phụng sự vị đại nhân ấy, lọt vào tầm mắt của ngài, tôi nguyện dâng hiến tất cả tâm hồn và sinh lực của mình……"
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Lời rỗi·về quá khứ"
  },
  Voice_4946_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "Nhìn tôi!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "Nhìn tôi!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "…thôi, miễn là không có kẻ cuồng tín quấy rầy ta, sống chung một phòng với họ cũng chẳng sao."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Hoài niệm · Về người dấn thân vào biển"
  },
  Voice_4949_UnlockDesc = {
    Text = "Sau khi nhận được một trong các thân thể được đánh thức \"Miriam\"\"Goliath\"\"Kẻ khắc sét\"\"Sơn\"\"Pháp Luân Tư\", tính năng sẽ được mở khóa"
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Tôi ghét cảm giác màu đen đó, như thể lòng mình bị moi trống rỗng, cảm giác không được thỏa mãn khiến ngứa ngáy khắp cả người…"
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Đừng, đừng, đừng nhắc đến..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_4954_AwakerVoiceContent = {Text = "Ừm!"},
  Voice_4954_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "Những nhà sử học cho rằng thần quốc đã sụp đổ, nói năng khoác lác đến mức khiến người ta khó chịu… nhưng không sao, ngôn từ sẽ không trở thành trở ngại cho sự huy hoàng tái sinh của thần quốc."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Thực ra… nói nhỏ với bạn, tôi cảm thấy không hài lòng với chiếc xe máy hiện tại của mình —— không phải là tôi không thích nó! Chỉ là, tôi luôn có cảm giác như nó thiếu điều gì đó…"
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_4958_AwakerVoiceContent = {
    Text = "Cắt nhỏ!"
  },
  Voice_4958_AwakerVoiceTitle = {
    Text = "Kỹ năng·2·cuồng loạn"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Xin lỗi... Tôi không muốn như thế này.."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Kỹ năng·2·u uất"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(thốt lên đầy hứng thú)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "@1@2 năm, ông Hoa Đức·Phi Lí Phách, Kheralkes và Tà Vy đã cùng nhau thành lập Trường học Misaque. Sau một quá trình phát triển dài, cuối cùng đã hình thành <Del:ngục tù đáng nguyền rủa này> Đại học Misag."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Công lý, trung thành, kiên cường, kỷ luật. Những điều này đã sớm khắc sâu trong lòng tôi."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Tôi sẽ hoàn thành tốt công việc ngài giao phó."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Rốt cuộc là những bậc cha mẹ thiếu trách nhiệm ra sao mới đặt tên con gái mình là khiên của yêu nữ? Ý bạn là cô bé mồ côi sao? Ừm… chuyện này không cần cho cô ấy biết."
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Ai Jī Sī"
  },
  Voice_4964_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Ai Jī Sī\", sẽ mở khóa"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "If you're bored, why not come to the maze and \"keep me company\"? Anyway, your hopeless life and this endless maze are no different!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về mê cung"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Khi đóa ở đó, hiệu suất của các điều tra viên tăng lên 78.312%, tương ứng cũng có nhiều người hơn rơi vào trạng thái tâm trạng thấp. Trích một câu của cô ấy: Nếu một số người có thể nói năng cẩn thận, thế giới sẽ vận hành trơn tru hơn."
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chuyện trò · về đóa"
  },
  Voice_4966_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"đóa\""
  },
  Voice_4967_AwakerVoiceContent = {
    Text = "Đến đi!"
  },
  Voice_4967_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_4968_AwakerVoiceContent = {Text = "?"},
  Voice_4968_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Làm sao có người không thích mạo hiểm được chứ? Thâm nhập vào những vùng lãnh thổ huyền bí mà chưa ai đặt chân đến, khám phá điều chưa biết, dệt nên câu chuyện của riêng mình… Quả là kích thích!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về cuộc phiêu lưu"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Quý an, tôi là Ninh Phi Nga đến từ Fèi Fúer. Quý vị đã mang đến cho tôi thân thể có thể tự do hô hấp này… Tôi nên làm gì để báo đáp quý vị đây?"
  },
  Voice_4970_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_4971_AwakerVoiceContent = {
    Text = "Vừa rồi tôi lại nghe thấy những tiếng rên rỉ của những kẻ tự xưng là chủ nhân của tôi —— thật tuyệt vời."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_4971_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Có thể không ăn rau không? Mặc dù Tinkert đã nói rằng không được kén ăn, nhưng tôi không thích màu sắc của chúng…"
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Thần sáng tạo có lời: Khổ đau không phải là sáng tạo của ta. Hãy gánh vác và hóa giải nó, hỡi đại diện của ta, hãy xây dựng một quốc gia không khổ đau trên mặt đất. Vì điều đó, ta nguyện dâng hiến tất cả. Kể cả sinh mệnh của mình."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_4973_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Trước lời nguyền hủy diệt mọi thứ, tất cả những đau khổ khác đều nhạt nhòa. Dù không thể gánh chịu lời nguyền thay người khác, tôi vẫn sẽ làm hết sức để giảm bớt thương tổn cho họ."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_4974_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Bây giờ, liệu tôi có đủ sức để giảm bớt nỗi khổ của họ, an ủi linh hồn của họ không?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_4975_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "Như vậy, tôi có thể gánh vác mọi đau khổ của vạn vật, mở đường cho tất cả sinh linh tiến đến miền đất không có khổ nạn."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_4976_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Lòng ấm áp từ sâu thẳm linh hồn này… Xin cảm tạ ngài vì món quà quý giá, lửa nhợt nhạt. Với lực lượng này, có lẽ tôi cuối cùng cũng có thể hoàn thành sứ mệnh của kẻ thay thế, cứu giúp thêm nhiều người."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_4977_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Tôi thật sự có thể ăn nhiều như vậy sao?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_4978_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hừm hừm……đó không phải là cái chết, đó chỉ là tương lai của bạn, tương lai của tôi, tương lai của thế giới này."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinkerer… Nghe thấy tiếng hát ai oán của cô ấy, sẽ không kiềm được mà muốn nhảy múa…"
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chuyện trò·về tinkerer"
  },
  Voice_4980_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"tinkerer\""
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Rèn luyện bình thường cũng có thể khơi dậy giá trị của dòng máu ư? Điều này thật bất ngờ đối với tôi."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "Vũ khí trở nên thuận tay."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Đừng nghĩ rằng như vậy tôi sẽ biết ơn bạn, điều này không được phép trong chủng tộc của tôi."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_4984_AwakerVoiceContent = {Text = "À hem!"},
  Voice_4984_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_4985_AwakerVoiceContent = {
    Text = "Người đàn ông đó… Này, chờ tôi một chút, cuộc đấu của chúng ta chưa kết thúc phải không?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về những người khác"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Tôi rất thích máy ghi âm của học viện, nếu có thể cải tạo thành phiên bản cầm tay, nhắc nhở tôi thực thời về những thứ tôi quên thì thật tuyệt vời…"
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Đầy rẫy sâu bọ…… không, thậm chí còn không bằng sâu bọ, chỉ là mẩu bánh vụn, cung cấp chất dinh dưỡng cho Sự ra đời của Người."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Vật tư đã đến nơi."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Vật tư đã đến nơi."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Ừm...... dùng sức, dùng sức hơn chút. Đúng rồi, giống như vậy......"
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Chưa hoàn toàn thức tỉnh, đã giành chiến thắng một cách dễ dàng."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Ôi, mũ lệch rồi… ừ, như thế này có được không? tuyệt vời!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_4992_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Có được khả năng như vậy, tôi thực sự còn là con người sao?\" Kể từ khi bắt đầu huấn luyện chiến đấu, tôi đã tự hỏi bản thân mỗi ngày. Tôi yêu thế giới này, dù nó có thể xám xịt, ô uế và tẻ nhạt, nhưng sự tồn tại của các bạn khiến nó lấp lánh như viên kim cương giữa đống bụi bẩn. \nTôi từng rất sợ rằng, cùng với sự gia tăng của lực lượng, lập trường của tôi như một con người sẽ thay đổi... Giờ đây, tôi cảm thấy may mắn vì có bạn bên cạnh, sự ăn ý giữa chúng ta đã ràng buộc tôi chặt chẽ với thế giới loài người. Trong những ngày sắp tới, cũng mong bạn tiếp tục giúp đỡ tôi, Người Giữ Gìn."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_4993_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ôi… Việc bạn có những lo lắng cũng là điều hiển nhiên, là do tôi đã không suy xét kỹ lưỡng. Với tư cách là đồng đội, lẽ ra ngay từ đầu tôi nên giải thích rõ ràng với bạn. Như bạn đã thấy, trên người tôi quả thực có những điểm khác biệt so với người thường, điều này có lẽ liên quan đến thân thế của tôi. Nói không tò mò thì quả thật khó tin đúng không? Nhưng việc có một nơi dung thân như Học viện chính là may mắn của tôi, vì vậy, tôi chọn cách không vén bức màn số phận."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_4994_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "Bạn đã gặp người phụ nữ đó rồi phải không? Chính là thân thể được đánh thức khoác tấm voan trắng, cô ấy là một trong những nền tảng khi trường đại học này được thành lập……\nNhưng nói thật, tôi không thích cô ấy. Cái thái độ coi thường tất cả, dường như không quan tâm đến toàn thế giới thực sự khiến người ta tức giận……À, bạn nói cảm thấy tôi và cô ấy trông giống nhau sao? Để tôi đi cùng bạn đến bệnh viện trường kiểm tra thị lực nhé?"
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_4995_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Bạn đang tò mò về mối quan hệ giữa tôi và giáo sư? Không có gì bí mật, kể cho bạn cũng không sao. Giáo sư Dexter là cha nuôi của tôi, còn mẹ nuôi… Tôi lớn lên trong trường học và được các thầy cô chăm sóc như người nhà, tuy nhiên, tôi gần gũi với đóa hơn."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_4996_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Dù là thủ tục của Văn phòng thân thể được đánh thức hay ngày cung cấp món ăn Ấn Độ tại căng-tin, tôi đều có thể trả lời mọi vấn đề của Học viện cho bạn——đừng lo lắng về việc làm phiền tôi, tôi có vẻ khó gần đến vậy sao?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_4997_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Ôi gương thần kia, ai là người phù thủy giỏi nhất thế giới? Tôi? Đúng rồi!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_4998_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Khá tốt."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Thật tốt～"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5001_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5001_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Thành công… chưa? Tôi có giúp được gì cho bạn không?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5003_AwakerVoiceContent = {
    Text = "Không có ích gì!"
  },
  Voice_5003_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5004_AwakerVoiceContent = {
    Text = "(nhẫn nại)"
  },
  Voice_5004_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Nhìn đây!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Hãy biến nơi đây thành đại dương sôi động của mọi người!"
  },
  Voice_5006_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5007_AwakerVoiceContent = {
    Text = "Cần có sự bảo vệ cùng đi không? Nếu mục đích của bạn là vì chân lý, tôi sẽ giúp bạn."
  },
  Voice_5007_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5008_AwakerVoiceContent = {
    Text = "Không thể đốt cháy."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Không thể đốt cháy."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Bạn muốn một cái ôm phải không?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Hãy nhìn những xiềng xích trên người tôi——chúng không phải là trang sức, mà là lời nhắc nhở. Nhắc nhở tôi không bao giờ quên cảm giác bị bội phản và bị dẫm đạp."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Nếu muốn biết về quá khứ của học viện, tôi khuyên bạn nên đi đến thư viện để lục tìm tài liệu. \nLàm ơn, kể cả tiền thân của học viện, đó là một lịch sử kéo dài 300 năm! Bạn không thật sự muốn tôi kể lại từng năm chứ?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Đây là đang khiêu khích tôi sao? Bất cứ lúc nào cũng sẵn sàng!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Biển sâu sẽ ban cho bạn giấc ngủ vĩnh hằng."
  },
  Voice_5014_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5015_AwakerVoiceContent = {
    Text = "Biển sâu sẽ ban cho bạn giấc ngủ vĩnh hằng."
  },
  Voice_5015_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5016_AwakerVoiceContent = {
    Text = "Hãy chìm đắm đi,hãy bùng cháy đi!Vũ điệu báo tử!"
  },
  Voice_5016_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5017_AwakerVoiceContent = {
    Text = "Ở đây, tôi dâng lên Vũ điệu báo tử của ngọn lửa xanh vĩnh cửu!"
  },
  Voice_5017_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5018_AwakerVoiceContent = {
    Text = "Cô gái ấy như một ngọn hải đăng…… Trong chuyến hành trình vĩnh dạ, nếu có thể nhìn thấy ánh sáng rực rỡ của cô ấy, có lẽ tôi đã không lạc lối……"
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Pháp Luân Tư"
  },
  Voice_5018_UnlockDesc = {
    Text = "Giải khóa sau khi nhận được thân thể được đánh thức \"Pháp Luân Tư\""
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Bạn tốt nhất nên thể hiện được giá trị xứng đáng để tôi rời khỏi phòng thí nghiệm, tân thủ lĩnh bí mật."
  },
  Voice_5019_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5020_AwakerVoiceContent = {
    Text = "Tôi là chủ nhân, còn ngươi là người hầu. Tôi muốn gì, ngươi phải đưa ngay. Sao nào, ngươi này người hầu còn đòi phần thưởng sao? Thôi được rồi, ta sẽ cho ngươi!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5021_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5021_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Đã đến lúc gọt sạch những vết nhơ này!"
  },
  Voice_5022_AwakerVoiceTitle = {Text = "Nộ"},
  Voice_5023_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5023_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5024_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5024_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Dâng hiến chính là nhận được."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Dâng hiến chính là nhận được."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Sẽ bị thương!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Đừng đến đây!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Tôi thích ánh trăng vàng vào đêm trăng tròn. Bí ẩn, dịu dàng, khi gió thổi tới, mặt biển lấp lánh ánh vàng như những đốm sáng mộng mơ, lãng mạn."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Nếu quê hương của chúng tôi không bị rỗng rỗng, tôi và tinkerer đã không phải xa cách… Tôi ghét rỗng rỗng, còn hơn cả ghét cay đắng."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Phía trước là kho báu hay cảng, đối với tôi không có gì khác biệt. Sứ mệnh của tôi là đảm bảo ngài về đích bình an."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5031_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Hãy theo dấu vết của chim thiên đường, đích đến đang ở phía trước màu xanh lam."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5032_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Tôi thường hay ngắm nhìn đường chân trời, tưởng tượng về khung cảnh bên kia đường chân trời. Đó là vùng đất xa xôi, càng gần lại càng khó chạm tới. Nếu có một ngày như thế, bạn hãy cùng tôi đi xem nhé."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5033_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Nhận được sự yêu quý của ngài, giờ đây, dù là biển dữ, tôi cũng có lòng can đảm mang đến cho ngài những lời chúc phúc không hối tiếc."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5034_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Dường như nghe tiếng hát của các thủy thủ, mùi vị quen thuộc của quê hương."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5035_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Anh đến để cứu tôi, phải không? Từ thế giới thối rữa, từ sự căm thù ngấm sâu vào tâm trí, từ ngọn lửa xanh vĩnh cửu…"
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Kẻ vô lễ!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Tôi xem đây như là tham gia vào cam kết trung thành của ngài."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5038_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Nếm thử bài học này đi!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5040_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5040_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5041_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5041_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5042_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5042_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Cảm nhận sức mạnh của loài chuột này đi!"
  },
  Voice_5044_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5045_AwakerVoiceContent = {
    Text = "Cảm nhận sức mạnh của loài chuột này đi!"
  },
  Voice_5045_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5046_AwakerVoiceContent = {
    Text = "Xúc xắc đã được ném. Vậy thì, hãy kết thúc nhanh chóng!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Xin cảm ơn ngài vì đã cho đôi chân từng bị máu đen làm nhơ nhuốc này một cơ hội trở lại với thế giới ballet tuyệt vời. Từ giờ phút này, xin hãy dõi theo điệu nhảy của tôi, Người Giữ Gìn."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5047_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Dù có đấu tranh thế nào, vẫn không thể chống lại số mệnh. Nhưng ánh sáng chói lọi ấy sẽ ngưng đọng thành vĩnh cửu."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5048_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Bạn nói xem, nên xử lý những người thất bại này như thế nào?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Dù trong lòng không còn niềm khát khao, tôi vẫn sẽ đóng vai con thiên nga đó."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5050_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Đóng mắt lại, hãy nói cho tôi biết, ngài thấy gì? Ánh trăng trong veo, mặt hồ yên bình…"
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5051_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Hỡi thảm họa mang lại hủy diệt và vận rủi, vì sao lại quấn lấy chị em tôi?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Hãy chấp nhận tình yêu của tôi."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Hãy chấp nhận tình yêu của tôi."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Cảm thấy thoải mái hơn nhiều, cảm ơn ngài."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5056_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5056_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Nếu có thể, tôi muốn tặng bạn một bông hoa súng màu tím nhạt làm quà đáp lại."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Tôi cũng có thể trở nên mạnh mẽ hơn không?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Đang chuẩn bị...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5060_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5060_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Chân bị thương này à? Không ngờ bạn cũng để ý đến chuyện này. Đây là vết thương còn lại từ chiến trường khi tôi còn sống.\nKhông cần bận tâm, sau khi trở thành thân thể được đánh thức, nó sẽ không còn ảnh hưởng đến việc chiến đấu của tôi nữa.\nĐau đớn ư? Không, tôi chưa từng suy nghĩ về vấn đề này."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5061_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia đã hỏi về tình trạng tâm lý của tôi, là bạn đã gọi cô ấy đến phải không? Tôi thừa nhận rằng cơn đau chi ảo thỉnh thoảng sẽ tái phát. Nhưng không cần phải bận tâm đến cảm giác của tôi. Tôi là thanh kiếm của bạn, là lưỡi dao của bạn, chỉ cần còn có thể chiến đấu vì chính nghĩa, thì cơn đau nhỏ bé không thể ảnh hưởng gì."
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5062_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Hội trà, hội trà, hãy tổ chức hội trà đi! Tôi đã lấy được rất nhiều trà và đồ ngọt từ Silvia! Vâng, là đổi bằng vũ điệu Fortviken!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Tên tôi? Ông quan tâm đến việc riêng của tôi vậy sao? Chỉ muốn trò chuyện một chút… Được rồi. \nTrong quân đội, chúng tôi không phân biệt đồng đội dựa trên giới tính, bao gồm cả lực lượng và tốc độ, cũng như kiểu tóc và cách xưng hô. Dần dần, đã quen với cách diễn đạt như vậy."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5064_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Có ý nghĩa... Ngươi không sợ sau khi ta có được lực lượng, ta sẽ xé ngươi ra thành mảnh và ném cho cá ăn sao?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Để xứng đáng trở thành Người Giữ Gìn của tôi, bạn cũng đã cố gắng lắm đấy!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Đã đến lúc thử xé toạc cổ họng của vài kẻ yếu đuối."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Múa là thuần khiết. Lời nói có thể gây hiểu lầm, nhưng điệu nhảy thì không."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Lời phiếm·về điệu múa"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Tôi ghét biển, đó là điều đương nhiên phải không? Biển cả đã nuốt chửng tất cả những gì tôi yêu quý…"
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Dù có quên đi hay mất mát, lần này chúng ta chắc chắn sẽ trở về!"
  },
  Voice_5070_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5071_AwakerVoiceContent = {
    Text = "Dù có quên đi hay mất mát, lần này chúng ta chắc chắn sẽ trở về!"
  },
  Voice_5071_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5072_AwakerVoiceContent = {
    Text = "Xin đừng lại gần tôi nữa, rất nguy hiểm."
  },
  Voice_5072_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5073_AwakerVoiceContent = {
    Text = "Sờ thử......đây đều là những vết sẹo để lại từ sân đấu giác năm xưa, dấu hiệu của một người đàn ông mạnh mẽ!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(hét lên vì đau)"
  },
  Voice_5074_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5075_AwakerVoiceContent = {
    Text = "Đau đau đau!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(tiếng rên khẽ vì đau đớn)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(một tiếng rên nhẹ, không quá phiền muộn)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Trong thân thể dường như có cái gì đó sôi sục, có phải đây là cảm giác khi khởi linh không?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5078_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Đây là công nghệ mới ? Chiếc chân giả của tôi dường như nhẹ nhàng hơn nhiều."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5079_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "Có thể ngửi thấy hương vị mặn mà của biển cả, đất nước của tôi đã không còn xa nữa."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5080_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Những người đồng bào đã khuất, có thể theo ánh sáng này tìm thấy con đường trở về."
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5081_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Tôi đã tìm kiếm hàng nghìn, hàng vạn năm, không thiếu gì một trăm năm thoáng qua này. Trước khi đến được bờ bên kia của bạn, tôi sẽ tiếp tục giúp đỡ bạn."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5082_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Tôi chỉ lấp lánh vì cố quốc, còn bạn…"
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5083_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Tôi cảm nhận được làn gió nhẹ, nó mang theo cát mịn lướt qua mặt chân tôi."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5084_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Tôi có thể đóng góp lực lượng cho bạn đến đây thôi, tham lam quá không tốt đâu nhé?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5085_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Lời đã nói đến đây, ông hy vọng tôi đáp lại điều gì? Chỉ là chiến đấu thôi sao?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5086_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Đầu lâu của tình yêu, đầu lâu của oán hận, đầu lâu của căm ghét, đầu lâu của dục vọng… Ồ, quý khách lại đến rồi à?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5087_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Vì đây là một cuộc giao dịch, tôi cũng không thể chỉ nhận món quà của bạn. Bạn có cần chọn gì đó trong cửa hàng này không?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5088_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Tôi sẽ dạy bạn niềm vui, sự hứng thú, cảm giác khi đạt đến đỉnh cao… và ngược lại, bạn cũng phải thành thực bộc lộ dục vọng của mình nhé?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về Người Giữ Gìn 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Tôi là cây mẹ, cây mẹ cũng là tôi. Nước sữa của cây chảy trong huyết mạch của tôi, ý chí của cây lởn vởn trong biển thức của tôi…"
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về cây mẹ phong thịnh"
  },
  Voice_50899_UnlockDesc = {
    Text = "Hoàn thành \"Điều tra Hành động\" Chương 7 để mở khóa"
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Hãy trả giá cho hành động bội phản!"
  },
  Voice_5089_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_50900_AwakerVoiceContent = {
    Text = "Tôi vừa tìm kiếm một nơi ẩn náu trong Khoá Phần khi nãy, dường như đã nhìn thấy bia mộ của ngài... Xác ướp của tôi cũng sẽ được chôn cất ở đây sao? Hay không phải? Thật đáng tiếc làm sao."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Hòm Khóa"
  },
  Voice_50900_UnlockDesc = {
    Text = "Hoàn thành \"Điều tra Hành động\" Chương 7 để mở khóa"
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Chàng trai trẻ của sói… người đó và người N kia có mối quan hệ khó nói rõ…"
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chuyện vặt·về Lắc"
  },
  Voice_50901_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lắc\""
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Lại gần tôi, ôm tôi, nếm thử tôi… đừng quên tôi."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Liên quan đến Người Giữ Bí Mật 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Hoàn thành \"Điều tra Hành động\" Chương 7 để mở khóa"
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Đó là một đứa trẻ rất chăm chỉ và cẩn thận, tôi tất nhiên sẽ không trách cô ấy~ Nếu không có cô ấy, những kẻ sống buông thả kia đã sớm bị hủy diệt trong sự thay đổi rồi chứ?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Elva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Elva\""
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Sinh ra từ cát vàng, lại trở về trong cát vàng. Trong chuyến hành trình ngắn ngủi này, bạn nên để lại điều gì đó, gieo trồng điều gì đó."
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về sa mạc"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Dục vọng đều do tình yêu sinh ra. Tình yêu chính là hạt giống ban đầu, trước khi cây lớn sừng sững mọc lên."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · về dục vọng"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Ài ya, con chuột đáng yêu kia đã chạy qua… tôi nghe nói, chuột là loài động vật thích gặm nhấm đồ ăn vụng, tiếc thay, con này còn quá nhỏ, vẫn còn bú mẹ…"
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_50906_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Họ đã tiếp nối xương máu và dòng dõi của tôi, hòa vào dòng sông dạt dào tưới mát vùng Lemvahi… Từ giờ trở đi, chỉ có thể nhờ ngài tiếp tục duy trì huyết mạch này thay tôi…"
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Á Lan"
  },
  Voice_50907_UnlockDesc = {
    Text = "Hoàn thành \"Điều tra Hành động\" Chương 7 để mở khóa"
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Con nhện… con nhện. ừ~ tôi thích con nhện, chúng sinh ra dày đặc và ngay lập tức có được lực lượng để di chuyển, khả năng sinh sản và sống sót của chúng thật đáng ngưỡng mộ…"
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Agrippa\", bạn sẽ mở khóa"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Tất cả những sinh linh mang dòng máu của cây đều là con của ta, ngài cũng vậy nhé, khi đã nuốt hạt giống của cây?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về con cái"
  },
  Voice_50909_UnlockDesc = {
    Text = "Hoàn thành \"Điều tra Hành động\" Chương 7 để mở khóa"
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Tôi bán hàng hóa sao? Có thể nói là có mọi thứ, đáp ứng toàn bộ mong muốn của bạn… chỉ là phải trả một cái giá tương xứng."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5090_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Ôi, phải thừa nhận rằng tôi đã thua cô ấy một lần rồi… May mắn thay, người được cô ấy chọn cũng sẽ uống sữa của cây, mang máu và hạt giống của tôi đến thế giới mới."
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Tà Vy"
  },
  Voice_50910_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Ramona\"để mở khóa"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Là một trong ba chất thể, tên đó là một con quái vật khó lường, ngài đừng dễ dàng tin vào những lời mật ngọt của hắn, tôi sẽ đau lòng lắm đấy…"
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Có ý thức, thì sẽ có dục vọng, ngay cả sinh vật cơ khí cũng không ngoại lệ, đúng không?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Erika"
  },
  Voice_50912_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức “Erika”"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Hãy trả giá cho hành động bội phản!"
  },
  Voice_5091_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5092_AwakerVoiceContent = {
    Text = "Chào mừng đến với vương quốc diệu kỳ!"
  },
  Voice_5092_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5093_AwakerVoiceContent = {
    Text = "(số thấp)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Tôi thấu hiểu nỗi đau của việc điêu khắc, và sự bỏng rát của sự biến đổi. Tuy nhiên, tất cả những điều này, trước vẻ đẹp vĩnh cửu, mờ nhạt như hạt bụi trong gió."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5094_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Những lời chưa từng cất lên, tôi sẽ kể cho bạn trong tác phẩm của mình."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5096_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5097_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5097_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Chúa tể đang chìm trong giấc ngủ thì thầm bên tai tôi, những tàn tích dưới biển sâu không ngừng tái cấu trúc trước mắt tôi... Cảnh tượng đã xuất hiện vô số lần trong giấc mơ, cuối cùng đã trở thành sự thật sao?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5098_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Cảm ơn bạn đã chuẩn bị xưởng làm việc cho tôi. Ở đây, mọi thứ đều được tắm trong ánh nắng. Có vẻ như mỗi tác phẩm, mỗi con dao khắc, đều tỏa ra ánh kim. À, mùa xuân là màu vàng óng."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5099_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Dù tính cách khác biệt, tôi vẫn rất yêu quý đứa trẻ ấy. Cô bé có một lòng can đảm đủ sức vượt qua mọi khó khăn và ràng buộc. Nếu tôi cũng can đảm và kiên cường như vậy, có lẽ sẽ không chọn kết cục gửi mình vào lòng biển cả…"
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_5100_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "Bà Đỏ và bất kỳ chủ nhân nào tôi đã phục vụ đều khác nhau… không, tôi không phải là ghét bà ấy, chỉ là có chút khó đối phó với bà ấy…"
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Sorrel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Sorrel\""
  },
  Voice_5102_AwakerVoiceContent = {
