  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Gắng gượng sống sót."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5104_AwakerVoiceContent = {
    Text = "Tiêu diệt hết sạch!"
  },
  Voice_5104_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5105_AwakerVoiceContent = {
    Text = "Bạn không cần phải như vậy.."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Trái tim là vực thẳm không đáy, mãi mãi không thể được lấp đầy."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Không đau không ngứa, nhưng...vẫn rất cảm ơn."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "À……bạn đang bắt chuyện với tôi sao? Xin lỗi, tôi vừa rồi đang nhớ lại cảnh tượng đã nhìn thấy từ trên cột buồm. Bạn có thể nhắc lại câu hỏi được không?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Lời rỗi·về quá khứ"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Là chủ nhân, cũng là mẹ."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Cơ hội tốt!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Cơ hội tốt!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5112_AwakerVoiceContent = {
    Text = "Dự bị——"
  },
  Voice_5112_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Lại dùng sức một chút nhé~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Tình yêu nồng cháy!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "Hiện tượng rỗng rỗng… Tôi không thể nói thêm. Tuy nhiên, nó xuất hiện sớm hơn nhiều so với dự đoán."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Ừ——"},
  Voice_5118_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5119_AwakerVoiceContent = {Text = "Ừm."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "Xuất phát đi."
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Hừ, công chúa bù nhìn của chúng ta lại đang khóc lóc rồi. Là vú giả không vừa miệng, hay là bài hát ru không dễ nghe?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_5121_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Hu hu… tôi không muốn đối mặt với những thứ đó…"
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Bây giờ, đến lượt tôi báo đáp ngài."
  },
  Voice_5123_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5124_AwakerVoiceContent = {
    Text = "Cảm giác tăng cường lực lượng, như ngọn lửa thiêu đốt tận xương."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "À……xin lỗi ạ, đừng di chuyển lung tung!"
  },
  Voice_5125_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5126_AwakerVoiceContent = {
    Text = "Nhiệt độ như trong tầm tay.."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Hoa hồng trong sân đang nở."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Làm tốt rồi, còn sức để tiếp tục tiến lên không?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Kỵ sĩ là một thực thể vô hình, được định hình bởi lòng trung thành, sự dũng mãnh và đức hạnh. Vũ khí của ta cũng vậy, chính ý chí bảo vệ đã ban cho chúng hình hài của thương và thuẫn."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Hiệp sĩ"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tiyug, Brun… Wow! Xin lỗi, tôi chỉ đang nói chuyện một mình! Bạn hỏi tôi tại sao lại đọc những cái tên này ư? Vì Ai Jī Sī không muốn quên mọi người…"
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về bạn bè"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Đừng lại gần tôi!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Ghét quá!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5133_AwakerVoiceContent = {Text = "À~ hey!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5134_AwakerVoiceContent = {Text = "À~ hey!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Cảm ơn bạn đã gọi. Nếu có dịp cần tôi lên tiếng, vui lòng thông báo cho tôi trước."
  },
  Voice_5135_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5137_AwakerVoiceContent = {
    Text = "Đó là... dòng chất lỏng đen sẫm chảy trong mạch máu, lực lượng cuối cùngxóa bỏ mọi tiếng rên rỉ!\"Tôi\"đã ra đời từ đó, sinh ra để phá hủy! Hahaha!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Gọi tôi ra, là muốn đánh bạc à?... Gì vậy, điều tra án à? Không muốn đâu, quá lãng phí may mắn rồi.."
  },
  Voice_5138_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5139_AwakerVoiceContent = {
    Text = "Thực ra, lý thuyết khá là nhàm chán, lúc lên lớp tôi thường lén đọc bản ghi điều tra ở hàng ghế cuối cùng. Chuyện này chỉ nói với cậu, đừng để cô ấy biết nhé."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Hãy nếm trái cấm!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Hãy nếm trái cấm!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Tôi không bao giờ trách Yu Li-ét, cô ấy cũng chỉ là nạn nhân của nỗi khổ đen tối mà thôi, nhưng mà... dường như cô ấy không muốn nghe tôi nói những điều này. Anh có thể chuyển lời giúp tôi được không, Sứ giả."
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Yu Li-ét"
  },
  Voice_5142_UnlockDesc = {
    Text = "Chưa được trang bị giọng nói"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Chậm lại."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Ừm."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Này! Đừng sờ nữa, làm rối tùng phèo rồi! …Thôi được, ta đây lòng dạ rộng rãi."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Không cần thiết!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Chậc!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Từ ngày bạn khiến tôi được thức tỉnh khỏi bóng tối, tôi đã xác định rằng, bạn có thể cứu vớt muôn vật khỏi tuyệt vọng mang tên rỗng rỗng, đưa chúng vào cõi thanh tịnh vô nhơ. Tôi mong chờ ngày này đến."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Lời nói chuyện · Về Người Giữ Gìn · I"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Ngửi thấy…… mùi máu tươi."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Mục tiêu ở đâu? Đổi lại việc thức tỉnh tôi, tôi sẽ giải quyết đối phương cho bạn."
  },
  Voice_5150_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5151_AwakerVoiceContent = {
    Text = "Mũ của tôi đang rất háo hức!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Thân thể này, không nên rung động vì bất kỳ sự tồn tại nào khác ngoài Người… nhưng hơi ấm của bạn…"
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Sao, muốn đánh một trận không?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Người làm ô uế…"
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Không thể tha thứ."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erika hiện đang hoạt động bình thường, kết nối tốt với thiết bị điện trong Đại học Misaque. Bạn có muốn tôi mở đèn trong phòng ký túc xá không?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Erika"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Tiếp theo, đến giờ ăn rồi, hì hì…"
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Đừng để người phụ nữ đội mũ rộng vành màu tím đến gần sân khấu! Không có lý do gì, chỉ cần bạn không muốn chất lỏng màu xám nhầy nhụa chảy ra từ mũ rộng vành thì đừng để cô ta lại gần!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Đào Đen Đá"
  },
  Voice_5159_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Đào Đen Đá\", tính năng sẽ được mở khóa"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Bạn luôn như vậy sao? Giao phó niềm tin cho tất cả mọi người? Quá ngây thơ."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Sự thù hận có thể được giảm bớt, nhưng hoàn toàn không thể xoá bỏ."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Thân thể được đánh thức? Ừ… đúng vậy, bảy giờ là thời điểm lý tưởng để thức dậy! Mai lúc bảy giờ sáng mình cùng ra biển nhặt vỏ sò nha!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về thân thể được đánh thức"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Ta ban cho ngươi sự bất tử!"
  },
  Voice_5163_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5164_AwakerVoiceContent = {Text = "Ha a!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Ha a!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Xin lỗi, nếu Ai Jī Sī ở đây gây phiền phức cho anh, tôi sẽ rời đi ngay!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5166_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Quý vị đã cung cấp nơi trú chân cho tôi, tôi rất biết ơn. Nhưng xin hãy tha thứ, tôi không còn đủ tư cách để đứng trên sân khấu một lần nữa."
  },
  Voice_5167_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5168_AwakerVoiceContent = {
    Text = "Cảm ơn ngài đã cho phép tôi ở lại đây, nếu có thể báo đáp ngài, Ai Jī Sī sẽ làm bất cứ điều gì. Ngài cần cô ấy rót trà cho ngài không?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5168_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Vì rất ấm áp, nên không muốn rời đi. Khi ở một mình, thật sự rất tối, rất lạnh, rất sợ hãi…"
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5169_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Ai Jī Sī… thật sự có thể quay lại với mọi người sao? Tôi vẫn chưa chuẩn bị sẵn sàng, nhưng ngài đã chấp nhận tôi rồi… Nếu vậy, từ nay về sau cũng xin hãy chiếu cố nhiều hơn… Người Giữ Gìn."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5170_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Nhớ rồi, tôi nhớ rồi…! Máu ô uế của loài người đã làm tôi bị mắc kẹt… Tôi, tôi không thể tiến hóa! Sao lại thế này? Tôi làm sao vậy…? Mang của tôi đâu? Tại sao chúng không cử động?! Tại sao!"
  },
  Voice_5171_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5172_AwakerVoiceContent = {
    Text = "Tôi thích ăn bạch tuộc nướng, bạch tuộc luộc, bạch tuộc chiên... Một số người nghĩ rằng tôi đang cố ý xúc phạm thần minh, xin lỗi, vì bạch tuộc thực sự quá ngon, hahahaha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Sâu. các vì sao. ta là...... Yu U Hahi!giết...... để ta giết!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5173_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Thân thể màu đỏ sẫm, xúc tu đập nhịp, miệng không ngừng mở và đóng... Tuyệt vời! Tuyệt vời! Tôi đã không thể chờ đợi để xé toạc cổ họng của ai đó!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5174_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahahaha, chính là cảm giác này! Cho tôi thêm một chút...... gấp đôi, không, gấp mười lần liều lượng!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5175_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Tôi sẽ luôn chịu đựng."
  },
  Voice_5176_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5177_AwakerVoiceContent = {
    Text = "Cảm giác kỳ diệu này...... cũng không tệ. Tốt hơn cà độc dược của phù thủy Levant."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5177_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Đồng bạn? Hừ... không cần đồng bạn, tôi sẽ không để bị cản trở như trước đây thêm lần nào nữa."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5178_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Sẽ hợp tác với ngươi, chỉ vì ngươi đã thể hiện ra lực lượng đủ để xứng đáng với ta. Đừng quên, bản hợp đồng này sẽ kết thúc khi lực lượng của ngươi suy yếu, đến lúc đó, ta sẽ không ngần ngại xử lý ngươi."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5179_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "Tôi từ trong đôi mắt của bạn... đã thấy ánh sáng, đó là ngọn lửa của tham vọng và dục vọng. Hỡi phàm nhân, hãy hiểu rõ chính mình! Chúng ta... mới thực sự là đồng loại!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5180_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Bạn biết về chim hải âu lớn chứ? Chúng chẳng bao giờ coi con người ra gì, mà chỉ dốc sức vỗ đôi cánh, đón nhận thử thách của bão tố. Thế nhưng một khi bị đày xuống mặt đất, rơi vào giữa tiếng chế nhạo, đôi cánh khổng lồ rũ xuống lại trở thành trở ngại đáng thương.\nCâu chuyện này chẳng có ý nghĩa sâu xa gì đâu, chỉ là ở bên bạn rất thoải mái, nên tán gẫu vậy thôi."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5181_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Có lẽ, thời đại thực sự đã thay đổi. Hiện nay, kể cả những người từng yếu đuối cũng có thể vượt qua đá ngầm, tung hoành trên sóng biển, trở thành vua của bầu trời xanh. \nNgười phàm, ta đang chờ ngày ngươi viết lại lịch sử. Đến lúc đó, ta sẽ vô cùng vinh dự khi trở thành thanh kiếm khổng lồ trong tay ngươi!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5182_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Tỷ lệ chuyển đổi quá thấp. Ngày mai hãy đến văn phòng của tôi để báo cáo và học lại."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Bạn đã gặp đóa khác chưa? \"Sự thật của thế giới\" lại có thể biến đóa bình tĩnh và lý trí thành một người hoàn toàn khác... Cuối cùng, liệu bạn và tôi cũng sẽ trở thành như vậy không?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Lời nói phi chính · về @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức @2 sẽ mở khóa"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Chủ nhân…… tôi cần lệnh, xin hãy ra lệnh cho tôi."
  },
  Voice_5185_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5186_AwakerVoiceContent = {
    Text = "Hiệu suất của hệ thống đã được nâng cao."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "Ừ hum hum!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Nhiều đối tác hơn!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Nhiều đối tác hơn!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Xin lỗi, tôi không thể rời khỏi nôi… Làm vậy có thể chắn tầm nhìn của mọi người, nên tôi ở lại phía cuối lớp là được rồi."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Gì! Thảm Constantinopolis, trà đỏ Đảo Ceylon, bánh quế Andalucía… một cái cũng không mua được sao?! Ô… người phụ nữ đó luôn dễ dàng có được những thứ này, tôi còn tưởng chúng rất phổ biến…"
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Vẫn còn xa mới trở lại hình bóng ban đầu của tôi."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5194_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "Như vậy vội vàng, đối với một người tài ba kiệt xuất như ngài, quả thật có chút không tinh tế."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Dù có nâng cấp thế nào đi nữa, diện mạo của con thú này cũng sẽ không thay đổi. Cuối cùng, nó chỉ là hiện thân của lực lượng của tôi mà thôi."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5196_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Cảm giác như đang trở lại đại dương hỗn loạn vậy, khá ổn."
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5197_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "Nhìn vào sự cố gắng hết mình của ngươi, ta sẽ tạm thời chấp nhận ngươi là người đồng hành."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5198_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Hãy phá vỡ rào cản lực lượng như phá tường mê cung."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5199_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Không được xé nát thức ăn, cũng không được nghiền nát ghế trong căng-tin…… Được, Lily sẽ không làm vậy nữa."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5200_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Tôi có thể gọi mẹ là mẹ không?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5201_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Có lệnh gì không, chủ nhân? \n \"Đừng mang chúng ra ngoài, mọi người sẽ sợ hãi\"? \n Lily hiểu rồi, Lily sẽ giấu chúng ngay."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5202_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Trở thành thân thể được đánh thức, thì ra là như thế này."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5203_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mẹ ơi, con có thể ngủ bên cạnh mẹ không? Khi ở một mình, con thường mơ thấy những giấc mơ tối om. Tay và chân của Lily đều bị rớt xuống, thật đau quá…"
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5204_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ya! Được chủ nhân coi trọng, Gia Lân chỉ là một nữ hầu thấp hèn mà thôi..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5205_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hừ hừ~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Tôi cần thu thập một số vật liệu điêu khắc, tốt nhất là vẫn còn tươi mới."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Xin hãy im lặng."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Người ngoan cố không tỉnh ngộ, làm những việc vô ích."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5209_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "Đến nước này rồi, ta vẫn có thể hiểu được ý định của ngươi. Không sao cả, tiếp tục đi."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5210_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Người đã thấy được quyết tâm của ngươi. Trước khi chìm vào giấc ngủ một lần nữa, ta sẽ trở thành người chứng kiến, chứng kiến hành động anh hùng của đứa con được sinh ra từ dòng dõi của định mệnh chống lại số phận. Nhưng bây giờ, ta cần một chút thời gian nghỉ ngơi."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5211_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Thuận theo thiên mệnh, không tốt sao? Tại sao phải phản kháng ý chí của số phận."
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5212_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Để thực hiện ước nguyện, bạn lại có thể trả giá nhiều như vậy…"
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5213_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Hả~? Không thấy phiền sao? Đừng làm phiền tôi vì chuyện của thằng đó nữa! … Thôi, tùy các người, coi như là để giết thời gian vậy."
  },
  Voice_5214_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5215_AwakerVoiceContent = {
    Text = "Rỗng rỗng… những dòng lỏng đen bẩn thỉnh thoảng xâm chiếm giấc mơ của ta, không thể chịu đựng được."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Quyền lực là thanh kiếm hai lưỡi, tôi làm sao không hiểu được… Chỉ là tỉnh ngộ quá muộn, quá muộn. Một khi tôi buông tay, họ sẽ ùa tới, xé tôi thành phân mảnh… Nếu từ đầu tôi đã tỉnh táo như ngài, có lẽ cũng không phải kết thúc bằng cách bi thảm như vậy. À, à? Ngài nói, tôi sau này có thể tổ chức salon ở phòng nghỉ?! Điều này thật… Ngoài việc tự mình phục vụ ngài, tôi còn có thể báo đáp ngài như thế nào nữa…"
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5216_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Quý khách thật là một người không dễ thuyết phục, rốt cuộc tôi phải chiêu đãi ngài thế nào để ngài chịu nhượng lại quyền lợi trong tay? Quyền lực chỉ dẫn đến tai họa, lẽ đơn giản này, ngài không thể không hiểu được chứ?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5217_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Trước khi buổi tiệc bắt đầu, bạn có muốn nghe một câu chuyện không? Câu chuyện về một cô gái làng mạc đã hái được vương miện quyền lực… Nên bắt đầu từ đâu nhỉ? Từ việc cô bị cha mẹ ép gả cho một cụ già tám mươi, hay bạn muốn nghe về cảnh cô tỏa sáng trong khu vườn quý tộc?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5218_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "Trong quá khứ, khách mời đều gọi tôi là\"Bà Chủ Nhà\". Tất nhiên, ngài cũng có thể gọi tôi là\"Sorrel\", dù sao ngài cũng là vị khách đặc biệt nhất của tôi..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5219_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Là chủ nhân của buổi salon, làm cho mỗi vị khách hài lòng là trách nhiệm của tôi."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5220_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5221_AwakerVoiceContent = {Text = "À"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Chủ quân? Là tư thế đứng của tôi có vấn đề sao?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Ối!"},
  Voice_5223_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5224_AwakerVoiceContent = {
    Text = "Vận đen~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5225_AwakerVoiceContent = {Text = "À"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Tôi nhớ cảm giác này, thời khắc vinh quang đáng tự hào sắp đến rồi…"
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5226_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Dù dấu vết mang vẫn chưa xuất hiện, nhưng tôi đã không còn lo lắng về điều đó nữa. Màng cánh này sẽ hóa thành lá chắn bảo vệ bạn, Người Giữ Gìn."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5227_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Bạn… thực sự kiên nhẫn hơn những người khác… đã dành nhiều tài nguyên như vậy cho tôi. Bạn thật sự… không ghét tôi sao?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5228_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "À? Buổi lễ đã kết thúc, tại sao tôi vẫn chưa thể mọc mang? Sự biến đổi lại thất bại sao! Chết tiệt! Chết tiệt! Chết tiệt!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5229_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Giọng nói đó lại gọi tôi… Tiếng ca trong trẻo từ biển sâu thẳm!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5230_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Đoán——sai——rồi——"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Điêu khắc gia Sơn từ Tây Đài, xin dâng tặng bạn con dao khắc. Mặc dù bạn có khuyết điểm, nhưng vẫn xứng đáng được khắc họa."
  },
  Voice_5232_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5238_AwakerVoiceContent = {
    Text = "Những đứa trẻ không nghe lời, tập trung lại đây nào~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Nghệ thuật đích thực không cần giải thích."
  },
  Voice_5239_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5240_AwakerVoiceContent = {
    Text = "Nghệ thuật đích thực không cần giải thích."
  },
  Voice_5240_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5241_AwakerVoiceContent = {
    Text = "Ô Ryta, có thể giúp được không?"
  },
  Voice_5241_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5242_AwakerVoiceContent = {
    Text = "Thổi vang sừng hiệu!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "Bất kể giá nào!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "Cảm giác được tắm trong ánh nắng mặt trời... hóa ra lại mềm mại đến vậy, khiến người ta muốn rơi nước mắt."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5244_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Vì lòng biết ơn... tôi sẽ dựng lên một bàn thờ bí ẩn sâu trong nỗi đau của mình dành cho bạn."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5245_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Thịt máu của anh trai và thân thể của tôi, hòa hợp chặt chẽ hơn..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5246_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Tôi kiên cường hơn bạn tưởng. Vì vậy, khi sử dụng tôi, bạn có thể dùng lực mạnh hơn một chút, đừng khách sáo nhé."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5247_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Có phải đó chỉ là ảo giác của tôi chăng? Sự khao khát máu dường như đã giảm đi một chút."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5248_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Từ khi chưa chính thức nhập học, tôi đã mong chờ sự xuất hiện của bạn. Bây giờ xem ra, chúng ta phối hợp khá tốt phải không? Bạn đồng hành."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Thật là không ra gì."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Á a!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Đánh đập·cuồng loạn"
  },
  Voice_5253_AwakerVoiceContent = {
    Text = "Ừm…ừm"
  },
  Voice_5253_AwakerVoiceTitle = {
    Text = "Đánh bại·trầm cảm"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Hãy làm tôi bị thương đi!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Ai Jī Sī hoàn toàn sợ hãi. Không, không phải sợ mọi người, mà là sợ bản thân lại mang đến nỗi sợ hãi và buồn bã cho các bạn."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Sách cổ tích của thời đại này thú vị hơn nhiều so với những gì tôi đã đọc hồi đó! À, à! Xin đừng hiểu lầm, thưa chủ nhân! Tôi đã qua tuổi nghe câu chuyện trước khi đi ngủ rồi!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Hãy làm tôi bị thương đi!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Phù… Ai Jī Sī có gây rắc rối cho mọi người không?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Bạn luôn giữ lấy niềm tin đáng cười đó, ở bên tôi… Được thôi, có lẽ dùng đến bạn cũng chẳng tệ. Nhưng bạn hãy nhớ: tôi không thể dung thứ bất kỳ sự bội phản nào, đặc biệt từ bạn."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5259_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Tôi chỉ hối hận là lúc đó không đóng xương cốt của họ lên cọc gỗ, treo lên thành tường! Tất cả những kẻ bội phản, chà đạp, sỉ nhục tôi, tôi sẽ không tha một ai!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5260_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Đúng, tôi cũng từng khúm núm cầu xin trước mặt những người đó, điều này không có gì để chối cãi. Họ đã lợi dụng sự ngây thơ của tôi, và tôi cũng đã buộc họ phải trả giá."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5261_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Bạn nghĩ rằng vài lời hoa mỹ, vài ngày đãi ngộ giả dối, có thể khiến tôi tự nguyện đeo lại xiềng xích, trở thành vật sở hữu của bạn sao?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5262_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Tất cả những người cố gắng kiểm soát tôi, lợi dụng tôi, cuối cùng đều bị chính tay tôi gửi xuống âm giới—— tôi không ngại đưa bạn một chuyến đi nữa."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5263_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "À……xin lỗi ạ, đừng di chuyển lung tung!"
  },
  Voice_5264_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5265_AwakerVoiceContent = {
    Text = "Đừng chạm vào tôi!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Không kính trọng!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Hãy khuất phục… Chào mừng đến với vương quốc của khoái lạc và mộng mơ."
  },
  Voice_5267_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5268_AwakerVoiceContent = {
    Text = "Đây là thành phố mà hàng vạn người chết lang thang, mất đi quê hương của mình."
  },
  Voice_5268_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5269_AwakerVoiceContent = {
    Text = "Ai Jī Sī sẽ cố gắng!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Cái đó... tôi không thể kiểm soát việc hấp thụ sức sống, vì vậy xin đừng đưa tay vào nôi, làm như vậy bạn có thể bị ốm."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Hy vọng trong suốt cuộc trò chuyện này, cô ấy sẽ không gặp lỗi. Người trợ lý vừa đáng yêu vừa đáng ghét của tôi, đã không còn phòng thí nghiệm nào để cô ấy phá hủy nữa rồi."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về Erika"
  },
  Voice_5271_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức “Erika”"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Cánh tay, những cánh tay thật phiền phức! Chúng cứ kéo tóc tôi mãi. Không thể kiểm soát được đôi tay của mình, tôi thật sự tệ hại... hay là..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về bản thân"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Cảm ơn sự hướng dẫn của bạn, cuối cùng tôi đã hiểu lựa chọn của Phiệt. Tôi luôn coi mọi thứ là hiển nhiên, không ngờ lại tạo áp lực tâm lý lớn như vậy cho cô ấy. Từ nay, tôi sẽ sống vì chính mình…"
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5274_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Trong quãng thời gian dài đằng đẵng, tôi và Phiệt chỉ có nhau… Tuy nhiên, bây giờ tôi đã có người quan trọng mới… Người giữ bí mật, xin hãy cho tôi rút lại lời nói trước, ngài khác với họ, ngài không chỉ chú ý đến giọng hát và trang phục của tôi, mà còn nhìn vào tôi. Vì vậy, tôi cũng sẽ nhìn vào ngài."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5275_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Những ngôi sao chìm trong giấc mơ, đi đến nơi định mệnh chỉ lối, hướng về thần quốc!"
  },
  Voice_5276_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5277_AwakerVoiceContent = {
    Text = "Tại sao tôi luôn mặc bộ lễ phục này mọi lúc mọi nơi? Như vậy, tôi có thể sẵn sàng cất tiếng hát vì bạn bất cứ khi nào."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5277_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Tôi tự mình muốn làm gì? ……Xin lỗi, tôi không rõ ý bạn là gì……Thực tế, Phiệt cũng đã hỏi tôi câu này nhiều lần, nhưng tôi chỉ mong cô ấy sớm khỏe lại……"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5278_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Trong thời gian ở hành tinh hoang, sự giúp đỡ của những người quyền thế đã cho hai chị em chúng tôi nguồn lực để sống sót. Cuối cùng, cũng chính họ đã trao cho tôi cơ hội rời khỏi nơi đó, dù chỉ một mình. Họ đều là ân nhân của tôi, giống như Người Giữ Gìn đã cho tôi chỗ nương thân."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5279_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Bạn là người tốt bụng cung cấp nơi ở cho tôi, Ai Jī Sī sẽ nghe theo lời bạn. Nếu Ai Jī Sī có thể hữu ích hơn một chút thì tốt quá……"
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Nhớ chuẩn bị địa điểm nhé. Chỗ bạn đặt chẳng lẽ nhỏ hơn chỗ ở Elworth?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5281_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Rất tốt, Gia Lân hiện tại có thêm động lực, có thể dọn dẹp hai mươi phòng trong một ngày!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5282_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Đây là âm nhạc cổ xưa như nước hồ, thuộc về 「chúng ta」. Chủ nhân, hãy cùng nhảy múa nào! Trong khi giọng nói của Gia Lân vẫn còn đây..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5283_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Chủ nhân!Giọng của Gia Lân... đang biến mất... cứu..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5284_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "Mắt của Gia Lân đã được cải thiện... Chủ nhân, anh có phải lại quên chải đầu không!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5285_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Dù mạnh hơn, Gia Lân cũng không hề muốn trả thù đâu. Gia Lân chỉ muốn hát, nhảy múa và tổ chức tiệc tùng!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5286_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Để tồn tại sau khi mọi thứ bị hủy diệt, tôi đã chia sẻ linh hồn và máu cho quá nhiều người. Lực lượng của tôi hiện nay, so với lúc mới nhận lấy ý chí này, đã kém xa rất nhiều…"
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Lời rỗi·về quá khứ"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Không mong đợi tìm thấy tôi trong tòa nhà giảng dạy. Nơi đây đầy mùi hôi khó chịu của những học giả già nua, tôi không thể chịu đựng ở đây dù chỉ một ngày."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Đừng chạy trốn."
  },
  Voice_5289_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5290_AwakerVoiceContent = {
    Text = "Quê hương của tôi tin vào \"thần minh\", tương ứng với điều đó, vị vua mà tôi theo đuổi đương nhiên là một \"người có thể giao tiếp với thần linh\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Quốc Gia Vĩnh Hằng"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Quý vị đây thật là nhân tài tụ hội, xứng đáng với một buổi họp mặt sang trọng… Yên tâm, đến lúc đó, thư mời chắc chắn sẽ được người hầu của tôi giao tận tay quý vị."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5292_AwakerVoiceContent = {
    Text = "Đến đây!"
  },
  Voice_5292_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Nếu có thêm nhiều bạn đồng hành thì.."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Tôi và người đó khác nhau, cô ấy chỉ mang đến những run rẩy đầy thù địch và nỗi sợ hãi, còn tôi ban tặng sự âu yếm da thịt, nỗi đau ngọt ngào và nóng bỏng của tình yêu."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Chuyện trò·về Vanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Vanda\""
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Đừng nghĩ là mọi chuyện sẽ kết thúc như vậy! Lần này bị sỉ nhục, tôi sẽ đòi lại từng chút một!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Tay của bạn ấm áp như linh hồn của bạn vậy, lửa nhợt nhạt, tôi… cảm ơn vì đã chạm vào tôi."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Chơi bài cầu trong lớp học có gì không được? Có bàn, có người, tôi đã mang theo bộ bài, điều này có nghĩa là \"ván bài bắt đầu\"!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5299_AwakerVoiceContent = {Text = "Đừng…"},
  Voice_5299_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Hãy ngắm nhìn hố sâu!"
  },
  Voice_5300_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5301_AwakerVoiceContent = {
    Text = "Hãy ngắm nhìn hố sâu!"
  },
  Voice_5301_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5302_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5302_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5303_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5303_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5304_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5304_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5305_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5305_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Tắm trong ánh sáng thiêng liêng!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Ê!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Linh hồn yếu đuối tụ tập lại, ngoài việc ầm ĩ ra còn có ích gì nữa chứ, ôi…"
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "Chiến tranh luôn mang lại đau khổ, và chịu đựng gian khổ là bổn phận của người lính. Dù mất đi đôi tay, đôi chân, thậm chí mất tất cả, tôi vẫn sẽ tiếp tục chiến đấu vì bạn, vì công lý của thế giới."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Đây chính là lễ vật ngươi dâng lên Ngài?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Bạn nghĩ rằng như vậy có thể thay đổi tương lai chăng?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Việc mang thai……trong bụng tôi……"
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Hừ, coi như mày đã hiểu chuyện."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Đóng góp cho chủ tử, là chuyện đương nhiên."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Bạn cố gắng lấy lòng tôi trông cũng thật đáng yêu."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Bánh brun, bánh pudding caramel, bánh Sachertorte, bánh mousse sô cô la, bánh quy,… phải có trên mỗi bàn!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5318_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Hãy giúp tôi xem, váy của tôi đã được chăm sóc kỹ lưỡng chưa? Không được có nếp nhăn, không được có chỗ lơi lỏng… Có vấn đề gì à? Bạn không hài lòng điều gì à?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5319_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Chào mừng đến với nghi thức khởi linh cuối cùng của bản tiểu thư! Tất cả đều là do bản tiểu thư thiết kế tỉ mỉ. Tất nhiên, Người Giữ Gìn cũng có một chút công lao.."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5320_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Bàn ghế phải được trang trí bằng ren phù hợp với khí chất của tôi, chậu cây phải dùng lan treo màu đỏ… Mau đi chuẩn bị nhé!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5321_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Đi hẹn khách thôi! Sao chuyện nhỏ này cũng không làm được?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5322_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Không có đường thoát!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Không có đường thoát!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Tôi sẽ cố gắng! Để không phụ lòng mong đợi của ngài."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5325_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Tôi cũng khá thích người phụ nữ đó, chúng tôi có cái gì đó... À, đúng rồi, tiếng nói chung!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Chuyện trò·về Vanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Vanda\""
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Kẻ vô lễ!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Kẻ vô lễ!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "Hóa thành tàn tích."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5330_AwakerVoiceContent = {
    Text = "Hủy diệt đi."
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Xuyên thủng rào cản thực tại đi!"
  },
  Voice_5331_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5332_AwakerVoiceContent = {
    Text = "Gần đây có dự định vượt biển không? Liệu anh/chị có thể nhận lời nhờ vả đặc biệt này, cho tôi đi cùng được không? Chỉ cần được ra biển lớn là đủ rồi…"
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5332_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Nếu bạn vẫn tin tưởng tôi, hãy cho phép tôi trở thành cột mốc trên hành trình của bạn. Tuy nhiên, ngay cả công việc đơn giản như vậy, tôi cũng đã từng thất bại…"
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5333_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Không muốn ra khơi sao? Để tôi xem bản đồ biển hiện nay… Vĩ độ Nam 47 độ 9 phút, Kinh độ Tây 126 độ 43 phút, chính là nơi đây."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5334_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Quá khứ của tôi đã gây ra không ít thảm họa, thậm chí suýt nữa hủy diệt một số nền văn minh… Tôi… Nếu nói rằng không phải cố ý, liệu có còn quá muộn không?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5335_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Tôi là người canh giữ lối vào vĩnh cửu, chỉ đường cho những người trở về quê hương. Thật đáng cười, người mang trọng trách này lại quên mất nơi chốn quê hương của mình…\nBạn… có thể trở thành ánh sáng dẫn lối cho tôi không?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5336_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Đám mây sao."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5338_AwakerVoiceContent = {Text = "À"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Sương mù dày đặc."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hừ."},
  Voice_5340_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5341_AwakerVoiceContent = {
    Text = "Hầu hết các vệ sĩ không khác nhau, trừ người phụ nữ đặc biệt này. Nếu có thể, xin hãy sắp xếp một lộ trình khác cho tôi."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về MIRIAM"
  },
  Voice_5341_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Miriam\"để mở khóa"
  },
  Voice_5342_AwakerVoiceContent = {Text = "À"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Không sao cả."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Đưa tay ra."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Trước khi tôi trở lại cung điện dưới đáy biển, tạm thời cho con người yếu đuối này mượn một chút lực lượng của biển sâu, chỉ có vậy thôi."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5346_AwakerVoiceContent = {
    Text = "Đến đây!"
  },
  Voice_5346_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5347_AwakerVoiceContent = {
    Text = "Thích? Tôi thích đau đớn, thích làn da sưng đỏ nóng bỏng, thích những tiếng rên rỉ pha lẫn giữa khoái cảm và đau đớn. Đau đớn mới chính là dục vọng nguyên thủy và chân thật nhất, phải không?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Tham gia Ô Ryta đi!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Tham gia Ô Ryta đi!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Người chị lớn kia, luôn trừng mắt nhìn tôi đầy đe dọa. Nhưng không hiểu vì sao, tôi vẫn cảm thấy gần gũi. Có phải vì chị ấy giống như mẹ?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Hiro"
  },
  Voice_5350_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận thân thể được đánh thức \"Hiro\""
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Đầu óc trở nên linh hoạt hơn, cảm thấy khá ổn."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5351_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Thay vì đi làm, tôi thích công việc ở phòng thí nghiệm hơn — hay bạn nghĩ rằng, những công cụ phụ trợ đó được vớt từ biển lên?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5352_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Dù là đinh vít hay đinh, tất nhiên là càng nhiều càng tốt rồi."
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Thân thể đã khó khăn trong việc gánh chịu lực lượng này, nhưng bây giờ chưa phải lúc thay đổi con rối. Này, đứng đó làm gì vậy, đến giúp tôi đỡ lấy cái chân này, tôi cần kiểm tra lại một chút."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5354_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Gánh nặng dẫn dắt ánh sáng có thể làm sụp đổ cả những vị thánh thuần khiết nhất. Nếu bạn cảm thấy mệt mỏi, ngọn lửa trắng của tôi, xin hãy chia sẻ với tôi. Tôi sẽ dốc hết sức để giúp bạn vơi đi nỗi buồn và san sẻ gánh nặng từ vô vàn phúc lành."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về sự mệt mỏi"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Sự công nhận của ngài là lý do tồn tại của tôi với tư cách là một hiệp sĩ."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5356_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Tắm trong ánh sáng của thần linh, đây chính là thần lực mà chủ nhân của ta sở hữu sao? Như vậy bao la, như vậy thiêng liêng."
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5357_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Cánh cửa của thần linh, gần trong gang tấc."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5358_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Càng lúc càng sáng, càng lúc càng rõ ràng…"
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5359_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Thật không ngờ lại có thể trở về hoàn hảo với thân thể được đánh thức… Tôi đã nghe thấy, những âm thanh thiêng liêng của thần quốc đang vang lên vì tôi…"
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5360_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Ngài sẽ đón tôi vào đền thánh, cho tôi an giấc trên giường…"
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5361_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Hãy yên tâm, chúng tôi đều rất có ích. Tôi có thể may vá, dọn dẹp, một người khác lại rất mạnh mẽ trong chiến đấu, còn những người khác..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Tôi ghét những thứ sáng bóng, mềm mại. Sự dịu dàng như một tấm gương, tất cả sự xấu xí, tham lam và yếu đuối đều không thể che giấu trước nó."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Muốn sờ brun không? Tôi không thể quyết định được, bạn phải hỏi cô ấy trực tiếp."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Muốn làm tôi vui? Vậy thì quỳ xuống, duỗi cổ ra và đảm bảo câm miệng lại cho đến khi tôi hút cạn bạn."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Uống!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "Tôi đã mơ một giấc mơ đêm qua, đó là bước khởi đầu trong hành trình lang thang giữa các vì sao của tôi."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5367_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Ai Jī Sī có thể giúp được không?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5368_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Đã cảm nhận được rồi~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Đập!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Kỹ năng·3"
  },
  Voice_5371_AwakerVoiceContent = {
    Text = "Cẩn thận!"
  },
  Voice_5371_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "Lùi lại."
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Không ai sẽ bị thương... trong thế giới này.."
  },
  Voice_5373_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5374_AwakerVoiceContent = {
    Text = "(nhõng nhẽo)"
  },
  Voice_5374_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5375_AwakerVoiceContent = {
    Text = "Xin hãy cho tôi đặt một bàn thờ của chủ nhân tôi. Đây là tượng pháp được điêu khắc bởi tín đồ trung thành, sẽ không mang lại bất kỳ lời nguyền nào cho bạn."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Chỉ cần một chút…"
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Cờ lê của tôi chưa sẵn sàng!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Hóa học, vật lý học, ứng dụng học bạc tâm… Thời đại này, đã không cần phải học bảy kỹ năng của hiệp sĩ nữa rồi sao? Thì ra là vậy. Vậy thì, xin ngài chủ sắp xếp cho tôi các khóa học tương ứng!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Ô Ryta đã đi du lịch! Không phải trôi dạt theo sóng biển, mà là đi du lịch bằng xe lều lớn!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5379_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Sứa đèn, sứa vương miện, sứa hoa đào, mọi người đều tụ tập thành đàn, tất nhiên, Ô Ryta cũng vậy! Ô Ryta cũng muốn ở cùng mọi người!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5380_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Công việc trước đây? Không còn nhớ rõ nữa… nhưng Ô Ryta nhớ rằng mình đã từng làm việc ở thủy cung! Lương hàng ngày là 2 phiến gì!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5381_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Thì thầm với bạn, Ô Ryta thực ra là Alan, Trans... à, tóm lại Ô Ryta là người dưới biển! Nếu Ô Ryta ngoan ngoãn, ăn nhiều rau và kết bạn, những người như Atres sẽ chào đón Ô Ryta!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5382_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "Nhà của Ô Ryta, những người bạn ở thủy cung, những con sứa mà Ô Ryta yêu thích nhất, tất cả đều biến mất… Liệu cậu cũng sẽ biến mất sao? Có phải cậu không thể ở bên Ô Ryta mãi mãi để chơi cùng cô ấy sao?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5383_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Thắng rồi sao? quá tốt…"
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Để hòa bình!"
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Vì công lý."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Tôi biết bạn đang ở trong cơ thể tôi."
  },
  Voice_5389_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5390_AwakerVoiceContent = {
    Text = "Con người, vị thần giả, thể xác tỉnh thức, cho đến sự hòa tan…… tất cả trong thế gian này đều sẽ trở thành nền tảng để tôi tái tạo quốc gia vĩnh hằng."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Dậy đi, hãy dậy đi, tôi biết bạn đang ở trong tôi!"
  },
  Voice_5391_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5392_AwakerVoiceContent = {
    Text = "Yu U Hahi...... anh ấy có chút giống như anh trai tôi, thường khiến tôi nhớ đến những ngày u ám, lạnh lùng và mất ngủ."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về Yu U Hahi（Yu U Hahi）"
  },
  Voice_5392_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Yu U Hahi\""
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Mối quan hệ của chúng ta, giống như Sherlock Holmes và Dr. Watson phải không? Ông có theo dõi các tạp chí phổ biến gần đây không?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Quỳ gối trước vẻ đẹp."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Quỳ gối trước vẻ đẹp."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Sự ghét, tính từ, có nghĩa là cảm thấy khó chịu đối với một điều gì đó. ghét, động từ, có nghĩa là cảm xúc khi tránh và không thích một điều gì đó. phản cảm, danh từ, cảm giác khó chịu, <Del:ghét bị áp chế để tôi phá hủy để tôi phá hủy để tôi>—— xin lỗi, tôi sợ rằng tôi không hiểu \"ghét\" là gì."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5397_AwakerVoiceContent = {
    Text = "Cuối cùng vẫn…"
  },
  Voice_5397_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Trở nên khác biệt hơn."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Hãy nhớ tên tôi, Goliath. Tên này được định sẵn để xóa nhòa lịch sử tầm thường của loài người."
  },
  Voice_5399_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5400_AwakerVoiceContent = {
    Text = "Đừng lo lắng."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Hy vọng bạn không phụ lòng tiềm năng của mình và sự kỳ vọng của nhân loại, tân Thủ Mật Nhân."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Quá tải."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "Chạy quá tốc độ."
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Ừ, bức ảnh bạn lật tìm trong ví à? À, đó là tôi ngày xưa. Ngoại hình hiện tại của tôi là do người bạn cờ bạc, cũng là đối thủ của tôi, tạo ra đấy."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5404_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Đúng rồi — muốn đánh một ván không? Nếu thắng, tôi sẽ kể cho bạn một bí mật nhé? \nNhưng cẩn thận đấy, đừng để Elva bắt được~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5405_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Bạn có quan tâm đến bộ lông này không? Có muốn sờ thử không? Đừng lo, tôi rất hào phóng!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5406_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Tất nhiên cũng có những lợi ích, chẳng phải tôi đã gặp được Watson của mình sao? So với việc này, sinh tử và ngoại hình đều không đáng kể, đúng không?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5407_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Bạn có hỏi tôi có hối hận không? Hoàn toàn không. Nếu cuộc đời luôn suôn sẻ, thì cũng quá nhàm chán phải không?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5408_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "Trong thời đại của tôi, trường học là nơi huấn luyện chiến binh, có vẻ như bây giờ cũng vậy."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... không, như thế này đã tốt rồi, ít nhất chúng ta lại có thể ở bên nhau, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Lời chuyện trò · Về \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Mở khóa sau khi nhận \"24\""
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Tôi làm khá tốt phải không? Vậy thì, thù lao. —— Sao nào, trên đời này đâu có bữa trưa miễn phí!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Tôi đến từ Tây Đài. Ở đó, mọi người đều muốn trở thành diễn viên, không ai chịu làm khán giả. Thực ra, chúng tôi chỉ là những phần không quan trọng của thành phố này mà thôi."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Lời rỗi·về quá khứ"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Bạn có từng thấy các bức điêu khắc cổ đại không? Hòa mình vào núi non, dựa vào thiên nhiên để thoát khỏi sự xói mòn của thời gian, một kiệt tác tuyệt vời biết bao… tiếc thay, vẫn chưa đủ…"
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Bồ câu, chưa bay về nữa…"
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "Lui xuống!"
  },
  Voice_5415_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5416_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Thực hiện lệnh!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Ngu si"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "……À? Bạn đang gọi tôi à? Tôi đang sửa xe máy nên không nghe thấy……Nói đến chuyện này, người lạ tốt bụng ơi, bạn có thấy cờ lê của tôi không?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5419_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Ký ức của tôi luôn mờ nhạt, chỉ có thể tập trung vào những việc hiện tại. Tuy nhiên, tôi sẽ cố gắng ghi nhớ tên của bạn... Là gì mà nhỉ?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5420_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Bạn trông có vẻ quen thuộc, nhưng tôi không nhớ tên bạn... Bạn là trợ lý của tôi à? Vậy bạn có thể giúp tôi lấy bảy con ốc vít không?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5421_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Tôi đã khắc tên bạn trên tàu Phantom. Một ngày nào đó khi chúng ta cùng nhau đi phiêu lưu, tôi sẽ không quên cách gọi bạn."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5422_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "Rất quen thuộc, rất quen thuộc, giữa chúng ta chắc chắn đã xảy ra điều gì đó phải không? Cho tôi chút thời gian để nhớ lại… À, là cậu đấy, Người Giữ Gìn!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5423_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Bạn thật là một đứa trẻ không thành thực. Rất may là, tôi có đủ thời gian và sự kiên nhẫn để chờ đợi bạn…"
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "\"mọi người đều vui vẻ\", phải không?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Đã thu được một số đầu lâu khá tốt… Mặc dù không thể so sánh với bộ sưu tập tốt nhất của tôi, nhưng chuyến đi tìm kiếm các món đồ mới luôn khiến người ta hào hứng. Lần sau nhớ mời tôi nữa nhé."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Ừm…"},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Một nữ hầu chuyên nghiệp sẽ giúp chủ nhân dọn sạch mọi thứ, kể cả kẻ xấu nhé~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Bây giờ chúng ta coi như là đồng bọn rồi. Nếu một ngày nào đó bạn không còn nơi nào để đi, tôi sẽ không để bạn phải ăn rác để sống đâu."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Phát triển đi, lớn lên đi, chồi non của tôi."
  },
  Voice_5430_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5431_AwakerVoiceContent = {
    Text = "Phát triển đi, lớn lên đi, chồi non của tôi."
  },
  Voice_5431_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5432_AwakerVoiceContent = {
    Text = "Cảm thấy vận may của xúc xắc tăng lên một chút!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Ô hô! Tay thật may mắn!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5434_AwakerVoiceContent = {Text = "May mắn~"},
  Voice_5434_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Không được lại gần tôi."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Không được lại gần tôi."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Tôi phải tố cáo anh, Người Giữ Gìn. Anh đã quá dịu dàng với tôi, điều này khiến tôi rất bất an—— đối với tôi, chỉ có nỗi đau thể xác mới là sự thật vĩnh cửu."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Rất tốt, chăm sóc rất chu đáo."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Điều này quả thật còn quá xa để đủ."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Nói đi, bạn muốn phần thưởng nào?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ôi! Những vết bẩn và hỗn loạn này...... Đôi chân tôi không có nơi để đặt. Vậy thì, hãy dâng tấm lưng mềm mại của ngươi ra, phàm nhân."
  },
  Voice_5441_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5442_AwakerVoiceContent = {
    Text = "Cuối cùng... đã tìm thấy!"
  },
  Voice_5442_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5443_AwakerVoiceContent = {
    Text = "Chỉ riêng bộ lông của Brun cũng trở nên mượt mà."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5443_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Làm bảo vệ thì có chút khó khăn, nhưng những công việc như đi công việc vặt và đưa thư có thể giao cho tôi làm."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5444_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Hãy nhìn xem bạn đối mặt với Brun như thế nào. \n…haha, Brun đại nhân tối nay sẽ ăn ngón chân của kẻ nhát gan, xem ai sẽ xui xẻo vậy?"
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5445_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Không biết có thể cao lên một chút không."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5446_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "Được rồi, được rồi, Brun, hãy cố gắng lên!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5447_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Xin lỗi, tôi đã tiễn đưa quá nhiều người bằng chính tay mình, họ phần lớn đều mờ nhạt, không có đối thủ nào đáng để ghi nhớ."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Agrippa\", bạn sẽ mở khóa"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Nguy hiểm cho thuyền viên… không, chỉ từ góc độ an toàn hàng hải…"
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Pháp Luân Tư"
  },
  Voice_5449_UnlockDesc = {
    Text = "Giải khóa sau khi nhận được thân thể được đánh thức \"Pháp Luân Tư\""
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Đừng đến đây!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "Hãy cẩn thận!"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "Bạn đã hoàn thành lệnh của tôi… Ôi, tôi lại làm mọi thứ trở nên hỗn độn rồi, phải không?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "À, đây chính là linh kiện tôi cần, cảm ơn bạn! … Ơ? Tôi có nhờ bạn giúp tìm không? Tôi không có ấn tượng gì cả, bạn có phải đã nhầm lẫn không?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về linh kiện"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Cảm hứng, liên tục..."
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Gu thẩm mỹ không tồi"
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Bạn đã chọn đúng con dao khắc tốt nhất cho tôi."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Tôi ghét mất kiểm soát. Tuy nhiên, sự tồn tại của bạn đã giúp tôi nhận ra rằng, một chút mất kiểm soát nhẹ nhàng cũng có thể mang lại niềm vui khác biệt."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Có lớn hơn một chút không ?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Thật xin lỗi, tôi rất khó phát triển cơ thể…"
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_54601_AwakerVoiceContent = {
    Text = "Để nhận thức thế giới."
  },
  Voice_54601_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_54602_AwakerVoiceContent = {
