  Voice_54615_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "\"Đúng vậy, đứa trẻ, bạn đã bị dòng sông cuồn cuộn nuốt chửng!\""
  },
  Voice_54616_AwakerVoiceTitle = {
