  Voice_54621_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_54622_AwakerVoiceContent = {
    Text = "Trong hố sâu… sẽ có ánh sáng của công lý."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Tôi là người xé rách xiềng xích — Tokuli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Tôi là người xé rách xiềng xích — Tokuli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Thân này chính là, người tiết lộ tương lai!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Thân này chính là, người tiết lộ tương lai!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Hãy quỳ xuống và thành khẩn hôn chân ta ngay!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ 2"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Tất cả vỏ ốc đều ở đây rồi!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Tất cả vỏ ốc đều ở đây rồi!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Sức mạnh vượt trội, chỉ có thể được chịu đựng bởi thân thể biển sâu. Bạn hẳn là rất ghen tị với tôi, hehe, sinh ra là một con người yếu ớt không phải là lỗi của bạn, cố gắng chấp nhận đi."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5462_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Hãy quỳ xuống và thành khẩn hôn chân ta ngay!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Có thể biến những kẻ thua cuộc này thành nô lệ của tôi không?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Hừ."},
  Voice_5464_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5465_AwakerVoiceContent = {
    Text = "Tuy nhiên, chỉ có vậy thôi."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5466_AwakerVoiceContent = {Text = "À"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5467_AwakerVoiceContent = {Text = "À"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Nếu tôi biết sớm hơn, những người năm xưa đã phải chịu đau khổ vì lời nguyền hủy diệt mọi thứ, tôi... không, biết bây giờ cũng chưa muộn. Tôi nhất định phải xóa bỏ nó, xóa bỏ mọi đau khổ, dù phải trả giá bằng sức sống của mình một lần nữa."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Đừng nản lòng. Biển cả sẽ bao dung tất cả mọi người."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Chỉ với thân hình yếu đuối như vậy, trở thành đồng bạn của tôi vẫn còn quá khó. Đi nào, tôi sẽ đưa bạn đến câu lạc bộ thể thao của học viện để mở rộng tầm mắt và tăng cường luyện tập!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Hãy cho tôi lực lượng, kẻ đáng thương kia, cô ấy đã bị rỗng rỗng hành hạ không ít… Bạn đang nhìn tôi với ánh mắt gì vậy? Đừng nghĩ nữa! Tôi sẽ không nói cho bạn biết cô ấy ở đâu!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Chỉ cần đủ may mắn, bạn cũng có thể chiến thắng trong mọi cuộc chiến."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Có quá mạnh bạo không?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Ài, mọi người ở đây đa số vẫn còn là trẻ con. Vị quý ông kia đã bạc cả tóc và râu, còn chàng trai lạnh lùng kia thì thiếu một cánh tay, đều không phải là lựa chọn hoàn hảo… Thật khó xử."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Có quá mạnh bạo không?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Bùa chú được vẽ cẩn thận, tượng thần được điêu khắc thành tâm, thuốc cấm kỵ được tinh luyện đi tinh luyện lại… một thứ cũng không thể thiếu."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5476_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Ngai vàng phải được xây bằng đá xanh cổ đại khai thác từ biển sâu, bàn thờ phải được bôi đầy máu của lễ vật… Còn không mau đi chuẩn bị?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5477_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Hãy triệu tập tất cả những kẻ đó, họ đáng run rẩy và quỳ gối để đón chào Người đến."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5478_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Tôi sẽ đến di tích biển sâu, tắm trong nước biển được sinh ra từ nơi Người hiện diện……"
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5479_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Chào mừng đến với lễ sinh của Người, cùng chứng kiến ngày sinh của Người... Gì? Bạn nói rằng sự diệt vong của Người cũng là số phận đã định?... Không, hoàn toàn không thể... Tôi đã trả giá quá nhiều.."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5480_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Tuân theo lời răn của Thần."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Bạn bên cạnh, có phải là nơi trở về của tôi và Phiệt không?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5482_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5483_AwakerVoiceContent = {
    Text = "Vâng, vào thời điểm đó, tôi đã mất giọng nói của mình. Chính sự ân điển của ngài đã giúp nó trở lại như ban đầu."
  },
  Voice_5483_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5483_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5484_AwakerVoiceContent = {
    Text = "Tuân theo lời răn của Thần."
  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "Vũ trụ bao la, không gian sâu thẳm vô tận, hành trình không có điểm dừng từng khiến tôi sa vào sự lạc lối…"
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5485_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Phương pháp nâng cao đã đi lối tắt, nhưng việc rèn luyện kỹ năng cũng không được bỏ qua."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "Thì ra phương pháp này cũng áp dụng được cho tôi…"
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Cảm giác kỳ diệu."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "Sự đến của Ngài sẽ chấm dứt nỗi đau do cái chết đen này mang lại, phải không?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Chào buổi sáng, thưa ngài. Nếu ngài muốn ra ngoài điều tra, xin hãy để tôi đi cùng bảo vệ ngài."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5493_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Làm gì? Nếu thấy chán, thì hãy viết báo cáo hành động lần này đi."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Cuối cùng cũng bắt đầu rồi sao? Những con thú cưng nhỏ của tôi đã đói suốt một thời gian dài……"
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Lực lượng của dòng máu đang tuôn chảy mạnh mẽ."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Chờ đã, ta từng thấy thứ này. Trong nước họ cho ta uống có loại dịch đen này. Có lẽ điều này liên quan đến việc ta có được lực lượng của Ngọn Lửa Xanh? Coi như đó cũng là một điều may mắn trong cái rủi."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, hãy gọi tôi là Ramona. Mong chờ sự hợp tác với bạn, Người Giữ Gìn."
  },
  Voice_5498_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5499_AwakerVoiceContent = {Text = "Vâng."},
  Voice_5499_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Lệnh đã nhận."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Hừm, kẻ vô lễ, để bản tiểu thư chơi cùng các người một chút."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Điều gì khiến bạn ghét? Ống thuốc lá vừa hút xong, chuyến xe ngựa không kịp bắt, trời mưa khi đang mang giày da mới. Nói chung, tất cả những điều xui xẻo đều thật sự đáng ghét."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Cờ lê cố định, cờ lê điều chỉnh, cờ lê hoa mai, tua vít dẹt, tua vít chữ thập, vít chìm, vít pan... Chỉ cần có thể sửa được thứ bị hỏng, tôi đều thích."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Ểy ya~ bị cậu phát hiện rồi~ \n Không sao đâu, sức mạnh tinh thần của thân thể được đánh thức phong phú như vậy, ít nhất phải trộm thêm 365 lần nữa họ mới trở thành những con rối vô tri vô giác~ Không làm được sao? Thôi được, lần sau mình sẽ chú ý! Ừm, chỉ lấy một chút \"sợ hãi\" khi cưa cơ thể thôi, không vấn đề gì chứ?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5504_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Này, bạn đã biết bí mật về ảo thuật của Kassia rồi phải không? Ừ, để tránh việc bạn tiết lộ, bạn sẽ phải đi theo tôi~ Hì hì, bạn nói tôi muốn thu thập cảm xúc của bạn? Quả nhiên, không có bí mật nào có thể giấu được bạn!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5505_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Bạn, hãy làm trợ lý ảo thuật của Kasia đi! Đừng sợ~ Chỉ cần chui vào trong hòm ảo thuật của tôi một lát thôi. \n\nĐã trốn kỹ chưa? Tôi sẽ chọc kiếm vào đấy~ À, bên trong không có cơ quan gì đâu."
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5506_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Đến đây, hãy đeo chiếc mũ này! Sau đó, nói cho tôi biết món quà tặng bạn muốn nhất. Được rồi, vậy à, tôi đã hiểu! Bây giờ, hãy sờ vào bên trong mũ —"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5507_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Có chút khó khăn đây. Những đứa trẻ kia mỗi lần đều đến xem biểu diễn, hàng tồn kho của tôi nhanh chóng cạn kiệt rồi… À, một ảo thuật gia không thể biểu diễn cùng một trò ảo thuật trước cùng một nhóm khán giả. Tạo ra những ảo thuật mới? Xin lỗi, tôi không có tài năng như vậy, điều tôi giỏi chỉ là bắt chước mà thôi."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5508_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Trường học này đã cũ kỹ, chỉ có phòng nghỉ của ông hiệu trưởng là vẫn có thể coi là dễ chịu. Quý vị thấy sao?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5509_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Những kẻ ngạo mạn và đê tiện kia, toàn bộ đều sẽ trở thành hồn ma dưới tay tôi."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "Lưỡi dao trả thù, càng thêm sắc bén."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Buổi tụ họp của tôi không trong sáng như một buổi khiêu vũ, ngài đã sẵn sàng chưa?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5512_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Salon của tôi là đất, là vườn, nơi vẻ đẹp và quyền lực quyến rũ sẽ nở rộ…"
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5513_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Lụa mềm, trà đỏ, macaron… Cần thêm hoa hồng còn đọng sương mai để trang trí phòng khách của tôi."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5514_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Không thể thông cảm một chút, để cho khách quý bên ngoài cũng vào học viện được không?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5515_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Lỗi chạy, lỗi, lỗi, lỗi……"
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ya! Bây giờ là mấy giờ rồi! Xin lỗi chủ nhân...... Gia Lân không nên làm việc mà lại mất tập trung! Nhưng thực sự là quá buồn ngủ......"
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Tôi chỉ có thể chờ đợi cái chết sao? Có ai có thể giúp tôi không? Tôi có thể chống lại sự kiểm soát của họ không? Tôi đã tự hỏi bản thân những điều này mỗi ngày, nhưng câu trả lời thực ra luôn ở trong đầu tôi, chỉ là tôi không dám đối mặt mà thôi… Nếu bạn không xuất hiện, tôi không chắc mình có đủ can đảm để chống lại đến cùng hay không. \nCảm ơn bạn lắm——đừng hiểu lầm, đây không phải là lời tỏ tình đâu!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5518_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Tôi sống trong giấc mơ hư cấu của họ, bị một lời tiên tri buồn cười tước mất quyền được sống như một người bình thường, thậm chí không có quyền lựa chọn… Để thoát khỏi cuộc sống như vậy, tôi sẵn sàng làm bất cứ điều gì."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5519_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"Những bông súng thấp thoáng thở than xung quanh, \ngiữa những cây trâm ngủ say, thỉnh thoảng nàng giật mình tỉnh dậy; \nmột con chim run rẩy trong tổ, \ntiếng hát bí ẩn vang xuống từ những vì sao vàng.\"\nÀ, anh có nghe thấy không? Xin lỗi, đây là câu mà tôi rất thích... Anh có muốn cùng đọc không?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về việc đọc sách"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Đừng tùy tiện vào phòng của một quý cô, cũng đừng bình phẩm về dáng vẻ của quý cô. Hãy lui ra nhanh, bản tiểu thư muốn nghỉ ngơi rồi."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5521_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Bạn tốt nhất đừng lên mặt với tôi, nhận rõ thân phận của mình, mở to mắt ra xem ai mới là chủ thật sự."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5522_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Ôi, cần trưng bày sản phẩm không?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Làm tốt lắm. Đã đến lúc uống một thùng rượu rum để mừng chiến thắng!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Biến mất đi."
  },
  Voice_5525_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Giao cho tôi nhé!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "Cảm giác bị tôi dẫm dưới chân, chắc chắn rất tuyệt vời nhỉ~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Nhịn nhé!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Rất tò mò về diện mạo bên dưới chiếc khăn che mắt sao? Vào thời điểm thích hợp, ta sẽ cho ngươi thấy. Đừng quá nóng vội."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Sao lại kết thúc nhanh như vậy?...Hứng thú của tôi mới vừa được khơi dậy."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Này, đừng có chạm vào tôi, chiến binh chân chính không bao giờ dựa vào đồ ngoài."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5531_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Ai Jī Sī đã trở nên mạnh mẽ hơn…… Tôi sẽ dùng đôi mắt này để khiến kẻ địch không thể động đậy!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Đại học Misaque và quân đội không có gì khác biệt. Mỗi chúng ta đều canh gác ở tiền tuyến, vệ sinh vũ khí, chuẩn bị chiến đấu."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5534_AwakerVoiceContent = {
    Text = "Hoàn hảo!"
  },
  Voice_5534_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5535_AwakerVoiceContent = {
    Text = "Hoàn hảo!"
  },
  Voice_5535_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Tôi có thể bị xích lại, có thể bị kéo tóc quỳ trước mặt bạn, làm nô lệ của bạn. Những điều này không thành vấn đề — chỉ cần cho tôi giết người, nhà điêu khắc, người cầm đèn, bà lão hen suyễn đi ngang qua... bất cứ ai, tôi đảm bảo sẽ giúp bạn xé toạc họ ra, uống cạn máu của họ."
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5536_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Từ vết thương bị rỗng rỗng chảy ra, ngoài chất nhầy màu đen, còn có cảm hứng liên tục không ngừng. Nói thật, tôi không ngại nhận thêm một chút."
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Sợ hãi? Ha ha ha ha, vậy là đúng rồi! Đi chết đi, tôi chỉ muốn nếm thử nỗi sợ của các người."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5538_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Thú vị, mùi máu của bạn nếm thử... rất ngọt ngào, như rượu ngọt vậy."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5539_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Lúc đó, hàng vạn người cùng reo hò tên tôi, biển \"Yu U Hahi\" nhấn chìm mọi thứ, mừng việc tôi vừa bẻ gãy cổ một kẻ đầu trọc hèn nhát. Cảm giác thật tuyệt vời, là đồng bạn của tôi, bạn chắc chắn sẽ hiểu."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5540_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Đợi, đợi đã!"
  },
  Voice_5541_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5542_AwakerVoiceContent = {Text = "Đừng!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Đau!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5544_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5544_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Đang tìm kiếm \"rỗng rỗng\" trong hồ sơ rộng lớn… Không cần thiết? Bạn muốn biết thái độ của tôi với \"rỗng rỗng\" chứ? Tôi hiểu rồi, đang thức tỉnh hệ thống để tìm kiếm \"vũ khí chống rỗng rỗng\"… Kết quả: 「0」."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Vật giả tạo, yếu đuối như khói bụi, chỉ cần một làn gió nhẹ là có thể thổi tan……"
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_5546_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Có vẻ hơi ồn ào, là học sinh sao? \nHọ thật sự rất giống những chú chim tín thiên ông, bạn có biết về loài chim ấy không? Sức sống vô tận, dường như hành trình của chúng chẳng bao giờ kết thúc…"
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Hì hì"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hừ"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Trong học viện, chỉ có mỗi Ramona là có chút thú vị. Cô ấy có năng khiếu đặc biệt về kiếm thuật, còn lại toàn là những kẻ rập khuôn... Bạn không phải cũng vậy chứ? Bạn thực sự nghĩ rằng viết báo cáo hành động là thú vị sao?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Không đáng kể."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "Các người mẹ không hoàn toàn giống nhau. Có những người mẹ tốt và cũng có những người mẹ xấu. \n Chủ nhân là một người mẹ tốt."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5552_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Là do tôi không thể bảo vệ ngài.."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Đã đặt sân chưa? Cần vườn lớn hơn một trăm năm mươi mét vuông (150 m²) nhé!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5554_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Máu của người sắp chết là một chất lỏng nhầy nhụa. Chỉ cần một đường cắt nhẹ trên cổ, máu sẽ chảy qua kẽ răng, biến thành những dòng ấm áp mảnh mai, từ từ nhỏ giọt vào bụng tôi... hehe, thật ngon lành."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về máu"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Á"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Ê!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5558_AwakerVoiceContent = {Text = "À"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Cảm ơn sự từ bi của ngài, đã cung cấp nơi trú ẩn cho tôi. Hy vọng tôi không mang đến điều không may cho ngài…"
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Tôi đến từ một hành tinh xa xôi. Nơi đó, gió tuyết hoành hành và khí hậu cực kỳ lạnh giá. Tuy nhiên, không sao cả. Trong dinh thự của tôi có hơn một nghìn người hầu, sự thân thiết và tình cảm họ dành cho nhau khiến lòng người ấm áp lạ kỳ."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Lời rỗi·về quá khứ"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Trước khi chào đón sự trở về của ngài, tôi không thể gục ngã tại đây."
  },
  Voice_5561_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5562_AwakerVoiceContent = {
    Text = "Trước khi chào đón sự trở về của ngài, tôi không thể gục ngã tại đây."
  },
  Voice_5562_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5563_AwakerVoiceContent = {
    Text = "Ôi trời ơi, thế gian làm sao có thể có khách kiêu ngạo như vậy, muốn \"vũ khí tốt nhất trên thế giới\"? Tôi nói với anh ta, cần dùng đầu lâu ngập tràn hận thù để đổi, anh ta liền vẻ mặt khó chịu rồi bỏ đi..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Goliath"
  },
  Voice_5563_UnlockDesc = {
    Text = "Mở khóa sau khi có thân thể được đánh thức \"Goliath\""
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Dáng vẻ đầy tự tin của cậu, như thể sẵn sàng hy sinh vì \"cứu thế giới\" bất cứ lúc nào, khiến người khác nhìn vào cảm thấy ngứa ngáy khó chịu."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5564_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Trước khi các người ban hành lệnh cấm nghiên cứu, chỉ còn một chút nữa thôi, tôi đã có thể để Sự Diệt Vong bao phủ cái gọi là Bunker Rỗng Rỗng này... Thật đáng tiếc, biết bao tiếc nuối."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5565_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Có, tôi có vô số thân thể dự phòng và cũng có vô số cơ hội để trốn thoát khỏi sự tan chảy. Nhưng, khi một con đường dẫn đến chân lý mở ra trước mắt, không một học giả nào có thể cưỡng lại. Tôi đã đáp ứng khát vọng trong lòng mình, và vì điều này, tôi không hề hối tiếc."
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5566_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "Sự thật của thế giới, điểm khởi đầu của thế giới, điểm cuối cùng của thế giới, tất cả đều là những thứ vô nghĩa. Nếu bạn cũng muốn bước trên con đường dẫn đến sự thật, tôi không ngại trở thành người hướng dẫn của bạn… giống như những gì chúng ta từng trải qua."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5567_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Các người có thể ngăn cản tôi, nhưng sự kết thúc không thể bị chặn đứng… Tôi sẽ giữ lại ngôi trường này, giữ lại cậu đến cuối cùng. Chúng ta sẽ đứng trên ngọn tháp, tắm trong ánh hoàng hôn của thời gian, chứng kiến sự sụp đổ của văn minh… Phải chăng, làm vậy, không phụ lòng tình bạn giữa chúng ta?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5568_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5569_AwakerVoiceContent = {
    Text = "Được thôi."
  },
  Voice_5569_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "Biến mất đi."
  },
  Voice_5570_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Mong rằng lời cầu nguyện của tôi sẽ trở thành tiếng chuông thức tỉnh cho đất nước xưa…"
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Tôi không nghĩ rằng sẽ có ai khác ngoài Tinkerer chấp nhận tôi. Tôi rất mừng vì đã gặp bạn, Người Giữ Gìn. Tôi sẽ dốc hết sức để học cách kiểm soát lực lượng. Như vậy, khi tôi ôm bạn sẽ không hút cạn sức sống của bạn nữa... Đó là hành động ôm, đúng không? Cách mà con người bày tỏ sự cảm kích?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5572_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Tôi ở lại đây, có cần phải trả thù lao gì không? Tôi có thể giúp bạn nâng cao địa vị ở đây. Chỉ cần khéo léo đe dọa sẽ hút cạn sức sống của họ, rất đơn giản, giống như trước kia tôi đã giúp tinkerer vậy… À! Cái, cái chuyện này bạn tuyệt đối đừng nói cho ai khác nhé!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5573_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Xin lỗi, tôi khác với những người cùng loại, là một sản phẩm kém chất lượng…"
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5574_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Một người hầu nữ xuất sắc có thể làm tăng vẻ đẹp cho salon, nhưng một người hầu nữ màu xanh ngọc… để tôi suy nghĩ thêm…"
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Gia Lân"
  },
  Voice_5575_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Gia Lân\""
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Tinkerer là em gái song sinh của tôi, khác với tôi, cô ấy luôn tỏa sáng……\nNếu không có gánh nặng từ tôi, cô ấy chắc chắn sẽ có một tương lai tươi đẹp hơn, giọng hát của cô ấy sẽ vang vọng khắp cả hệ sao……"
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5576_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "Giường nôi rất chật, không có cách nào để duỗi thẳng thân thể… nhưng Tinkerer đã nói rằng, vì sự an toàn của mọi người, cô ấy muốn tôi đừng rời khỏi giường nôi… Vì cô ấy mong muốn như vậy, tôi sẽ nghe theo."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5577_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Tôi thường xuyên cảm thấy mình đang ở trong khe hở giữa sự sống và cái chết. Chỉ cần nơi tôi hiện diện, nỗi buồn lan tỏa như sóng triều, bi kịch nối tiếp nhau kéo đến. Dù vậy, bạn vẫn muốn tôi viết thơ cho bạn sao? Ừm… có lẽ, bạn xứng đáng với một bài thơ ngọt ngào nhất.."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5578_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"Đóa hồng chưa nở, bình minh đã đến rồi.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5579_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Bạn khao khát điều gì? Là vẻ đẹp đượm chất thơ và sâu lắng, tiếng tăm vang dội khắp bốn bể, hay là trái tim chân thành đang chảy máu đằng sau những câu từ ấy?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5580_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Bằng mực vô hình, khắc họa những nụ hoa quái dị... Cành hoa hồng ma mị này lại có thể khơi dậy cảm hứng thi ca.."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5581_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Xin hãy lắng nghe lời của chủ nhân."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Thức tỉnh linh tri · Nhị"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Hy sinh! Tái tạo thần quốc ——"
  },
  Voice_55826_AwakerVoiceTitle = {
    Text = "Thức tỉnh linh tri·ba"
  },
  Voice_5582_AwakerVoiceContent = {
    Text = "Nếu ngài kiên quyết, tôi sẽ bước trở lại dưới ánh nắng… ánh nắng y hệt như ngày tôi rời khỏi Tây Đài ấy…"
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5582_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "He he, bạn có muốn thấy vũ trụ bị hủy diệt không? À, bây giờ hối hận thì đã muộn rồi!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5583_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Uống đi, cái chết ngọt ngào."
  },
  Voice_5584_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5585_AwakerVoiceContent = {
    Text = "Uống đi, cái chết ngọt ngào."
  },
  Voice_5585_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5586_AwakerVoiceContent = {
    Text = "Đến đây là đủ!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Đừng…"},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Hãy chứng kiến uy nghi của **Dư**."
  },
  Voice_5588_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5589_AwakerVoiceContent = {
    Text = "Không khí ở trường đại học vào lúc 4 giờ sáng thật dễ chịu, tôi rất vui vì bạn đồng ý tập luyện cùng tôi. Thực sự phải nói, điêu khắc là một công việc đòi hỏi nhiều sức lực."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về buổi sáng"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Lực lượng này, sử dụng khá tốt."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5590_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Tôi ghét những người mua hàng mà không trả tiền. Nếu cửa hàng hoạt động đủ lâu, chắc chắn sẽ gặp phải loại rắc rối này. Không có cách nào khác, tôi cũng chỉ có thể tự mình ra tay, thu hồi hóa đơn~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Hành hạ từ từ."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Hành hạ từ từ."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Tải."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5595_AwakerVoiceContent = {
    Text = "Bắt đầu."
  },
  Voice_5595_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Hãy biến nơi đây thành đại dương sôi động của mọi người!"
  },
  Voice_5596_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5597_AwakerVoiceContent = {
    Text = "Sao, mong đợi tôi cảm ơn bạn sao?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Như một món đồ cúng thì hoàn toàn không đủ tiêu chuẩn…… nhưng vì tấm lòng chân thành của bạn, tôi sẽ miễn cưỡng nhận lấy."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Bạn nghĩ chỉ cần như vậy là tôi sẽ nghe lời bạn sao?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Ha a!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5601_AwakerVoiceContent = {Text = "Lên!"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Quái vật bạc nghĩa, sát thủ, kẻ giết người, cũng có giá trị được ngươi công nhận sao? Người kỳ lạ."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5602_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Dù có chất chồng bao nhiêu đệm mềm, ngai vàng lapis lazuli cũng không thể sánh bằng giường lông vũ. Từ góc độ này, nơi này của các ngươi còn có vài điểm đáng giá."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Hình phạt nhỏ"
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Tôi ghét sự cô đơn, ghét việc phải lo lắng về cảm xúc của người mà tôi quan tâm trong bóng tối không thấy được cuối đường… Vì vậy, xin hãy đừng bỏ rơi tôi, được không?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Nếu tôi là bạn, tôi sẽ nhốt tất cả thân thể được đánh thức vào trong lồng! Khi chó điên thoát ra, nó luôn cắn chết chủ nhân đầu tiên."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5606_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Lần gặp mặt này tôi đã muộn một giờ —— đều tại những kẻ tự nhận làm điều tốt đã lật đổ chế độ nô lệ, bây giờ chẳng còn ai chải đầu cho tôi nữa!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5607_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Khó có thể tưởng tượng, quê hương của tôi lại bị tiêu diệt như vậy… Đó chính là La Mã vĩ đại! Bạn chắc chắn đã từng nghe nói!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5608_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Thử nào, thắng một trận mở màn!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Đây chính là phúc lành mà chủ nhân ban cho tôi."
  },
  Voice_5610_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5611_AwakerVoiceContent = {
    Text = "Đừng nhìn tôi với ánh mắt thương hại nữa, tôi không thích và cũng không cần ai thương hại. Nếu còn tiếp tục nhìn tôi như vậy, tôi sẽ không nhịn được mà tàn nhẫn hành hạ bạn… Bạn cũng không muốn mọi chuyện trở nên không thể cứu vãn chứ? Vậy thì, ngoan ngoãn một chút, nghe lời một chút, làm tốt vai trò đấu sĩ của tôi…"
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5611_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Đừng*tắt tiếng*nữa. Tôi đã sơ suất, chủ quan, để đấu sĩ trốn thoát, khiến cả gia đình đều chết! Giống như Đế quốc La Mã, bị thiêu rụi đến tận tro tàn!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5612_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "So với những người đầy tài năng, Ninh Phi Nga chỉ là một người bình thường chưa từng lập được thành tích hay tạo ra giá trị đáng kể. \n Điều khiến tôi được đánh thức… có lẽ chỉ là những nguyện vọng nhỏ bé và khiêm nhường thôi…"
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Hôm nay tôi lại vi phạm nội quy, đi học muộn 5 phút…… Vì vậy, tôi thành khẩn xin chịu hình phạt nghiêm khắc nhất, nếu do Người Giữ Gìn thực hiện thì càng tốt."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Công cụ cũng cần được bảo trì đấy, một bộ công cụ vừa tay chính là bản chất của thợ cơ khí."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5615_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(khinh thường nhưng cố nhịn)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Nếu có lần sau, tôi sẽ đề nghị xem xét giữ bạn lại trường."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Ngoài chiến đấu, tôi đương nhiên còn có công việc khác để làm. Dù ở thời đại Thái Cổ, tôi cũng không phải là người rỗi việc… Này, cậu đừng có thật sự coi tôi là một thằng chỉ biết đánh nhau đấy nhé!"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về công việc"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Khi mọi người đến gần tôi, họ luôn nhớ lại những trải nghiệm buồn nhất trong cuộc đời mình và không thể kiềm chế được nước mắt. Liệu tôi có thể trưởng thành không?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5619_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "Phải không?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Đây tốt hơn nhiều so với nhà tù Newgate bẩn thỉu và hôi hám! Nằm trên sofa thì thoải mái, dựa vào góc tường cũng dễ chịu đấy chứ?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5623_AwakerVoiceContent = {
    Text = "Brun……!"
  },
  Voice_5623_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5624_AwakerVoiceContent = {
    Text = "Vỏ ốc, đi đâu rồi…"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5625_AwakerVoiceContent = {
    Text = "Xảo trá!"
  },
  Voice_5625_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Vỏ ốc đâu mất rồi!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "Dòng Ngân Hà……"
  },
  Voice_5627_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5628_AwakerVoiceContent = {
    Text = "Ô Ryta không thích những người bạn đột nhiên bỏ đi… nhưng, nhưng nếu họ còn quay lại, Ô Ryta sẽ tha thứ cho họ!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Phụ nữ có thể điều khiển con thuyền vượt qua đại dương, ngoài nữ thần, còn có phụ nữ liều lĩnh. Lúc đầu tôi đã coi Miriam là nữ thần, đó thực sự là một sai lầm lớn."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về MIRIAM"
  },
  Voice_5629_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Miriam\"để mở khóa"
  },
  Voice_5630_AwakerVoiceContent = {Text = "Ừm!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Tôi đã lén đi xem màn ảo thuật của cô Kassia. Biểu diễn của cô ấy đã mang lại nhiều niềm vui cho khán giả, nhưng tôi thì luôn mang đến nỗi buồn cho mọi người… Ngài có nghĩ rằng, nước mắt và nụ cười, đều là những thứ quý giá như nhau không? Có lẽ…"
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Kassia"
  },
  Voice_56313_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Kassia\""
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Thơ, ngọn lửa và nỗi buồn là những thứ tương tự, chúng sẽ nuốt chửng bạn mà không hay biết… Khi bạn nhận ra, đã chìm đắm trong thế giới của thơ rồi…"
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Bài thơ từ thuở uyên ương, mở ra cánh cửa khu vườn trong tim."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Thơ ca và hoa, có lẽ là cùng một thứ? Tương tự như nhau, ngắn ngủi nhưng sâu sắc, trên thế giới vô tận này, chỉ cần một khoảng không gian nhỏ, đã chứa đựng những khoảnh khắc in sâu vào tâm trí… Tôi nghĩ, tất cả mọi người đều từng im lặng vì một bài thơ, giống như dừng lại ngắm nhìn một bông hoa nở vậy."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về thơ"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Tôi đã gần như quên mất… mùa này ở Tây Đài sẽ nở những loài hoa gì?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Tây Đài"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Bạn đã khiến mực trong bút của tôi tụ lại thành dòng chảy nhẹ nhàng, và tôi cũng sẽ viết tiếp những vần thơ cho câu chuyện của bạn."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Lời bâng quơ · Về Người Giữ Bí Mật 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "Hoa nở đẹp biết bao nhiêu, thì hoa tàn cũng buồn bã biết bấy nhiêu. Dù có buồn bao nhiêu lần đi nữa, tôi vẫn không thể cưỡng lại được việc dừng lại, thương xót những bông hoa ấy. Nếu vì sợ đau khổ mà làm ngơ trước chúng, thì những bông hoa ấy sẽ buồn biết bao nhiêu…"
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Lời nói · về nỗi đau"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Để nghiên cứu cấu trúc nội bộ của thân thể này khi Erika \"ngủ\", Wenkel yêu cầu tôi đến văn phòng của cô ấy vào ban đêm để ngủ. \nCó cần thông báo rằng, khi Erika ngủ, cô vẫn giữ một phần ý thức?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Wenkel"
  },
  Voice_5631_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Vị phu nhân đỏ thật đẹp. Sự mạnh mẽ và tự tin, nụ cười tao nhã trước số phận, cùng sức sống mãnh liệt như hoa hồng đỏ của cô ấy khiến tôi vô cùng ngưỡng mộ…"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Sorrel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Sorrel\""
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Tôi hôm qua vừa viết một bài thơ mới, chưa cho ai xem cả. Viết không tốt, nhưng… Người Giữ Gìn, có muốn xem không?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về Người Giữ Gìn 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Hội thơ sinh viên mong tôi trở thành người hướng dẫn của họ…… Tôi không thể đồng ý. Tôi không muốn làm mất hứng thú của giới trẻ, nhưng tôi chỉ mang lại cho họ sự thất vọng và u uất."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Không có gì đáng ghét trong thế gian này. Thời vàng son đáng ca ngợi, còn tuổi xế chiều thì đáng thương cảm; trang phục của tuổi trẻ khiến người ta ngưỡng mộ, còn hình ảnh tàn phai gợi lên sự hoài niệm."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Mỗi lần nhìn thấy cô Ninh Phi Nga, tôi đều nhớ đến bức tranh vẽ hoa súng. Trên người cô ấy, có sự thanh bình, đắng cay nhẹ nhàng và hương thơm tinh khiết như hoa súng… Không biết thế giới trong mắt cô ấy sẽ ra sao?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Ninh Phi Nga"
  },
  Voice_56324_UnlockDesc = {
    Text = "Sau khi nhận thân thể được đánh thức \"Ninh Phi Nga\", sẽ mở khóa"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Từ trước đến nay, tôi luôn cảm nhận được sự tồn tại của \"ma\" xung quanh mình, giống như một loại hiện tượng nhập thân khó giải thích, hoặc là bị ám ảnh. Nó khiến tôi dần mất đi hy vọng vào thế giới này. Nhưng nếu đó là ma, thì việc sữa và nước sạch biến mất không rõ nguyên nhân lại càng khó lý giải hơn…"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về hồn ma"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Thân thể tôi chưa bị xâm nhiễm bởi rỗng rỗng, chất lỏng đen đó chẳng qua chỉ là mực đậm đặc mà thôi. Nhưng nói đi cũng phải nói lại, ngay cả khi không có rỗng rỗng, sự tồn tại của vạn vật cũng sẽ biến thành hư vô, phải không?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Trong bia mộ của Yếu Trủng, tôi đã nhìn thấy tên của Người Giữ Gìn… Ký ức về cuộc sống trước đây thật đau đớn, nhưng tôi chưa bao giờ nghĩ đến việc quên chúng. Đối với Người Giữ Gìn, những ký ức đã mất hẳn cũng rất đáng trân trọng."
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về ký ức"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Nếu như thơ ca tồn tại để ca ngợi cái đẹp, thì sự tồn tại của cô ấy giống như chính bài thơ. Khi cô ấy bắt đầu hát, tôi đột nhiên hiểu được các tiền bối đã miêu tả giọng hát như chim hoàng oanh……"
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chuyện trò·về tinkerer"
  },
  Voice_56328_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"tinkerer\""
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "Vị vũ công tuyệt sắc… ngọn lửa xanh lục bảo trên người cô ấy khiến người ta không thể cưỡng lại được việc muốn chạm vào, dù bị thiêu rụi hoàn toàn cũng không sao…"
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Giải khóa sau khi nhận được thân thể được đánh thức \"Liz\""
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Liệu cách này có thể thay thế việc hút nguyên chất được không?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Ngon, rất ngon."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Thưa quý khách, quý khách muốn phần thưởng như thế nào?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Hãy kết thúc nhanh đi, đừng nán lại trên đường phố."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Sự hy sinh không thể tránh."
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(nhẫn nại khịt khịt)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Dòng điện đã được nhập.Dòng điện phát ra."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Đừng coi thường thần trộm đầu đường!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Dâng lên lời ca ngợi khai mạc!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Những ảo ảnh ngàn mặt đang dần hiện ra tại đây!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Gần hơn rồi…"
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5638_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Hãy chìm đắm đi,hãy bùng cháy đi!Vũ điệu báo tử!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Đây là thành phố mà hàng vạn người chết lang thang, mất đi quê hương của mình."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Hãy để tôi trao cho bạn, năng lượng di chuyển còn lại của tôi…!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Đừng coi thường thần trộm đầu đường!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = "Có phải là kẻ địch không? Hãy cho tôi lệnh tấn công. \n Chất nhầy màu đen là kẻ địch... Lily cũng là kẻ địch?"
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Người máy tự động Erika, số hiệu thân EA307881, số hiệu mô tơ MF311028. Rất vui được phục vụ bạn."
  },
  Voice_5640_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5641_AwakerVoiceContent = {
    Text = "Hãy chiến đấu hết sức trước khi kẻ địch hoàn toàn sụp đổ!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Xin chào, tôi là…… bạn có thể cho tôi biết tên mình là gì không?"
  },
  Voice_5642_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5643_AwakerVoiceContent = {
    Text = "Khi đến trường, tôi mới hiểu được căn bệnh mà tôi đã bị lây nhiễm, gọi là rỗng rỗng. Trước đây, cha mẹ luôn mong muốn tôi tránh xa đại dương, và giờ đây xem ra, sự lây nhiễm này có thể thực sự liên quan đến việc tôi tiếp xúc với đại dương…"
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "Được rồi, tôi sẽ không làm bạn \"thất vọng\"."
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Hơi thở nóng bỏng này——"
  },
  Voice_5645_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5646_AwakerVoiceContent = {Text = "Đi nào."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5647_AwakerVoiceContent = {Text = "Xoay đi."},
  Voice_5647_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5648_AwakerVoiceContent = {Text = "Ôi!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "Cuối cùng ngày này đã đến……"
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Tôi vẫn chưa đã hết mình… hay là ngươi bò dậy, để tôi giết lại một lần nữa nhé?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Người giữ bí mật, tôi phải nói chuyện với anh. Trước khi chúng ta đạt được chiến thắng cuối cùng, một số người không nên sống xa xỉ và lãng phí như thế. Hãy nhớ, tôi không chiến đấu vì cuộc sống quý tộc của những người như thế."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Sorrel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Sorrel\""
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Nếu bị bắt làm tù binh, số phận khắc nghiệt nào đang chờ đợi tôi đây?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Xem chiêu!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Phù——rất buồn ngủ, trước khi nghỉ ngơi, các bạn đã chuẩn bị sẵn đồ uống và bánh ngọt để thư giãn chưa?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mẹ, bà có muốn sờ chúng không? Chúng rất mềm mại, người ta nói."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5659_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hừ hừ hừ, la la la~ dọn dẹp thôi, tôi yêu dọn dẹp, tâm trạng thật tốt~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về công việc"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(tiếng rên đau đớn khó chịu)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Ừm…… không tồi."
  },
  Voice_5662_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5663_AwakerVoiceContent = {
    Text = "(tiếng rên đau đớn khó chịu)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(tiếng rên đau đớn khó chịu)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Nộ hỏa đốt cháy!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Tôi thấy không ít người phát điên vì rỗng rỗng. Thực ra, tôi đã đủ điên rồi, rỗng rỗng có lẽ chẳng ảnh hưởng gì đến tôi."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Hế~ hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5668_AwakerVoiceContent = {
    Text = "Công cụ tốt là một nửa thành công!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Cảm giác như được sống lại vậy."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Khá tốt."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Có thể vung ra một kiếm mạnh hơn."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Phải duy trì tỷ lệ điểm danh, phải duy trì tiến độ nghiên cứu, còn có nhiệm vụ hướng dẫn cần hoàn thành. Xem ra, thí nghiệm đảo ngược quá trình nén thời gian cần được đưa vào kế hoạch."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5672_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Chúng ta lại tiến thêm một bước tới cuộc phiêu lưu chính thức."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Đừng để người khác tiếp cận nước nhé, ngọn lửa tình yêu của bạn sẽ tắt mất đó?"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Chiến đấu đến cùng!"
  },
  Voice_5675_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5676_AwakerVoiceContent = {
    Text = "Bạn thật sự rất can đảm. Nhìn những xúc tu này, bạn chẳng sợ bị điên rồ nuốt chửng sao?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
