  Voice_5678_AwakerVoiceContent = {Text = "Đau……"},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Hãy dừng lại!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Muốn chạm thử không? Trái tim tôi đang rung động vì sự hiện diện của bạn."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5680_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Chúng chí chóe, rất vui vẻ. Cảm ơn ngài, chủ nhân ạ."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5681_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Có cái gì đó đang thức tỉnh trong ngực… ấm áp, nước mắt của Lily, Lily, sắp… \nMẹ ơi, hãy cùng ăn mừng đi."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5682_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Ở bên mẹ, sẽ có cảm giác hạnh phúc."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5683_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Đã no rồi… Bụng căng tròn. \nSau khi lễ hội kết thúc, Lily có trở nên mạnh mẽ hơn không?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5684_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Tôi thích biển, có phải rất mỉa mai không? Vì tất cả những gì tôi có đều đã chìm xuống biển sâu…"
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Cẩn thận!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Điều ghét...? Không có đâu. Bạn có từng ghét một hạt bụi, hay một chiếc lá không?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Tôi đã từ chối lời mời tham dự bữa tiệc của cô hầu gái vài lần, cô ấy trông có vẻ buồn bã… nhưng so với việc vui chơi, sự an toàn của chủ nhân đương nhiên quan trọng hơn!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Gia Lân"
  },
  Voice_5688_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Gia Lân\""
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Chủ quân là lý do tồn tại của kị sĩ, nên xin hãy cứ sai khiến tôi!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "... có thể cần dùng đến cờ lê lực... ừ, xin lỗi, bạn vừa gọi tôi à?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "Quá táo bạo!"
  },
  Voice_5692_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5693_AwakerVoiceContent = {
    Text = "(những tiếng hú nhẹ nhàng)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(nhẫn nại khịt khịt)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Thôi đủ rồi."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5696_AwakerVoiceContent = {
    Text = "Dịu dàng hơn đi."
  },
  Voice_5696_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Quả nhiên vẫn khó để tập trung tinh thần…"
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Cô ấy ban đêm thường hay ở gần tôi, có phải cái đầu lâu của tôi quá nổi bật không?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Wenkel"
  },
  Voice_5698_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Tôi luôn chờ đợi sự hủy diệt đến, nhưng chưa bao giờ nghĩ rằng còn có lựa chọn \"chống lại\"... Ngài có nguyện đưa linh hồn nông cạn này vượt qua sự hủy diệt không? Trong thế giới thoát chết, vẫn ban cho tôi sự cứu rỗi.."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5699_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Vì đã được thức tỉnh như một sứ đồ của ngài, điều tôi mong muốn duy nhất chính là sự bình an và niềm vui của ngài… Ừm a… A… Quả nhiên, chỉ cần tồn tại, tiếp tục sống… là đủ"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5700_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Hãy thử không chìm đắm trong tình yêu của tôi? Bạn đã thức tỉnh tôi, lẽ nào không phải vì hơi ấm trong vòng tay tôi sao?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5701_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Không muốn dây dưa với người phụ nữ có nguồn gốc không rõ ràng phải không? Được rồi, được rồi. Vị vua đã mất nước của Niniveh, người có ý định thông thiên từ vùng đất Sư tử, thiếu nữ bị tước đoạt ý chí dưới gốc cây Thánh Euphrates… Ngài muốn nghe từ đâu đây?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5702_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Tại sao bạn luôn tránh tôi vậy? Có phải là vì ngại không? Thật đáng yêu, dáng vẻ bạn không dám đối mặt với dục vọng của mình.."
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5703_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Thật là một nơi kinh khủng! Sao có thể để tiểu thư ta ngồi chung bàn uống trà chiều với người khác!... Bánh quy tự làm mùi vị cũng tạm được, sau bữa tối mang một ít tới phòng ta."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Hây da!"},
  Voice_5705_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "Xem chiêu!"
  },
  Voice_5706_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Tan biến… thư viện quê hương có ghi chép liên quan, nhưng Gia Lân vốn ghét đọc sách, quên hết sạch rồi!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Bạn có muốn tôi tiếp tục hành trình không? Nếu bạn không phiền về những khuyết điểm trước đây của tôi, tôi sẽ thử làm như vậy."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5708_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Điều ghét nhất ư? Có quá nhiều——ông chủ bắt công nhân làm việc tới khuya, nữ tu sĩ kiêu ngạo, cái bụng réo ùng ục vì đói, bánh mì đen cắm đầy mảnh thủy tinh…"
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Là lỗi của Ai Jī Sī, tất cả đều là lỗi của tôi…"
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Kết thúc thôi!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Nhờ sự chăm sóc của cô Hanna, tôi đã được tham gia buổi tập luyện của dàn hợp xướng. Hát thánh ca và hát trên thuyền rất khác biệt. Trong thời gian bảo vệ con tàu, tôi chưa từng nghe những giai điệu đặc biệt đến thế…"
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Chiêu này thế nào!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Chiêu này thế nào!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "Rất đáng sợ~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Ư......"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Xin chào, chủ nhân mới của tôi! Món ăn hôm nay có pudding ốc sên, canh ếch và rượu Lửa Xanh, chủ nhân cứ thoải mái lựa chọn nhé~"
  },
  Voice_5717_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5718_AwakerVoiceContent = {
    Text = "Đó là hình dạng trở về nguồn gốc sao…… Không, không hoàn toàn giống với những gì tôi tưởng tượng. Nhưng, nếu tôi cũng có thể biến thành như vậy thì thật tuyệt vời."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về dòng máu biển sâu"
  },
  Voice_5718_UnlockDesc = {
    Text = "Sau khi nhận một trong các thân thể được đánh thức \"tulô\", \"Muphí\", \"Miriam\", \"Goliath\" sẽ mở khóa"
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Đợi thời cơ."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "Xem chiêu!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Cừu con ơi, lòng thương xót của Chúa sẽ cứu chuộc các con."
  },
  Voice_5721_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5722_AwakerVoiceContent = {
    Text = "Cừu con ơi, lòng thương xót của Chúa sẽ cứu chuộc các con."
  },
  Voice_5722_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5723_AwakerVoiceContent = {
    Text = "Chết đi!"
  },
  Voice_5723_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "Cô ấy cũng là một người đáng thương, cuối cùng sẽ bị số phận dày vò. Bởi vì, lúc Người thực sự giáng sinh, chính là lúc tôi ban cho cô ấy cái chết."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về MIRIAM"
  },
  Voice_5727_UnlockDesc = {
