  },
  Voice_5733_AwakerVoiceContent = {Text = "Đau……"},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Bạn có muốn cùng tôi chìm xuống không?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5735_AwakerVoiceContent = {
    Text = "Biến đi!"
  },
  Voice_5735_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5736_AwakerVoiceContent = {
    Text = "Đồ vật ghét... bàn học lộn xộn, tủ quần áo bừa bộn, bệ cửa sổ đầy bụi —— đúng vậy, tôi đang mô tả phòng của bạn. Trước bảy giờ sáng mai, tôi muốn thấy nó trở lại như lúc bạn mới dọn vào."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(hừm nhẹ với hứng thú)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Có ý nghĩa!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(cười nhạo khinh miệt)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Nếu cần thiết, tôi có thể rời khỏi nôi.."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Có muốn không?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5742_AwakerVoiceContent = {
    Text = "Xem~ chiêu!"
  },
  Voice_5742_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "Gấp đôi! Gấp đôi! Gấp đôi!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Điều này khiến tôi nhớ đến đôi giày múa đỏ đầu tiên mà tôi nhận được khi tám tuổi. Tôi thực sự rất thích, cảm ơn ngài, Người Giữ Gìn."
  },
  Voice_5744_AwakerVoiceTitle = {
