  Voice_5745_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Sự bảo vệ của tôi, cũng có lúc không còn hiệu quả……"
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5747_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_5747_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5748_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5748_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5749_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5749_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Thích điều gì? Trên chiến trường Peloponnesian, cũng đã có người hỏi tôi câu này... Quá muộn, tôi đã từ lâu từ bỏ những sở thích cá nhân như vậy."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Shhh... về việc tôi trở nên mạnh mẽ hơn, đừng để \"họ\" phát hiện."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"các cô ấy\" nói... rất cảm ơn."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Cái đó... đây là gì?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Điều này chỉ khiến tôi càng gần vực thẳm."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5754_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Bạn là người hầu yêu quý của tôi. Tôi biết, các bạn gọi đó là bạn bè, đồng đội, đồng chí... không sao cả, tùy bạn thích."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Tôi đã nhận được câu trả lời… dù đó không phải là điều tôi mong đợi, nhưng tôi đã nhận được câu trả lời."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5756_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Là \"sợ hãi\" sao? Hay là \"buồn bã\"? Khuôn mặt thất vọng của bạn thật cuốn hút."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5757_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Mùi vị của cái chết và sự tiêu diệt, thật rõ ràng."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5758_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Cuộc sống ở đây? Khá, khá tốt. Nếu tôi chia sẻ với cô đóa một vài kiến thức về khoa học cơ khí và nghiên cứu tinh thần, cô ấy sẽ cho phép tôi giữ đèn luôn bật."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Hy vọng Jenkin và Brun sẽ vui vẻ tại học viện. Khuy măng sét của cha cô ấy, so với sự tự do của cô ấy, không đáng kể. Tôi tin rằng ông ấy còn có cả một hộp dự phòng."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_5760_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Không thể rời đi……"
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Tôi đã thoát khỏi chủng tộc thấp kém, hoàn toàn không sợ hãi ảnh hưởng này. Ngay cả khi thân thể bị vỡ tan, dòng máu cao quý cũng sẽ không bao giờ tiêu biến."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Ghét những kẻ cười giả tạo! Chẳng thể moi được chút cảm xúc nào từ họ!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Ừ? Mọi người sao lại im lặng vậy? Gia Lân ghét sự yên tĩnh, để tôi kể cho các bạn một câu chuyện nhé. Xưa kia có một ngọn núi..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5765_AwakerVoiceContent = {
