  Voice_5772_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Nhà tắm là nơi tuyệt vời để tiêu mài thời gian, không chỉ có cơm ngon mà còn cung cấp dịch vụ thư giãn cơ bắp. Bạn có thấy hấp dẫn không? Hãy xây ngay một phòng như vậy ở trường!"
