  Voice_5788_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5789_AwakerVoiceContent = {
    Text = "Tôi đã gặp một số người trong hành lang khiến tôi cảm thấy không ổn. Có thể do tình hình bắt buộc, bạn phải chiến đấu cùng họ, nhưng hãy luôn giữ sự cảnh giác. Điều tàn nhẫn hơn chiến tranh chỉ có lòng người, và sự bội phản nguy hiểm nhất thường xuất phát từ nội bộ."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Lời nói phi chính · về @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Hiro\" hoặc \"Lily\", sẽ mở khóa"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Bài tập của bạn đã hoàn thành rồi phải không, có thể đi cùng tôi đến thành phố Lentiennam một chuyến không…… A? Bài tập Toán chưa hoàn thành?! \nÀ, à… xin lỗi, tôi không nghĩ rằng có người lại không hiểu về vi phân tích… Để tôi giúp bạn."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về việc học"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Tôi thề với bạn, người chủ cửa hàng đó chắc chắn đã xuất hiện ở salon Fontainebleau… Thì ra từ lúc đó, cô ta đã có vẻ ngoài như vậy rồi. Không biết từ tay cô ta có thể đổi được bao nhiêu bí mật nhỉ?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Đào Đen Đá"
  },
  Voice_5791_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Đào Đen Đá\", tính năng sẽ được mở khóa"
  },
  Voice_5792_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5792_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5793_AwakerVoiceContent = {
    Text = "Đừng làm vỡ."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Ô Ryta thích chơi cùng mọi người! Bạn có muốn tham gia không? Đứa trẻ này tên là Gel, còn bên kia là Hela, còn đằng kia cũng tên là Gel… À?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Đã đến lúc gọt sạch những vết nhơ này!"
  },
  Voice_5795_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5796_AwakerVoiceContent = {
    Text = "Cửa hàng nhỏ của Đào Đen Đá đã mở cửa, trẻ em chưa sẵn sàng tốt nhất không nên bước vào một cách tùy tiện nhé?"
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5796_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Xin đừng chạm vào cổ tôi... không nhìn thấy, không có nghĩa là không tồn tại."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Tôi thích những người có niềm tin, dù là động vật, thân thể được đánh thức hay con người. Nếu những người này giỏi võ nghệ, thì càng tuyệt."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Đi nào."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "Đừng lo lắng!"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona không thích việc mất đi…… xin lỗi, ý tôi là, tôi không thích chia ly, điều đó quá buồn bã."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Tôi không giỏi giao tiếp với những người theo đạo. Họ nhàm chán và cứng nhắc, còn trao dây nịt cho vị \"thần\" mà họ tôn kính, thật đáng tiếc, ông Salvador lại có mùi thơm ngọt ngào như vậy..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Salvador\""
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "Trận đấu hết mình hơn tất cả, kể cả thắng hay thua."
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Ai không thích giường mềm mại và hệ thống thoát nước kín đáo… phòng chứ?"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "……đừng để tôi nhớ lại……những ngày bị giam cầm ở [Elworth]……"
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Đốt cháy mọi thứ!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Đốt cháy mọi thứ!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Tôi theo mùi máu tìm đến nơi này. Xin hỏi… có cung cấp túi máu tươi không?"
  },
  Voice_5808_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5809_AwakerVoiceContent = {
    Text = "Ừm… Agrippa cũng có rất nhiều bạn đồng hành, nhưng mọi người trông đều rất sợ cô ấy. Chẳng lẽ, cô ấy sẽ cướp đồ ăn của các bạn đồng hành?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Agrippa\", bạn sẽ mở khóa"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Cuộc sống của tôi chỉ có vũ đạo, dù có ép tôi học những kiến thức khác, tôi vẫn khó mà trưởng thành được. Nhưng mọi người đều là những người tốt, không ai bán tôi vì danh vọng hay tiền bạc, tôi có thể cảm nhận được."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Kẻ nhát gan, rõ ràng có lực lượng mạnh mẽ tương tự như tôi, lại kiềm chế bản thân như vậy, điều này khác gì tự nguyện đeo dây xích!"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lily\""
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Chưa đủ… lực lượng còn chưa đủ…"
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5813_AwakerVoiceContent = {
    Text = "Quay lại đi"
  },
  Voice_5813_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Á!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Mũ lớn, mũ melon (kiểu mũ tròn cổ điển), mũ săn nai, mũ beret… Thật không thể không nói, những quý ông thượng lưu của các người đã cố gắng hết sức để che giấu đầu hói trông thật buồn cười."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về lễ nghi"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Tôi rất ngưỡng mộ vị thần minh ấy, tinh khiết cao quý như hoa bách hợp… Quý vị nói rằng, một người như thế cũng không thể kiểm soát được số phận của mình, cuối cùng chìm xuống đáy biển sao? Điều này thật khó tưởng tượng…"
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Hilaster"
  },
  Voice_5816_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Hilaster\""
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Trên thế giới này, không có gì mà người khổng lồ không thể vượt qua!"
  },
  Voice_5817_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5818_AwakerVoiceContent = {
    Text = "Trên thế giới này, không có gì mà người khổng lồ không thể vượt qua!"
  },
  Voice_5818_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5819_AwakerVoiceContent = {
    Text = "Khốn kiếp, khốn kiếp...! lực lượng chỉ giam cầm tôi trong thân thể này.."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5819_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Rất muốn ở lại nơi luôn sáng sủa… Đúng vậy, cực điểm, trên hành tinh này, chỉ có cực điểm mà thôi."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5820_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Tôi, tôi không thể gánh vác trọng trách gì lớn, chỉ có thể chạy theo ánh sáng. Vì vậy, xin hãy đừng ngừng tỏa sáng…"
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5821_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Nếu còn có thể di chuyển, tôi sẽ muốn trở thành một ngôi sao…"
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5822_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Dù có tính toán thế nào đi nữa, công thức chuyển đổi ý thức cũng không thể tìm ra lời giải……"
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5823_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Chào mừng quý khách, cùng nhau vui hết mình nào!"
  },
  Voice_5824_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5825_AwakerVoiceContent = {
    Text = "Khách quan, xin hãy từ từ dùng!"
  },
  Voice_5825_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5826_AwakerVoiceContent = {
    Text = "Huhu——là Ô Ryta đây! Một, hai, ba…… Wow! Chào mừng, chào mừng! Có thêm thành viên mới rồi! Hả? Là tôi trở thành người bạn mới của mọi người ư? Cũng có thể nói như vậy đấy!"
  },
  Voice_5826_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5827_AwakerVoiceContent = {
    Text = "Các người gọi đồ chơi này là súng ư? Chỉ dám tấn công đối thủ từ bóng tối, đúng là vũ khí của kẻ hèn nhát."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Không có ý nghĩa, làm vậy thật vô ích."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Bạn chẳng hiểu gì cả."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Còn trông mong tôi trở thành \"cứu thế chủ\" sao?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "À, xin lỗi bạn, có thấy đinh vít của tôi không? Thật kỳ lạ, cứ khi có đứa trẻ tai chuột kia ở đây, tôi lại dễ quên mất mình để đồ ở đâu hơn…"
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_5831_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Tôi sẽ không quên, tất cả những gì bạn đã dâng cho cuộc tái ngộ giữa tôi và chủ nhân của tôi.."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Như điêu khắc!"
  },
  Voice_5833_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5834_AwakerVoiceContent = {
    Text = "Bạn đã đồng ý với mong muốn của tôi chưa?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Hy vọng rằng sự chỉ huy của bạn không làm người khác thất vọng."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Được nâng cao, là thân xác này hay ý thức của ta? Một đề tài thực sự thú vị."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5836_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "Lùi lại."
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5838_AwakerVoiceContent = {Text = "Tránh ra."},
  Voice_5838_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Máu của tôi sôi sục với ý chí sinh tồn mãnh liệt, nó hét lên, thúc đẩy tôi rải máu khắp hành tinh… Aa, xin lỗi vì đã than vãn nhiều như vậy. Tôi là Thái Di Sơ, ngài gọi tôi, là đã sẵn sàng hòa mình với tôi rồi sao?"
  },
  Voice_5839_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5840_AwakerVoiceContent = {
    Text = "Nếu Ai Jī Sī có thể thay mọi người chịu đựng chất lỏng màu đen này thì tốt biết bao… dù sao, Ai Jī Sī chưa từng tồn tại, đối với thế giới này mà nói, đó hẳn là một điều tốt?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Sở thích là Giả thuyết Riemann——đây là khẩu hiệu của con công kia, không phải của tôi. So sánh với điều đó, tôi quan tâm hơn đến nghiên cứu về chuẩn mực nguyên tử."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Bị quét ra khỏi cửa, lưu lạc trên biển...... trải nghiệm một lần là đủ rồi."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Hãy xem kỹ!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Hãy xem kỹ!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Miễn là bạn có thể giữ vững niềm công lý này, tôi sẽ luôn gánh vác vai trò như một lưỡi dao sắc bén."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Bạn có biết truyền thuyết về \"Người Vẽ\"đang lưu truyền ở đây không? Từ những nét vẽ graffiti theo phong cách biểu hiện, tôi cảm nhận được chút gì đó quen thuộc..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "Đau quá, phấn khích quá——"
  },
  Voice_5848_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5849_AwakerVoiceContent = {
    Text = "Hãy cảm nhận cơn giận dữ của tôi!"
  },
  Voice_5849_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5850_AwakerVoiceContent = {
    Text = "Hãy ghi lại chiến thắng này bằng thơ ca."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Lớn lên đi——"
  },
  Voice_5851_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5852_AwakerVoiceContent = {
    Text = "Xem chiêu!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Ơ!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Có lẽ khi lớn lên, tôi có thể kiểm soát bản thân, không làm hao mòn sức sống của người khác… chỉ cần một chút là đủ để tôi sống sót."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5854_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Hình như nặng hơn chút xíu, chiếc nôi còn chịu được trọng lượng của tôi không?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5855_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Sức mạnh sắp tràn ra, lưng ngứa ngáy, có phải là sắp lớn lên rồi không?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_5856_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Mặc dù vẫn còn vẻ ngoài của một đứa trẻ, nhưng bây giờ tôi…… đã có sức mạnh để bảo vệ bạn rồi."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5857_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Tôi sẽ cố gắng trưởng thành đấy."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_5858_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Đồ không biết điều, tại sao lại cố chấp thức tỉnh tôi?"
  },
  Voice_5859_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5860_AwakerVoiceContent = {
    Text = "Tôi sẽ trở thành mẹ của thần!"
  },
  Voice_5860_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5861_AwakerVoiceContent = {
    Text = "Đây là lần thứ mấy được gọi rồi... con người, tốt nhất là ngươi đã chuẩn bị đủ \"thức ăn\", nếu không ta không dám đảm bảo điều gì cả."
  },
  Voice_5861_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5862_AwakerVoiceContent = {
    Text = "Cánh cửa bên ngoài!"
  },
  Voice_5862_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5863_AwakerVoiceContent = {
    Text = "Ngu ngốc."
  },
  Voice_5863_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Hì hì"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Hừ, không tệ. Lần đối đầu tiếp theo tôi sẽ dốc hết sức."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Người vô lễ!"
  },
  Voice_5866_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Đôi khi, vẻ đẹp của nghệ thuật nằm ở sự tiêu tan. Còn thất bại của bạn? Rõ ràng không phải vậy."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Bạn là thính giả quan trọng nhất của tôi, bất kể khi nào, tôi luôn sẵn sàng hát tặng bạn và dâng hiến tất cả."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Thích những thứ gì? Cỏ nước, đàn cá, cột hiên, mê cung... Tất nhiên là tôi đã thấy rồi! Trên quyển sách của chú Orn đều có cả!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Đây là chuẩn bị cho nhiệm vụ điều tra phải không? Tôi hiểu rồi."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5870_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Tên tôi là Hilaster. Nếu bạn vẫn cần tôi, tôi sẽ tồn tại ở đây."
  },
  Voice_5871_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5872_AwakerVoiceContent = {
    Text = "Nếm thử bài học này đi!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Hãy tỏ ra tôn trọng, người trẻ. Trong quân đội, có thứ tự về tuổi tác và phải tuân lệnh, hành vi vượt quá giới hạn sẽ bị trừng phạt."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Tôi cũng sẵn lòng cung cấp dịch vụ sau bán hàng cho những \"đồ chơi nhỏ\", vấn đề là, các bạn có dám chấp nhận dịch vụ của tôi không?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về phát minh"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Quý vị là chủ nhân ở đây, nhưng cũng là khách của salon tôi. Tôi sẽ chuẩn bị những món đãi tiệc tốt nhất cho chuyến thăm của quý vị — quý vị thích váy lót màu đỏ rực hay pyjama màu hoa hồng trắng?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Xin lỗi, ánh nắng ở đây có chút chói chang… chuột từ hang tối tăm tạm thời còn chưa thể thích nghi."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Có thể xâm thực vạn vật, mài mòn tất cả…… đó là một vũ khí không thể coi thường. Nếu như lúc đó tôi biết…… thở dài."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Có lời đồn rằng, trong ngọn lửa, cơ thể co giật như nhảy múa."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về ngọn lửa"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Đừng ra ngoài vào ban đêm, ngay cả khi mang theo nguồn sáng 2000 lumens cũng không hoàn toàn an toàn… một khi bước vào bóng tối, những quỷ dữ ẩn nấp ngoài tầm nhìn sẽ đuổi theo bạn, nuốt chửng bạn, đuổi theo bạn, tiêu thụ bạn… cho đến khi không còn gì cả."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Lời trò chuyện·về đêm"
  },
  Voice_5881_AwakerVoiceContent = {
    Text = "Hãy khóc."
  },
  Voice_5881_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5882_AwakerVoiceContent = {
    Text = "Đã nhận."
  },
  Voice_5882_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "Đó là sự khát khao của sức sống, thúc đẩy thiên nga đấu tranh để trở về bầu trời xa xôi."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5883_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Bắt đầu thay đổi!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5885_AwakerVoiceContent = {
    Text = "Cứu mạng đi!"
  },
  Voice_5885_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5886_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5886_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_5887_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5887_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5888_AwakerVoiceContent = {Text = "À"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "À, Brun đã chạy qua rồi! Tôi nên tránh đi một chút……\nRõ ràng là muốn làm bạn với cô ấy, nhưng cuối cùng lại trở thành ác mộng của cô ấy……Cô ấy chắc chắn không muốn gặp tôi đâu……"
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_5889_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Nhà thờ? Rất cảm ơn, nhưng thực tế là tôi không phải là người quá truyền thống. Miễn là trong lòng luôn ghi nhớ những lời dạy của Đấng Từ Bi và thực hành ý chí của Người mọi lúc, linh hồn của tôi sẽ không rời xa vinh quang của Người."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về nhà thờ"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Tên tôi là Orci. Theo hợp đồng với ngài, tôi sẽ dâng lên ngài lòng trung nghĩa của một hiệp sĩ, bảo vệ sự an toàn của ngài và loại bỏ kẻ thù của ngài. Lời thề hôm nay, tôi sẽ không bao giờ quên."
  },
  Voice_5891_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5892_AwakerVoiceContent = {
    Text = "Đàn bà mắt đôi khô héo kia, có mùi chẳng khác gì bọ chét thường thấy."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Agrippa\", bạn sẽ mở khóa"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Thích điều gì? Đương nhiên là may mắn rồi. Mỗi ngày ra khỏi nhà đều phải cầu mong có điềm lành."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "Xin đừng nói với cô Hannah rằng tôi đang trốn ở đây... Tôi chưa sẵn sàng.."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Hanna"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Như vậy được không nhỉ?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Quý khách là người tôi kính trọng. Hãy biết rằng, tôi chỉ có thể cho một mình quý khách mua chịu. Dù sao, đã nhiều năm rồi tôi mới thấy được một cái đầu tuyệt vời như vậy…"
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Đau!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5898_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_5898_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5899_AwakerVoiceContent = {Text = "Đau!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Thích điều gì… Vua không nên có những biểu hiện như vậy, nhưng nếu có thể tránh xa những văn bản báo cáo và lời cầu nguyện phiền phức, cuộn mình trên chiếc giường mềm mại, ta tự nhiên sẽ rất vui vẻ."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Ta sẽ coi hành động bất kính của các ngươi là sự khao khát yên nghỉ vĩnh hằng."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Ghét không? Tôi ghét số phận không thể trốn thoát và bi kịch đã được định sẵn."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(hừm nhẫn nại)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Đừng đến đây!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Ồ, muốn biết bí mật của ta sao? Cái tên này, thân thể này, dung mạo này, giọng nói này đều thuộc về chủ nhân của một chiếc đầu lâu tại Thánh Pedro. Cô ấy đã giao dịch với ta... Sau khi cô ấy chết, ta đã trở thành cô ấy. Còn về tung tích của cô ấy... đó chính là món sưu tập tuyệt vời nhất của ta đấy?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5906_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Quý khách thật là một người khách dễ chịu, đến nỗi tôi cũng bị mê hoặc bởi cái đầu độc đáo của quý khách……Nếu quý khách có ý định chuyển nhượng, nhất định hãy ghé thăm cửa hàng nhỏ của tôi. Hê hê……Chỉ là đùa chút với quý khách thôi."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5907_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Muốn biết thân phận thật sự của tôi ư? Bây giờ còn quá sớm. Bạn chỉ cần tin rằng: những đứa trẻ lạc đường đều có thể tìm thấy nơi nương náu trong cửa hàng của tôi. Cũng có bạn nữa đấy?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5908_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Không ai bị thương."
  },
  Voice_5909_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5910_AwakerVoiceContent = {
    Text = "Chưa kết thúc!"
  },
  Voice_5910_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5911_AwakerVoiceContent = {
    Text = "Thấy anh làm việc chăm chỉ như vậy, tôi còn cảm thấy không đành lòng nhận phần thưởng ngay lập tức. Vì vậy, cái đầu của anh tạm thời vẫn giữ nguyên vị trí của nó nhé. \nNhưng đừng quên, nó đã được đặt trước làm tài sản riêng của tôi rồi đấy?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5911_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Tôi trước đây không phải dạng này, chính cô ấy đã ban cho tôi sức sống mới. Như vậy, ngài cũng là người đã ban cho tôi sức sống thứ hai. Tôi sẽ trân trọng lưu giữ đầu của ngài."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5912_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Hoàn toàn thoát khỏi bóng tối"
  },
  Voice_5913_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5914_AwakerVoiceContent = {
    Text = "Thì ra phiêu lưu lại nguy hiểm đến vậy…"
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Cô gái ngốc nghếch kia sao vừa thấy tôi là chạy ngay? Lần sau tôi sẽ giẫm lên cuộn len của cô ấy, xem cô ấy còn chỗ nào để trốn."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Ai Jī Sī"
  },
  Voice_5915_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Ai Jī Sī\", sẽ mở khóa"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "Hừ~ ha ha ha!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Đứa trẻ đó rất có linh tính, để sống sót trên đường phố cần phải có trí tuệ như vậy. Nếu tôi còn đang điều tra bên ngoài, chắc chắn tôi sẽ thân thiết với cô ấy."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_5919_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Vị Thánh phụ không thể cứu tất cả mọi người. Ông có thể giúp một kẻ khốn khổ, nhưng không thể kéo tất cả mọi người ra khỏi bùn lầy…… Tôi rất mong chờ ông, mong chờ sự sụp đổ của niềm tin của ông."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Salvador\""
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Bạn có thể tìm thấy mọi thứ bạn cần trong cống rãnh của Lentiennam: cá hồi, xà phòng, whisky đã uống một nửa… \nGì, bạn hỏi tôi tại sao lại hiểu rõ như vậy? Tôi từng kéo xác anh trai mình, bò suốt năm dặm ở trong đó…"
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về cống rãnh"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Hãy quỳ xuống!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Hãy quỳ xuống."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Sau khi nhìn thấy thế giới thực sự bên ngoài chiến trường, tôi đã từng nghi ngờ giá trị của những người được gọi là \"anh hùng\". Nhưng may mắn thay, tôi đã gặp được bạn, người chính trực, dũng cảm và trong sáng. Dưới sự chỉ huy của bạn, tôi sẽ chiến đấu hết mình vì hòa bình và ổn định của thế giới. Lần này, tôi nhất định sẽ hoàn thành việc chuộc lỗi của mình."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5924_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Ya a! Tệ rồi…"
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Bất tịnh, ô uế, hỗn loạn — đây chính là lực lượng của chúng ta."
  },
  Voice_5926_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5927_AwakerVoiceContent = {
    Text = "Tôi ghét dáng vẻ đạo đức giả của các người. Nghĩ rằng tôi phát điên, tôi rất đáng thương, phải không? Theo tôi thấy, các người giống như Icarus bị mặt trời làm mù mắt, các người mới chính là lũ đáng khinh."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Xin hãy để tôi đi đầu!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Những kẻ đó có hơi thở rất lạ, họ không phải là sinh mệnh tự nhiên sinh ra trên hành tinh này."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về người ngoài hành tinh"
  },
  Voice_5929_UnlockDesc = {
    Text = "Sau khi nhận được một trong các thân thể được đánh thức \"Wenkel\"\"tinkerer\"\"Phiệt\"\"Vanda\", tính năng sẽ được mở khóa"
  },
  Voice_5931_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_5931_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "Hủy diệt đi!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Xin đừng…"
  },
  Voice_5933_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5934_AwakerVoiceContent = {
    Text = "Trở thành quái vật cũng không sao, điều tôi muốn từ đầu đến cuối chỉ là lực lượng trả thù mà thôi."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5934_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Ngoài việc loại bỏ đối thủ, bạn còn mong muốn điều gì khác không? Đổi lại, tôi sẽ thực hiện nguyện vọng của bạn... Tất nhiên, trong phạm vi khả năng."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_5935_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_5936_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_5936_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Bạn à?... Tôi sẽ cân nhắc, trước khi tôi quyết định, đừng để mình chết dễ dàng như vậy."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_5937_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Từ khi được ghi nhận rõ ràng lần đầu tiên, hiện tượng rỗng rỗng đã ảnh hưởng đến cuộc sống của hàng triệu người. Hành động của chúng ta quyết định sự sống còn của nhân loại."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5939_AwakerVoiceContent = {
    Text = "Mở hết công suất!"
  },
  Voice_5939_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Cẩn thận cơn điên cuồng của biển cả."
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Cẩn thận cơn điên cuồng của biển cả."
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Ê!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Tôi là công chúa của Người, cũng là mẹ của Người. Còn ngươi, trước mặt Người chỉ là một sinh vật hèn mọn mà thôi."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Mọi thứ đều suôn sẻ, hãy treo lên cột buồm chiến thắng."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Đừng lại gần tôi, muốn làm đồ chơi của công chúa hay lễ vật trong dịp lễ thần linh?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5945_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Dễ dàng, chiến thắng hoàn toàn!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Dễ dàng, chiến thắng hoàn toàn!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Tôi cho phép bạn trở thành người chứng kiến, chứng kiến khoảnh khắc huy hoàng đảo lộn luân lý."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5946_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Không gian trống à? Trong kỹ năng lấy vật từ xa cũng thường tạo ra những không gian trống như vậy! Không gian trống do Kasia tạo ra sẽ liên kết đến một chiều không gian khác, còn không gian trống do rỗng rỗng thì có phải vậy không?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Người giữ bí mật, ta sẽ dùng quyền năng của Mẹ thần để dành cho ngươi một chỗ bên cạnh ngai vàng biển sâu, ngươi sẽ chứng kiến thời đại tái sinh sau sự hủy diệt. Hãy tràn đầy lòng biết ơn, đây là lời hứa của Mẹ thần!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5948_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "Nhìn vào sự tôn kính của ngươi, ta sẽ ban cho ngươi một câu trả lời. Ban đầu, tất nhiên đã có những đấu tranh. Nhưng giờ đây ta đã hiểu rõ, cuộc sống xa hoa của ta đều bắt nguồn từ Ngài. Cái chết không phải là điểm kết thúc, Ngài sẽ tái sinh ta, thông qua vòng luân hồi đầy đau khổ này để đạt được sự bất tử.."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5949_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Ước muốn của người phụ nữ đó thật đáng châm biếm. Không có gì có thể sống sót sau khi bị xóa sổ, ngay cả \"thần\" cũng vậy."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Thái Di Sơ"
  },
  Voice_5950_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Thái Di Sơ\""
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Người nói là người thông linh, không phải là người vạn năng, tất nhiên cũng sẽ phạm sai lầm. Hiện tại, hành động của người phụ nữ kia kéo mọi người vào cuộc chính là một sai lầm vô ý của người nói… Vì thế, người nói cần sự trợ giúp của ngươi. Để có thể đáp ứng ngay khi được triệu gọi, ngươi được phép đặt giường trong cung điện nghỉ ngơi của người nói."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5951_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Bạn đang gánh vác nhiệm vụ đối mặt với thảm họa, thật là nặng nề đối với một người ở độ tuổi của bạn... Nếu, từ ban đầu đã biết mình không thể thay đổi tương lai, liệu bạn có còn trung thành thực hiện sứ mệnh này không? Đừng vội trả lời. Hãy suy ngẫm khi nghỉ ngơi, ta rất tò mò về câu trả lời của bạn."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5952_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Sau khi thức tỉnh ta, đã qua một khoảng thời gian rồi, cậu không có gì muốn xin từ ta sao? Lời tiên tri của thần minh, dự đoán chắc chắn sẽ thành hiện thực, thậm chí là kho báu của lục địa chìm —— cậu thật sự không muốn biết sao? \nHừ… kẻ kỳ lạ."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5953_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Dư chưa bao giờ yêu cầu bất kỳ ai sùng bái. Hành động tự cho là đúng của người khờ chỉ khiến dư cảm thấy càng mệt mỏi… Rút lui đi, đã đến giờ nghỉ ngơi."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5954_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Trên người ngươi, trẫm không thấy bất kỳ phẩm chất nào tương tự với thần hạ của trẫm… Thôi được, có lẽ điều này là tốt. Nghĩ đến người phụ nữ đó, trẫm cảm thấy mệt mỏi."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5955_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Thần, đối đãi công bằng."
  },
  Voice_5956_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5957_AwakerVoiceContent = {
    Text = "Tôi biết, bạn là khán giả đặc biệt, không thể đưa bạn vèo một cái vào chiều không gian khác được, nếu không sẽ gặp rắc rối to. Ê, có làm vậy với người khác bao giờ chưa? Ghét quá, đừng hỏi nữa, đó là bí mật của mình!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Ơ ya ya, bạn có quan tâm đến hình dạng này không? Xem ra có mất mát thì cũng có thu hoạch, đây có lẽ cũng là một trong những may mắn của tôi, Lắc?"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Misaque là nơi lưu lại nhiều ký ức nhất của tôi, cũng là ngôi nhà ấm áp nhất."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Giao cho tôi."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5961_AwakerVoiceContent = {
    Text = "Quá ngây thơ!"
  },
  Voice_5961_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Lời thánh ca của biển sâu!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Tôi đã được ban tặng——"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Kỹ năng·một·Biển Lặng"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Nếu bạn vẫn đồng ý gọi tôi là \"Ramona\", thì hãy tiếp tục gọi tôi như vậy nhé."
  },
  Voice_5964_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5965_AwakerVoiceContent = {
    Text = "Sao, cậu cũng muốn lợi dụng sự tức giận của tôi sao?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_5965_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "Sự thật… được làm rõ ở đây."
  },
  Voice_5966_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_5967_AwakerVoiceContent = {
    Text = "Thức ăn nhận được phải ăn ngay lập tức, đây là luật bất thành văn trên phố."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Cảm thấy như đã no."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Ưm… ngứa quá, Brun, giúp tôi gãi lưng."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "Phần cơ khí mới sẽ giúp ích rất nhiều cho hoạt động của tôi——điều này không thể coi là thích sao? Xin lỗi, tôi e rằng tôi không hiểu câu hỏi của bạn. Đối với một con rối cơ khí, sở thích không mang ý nghĩa gì."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Xem chiêu."
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "Xem chiêu!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Xem xét kỹ lưỡng."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Suy nghĩ bình tĩnh."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Cô Wenkel và tôi đều không có quê hương trên hành tinh này… Ngoài Tinker, quê hương của tôi không có gì để tôi nhớ nhung. Không biết cô Wenkel có cảm xúc như thế nào về quê hương của mình?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Wenkel"
  },
  Voice_5976_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Đừng lại gần tôi từ phía sau, trừ khi bạn muốn bị bẻ gãy cổ."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_5977_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hả a—— Sao các người lại để mặc mèo hoang chạy loạn trong khuôn viên trường?! Nếu con vật không ngoan đó cào người thì sao bây giờ!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Ánh mắt của tôi khiến người khác cảm thấy bất an sao? Đúng vậy, chính sự dữ dội này đã giúp tôi sống sót trong luyện ngục."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_5979_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Những lời đạo đức giả thì khỏi cần, anh muốn lấy gì từ tôi? Bỏ công sức để duy trì lý trí của tôi, chắc chắn là có mục đích gì đó."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_5980_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Đối tượng trả thù của tôi luôn chỉ có người Sparta, nhưng giờ đây, ngay cả thành bang này cũng đã không còn tồn tại… Thôi được, trở thành lưỡi dao của ngươi cũng chẳng sao. Ta tạm chấp nhận ngươi làm đồng hành, nhưng nếu ngươi dám bội phản, ta sẽ moi tim ngươi ra."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_5981_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Đôi tay tôi nhuốm đầy máu. Những đồng tộc yếu đuối không thừa nhận việc tôi báo thù, họ bàn tán về sự tàn nhẫn và vong ân của tôi… Báo thù, chỉ vì chính mình, không liên quan đến bất kỳ ai khác."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_5982_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Cũng nên dùng thêm nhiều thép rồi."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Cũng nên dùng thêm nhiều thép rồi."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5985_AwakerVoiceContent = {
    Text = "Hãy chết đi."
  },
  Voice_5985_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Tôi là…… hay gọi tôi là Wenkel, họ đều gọi tôi như vậy. Đúng vậy, cứ gọi tôi vậy, giống như họ……"
  },
  Voice_5986_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5987_AwakerVoiceContent = {
    Text = "Thân này chính là khiên của chủ quân!"
  },
  Voice_5987_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5988_AwakerVoiceContent = {
    Text = "Thân này chính là khiên của chủ quân!"
  },
  Voice_5988_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_5989_AwakerVoiceContent = {
    Text = "\"Cây kẹo hồ đào\" vốn là câu chuyện cổ tích lãng mạn của các cô gái, nhưng những kẻ mặt mũi đáng ghét chỉ nhìn thấy trong đó những hình ảnh cơ thể quyến rũ và dục vọng tầm thường... thật đáng ghê tởm."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Phải… phải tiêu diệt…!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... cô ấy gọi điều này là huấn luyện à? Haha... cho tôi cười một chút đã. Con người cuối cùng vẫn quá nhân từ và mềm yếu, làm gì cũng giống như đang đóng vai."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Lời rỗi · Về Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Pandia\""
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Đừng đến đây!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Còn phải tự giới thiệu lần nữa sao? Thật là không biết làm sao với cậu. Tôi là Jenkin, còn đứa trẻ này là Brun. \"Chít!\"\n Đừng quên nhé! Nếu nhớ sai tên chúng tôi, thì hãy chuẩn bị tinh thần để tôi dùng đèn lồng đánh cậu một trận *tiếng* nhé! \"Chít chít?!\""
  },
  Voice_5993_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_5994_AwakerVoiceContent = {
    Text = "Nhảy đi nhảy đi!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Nhảy đi nhảy đi!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Dâng lên lời ca ngợi khai mạc!"
  },
  Voice_5996_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_5997_AwakerVoiceContent = {Text = "Hừ."},
  Voice_5997_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_5998_AwakerVoiceContent = {
    Text = "Chỉ cần một chút đá, hai con dao khắc, và ba bó hoa diên vĩ hướng dương...... Tôi có thể tạo ra mọi thứ cho bạn."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_5998_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_5999_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_5999_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "Chỉ có vậy thôi?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Ừm."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Cuộc đấu tranh vô ích này…"
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6003_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_6003_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Sau khi Tiberius chết, người dân La Mã cuối cùng cũng thực hiện được ước nguyện bấy lâu nay——ném xác ông ta xuống sông Tiber, nơi đàn cá sẽ xơi tái. Tất nhiên, vì điều này họ đã phải trả một chút giá nhỏ: bị Caligula ném vào đấu trường, để tôi giải trí."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6005_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_6005_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6006_AwakerVoiceContent = {
    Text = "Tôi có thể cảm nhận được, cô bé đó sở hữu lực lượng giống tôi. Cô ấy chưa hoàn toàn hiểu rõ lực lượng này, vì bạn, tôi sẽ huấn luyện cô ấy một cách phù hợp."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lily\""
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Khốn kiếp, các người, các người vẫn coi thường tôi sao?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Bằng chứng tồn tại."
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Bằng chứng tồn tại."
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Tôi tin rằng mọi thứ đều có lý do, nhưng… những hành động bạo lực vô nghĩa, những định kiến khiến anh em quay lưng với nhau, thù ghét lẫn nhau, thực sự khiến tôi không giấu nổi nỗi buồn. Nếu phải nói điều gì khiến tôi khó chịu nhất, thì chính là điều này."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Tôi thực sự không muốn sử dụng lực lượng này."
  },
  Voice_6011_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6012_AwakerVoiceContent = {
    Text = "Đừng chủ quan."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hừ"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6014_AwakerVoiceContent = {
    Text = "Dừng lại đi!"
  },
  Voice_6014_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6015_AwakerVoiceContent = {
    Text = "Dừng lại đi!"
  },
  Voice_6015_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Kassia thật tài giỏi! Cô ấy có thể biến ra một con thỏ nhỏ chỉ trong nháy mắt!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Kassia"
  },
  Voice_6016_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Kassia\""
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Phép thuật, đã sẵn sàng!"
  },
  Voice_6017_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6018_AwakerVoiceContent = {
    Text = "Rỗng rỗng… Thật sự phải thừa nhận rằng, trên đời này có những điều mà quyền lực không thể nào kiểm soát được."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6019_AwakerVoiceContent = {Text = "À——"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Hãy nhảy múa trong lửa lục bảo."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Không cần buồn rầu, vết sẹo là dấu tích vinh quang của chiến binh."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Hãy run rẩy trước sức mạnh này...... Nó đang chờ để nghiền nát bạn."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Thời gian dùng bữa? Hay thời gian hoạt động?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6024_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Ừ ừ! Như vậy thì những người bạn của Ô Ryta sẽ không biến mất!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6025_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Thầy giáo Sylva nói, khi nhận được gì đó phải nói cảm ơn… cảm ơn cảm ơn cảm ơn!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6026_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "Lần này để Ô Ryta làm ma! Chỉ cho bạn 5 giây để trốn nhé! 5, 4 ——"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6027_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Mọi người bắt đầu chơi trốn tìm và đều biến mất, lần này, Ô Ryta nhất định phải tìm thấy mọi người!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6028_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Vì đã tìm thấy xương cốt của Dư ở đáy biển, nên cho rằng Dư thích nước, còn muốn xây hồ nước bên ngoài điện giường của Dư? \n Ha… tùy các người, đừng dùng những chuyện vặt vãnh này để làm phiền Dư nữa."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Một giọt nhỏ trong đại dương, tín đồ bất diệt khiêm tốn, Miriam… xin chào bạn."
  },
  Voice_6030_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6031_AwakerVoiceContent = {
    Text = "Đến lượt tôi ra tay."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Hè!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Thật đáng kinh ngạc......Một câu nói vô tư của bạn đã giải quyết được vấn đề sáng tạo khiến tôi đau đầu trong nhiều tháng."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6033_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "So với những tiểu thư quý tộc ở buổi tiệc rượu, tính khí của Muphí quả thực có thể coi là dễ thương."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_6034_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Thầy chữa lành tâm hồn? Chỉ là bọn trẻ đã quá khen tôi thôi. Tôi chỉ đơn giản là lắng nghe hết sức mình, để giúp chúng giải tỏa nỗi u uất trong lòng——như tôi vẫn luôn làm."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Đừng coi thường tôi nữa!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Đừng coi thường tôi nữa!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Có thấy khát không? Nguồn nước sạch trong nhà tù là một thứ hiếm có, đáng trân trọng."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6038_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Trẻ ngoan, trẻ ngoan~ không được bỏ cuộc nửa chừng nhé~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6039_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Bạn chắc chắn đã sa vào bẫy ngọt ngào của tôi rồi phải không?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6040_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Nỗ lực, cố gắng thêm một chút nữa~ sắp đến đỉnh cao cực lạc rồi~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6041_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Tôi gia nhập trường học khi mười bốn tuổi, nếu lúc đó có thể tốt nghiệp thuận lợi, thì bây giờ bạn nên gọi tôi là \"Hiệu trưởng\"."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Bộ não yếu ớt của bạn, xem ra là không thể nhớ lâu được rồi."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Bạn hỏi ước nguyện của tôi là gì à? Phước lành cho chuyến đi, bình an khi ra vào, chẳng lẽ không được sao? \nCòn lại, tôi chưa nghĩ đến… nhưng tôi sẽ suy nghĩ kỹ hơn rồi nói lại với bạn."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6044_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Điều tôi khao khát chính là bí ẩn của trời đất, tôi muốn làm rõ rốt cuộc là lực lượng gì đang chi phối tôi.\" Mặc dù tôi không hài lòng lắm với cốt truyện của tiểu thuyết này, và khoa học hư cấu trong sách cũng ngây thơ đến mức buồn cười, nhưng sau khi đọc, bạn nên có thể hiểu tôi… Chờ đã, bạn chưa đọc quyển sách này phải không?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6045_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Sứ mệnh và số phận là những thứ tương tự nhau. Không thể dễ dàng buông bỏ, cũng không cần thiết phải buông bỏ."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6046_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Tôi luôn trông bận rộn? Đúng vậy, các trợ lý thỉnh thoảng có thể chia sẻ một số công việc, nhưng trong một số nghiên cứu, tôi không thể thay thế được. Bạn muốn giúp đỡ? Vậy thì thỉnh thoảng hãy đến kiểm tra xem tôi còn sống không nhé."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6047_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Bạn nghĩ tôi đang giận? Bạn có biết mỉm cười cần sử dụng bao nhiêu cơ không? Tôi đã từng giảng điểm kiến thức này trong lớp, rõ ràng, nó đã trượt qua cái đầu trống rỗng của bạn. Câu trả lời là ít nhất mười bảy cơ, và tôi không có lý do gì để giận bạn."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6048_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Cô Ramona nói rằng tôi không cần phải nhượng bộ tất cả mọi người, bạn có hiểu ý cô ấy không?... Là không còn cần sự bảo vệ của tôi nữa sao?"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6049_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Có mười ba báo cáo cần được phê duyệt, sáu máy truyền tin bị hư hỏng đang chờ sửa chữa, đồng thời tôi còn phải theo dõi kết quả của năm thí nghiệm chiết xuất bạc tâm khác nhau… Vì vậy, thay vì dùng thời gian hạn chế để làm phiền tôi, hãy thử cải thiện tư duy của bạn."
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6050_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Hy vọng lần sau, quê hương sẽ đáp lại lời kêu gọi của tôi."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Khóa đã được mở."
  },
  Voice_6052_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6054_AwakerVoiceContent = {
    Text = "Tôi rất vui … Ông quá thiên vị, chiếu cố tôi."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6054_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Người khác có thể sẽ bực mình vì sự thiên vị của bạn đấy nhé."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6055_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Phải chăng bạn cũng thèm khát tôi?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6056_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Cuối cùng cũng kết thúc, cuối cùng cũng không phải nhìn thấy những thứ đen nhánh, dính nhớp nữa…"
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Đã dành cho tôi nhiều như vậy, tình yêu của ngài đã hòa quyện vào tôi như nước với sữa.."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6058_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Ê!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "Rất nguy hiểm."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Bạn đã hy sinh quá nhiều rồi, bây giờ cũng xứng đáng được hưởng thành quả rồi chứ? Lại gần đây một chút, tôi sẽ không để bạn thất vọng đâu~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6061_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Tôi, tôi hiểu rồi, lòng của ngài… Mặc dù vẫn còn vụng về, nhưng Ai Jī Sī sẽ cố gắng hết sức để chiến đấu cho ngài!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6062_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Ánh mắt của ngài làm tôi đau đớn… Ai Jī Sī có làm phiền ngài không?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6063_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Ai Jī Sī cảm thấy rất lo lắng… không biết có phụ lòng mong đợi của ngài hay không…"
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6064_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Ngài nhìn tôi như vậy, Ai Jī Sī rất không quen… Ngài không sợ lời nguyền sao?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6065_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "Xin...xin đừng nhìn vào mắt tôi… Ai Jī Sī sợ rằng mình sẽ làm thương ngài… Dù sao, tôi cũng là một sinh vật quái dị…"
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6066_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Khứu giác của thú vật chỉ là may mắn mà thôi. Đừng có nhìn nhầm đấy nhé?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6067_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Tôi còn chưa thể dừng lại…"
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Lực lượng, không ngừng chảy!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Lực lượng, không ngừng."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Bạn có thích biển không? Dù thế nào, tôi vẫn luôn yêu biển. Tôi vẫn nhớ, vào ngày đó nhiều năm trước, biển đã nhẹ nhàng ôm trọn cái chết mà tôi khao khát bấy lâu."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Không hiểu sao lại dâng trào một cảm giác khoái cảm chưa từng có……"
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Dòng chảy này sẽ nghiền nát kẻ thù."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Dòng chảy này sẽ nghiền nát kẻ thù."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Tôi luôn chờ đợi một người, một người có thể dạy tôi về tình yêu thực sự, nỗi đau và khát khao. Bạn có thể thỏa mãn tôi không? Có thể cứu tôi khỏi nhà tù tối tăm này không?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6076_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Bạn có muốn biết sự thật không? Tôi ghét nhà tù, ghét bóng tối, ghét đến mức gần như chết đi. Tôi muốn được chú ý, muốn được thắp sáng.."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6077_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Mọi thứ đều là vì tương lai hạnh phúc vĩnh cửu."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Muốn tận hưởng tôi sao? Vậy thì hãy trở thành nô lệ của tôi đi. Tôi sẽ làm bạn bừng cháy đó~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6079_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Xem như là đóng góp của bề tôi."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Đều chán rồi, đều chán rồi. So với những tên tù nhân to lớn và run rẩy kia, đây quả thực chỉ như trò chơi trẻ con mà thôi. Hay là bạn đến chơi với tôi đi~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6081_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Muốn có nhiều nô lệ hơn, muốn nghe họ rên rỉ và van xin mà——\nĐi kiếm thêm nô lệ cho tôi đi~ Làm ơn~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6082_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Xin lỗi, tôi lại chìm đắm trong ký ức rồi. Đừng để lộ biểu cảm buồn. Bây giờ đến lượt bạn kể câu chuyện của mình cho tôi nghe. Bạn có bao giờ có khát khao viết thơ không? Những cuộc phiêu lưu, những điều bạn chứng kiến, niềm vui, nỗi buồn của bạn, liệu chúng có trở thành dòng suối chảy từ tâm trí xuống đầu ngón tay không?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6083_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Tôi vốn là vệt nước mờ nhạt trên cuộn giấy da cừu, nhưng nhờ mối duyên với ngài mà dừng lại trong khoảnh khắc này, có lẽ đây chính là một điều kỳ diệu. Tôi sẽ trân quý điều kỳ diệu ấy, sáng tác nên những áng thơ sâu sắc dành cho ngài."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6084_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Có người từng nói với tôi rằng, thơ ca được sáng tác ra là để được thưởng thức… Bạn có thể chia sẻ suy nghĩ của mình không?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6085_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Bạn có từng trải qua điều này không? Đối mặt với sự xúc phạm của người khác bằng một trái tim rộng lượng, cuối cùng lại không nhận được kết quả như mong đợi. Tặng hoa hồng cho người khác, nhưng tay mình lại không còn hương thơm, chỉ để lại vết thương từ gai hoa."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6086_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Bút mực của tôi.."
  },
  Voice_6088_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6089_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6089_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6090_AwakerVoiceContent = {
    Text = "Sai rồi……"
  },
  Voice_6090_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6091_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6091_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Đây là sự bảo vệ đến từ những vật vĩ đại!"
  },
  Voice_6092_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6093_AwakerVoiceContent = {
    Text = "Sự bảo vệ của Đại Vật Bạc Trắng."
  },
  Voice_6093_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6094_AwakerVoiceContent = {
    Text = "Tôi không có thời gian nghỉ ngơi, hiện tượng rỗng rỗng đã hủy diệt hai thân thể của tôi, trước khi bị kết thúc đuổi kịp, tôi có quá nhiều điều muốn hiểu rõ… Hãy giúp tôi, bắt đầu từ việc chuẩn bị vật liệu thí nghiệm, tôi tin rằng bạn không đến nỗi kém cỏi đến mức tính sai cân bằng chứ?"
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6094_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Tôi thích cửa sổ hoa văn của Fontainebleau, nó tô điểm khuôn mặt của mọi người bằng những màu sắc khác nhau: tím u sầu, xanh dương khéo léo, và tất nhiên, còn có màu đỏ tham vọng mà tôi yêu thích nhất…"
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Ở nơi đây, tôi thường cảm nhận được hơi thở của Chúa Thượng, nhưng có lẽ tôi vẫn chưa sẵn sàng đối mặt với Ngài…… Dù sao đi nữa, cảm ơn bạn đã cho tôi nơi trú ngụ."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Sự bội phản sẽ biến con người thành quái vật, dù là bên nào đi chăng nữa. Vì vậy, tôi căm ghét những kẻ phản bội."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hamlin, sẵn sàng phục vụ bạn."
  },
  Voice_60985_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_60986_AwakerVoiceContent = {
    Text = "Tôi đã từng gặp một người có sự hiểu biết gần như bản năng về âm nhạc, những bản concerto và giao hưởng do người đó sáng tác đều khiến người ta khó quên. \n Đó mới là thiên tài thực sự."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về người xưa"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Tôi không thích lãng phí thời gian vào những toan tính. So với âm nhạc, giá trị nghệ thuật của các mưu đồ hầu như không đáng kể. Nhưng để loại bỏ những trở ngại trên con đường phía trước, đó là một công cụ không thể thiếu. Để đạt tới đỉnh cao cuối cùng của âm nhạc, tôi sẵn lòng sử dụng nó."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về mưu lược"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Vô lễ."},
  Voice_60988_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Lại nữa, giai điệu này rốt cuộc là gì? Từ lần trước khi nghe thấy, nó vẫn luôn vương vấn trong tâm trí tôi, không chịu rời đi, không ngừng lại."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_60989_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6098_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6098_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_60990_AwakerVoiceContent = {
    Text = "Về mặt kỹ thuật, việc lập kế hoạch và chỉ huy âm nhạc không có sự khác biệt. Bản chất con người, cảm xúc, dục vọng… chúng rõ ràng và mềm mại như những nốt nhạc trên dòng kẻ nhạc, hiện ra trước mắt tôi, nhảy múa theo nhịp của cây chỉ huy. Hiểu biết về âm nhạc, chính là hiểu biết về tất cả."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về tính chung"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Còn thiếu một chút, chỉ một chút nữa thôi, tôi phải hoàn thành nó, tôi phải nghe thấy nó."
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_60991_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Ừm."},
  Voice_60992_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_60993_AwakerVoiceContent = {Text = "Vô lễ."},
  Voice_60993_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Ừm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "Nhạc vượt qua ngôn ngữ, vượt qua chữ viết, vượt qua mọi thứ. Nếu điều này không phải là hoàn hảo, tôi không biết điều gì là hoàn hảo."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_60995_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Chú ý nhịp điệu."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Điều chỉnh tần số hoàn thành."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Rất vui khi bạn cũng hiểu được tầm quan trọng của việc tập luyện."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Tôi sẽ mang đến một màn trình diễn hoàn hảo."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Ghen tị chứ? Bộ vảy cứng này chính là bằng chứng của dòng máu cao quý."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "Tôi cũng từng được người ta ca ngợi, nhưng... đó không phải là tài năng thật sự. \nTác phẩm của tôi chỉ là phỏng theo người đi trước."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Lời nói chuyện · Về tác phẩm"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Nhạc cụ hơi, nhạc cụ dây,… xen kẽ nhau đi lên rồi lại xen kẽ, chủ đề tái hiện… Tôi nhớ ra rồi, đây là bản Requiem do chính tôi sáng tác, dành cho thiên tài đã qua đời sớm, dành cho ngôi sao đã tàn lụi."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_61001_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "À? Bạn có bản nhạc mới để trình diễn cho tôi xem không?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Bằng bài ca này, tưởng nhớ những linh hồn đã khuất."
  },
  Voice_61003_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_61004_AwakerVoiceContent = {
    Text = "Vị vũ công màu xanh ấy, có dáng vẻ thanh nhã đủ để trở thành vũ công chính của đoàn vũ công cung đình. \nNếu có thể, thật mong được hợp tác với cô ấy."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Giải khóa sau khi nhận được thân thể được đánh thức \"Liz\""
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Nhóm nhạc có thể có nhạc trưởng, nhưng nhạc trưởng không thể tạo thành một ban nhạc hoàn chỉnh, nhóm nhạc của tôi không cần những người chỉ biết khoe mẽ bản thân."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Tôi có vẻ như đã nghe thấy một đoạn giai điệu, có ai đó đang tập dượt gần đây không?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_61007_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "Chết đi!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Đúng rồi, đúng rồi, chính là như vậy, đây là buổi lễ cuối cùng, bản Requiem dâng tặng cho chính âm nhạc!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_61010_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "À, Người Giữ Gìn, anh đến vừa kịp. Hãy nói cho tôi biết, anh nghĩ gì về cách xử lý bản nhạc này?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Nhạc dây, bắt đầu."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Nó trở nên rõ ràng, đoạn giai điệu uốn lượn, như tiếng khóc than đau thương của linh hồn… Tôi chắc chắn rằng tôi đã từng nghe ở đâu đó."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_61014_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Lý trí, trật tự, tôi dùng chúng để xây dựng bậc thang, bước lên trên, cuối cùng, mở cánh cửa của điện đường đó. Và sau cánh cửa đó, lý trí và trật tự sẽ không còn tồn tại —— âm nhạc thực sự vĩnh cửu sẽ vượt qua lý trí."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về lý tính và trật tự"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Nhìn tay tôi, một, hai, ba."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Tôi đã nghe buổi biểu diễn của cái gọi là ban nhạc của các bạn, có nhiều chỗ còn chưa hoàn thiện. Nhưng không sao cả, tôi đã lập ra một kế hoạch chi tiết, chắc chắn sẽ trình diễn một chương trình hoàn hảo trước Lễ Bạc Sương."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Tôi vẫn không thể quên được ngày đầu tiên nghe thấy bản nhạc từ sâu thẳm trong tâm trí. Giữa những nốt nhạc và hợp âm, mọi thứ trong thế giới thực đều không còn tồn tại. Chỉ còn lại âm nhạc, âm nhạc thuần khiết và cao cả."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Thật đáng tiếc, chắc cần phải tăng cường luyện tập rồi."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Đây là lệnh."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Tôi thường không đưa ra loại lời mời này, nhưng… bạn có muốn thử xem không? Hãy cầm lấy cây chỉ huy, thổi hồn vào bản nhạc với sức sống mới?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_61020_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Thay vì diễn đạt qua ngôn từ, tôi thích thể hiện bản thân thông qua âm nhạc. Nhưng quá trình giao tiếp với bạn giống như chỉ huy một dàn nhạc đã tập luyện vô số lần, mượt mà, thậm chí thường xuyên mang lại bất ngờ. \nDù là đối với âm nhạc hay đối với tôi, bạn đều là người đặc biệt."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_61021_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = "Trong nhạc giao hưởng, sự phối hợp giữa các nhạc cụ rất quan trọng, cách các bè gia nhập và rời đi đều mang lại trải nghiệm khác nhau cho bản nhạc. \n Tôi muốn nói rằng, nếu chỉ huy thân thể được đánh thức là một buổi biểu diễn, bạn đã làm rất tốt."
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_61022_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Bạn cũng thích bản nhạc này sao? Chỉ với bốn ô nhịp đã thể hiện trọn vẹn motif, phần nhạc cụ hơi dẫn dắt giai điệu vút lên cho đến khi chạm đến chủ đề, cách thiết kế này đã ảnh hưởng tới vô số người sau… Xin lỗi, tôi có nói hơi nhiều không?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_61023_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Bản diễn hoàn hảo."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_61026_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Mỗi người trong chúng ta đều ẩn giấu một giai điệu riêng, nó bị giam cầm bởi lý trí và thân thể, chỉ có thể nở rộ hoàn toàn khi rơi vào trạng thái điên cuồng."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Âm nhạc là thứ duy nhất đáng để tôn vinh."
  },
  Voice_61028_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_61029_AwakerVoiceContent = {
    Text = "Âm nhạc là thứ duy nhất đáng để tôn vinh."
  },
  Voice_61029_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6102_AwakerVoiceContent = {Text = "Đi nào."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Hãy nghe đây, bản Anh hồn khúc cuối cùng!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Hãy xin tha thứ!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Hãy nghe đây, bản Anh hồn khúc cuối cùng!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_6104_AwakerVoiceContent = {
    Text = "(khẽ rên)"
  },
  Voice_6104_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Bạn cũng muốn bị thiêu rụi trong ngọn lửa xanh sao?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Dám để tâm trí lang thang hả?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "Chú tâm vào!"
  },
  Voice_6108_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Làm sao lại có đứa trẻ đáng yêu như vậy ở đại học~ Tôi vừa nói với cậu ấy \"Có muốn làm nô lệ của tôi không\", cậu ấy đã đỏ mặt và lắp bắp nói gì đó \"Tôi đã là hiệp sĩ của Người Giữ Gìn rồi\"...\nRõ ràng điều này không hề xung đột mà~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Chuyện trò·về Orci"
  },
  Voice_6109_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Orci\""
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Đừng nghĩ đến việc tiếp cận công chúa."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Kỹ năng·một·Sóng Gẩm"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Hãy chấp nhận số phận."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Kỹ năng·một·Thủy Triều"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Cánh cổng của quê hương đang dần rời xa tôi…không…đừng để xảy ra một lần nữa…"
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Đừng cản đường!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Đừng cản đường!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Đây là hậu quả cho hành động của các ngươi."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Muốn chết à?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Tôi cảm thấy mình lại bị rỗng rỗng… Trái tim của tôi bị rỗng rỗng! Chỉ cần vài viên aspirin, kết hợp với roi da và một chút đau đớn, chắc chắn sẽ khỏi…"
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Thậm chí cả bạn cũng không thể chữa khỏi cái tật quái đản này? Thế mà bạn vẫn cứ chạy theo rỗng rỗng, đúng là không biết sợ chết."
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Tôi là chiến binh La Mã cuối cùng —— Yu U Hahi!"
  },
  Voice_6119_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6120_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6120_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Tôi là chiến binh La Mã cuối cùng —— Yu U Hahi!"
  },
  Voice_6121_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6122_AwakerVoiceContent = {
    Text = "Rỗng rỗng...? Tôi đương nhiên biết, không phải chỉ có nghĩa là mối quan hệ chủ-tớ được giải trừ sao, điều này có gì khó đâu."
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Tôi đã được triệu hồi, ranh giới giữa thần linh và người khờ đã trở nên mờ nhạt."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6123_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Ừm...... vừa đủ nhẹ nhàng vừa đủ mạnh mẽ, kỹ thuật massage rất tốt~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Nơi này trang trí có vẻ quá cũ rồi. Tối om, cứ như là có ma vậy."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Đây có cây cỏ xanh tươi, không khí yên bình, còn có thể chữa khỏi bệnh của chị, đối với chúng tôi hai người, đây chính là ngôi nhà mới tốt đẹp nhất."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Không ngờ lại có thể trùng phùng ở đây…… Không biết cuộc sống của chị ấy thế nào sau đó. Dù hỏi ra sao, chị ấy vẫn bảo là mọi thứ đều ổn…… Thật lòng xin lỗi, vẫn phải cảm ơn bạn đã giúp hai chị em chúng tôi đoàn tụ."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Lời đùa · Về Phiệt"
  },
  Voice_6127_UnlockDesc = {
    Text = "Nhận thân thể được đánh thức \"Fiynt\"để mở khóa"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Lễ dâng lên Đức Chúa."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Lễ dâng lên Đức Chúa."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Bình tĩnh, bình tĩnh nào……"
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Trong thân thể tôi có nhiều \"tôi\": vui vẻ, buồn bã, giận dữ... Họ thích bánh bông lan, nhưng ghét những ngày mưa ở Lentiennam. Họ đều gọi là \"24\" và đều kính yêu ngài."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6131_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Tôi từng làm việc đến nửa đêm hàng ngày, dệt vải, giặt giũ, dọn dẹp, làm bảo mẫu, thậm chí là quét rác… Tôi đã làm mọi việc chỉ cần có thể kiếm tiền. Lúc đó, sống, cũng chỉ đơn giản là sống mà thôi. \n Bây giờ, chúng tôi có thức ăn tươi ngon, giường ấm áp, còn có những người tốt bụng như quý ông đây… thật sự là điều không dám nghĩ tới."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6132_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Dù sao đi nữa, chúng tôi sẽ chia sẻ một phần bít tết, một giường ngủ, tuyệt đối không gây phiền phức cho bạn."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6133_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Hì hì, người phụ nữ đó sợ tôi ra ngoài, buổi tối đến ngủ cũng không dám. Thư giãn đi, xem như vì quà tặng, tôi không nỡ giết bạn đâu. \nTôi là ai? Tất nhiên là \"24\" rồi, hahahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6134_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Tôi hiện đang cảm thấy rất tốt. Gì, bạn nói tôi đã bị một thứ khác chiếm lấy tâm trí? Buồn cười, thật nực cười... ờ…"
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6135_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Làm thần tử, ngươi còn biết điều. Trước khi đón chào giấc ngủ dài tiếp theo, bản cung sẽ hạ mình, tạm thời ở lại đây."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Ừm, nước biển đêm nay rất ấm…"
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "Con chim trắng bay lượn trong giấc mơ, đã đến."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Như bạn mong muốn, sự tồn tại của tôi trở nên rõ ràng hơn."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "Tốt quá tốt quá!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6141_AwakerVoiceContent = {
    Text = "Thật là vui!"
  },
  Voice_6141_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Giao cho tôi nhé!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Giao cho tôi nhé!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Chào mừng đến với —— bữa tiệc của chúng tôi!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Cơn thịnh nộ bùng phát·điên cuồng"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Cô gái này không nghi ngờ gì là mang trong mình dòng máu của ta…… Không, tuổi của ta còn chưa đủ để để lại con cái. Nhưng, lực lượng của cô ấy thực sự cùng nguồn gốc với ta."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về dòng máu của thần"
  },
  Voice_6145_UnlockDesc = {
    Text = "Sau khi nhận được một trong hai thân thể được đánh thức \"Ai Jī Sī\" hoặc \"Muphí\", tính năng sẽ được mở khóa"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Ơn huệ của chủ nhân, Gia Lân không dám quên dù chỉ một khắc!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "——ngọt ngào, thật ngon!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Gia Lân gần đây đang giảm cân, không thể ăn quá nhiều đâu~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Để trở thành đối thủ của tôi, những gã này còn chưa đủ trình."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Giải thích nghệ thuật giống như giải thích cổ phiếu đường sắt vậy —— xin đừng làm khó cho những nghệ sĩ tội nghiệp."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Ai Jī Sī… có làm sai điều gì không?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Lời cầu nguyện của bạn, tôi đã nghe thấy."
  },
  Voice_6152_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6153_AwakerVoiceContent = {
    Text = "Lời cầu nguyện của bạn, tôi đã nghe thấy."
  },
  Voice_6153_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6154_AwakerVoiceContent = {
    Text = "Hừ, kẻ vô lễ."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "À, vừa rồi đi ngang qua có phải là vị đại nhân đó không? Không, không sao đâu. Lần trước tôi chào ông ấy, ông ấy không hề nhận ra tôi… thế mà tôi vẫn luôn chờ ông ấy đến đón tôi khỏi nhà tù, nhưng đến tận khi có cuộc bạo động, ông ấy cũng chẳng xuất hiện…"
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Chuyện vặt·về \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Hoàn thành \"điều tra hành động\" chương 7 để mở khóa"
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Đáp lại sự thức tỉnh của con người, thiết lập mối quan hệ hợp tác, là để hoàn thành trách nhiệm chưa hoàn thành của tôi—— nếu bạn có thể trưởng thành đến mức đủ mạnh để đối đầu cùng tôi, thì không còn gì tốt hơn."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Chị gái, brun, và kẻ nhát gan ở nhà tế bần, có họ làm bạn là đủ rồi. Ừ... thôi được, coi như cậu cũng vậy. Brun, chia một viên kẹo cho Người Giữ Gìn. \n \"chít chít?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6157_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Khu ổ chuột phía Đông không phù hợp cho trẻ em sinh tồn. Ông chủ công trường xảo quyệt sẽ tìm mọi cách cắt giảm tiền lương của các cậu bé bán báo, bắt bẻ tốc độ của những cậu bé giao sữa, bắt lỗi chi li... gây khó dễ! Tóm lại, muốn sống sót trên phố, chỉ có thể dựa vào chính mình, hoàn toàn không thể tin tưởng được ai."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6158_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Những \"thói quen xấu\" của tôi không thể sửa ngay được, bạn hiểu chứ? Ngủ dưới gầm cầu và trong cống nước mưa, tồn tại bằng những thứ bỏ đi, chỉ việc sống sót đã đủ khó khăn rồi… Bạn không thể bắt tôi lập tức quen với việc gấp chăn sau khi thức dậy! Ít nhất cũng cần nửa tháng để thích nghi chứ!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6159_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Cảm giác bị lạc trong không gian thật sự rất tệ. Nhờ bạn đã cứu tôi khỏi đó, nếu có việc gì thì cứ nói thẳng, nhưng tôi không chắc mình có thể giúp được đâu. \nDù sao tôi cũng chỉ là một đứa trẻ, mong bạn đừng làm khó tôi nhé~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6160_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hey, ông Tây! Ông có thấy Brâu không? Thằng tham ăn ấy không biết lại chạy đi đâu vì mùi gì đó rồi."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6161_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Những người có lực lượng mạnh mẽ không được dùng sức mạnh của mình để bắt nạt người khác, vì các ngươi chia sẻ dòng máu của ta\" — Tôi ghi nhớ lời răn dạy của thần nhân từ và sẽ sử dụng lực lượng này để bảo vệ những người xung quanh tôi."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6162_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Bạn có tò mò về điều tôi đã thấy ở điểm khởi đầu của vũ trụ không? Tôi có thể nói với bạn, ở đó chẳng có gì cả."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6163_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Sáng hơn."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "Ngọn đèn sáng mãi…"
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Kết nối với cố quốc mạnh mẽ hơn rồi."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Nếu có thể giúp mọi người thoát khỏi khổ đau, tôi sẽ hoàn toàn mãn nguyện."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Hãy cho tôi thêm chỉ lệnh đi, sứ giả xanh xao, mong ngọn lửa của bạn soi đường dẫn lối cho tôi."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6169_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6169_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "Việc rèn luyện con người không chỉ ở thân thể, mà còn ở nội tâm."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6171_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6171_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Đau quá!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6173_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6173_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6174_AwakerVoiceContent = {
    Text = "Ư! Nhiệt độ của bạn vẫn còn hơi cao đối với san hô. Nhưng... nó vừa ấm áp, vừa nồng nhiệt. Tôi rất thích."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "À……bạn có việc gì không? Nếu được, mình vào khu vực phía sau nói chuyện nhé……"
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Chưa từng nở rộ, đã héo úa, giống như hoa súng bị nước nuốt chửng… Trong dòng nước lạnh lẽo và cuồn cuộn ấy, yếu đuối tìm kiếm sự yên bình, không dám theo đuổi hạnh phúc của chính mình… Đó chính là tôi, người gìn giữ bí mật."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6176_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Tôi từng rơi vào mối bận tâm như thế này: liệu nỗi đau có kéo dài hơn chính sức sống? Nếu vậy, giấc ngủ yên bình có hạnh phúc hơn sự tỉnh táo đầy tra tấn hay không? Sau khi thức tỉnh, tôi cũng đã từng chìm đắm trong đó, cho đến khi ngài mang đến cho tôi bến cảng tránh gió này…"
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6177_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Khi ở viện dưỡng lão, tôi đã từng thử kết bạn, nhưng mọi người không muốn tiếp cận tôi... có phải vì \"độc\" thấm vào tận xương tủy này không? Tóm lại, khi tiếp cận tôi, bạn cần cẩn thận một chút."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6178_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Gió đêm mang theo tiếng chuông khiến người ta cảm thấy bình yên. Bạn có muốn ngồi trên ghế đá nghe một lát không? Tôi sẽ dùng khăn mỏng trải sẵn chỗ ngồi cho bạn."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6179_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Bạn có từng nghe nói về \"hải táng\" (phong tục an táng dưới biển) không? Thị trấn nơi tôi sinh ra có một phong tục, cư dân sẽ chìm thi thể của người chết xuống biển, vì vậy đại dương là nơi quy về của tất cả mọi người. Còn tôi, là người sớm trở về vòng tay của biển cả……"
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6180_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hừ!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6182_AwakerVoiceContent = {Text = "À"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Á!"},
  Voice_6183_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6184_AwakerVoiceContent = {Text = "À"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Đã lưu trữ nhật ký chiến đấu. Cảm ơn vì sự nỗ lực của bạn, Người Giữ Gìn."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(rên rỉ)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(rên rỉ)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(rên rỉ)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Còn có thể tiếp tục."
  },
  Voice_6189_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6190_AwakerVoiceContent = {
    Text = "Khách đến thăm salon sẽ được đón tiếp chu đáo nhất… Để tham gia, liệu khách có chuẩn bị những bí mật xứng đáng với bữa tiệc này không?"
  },
  Voice_6190_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6191_AwakerVoiceContent = {
    Text = "Tôi thích những điều mới mẻ. Trong hành trình nghìn năm, tôi đã chứng kiến nhiều cải tiến và phát minh thú vị, như thể loại thơ ca, hình ảnh trong điện ảnh. Con người thật là những sinh vật đầy thú vị!"
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Ừ, Lily biết cô ấy. Khi mẹ không có nhà, Lily ở nhà cô ấy."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Đào Đen Đá"
  },
  Voice_6192_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Đào Đen Đá\", tính năng sẽ được mở khóa"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Người đã quấy rối giấc ngủ dài của tôi, chính là bạn sao?"
  },
  Voice_6195_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6196_AwakerVoiceContent = {
    Text = "Thần minh? Chỉ có những kẻ ngu ngốc mới đặt mạng sống của mình vào tay một tồn tại mờ ảo như vậy. Thay vì đặt cược vào thần minh, hãy nghĩ cách trở nên mạnh mẽ hơn."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Chủ nhân của đấu sĩ nào đó, chẳng qua chỉ là loài sâu bọ hèn mọn mà thôi."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Agrippa\", bạn sẽ mở khóa"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Sau khi chiến thắng, xin hãy để tôi lấy vật liệu cần thiết cho việc sinh sản và duy trì nòi giống."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Bạn lớn! Bạn bè! Hì hì, phải làm bạn tốt với Ô Ryta mãi mãi nhé!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Tôi hiện đang rất phấn khích... Nếu không muốn chết, tốt nhất là hãy tránh xa tôi."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Người đó… thái độ như vậy với người khác có thực sự ổn không? Bà Sara nói rằng trẻ con không được tùy tiện nổi giận…"
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_6201_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "Sự vinh quang của chiến thắng thuộc về bạn."
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Ăn, không ăn nổi nữa rồi~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Lỗ hổng trong lòng đã được lấp đầy rồi nè~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Lại nóng hơn một chút~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Tôi biết đứa trẻ đó, thỉnh thoảng cô bé đứng từ xa để xem buổi biểu diễn. Cũng may là cô bé không đến gần, nếu không, những khán giả nhỏ này sẽ \"kiệt sức cả về thể chất lẫn tinh thần\" đấy!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Lời đùa · Về Phiệt"
  },
  Voice_6206_UnlockDesc = {
    Text = "Nhận thân thể được đánh thức \"Fiynt\"để mở khóa"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tinkerer đã nói, biết ơn và trả ơn. Vì vậy, ở bất kỳ nơi nào tôi có thể giúp đỡ, tôi sẽ hỗ trợ.."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Xin chào, Người Giữ Gìn, có gì cần giúp đỡ không?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Sớm muộn gì đó, tôi sẽ trở lại chiến trường với tư cách là người tiên phong dẫn đầu trong trận chiến."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6209_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Bạn có thể tin được không? Tôi cảm nhận được rằng xương chân bị gãy đang dần hồi phục."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6210_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Xin chân thành cảm ơn sự tin tưởng của bạn, đã nuôi dưỡng tôi đến cảnh giới này. Nghĩ rằng bạn cũng là người theo đuổi công lý, vậy, tôi sẽ tiếp tục viết nên vinh quang quân ngũ ở đây."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6211_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Ngày khởi hành đang đến gần, dòng máu sục sôi mãnh liệt trong lồng ngực."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6212_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "Danh dự của một chiến binh đang được khôi phục."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6213_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6214_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6214_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Đau đau!"},
  Voice_6215_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6216_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6216_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6217_AwakerVoiceContent = {Text = "Đùa dai!"},
  Voice_6217_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Ôi trời ơi, xin lỗi, lần sau nhất định sẽ được!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Tôi nghe có người lớn tiếng gọi tên tôi, Agrippa, Agrippa, Agrippina…"
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6219_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Tôi thấy... Ngài ấy từ bóng tối dưới đáy giếng leo lên, vô số con mắt hiện ra trên những khối thịt. Chúng nhìn chằm chằm vào tôi, gọi tôi là... vị thần của mê cung."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6220_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Tôi có một ham muốn mãnh liệt muốn xem cuộc đấu… Nếu địa điểm là trong mê cung thì còn tuyệt hơn."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6221_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Hợp đồng… Đúng, tôi muốn ký một hợp đồng với bạn, một hợp đồng chủ và người phục vụ không bao giờ mất hiệu lực…"
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6222_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hừ……cũng được, thêm chút nữa đi, tôi phải làm no bụng mấy con nhện con này."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6223_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Ô uế đến mức nào, kinh tởm! A a—— đừng nói nữa, xin ngài! Đừng để tôi thấy nó, cũng đừng, đừng nhắc đến nó bên tai tôi…"
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Quá khứ của tôi tiến triển đều đặn, bình yên như vùng biển xích đạo, không có gì đáng để nhắc tới."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6225_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Ừm…? mẹ, ôm ôm… ừm, thật ấm áp…"
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Bụi sao…"
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Ôi, bạn bị lạc đường rồi à?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6229_AwakerVoiceContent = {
    Text = "Không có ích."
  },
  Voice_6229_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6230_AwakerVoiceContent = {
    Text = "Mỗi khi nhớ lại cảnh những kẻ phản bội quỳ trên mặt đất khóc lóc cầu xin tha thứ, tôi cảm thấy một cảm giác dễ chịu, ngọn lửa trong lòng dường như cũng tan biến đi không ít."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Chủ tàu đã đưa tôi ra khỏi nhà và trao cho tôi sứ mệnh của một nữ thánh hàng hải. Từ đó, ý nghĩa cuộc sống của tôi không còn do chính tôi kiểm soát. Có người nói với tôi rằng, ít nhất trong cuộc đời thứ hai này với thân phận là một thân thể được đánh thức, hãy sống vì ước muốn của mình… Bạn có thể giúp tôi không? Giúp tôi trở nên ích kỷ hơn, giúp tôi tìm thấy ước muốn của mình."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6231_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. Tôi không có gì để nói với anh —— trừ khi anh đủ can đảm tự nguyện trở thành gladiator dưới trướng tôi."
  },
  Voice_6232_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6233_AwakerVoiceContent = {
    Text = "Tà Vy… nguy hiểm hơn chúng ta tưởng rất nhiều. Sau này nếu tôi không còn nữa, cậu phải hết sức đề phòng cô ấy."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Tà Vy"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Dùng phương pháp này…… giải thích thế giới!"
  },
  Voice_6235_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6236_AwakerVoiceContent = {
    Text = "Dùng phương pháp này…… giải thích thế giới!"
  },
  Voice_6236_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6237_AwakerVoiceContent = {
    Text = "Hãy lấp lánh!"
  },
  Voice_6237_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6238_AwakerVoiceContent = {
    Text = "Tôi sẽ cố gắng hết sức."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Tôi sẽ cố gắng hết sức."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Hãy để nó thối rữa đi."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Hãy để nó thối rữa đi."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Nụ cười và lễ nghi là một lớp giáp, giúp tôi và người khác giữ khoảng cách, tránh xa những rắc rối nhàm chán. Còn về mặt thật của tôi... tôi không ngại thể hiện cho bạn đâu."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6242_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Suy nghĩ tích tụ thành vôi trắng, sau đó bị xối rửa thành sơn đẹp đẽ. Chúng hòa làm một với tôi, bên trong nhịp tim của tôi vẫn đập mạnh mẽ... Bạn có muốn lắng nghe chăng?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6243_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "Cảm hứng giống như những bong bóng liên tục nổi lên từ nước biển: chỉ cần chạm nhẹ, chúng sẽ biến mất. Bạn cũng giống vậy à?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6244_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Chiến tranh, cướp bóc, danh lợi đều là dục vọng của con người. Người thợ điêu khắc khiêm tốn không quan tâm đến những thứ con người theo đuổi, cô chỉ muốn làm nô lệ của cái đẹp."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6245_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Cuộc sống tuyệt vời nằm ở sự đắm chìm. Đôi khi, bạn không nên quá khắt khe với bản thân."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6246_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "Vết thương nhỏ nhặt.."
  },
  Voice_6247_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6249_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6249_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "Khốn kiếp!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6251_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6251_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "Hiện tượng rỗng rỗng sẽ mang lại nhiều biến động và thảm họa, có thể đất nước tôi đã chịu ảnh hưởng từ hiện tượng này, dẫn đến việc chìm vào biển sâu…"
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Uống!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Ya~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Uy nghi của người khổng lồ."
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Thử cái này!"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Sự hy sinh không thể tránh."
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Cũng không tệ, đây là vinh quang của chiến binh."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Tên kia, sao lại để một người phụ nữ như vậy vào! Vạch ra khu vực cấm cho ta! Đừng để cô ta đến gần ta trong phạm vi năm mươi bước!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về MIRIAM"
  },
  Voice_6259_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Miriam\"để mở khóa"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Tại sao muốn trở nên mạnh mẽ? Trong bộ tộc của tôi, kẻ yếu sẽ bị lột sạch quần áo, cạo trọc đầu, đối mặt với những sự sỉ nhục bẩn thỉu nhất mà bạn có thể tưởng tượng —— giá phải trả khi trở thành kẻ yếu —— không phải ai cũng có thể gánh chịu."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6260_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Nữ thần may mắn, hãy ban phúc lành cho tôi!"
  },
  Voice_6261_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6262_AwakerVoiceContent = {
    Text = "Quả nhiên… sức mạnh của con người, có giới hạn sao…"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Gân cốt hơi thả lỏng một chút."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6263_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Hãy để tình yêu của tôi trở nên sâu sắc hơn, đây là sự thể hiện của dục vọng của bạn sao?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6264_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6265_AwakerVoiceContent = {
    Text = "Hãy hành động tùy ý!"
  },
  Voice_6265_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6266_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6266_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6267_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6267_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6268_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6268_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6269_AwakerVoiceContent = {
    Text = "À..., không thể tha thứ…"
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Liều lĩnh một chút!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Biu——"},
  Voice_6272_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Tiếp tục như vậy, điểm cuối kỳ của bạn rất đáng để mong chờ."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Nghe nói có một tên trộm từ khu ổ chuột đến, còn mang theo một con chuột béo? Hê hê hê hê...... Hãy xem tôi thay trời hành đạo, giúp chủ nhân trừ hại!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_6274_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Lại đây, hít sâu ——"
  },
  Voice_6275_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6276_AwakerVoiceContent = {
    Text = "Thú vị, tốc độ trưởng thành của ngươi trong chiến đấu vượt xa sự tưởng tượng của ta. Nếu có thêm thời gian, rất có thể ngươi sẽ trở thành người kế tiếp... Quả thật kỳ lạ... Dù đã vượt qua thời gian, ta vẫn không ngờ rằng mình lại đặt hy vọng vào một sinh vật nhỏ bé như ngươi."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6276_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Có lẽ đây chính là thời điểm để nói những lời này, hãy nghe kỹ nhé. \nQuái vật sao Lơ-tan, chính thức gửi lời mời quyết đấu tới ngươi… Tất nhiên, trước khi ngươi trưởng thành đến đỉnh cao, ta sẽ bảo vệ sự an nguy của ngươi. Đối thủ đã được định sẵn bị chết yểu, loại chuyện này ta sẽ không để nó xảy ra lần thứ hai."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6277_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hừ… thật chẳng hiểu nổi, tại sao Ramona lại thừa nhận cậu làm đồng đội. Ta công nhận trên người cậu có mùi vị của kẻ mạnh, nhưng để trở thành đối thủ xứng tầm với ta, vẫn còn một khoảng cách khá xa."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6278_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Đúng vậy, hãy ngước nhìn tôi bằng ánh mắt sùng bái. Tôi là tạo vật cổ xưa nhất của hành tinh, đáng được những kẻ nhỏ bé tôn trọng — Tôi đã lính canh hành tinh này suốt hàng triệu năm, đòi hỏi một trận chiến thỏa đáng làm phần thưởng, chẳng lẽ lại quá đáng sao?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6279_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hả, tôi đâu có sức để chơi trò chơi con nít. Nếu còn biết điều, thì tìm chỗ ngồi im đi."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6280_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Các linh hồn không được che chở, tôi sẽ ban cho các bạn sự an bình cuối cùng."
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6282_AwakerVoiceContent = {
    Text = "Giữ mình."
  },
  Voice_6282_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6283_AwakerVoiceContent = {
    Text = "Cảnh báo"
  },
  Voice_6283_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Có thứ gì đó, trong não tôi rên rỉ…"
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6284_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Dường như có một lớp màn sương trắng bao phủ tư duy của tôi."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6285_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Tiếng động càng lúc càng to, vải trắng càng lúc càng dày."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6286_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Có phải là tiếng kim đồng hồ quay?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6287_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Khi tiếng chuông vang lên, liệu tôi còn ở đây không?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6288_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "Loại thủ đoạn thô lậu này… hừ, kẻ không biết trời cao đất dày, làm sao tôi có thể dễ dàng bị ngươi trói buộc như vậy?"
  },
  Voice_6289_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6290_AwakerVoiceContent = {
    Text = "Xin hỏi… các người có thấy em gái của tôi, Jenkin không? Đó là một cô bé mang theo một con chuột và hơi dữ dằn… Tôi sẽ không nhầm lẫn đâu."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_6290_UnlockDesc = {
    Text = "Hoàn thành Chương 2 của \"Điều tra Hành động\"để mở khóa"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Cảm ơn sự ưu ái của bạn."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6293_AwakerVoiceContent = {
    Text = "Đã sẵn sàng."
  },
  Voice_6293_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Hãy mong chờ nhé."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Ca hát vì bạn."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "Người giữ bí mật mới? Hãy dùng hết sức của bạn đi, để tôi xem bạn có đủ tư cách trở thành đối thủ của tôi không."
  },
  Voice_6296_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6297_AwakerVoiceContent = {
    Text = "Mặc dù tôi là một người chủ trương hòa bình, nhưng \"chị em\" rõ ràng không nghĩ như vậy..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6299_AwakerVoiceContent = {
    Text = "Lui xuống!"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Cư nhiên dám xúc phạm tôi như vậy…"
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Đã sẵn sàng chưa, buổi biểu diễn ảo thuật của Kassia sắp bắt đầu! Đừng dời mắt đi, đừng bỏ lỡ những khoảnh khắc tuyệt vời. It's showtime!"
  },
  Voice_6301_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6302_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "Tôi đã nhận được lịch trình của bạn từ cô Sylvie, điều này thật quá khắt khe đối với người mới. Tôi hiểu rằng các bạn đang làm những điều đúng đắn, nhưng để lính mới gánh vác gánh nặng có thể gây ra những rắc rối không cần thiết cho đội. \nBạn nói bạn không phải là lính mới? Không, tôi có thể thấy trong ánh mắt của bạn, bạn vẫn chưa trải qua nhiều điều."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6304_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Tôi ghét bản thân mình vô trách nhiệm… À! Ngài không cần phải an ủi tôi đâu! Những kỷ niệm quá khứ đã trở thành nguồn động lực giúp tôi trưởng thành, tôi đã trở thành trợ lực của ngài, phải không?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Tôi và người đàn ông đó không hợp nhau. Cuộc sống đâu có nhiều tội lỗi và trừng phạt như vậy, quan trọng là sống cho hiện tại, đúng không?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Salvador\""
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Thời gian không còn nhiều, xuất phát nào."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Ghét ngọn nến dễ tắt, ghét bánh mì đen, ghét sợi chỉ trên vạt váy… không có lý do đặc biệt, ghét những thứ này, chẳng phải là điều đương nhiên sao?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Vì đã gọi ta là Thánh Nữ, vậy các ngươi phải quỳ gối thần phục!"
  },
  Voice_6309_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6310_AwakerVoiceContent = {
    Text = "Vì đã gọi ta là Thánh Nữ, vậy các ngươi phải quỳ gối thần phục!"
  },
  Voice_6310_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6311_AwakerVoiceContent = {
    Text = "Hãy ca hát."
  },
  Voice_6311_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "\"Tủ đồ của quý cô\", \"Hướng dẫn cho người thợ may\"đều là những cuốn sách tuyệt vời... ngay cả khi không mua được, chỉ cần ngắm nhìn những chiếc váy đẹp cũng rất tốt."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Rất kỳ lạ, tôi nhớ những thứ khác luôn rất khó khăn, nhưng nhớ bạn chỉ mất vài ngày… Gì vậy, đã ba tháng rồi ư? Xin lỗi thật sự, tôi lại quên mất."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Hãy thưởng thức"
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Hãy tiếp tục cải thiện dáng vẻ."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Luyện tập động tác vung roi quay thêm hai mươi lần nữa."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Các động tác của tôi có đủ chính xác không?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Cứ tự nhiên!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Nhanh lên, đưa Brun đi!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Quỳ dưới ngai vàng."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Quỳ dưới ngai vàng."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Những biểu cảm đa dạng của con người khi đối mặt với dục vọng luôn khiến tôi ngạc nhiên. Đáng tiếc thay, con người vẫn quá yếu đuối, quá bé nhỏ… Chỉ có điều này khiến tôi khó chịu như bị mèo cào trong lòng."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Từ ký ức của cô ấy, tôi đã thấy rất nhiều điều về \"sự tan chảy\"... nhưng mỗi lần muốn kể cho bạn, tôi lại mất ý thức, có lẽ đây cũng là trò của cô ấy."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Như vậy mà tan biến, hay sao?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Một người hầu hợp cách phải yếu ớt, đầu óc trống rỗng——tôi thích những con cừu hiền lành."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Chúng ta có thể gặp nhau như vậy, hẳn là sự hứa hẹn của thần linh đối với những người khổ nạn——ngươi chính là ngọn lửa trắng xóa tiêu trừ tai họa, còn ta đương nhiên sẽ làm cánh tay của ngươi, kề vai sát cánh bên ngươi."
  },
  Voice_6327_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6328_AwakerVoiceContent = {
    Text = "Đến đây là đủ!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Đã thử qua việc đổ trực tiếp dung dịch ăn mòn vào thân thể chưa? Chất lỏng màu đen giống như rắn độc, leo lên tim bạn, sau đó... rầm! Thân thể bạn sẽ nổ tung thành một khối chất lỏng ấm áp. Kinh tởm, nhưng rất hiệu quả."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hừ, đúng là nơi tụ tập của những kẻ yếu đuối chỉ biết dựa dẫm vào nhau để sưởi ấm."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Thỉnh thoảng, cô bé đi xe máy đều giúp tôi bảo dưỡng chi giả. Tuy nhiên, tần suất bảo dưỡng gần đây hình như hơi dày đặc thì phải?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Nốtira"
  },
  Voice_6331_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Nốtira\""
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Mối quan hệ giữa chúng ta? Còn cần phải hỏi sao? Chính là mối quan hệ như bạn đã tưởng tượng đó!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Không phải thể loại tôi giỏi, nhưng nếu bạn nhất quyết muốn vậy thì cũng được."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Vòng mắt đen của bạn lại đậm hơn rồi... Sao lại phải vất vả đến vậy? Bạn cần phải học cách tận hưởng thời gian rảnh rỗi như tôi."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6334_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Chờ đã, chưa được phép tôi……"
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6335_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Tốt lắm......đang dần trở về hình dạng ban đầu."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6336_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Đây là lực lượng đủ để đối kháng \"sự thối nát xanh\"... Bạn đã chạm vào những gì không nên chạm. Còn tôi, sẽ không bao giờ để bạn rời đi nữa."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6337_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shhh...... Ánh sáng bình minh của thung lũng sông, có lẽ đây là lần đầu tiên bạn thấy nó, phải không? Đây là phần thưởng dành cho lòng trung thành của bạn."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6338_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Cuốn này \"@1@2Sách Khải Huyền\" thôi nào. giúp kích hoạt trí tuệ, hoặc nhanh chóng đi vào giấc ngủ."
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6339_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Thế gian vẫn quá ồn ào. Nếu bạn có thể tìm cho tôi một góc yên tĩnh trong học viện, thì không gì tốt hơn… Không, tôi không cần lò sưởi. Chỉ có tu luyện khắc khổ mới khiến thần linh nghe thấy lời cầu nguyện của tôi…"
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Dòng chất lỏng trên thân thể này là sáp nến hay mật ong, chỉ cần liếm một cái là biết ngay rồi?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6341_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Chào, chào gặp mặt. Tên tôi là Ai Jī Sī… Xin, xin hãy coi như tôi không tồn tại!"
  },
  Voice_6342_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6343_AwakerVoiceContent = {
    Text = "Chừng nào tôi vẫn là \"Ramona\", chúng ta vẫn sẽ là đối tác, phải không?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Vị tiểu thư có quầng mắt thâm đen ấy, từng hỏi tôi về phương pháp \"sống mãi dưới ánh mặt trời\"…… Thực ra, chỉ cần di chuyển qua lại giữa hai thế giới là được. Thế nhưng, cô ấy dù thế nào cũng không chịu bước vào đường hầm chiều không gian…… Thật đau đầu."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về Wenkel"
  },
  Voice_6344_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Wenkel\", mở khóa"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Chào mừng đến với thiên đường của tôi! Bạn có dám chịu đòn roi không?"
  },
  Voice_6345_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6346_AwakerVoiceContent = {
    Text = "Vì Người ấy đã thừa nhận bạn, ta sẽ không xem bạn là kẻ địch."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Cái gì mà tôi lấy, cậu đừng oan uổng người tốt nhé! Khi những con ốc vít hỏng của cô ấy biến mất, tôi chính là—brun!… Hehe, cậu cứ coi như chưa thấy gì cả đi?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Nốtira"
  },
  Voice_6347_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Nốtira\""
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Phiêu lưu quả nhiên thú vị như trong câu chuyện! Câu chuyện đó… là gì nhỉ?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "……ợ. À, xin lỗi, không cẩn thận lại hấp thụ quá nhiều năng lượng."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Sau khi vào thân thể con người, tôi đã mất liên lạc với tất cả đồng bào. Tôi sợ rằng những người khác không thoát khỏi sự truy đuổi của ác quỷ, sợ rằng tôi đã là người cuối cùng của chủng tộc... Cứu tôi, Người Giữ Gìn, hãy để tôi ở bên bạn, đừng bỏ mặc tôi trong bóng tối.."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6350_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Khi hành tinh bị hủy diệt, tôi đã từ bỏ thân thể và chuyển ý thức vào cơ thể của con người… nhưng tên quỷ đen đuổi theo tôi, giam cầm tinh thần, khiến tôi không thể thoát thân! Ngài ấy muốn kéo cả thế giới vào vũng lầy tối đen!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6351_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Xin hãy giúp tôi, Người Giữ Gìn… Chỉ cần để tôi ở lại trên thiết bị định vị mà không rời đi, trừ khi phải bước vào bóng tối và đối mặt với cái thứ đen tối đó… Tôi sẵn sàng làm mọi thứ! Tôi không thể rời khỏi thiết bị định vị, sắp rồi, tôi sẽ có thể định vị được tàn tích của hành tinh mẹ! Chỉ còn mười hai tỷ phép tính nữa thôi!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6352_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Có thể dùng phần cung cấp của bạn để giúp tôi xin hai túi chất bổ sung caffein không?…… Tôi không thể ngủ, tại sao phải ngủ? Đừng bao giờ ngủ! Khi nhắm mắt mọi thứ đều tối đen, tối đen……"
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6353_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Wow! Xin đừng đến gần tôi! Trước hết, hãy chứng minh bạn không phải là kẻ hầu của bóng tối! Đúng vậy, kẻ hầu, chỉ cần để tôi kiểm tra xem trên người bạn có dính loại chất lỏng màu đen ghê tởm đó hay không, tôi sẽ xác nhận bạn có phải là ác quỷ không…"
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6354_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Đừng hỏi nữa, đừng hỏi nữa…! Bạn rõ ràng biết tôi ghét nhất, sợ nhất điều gì! Bóng tối, bóng tối vô tận!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Phương pháp chữa trị rỗng rỗng? Thứ đó, không tồn tại ở đâu cả. \nBạn hỏi tôi làm thế nào để không bị lây nhiễm? Hì hì... chỉ cần \"không bị nhìn thấy\" là được rồi."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Cảm ơn chủ nhân."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Chúng cũng rất vui."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily, lớn lên rồi."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Muốn nghiền nát không?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Sao bạn lại gọi hắn ra! Tên vô dụng chỉ biết ngủ! Tự hạ mình, không chịu tiến bộ… Đáng lẽ tôi đã đặt nhiều hy vọng vào hắn! Chúng ta đi! Tôi không muốn nhìn thấy gã này!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về tulô"
  },
  Voice_6361_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_6362_AwakerVoiceContent = {
    Text = "Kinh tởm!"
  },
  Voice_6362_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Phiền quá!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Lần sau, hãy cùng bạn đi xem biển. Đi đến Fèi Fúer cũng được, tôi có thể làm hướng dẫn viên cho bạn, hoặc đi đến bất cứ nơi nào khác, khắp mọi nơi, tôi đều muốn cùng bạn đi xem."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6364_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "Biển có ngôn ngữ riêng của nó. \n……Như vậy, thỉnh thoảng tôi có thể trò chuyện với những con cá nhỏ trong hồ về chủ đề quê hương. Nếu bạn tò mò, bạn có muốn tôi giúp bạn dịch không?"
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6365_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Được cứu bởi ngài, tôi thường cảm thấy hạnh phúc đến nỗi sợ hãi… Xin ngài hãy nói với tôi, nơi này không phải là giấc mơ, và ngài cũng sẽ không biến mất âm thầm trong đại dương, phải không?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6366_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Cảm giác này có thể gọi là \"hạnh phúc\" không? Trước đây tôi… chưa bao giờ dám mong đợi điều này."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6367_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Thân thể cảm thấy ấm áp, như thể được bao quanh bởi làn nước biển dịu dàng, thật khó tin."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6368_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Đó có phải là lát cắt của Người không? Rất tốt, đúng là có uy nghi của một vị vua."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về tulô"
  },
  Voice_6369_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Không, đừng tiếp tục nữa… nó sẽ tìm thấy tôi!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Như vậy thì có lẽ sẽ luôn tỉnh táo rồi."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Xong rồi, xong rồi, chắc chắn sẽ bị phát hiện.."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Chúng ta đã thắng, bạn vui không? \"Vui\" là một cảm giác như thế nào?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Thích cái gì? Tôi thích bài ru của tinkerer... Đương, đương nhiên, bài hát của bạn cũng rất cảm động!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Anh ấy là một chiến binh tốt, tôi từng coi anh ấy là \"đồng đội\"... Gì, cậu nói, định nghĩa về \"đồng đội\" của tôi có vấn đề? Tôi muốn nghe thêm."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Goliath"
  },
  Voice_6375_UnlockDesc = {
    Text = "Mở khóa sau khi có thân thể được đánh thức \"Goliath\""
  },
  Voice_6378_AwakerVoiceContent = {
    Text = "Sao băng.."
  },
  Voice_6378_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6379_AwakerVoiceContent = {Text = "À——"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Lực lượng không ngừng, tràn ngập cơ thể…"
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6381_AwakerVoiceContent = {
    Text = "Hãy bay đi!"
  },
  Voice_6381_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Được đấy, bạn có ích hơn vẻ bề ngoài của mình."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Hai mươi, hai mốt, hai tư… Ơ không đúng, tôi đếm đến số nào rồi nhỉ? Một, hai, ba…"
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6383_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Tôi cuối cùng cũng đã làm rõ được số lượng vật liệu trước đây, như vậy tôi có thể hoàn thành việc sửa chữa nhanh hơn——ồ, những thứ này lại từ đâu ra vậy?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6384_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Hiệu suất sửa chữa gần đây có vẻ đã được cải thiện đáng kể, thật may mắn khi có bạn hỗ trợ! Nhờ vậy chúng ta sẽ sớm có thể bắt đầu cuộc phiêu lưu thôi!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6385_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Tôi có vẻ như bắt đầu nhớ lại một chút… Hôm qua bạn có phải đã đưa cho tôi một cái cờ lê loại 7 không?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6386_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Sửa, bổ, hoàn, thành! Hành trình phiêu lưu chưa biết, thế giới huyền bí, tôi đã đến!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6387_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom——"},
  Voice_6388_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Đừng tự lừa dối mình nữa, xiềng xích về tinh thần cũng là xiềng xích, đâu gọi là công bằng."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Như vậy, ranh giới giữa tôi và thân thể được đánh thức càng trở nên mờ nhạt. Bạn nhớ để mắt tới tôi nhé."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6390_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Đi nào, đi cứu thế giới."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6391_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Cảm giác như đọc hết \"Nguồn gốc các loài\" trong một hơi thật sảng khoái."
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6392_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Trở nên mạnh mẽ hơn rồi, lần sau hãy để tôi thực hiện nhiệm vụ một mình thử xem?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6393_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Ngoài chỉ số chiến đấu, ký ức và khả năng logic dường như không có sự cải thiện đáng kể, quả nhiên vẫn phải tự mình suy nghĩ."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6394_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Tôi sẽ cho họ nếm trải cảm giác cuộc đời bị đảo lộn, mất hết mọi thứ, bị vạn người giẫm đạp lên."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6395_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "Sự sỉ nhục mà tôi phải chịu, tất cả những gì tôi đã mất… Tôi thề sẽ bắt họ trả giá đắt, khiến tất cả họ phải trả giá."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6396_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "Thù hận ngọt ngào biết bao, nếu hòa cùng máu của kẻ thù, hẳn sẽ trở thành món ăn ngon nhất thế gian."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6397_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "À! Đừng bất ngờ từ phía sau như vậy!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Lửa rực cháy trong lồng ngực tôi… Đúng, tôi chưa bao giờ quên và cũng không thể quên."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6399_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Đốt cháy đi, linh hồn của bài thơ."
  },
  Voice_6400_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6401_AwakerVoiceContent = {
    Text = "(humm nhẹ)"
  },
  Voice_6401_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6402_AwakerVoiceContent = {
    Text = "(humm nhẹ)"
  },
  Voice_6402_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6403_AwakerVoiceContent = {
    Text = "(humm nhẹ)"
  },
  Voice_6403_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6404_AwakerVoiceContent = {
    Text = "(humm nhẹ)"
  },
  Voice_6404_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Ngứa quá! Giống như khi thị nữ dùng lông chim gãi lòng bàn chân vậy, bạn *âm thanh bị xóa* chắc không phải cố ý đâu nhỉ."
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6405_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Chúc bạn có một giấc mơ đẹp."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Chúc bạn có một giấc mơ đẹp."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Trao tặng sự bình yên…!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Hãy hành động thật thanh nhã nhé."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Có thể nghe thấy không? Đây là giọng của tôi."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Có thể nghe thấy không? Đây là giọng của tôi."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Đã mưa. Nước mưa sẽ rửa trôi tất cả, đồ ăn bị hỏng, vết bẩn cứng đầu, và những kẻ như tôi... thừa thãi.."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "Dòng sóng trả thù cuồn cuộn không bao giờ ngừng nghỉ."
  },
  Voice_6413_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6414_AwakerVoiceContent = {
    Text = "Máu, tắm rửa toàn thân!"
  },
  Voice_6414_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6415_AwakerVoiceContent = {Text = "Á!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Xem bên này!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Tôi chẳng sợ gì cả."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6418_AwakerVoiceContent = {
    Text = "Cẩn thận!"
  },
  Voice_6418_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Thế giới chưa từng trải qua khổ sở, chưa từng ngấm đẫm nỗi buồn, chưa từng bị bệnh tật hành hạ, chưa từng bị đen tối xâm chiếm——có lẽ đó là ảo ảnh vĩnh viễn không thể thấy, nhưng là lý tưởng mà tôi truy cầu suốt đời."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Hãy ngả mũ trước vẻ đẹp rực rỡ của vương quốc Vĩnh Hằng!"
  },
  Voice_6420_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6421_AwakerVoiceContent = {
    Text = "Hãy ngả mũ trước vẻ đẹp rực rỡ của vương quốc Vĩnh Hằng!"
  },
  Voice_6421_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6422_AwakerVoiceContent = {
    Text = "Lại đến dâng lễ vật rồi à? Đúng là biết nghe lời đấy."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6422_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Đau lắm không?"
  },
  Voice_6423_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Chú tâm vào"
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Nghìn năm thời gian khiến tôi hơi lơ là."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "Ngày đó, biển lửa hận thù lan rộng, như những đóa hồng máu bùng nở… Tất cả những vần thơ đều hóa thành tro bụi tan vỡ giữa những lưỡi lửa đỏ thẫm…"
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6426_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Học được kỹ thuật mới rồi nè!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Cẩn thận nhé."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "Cây đũa phép muốn nhảy múa rồi!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ừm, cảm giác trống rỗng quen thuộc này!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Các khớp hoạt động trở nên mượt mà hơn."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Gam màu đen u ám kia, trông có vẻ giống với thanh kiếm và khiên vô định hình của tôi… A! Xin chủ nhân yên tâm! Kiếm bảo hộ của tôi tuyệt đối không gây hại cho ngài!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "Đến đây nào."
  },
  Voice_6433_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Đủ qua cửa rồi."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Tôi sẽ cố gắng hết sức."
  },
  Voice_6435_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6436_AwakerVoiceContent = {
    Text = "Hôm nay có chơi ở đây không?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "Hầm chứa đầy nước, mềm mại và lạnh lẽo. Vì vậy, thân thể tôi luôn bị bao quanh bởi làn hơi ẩm... như thể giữa trời đất bao la, chỉ mình tôi mang hình hài thực tại. Đôi lúc, tôi khao khát được hòa tan vào dòng nước. \nNhưng nếu thế, sự tồn tại của tôi sẽ biến mất mãi mãi, và cũng chẳng bao giờ gặp được bạn."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6437_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = "Hãy để tôi nói với bạn một bí mật... thực ra tôi ghét máu. Ghét màu sắc của nó, ghét mùi vị của nó. Nhưng tôi không thể sống thiếu nó. \n... Tôi nuốt máu vào, rồi lại nôn ra hết... Tôi khinh thường chính mình."
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6438_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "À! Máu của ngài… có vị như rượu mật ong. Tôi nghĩ tôi có lẽ là người duy nhất biết bí mật này, phải không?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6439_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "Trong tưởng tượng của tôi, một hiệp sĩ dũng cảm sẽ kéo tôi ra khỏi bóng tối, sau đó dùng xích khóa tôi lại. Anh ta có thể đánh tôi, mắng tôi, và làm bất kỳ điều gì anh ta muốn —— nỗi đau chính là bằng chứng cho sự tồn tại của tôi. \nNgài có nguyện ý trở thành hiệp sĩ của tôi không?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6440_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Máu chảy như dòng sông. Tôi thuộc về ngài — cảm giác này chưa bao giờ mạnh mẽ đến vậy —."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6441_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Đây chính là ý chí của ba nữ thần Trả Thù!"
  },
  Voice_6442_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6443_AwakerVoiceContent = {
    Text = "Lưỡi kiếm rời vỏ."
  },
  Voice_6443_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6444_AwakerVoiceContent = {
    Text = "Không được nhé!"
  },
  Voice_6444_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "Bẩn quá bẩn quá!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "……Ai Jī Sī, thấy rồi!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "……Ai Jī Sī, thấy rồi!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Tiền boa, tất nhiên là tiền boa. Nhìn những người phục vụ ngốc nghếch trong căng-tin trường đi! Thậm chí còn không chuẩn bị sẵn ghế ngồi thoải mái, vậy mà còn muốn được trả thêm tiền, mơ đi!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Đen."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Hãy để tôi ra ngoài!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Kỹ năng·Nhất·cuồng loạn"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Đừng như vậy..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Kỹ năng·một·u uất"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Không cần phải quá khách sáo, sứ giả tái nhợt. Giữa chúng ta không nên có khoảng cách, vì tất cả đều là sáng tạo của thần và cùng bước đi trên con đường đầy bùn lầy và thử thách."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6452_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Tôi tất nhiên không sợ họ, những linh hồn đáng thương bị dày vò bởi lời nguyền tan rã, tôi chỉ cảm thấy đau lòng cho họ. Tôi biết mình không thể gánh vác nỗi đau thay họ, nhưng tôi có thể trao cho họ tất cả những gì tôi có thể, miễn là điều đó mang lại cho họ dù chỉ một chút an lành."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6453_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Bạn có muốn cầu nguyện cùng tôi không, lửa nhợt nhạt? Cầu nguyện cho những người đã chết trong trận chiến của chúng ta hôm nay. Dù họ đã điên cuồng vì bị lời nguyền tiêu tan, nhưng họ vẫn là sáng tạo của vị thần nhân từ, là anh chị em của bạn và tôi. Mong rằng họ sẽ được hưởng sự bình yên xứng đáng."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6454_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Dù ngọn lửa đỏ khiến tôi căng thẳng, tôi vẫn sẽ bước lên sàn gỗ đang cháy vì bạn. Đừng bận tâm làm gì, ngọn lửa trắng của tôi ơi. Trước những điều tốt đẹp mà bạn mang lại, sự hy sinh nhỏ bé của tôi chẳng đáng là bao."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6455_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Hối hận? Không, đương nhiên không. Cái chết của tôi đã giúp họ giảm bớt đau khổ và đổi lấy thêm nhiều thời gian, như thế đã đủ rồi. Nhưng… anh đã rất thẳng thắn với tôi, nên tôi cũng sẽ không giấu anh: hình phạt hỏa thiêu ngày hôm đó vẫn để lại vết sẹo trong lòng tôi."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6456_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Có thể hứa với tôi được không? Ừ... chúng ta hứa rằng, dù xảy ra chuyện gì, bạn sẽ luôn nhớ \"Ramona\" nhé?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6457_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Tôi không hối hận về việc chọn trở thành như thế này, nếu có cơ hội nữa, tôi vẫn sẽ làm như vậy. Nhưng, Người Giữ Gìn, tôi rất sợ... sợ rằng \"Ramona\" sẽ không để lại bất kỳ dấu vết nào trên thế giới."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6458_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Không cần lo lắng, miếng che mắt không ảnh hưởng đến khả năng nhìn của tôi. Thậm chí, nhờ vậy tôi mới có thể không bị phân tâm bởi mọi thứ xung quanh."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6459_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Dường như biểu cảm của tôi trông rất xa lạ? Tôi đã chú ý kiểm soát... Xem ra, sự hiện diện của cô ấy ngày càng mạnh mẽ."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6460_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Các bí ẩn cần giải quyết, những người cần cứu giúp thực sự quá nhiều. Tôi không biết mình còn có thể tiếp tục hành động trong bao lâu, cũng không có cách nào bảo vệ tất cả mọi người… Thật là nan giải."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6461_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Còn muốn tiếp tục đặt cược thêm trên người tôi không? Xem ra, muốn sống theo ý mình cũng chẳng dễ dàng gì. Yên tâm đi, tôi vẫn sẽ lười một chút khi giúp bạn giải quyết vấn đề."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6462_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "Đã đến nước này, không thể không cho thấy thực lực rồi chứ? Hiện trường vụ án ở đâu? Dù phải đánh đổi tất cả may mắn của mình, tôi cũng nhất định sẽ đưa nghi phạm về trước hạn chót!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6463_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Ôi ya, nhận được nhiều lợi ích từ bạn như vậy, tôi không thể không tiết lộ một số bí mật: thực ra, tôi có thể là người xui xẻo nhất trên thế giới này."
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6464_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Bạn có vẻ không để tâm đến những gì tôi nói… Thôi kệ, Thôi kệ, tôi vẫn sẽ giúp bạn xé nát kẻ địch. Dù sao, cái móng vuốt và răng nanh này cũng là do tình cờ mà có được, phải không?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6465_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "May mắn của tôi chưa chắc đã có thể truyền cho bạn đồng hành. Bạn chắc hẳn đã nghe câu đó rồi phải không? \"Chân thỏ may mắn đối với thỏ thì chẳng có tác dụng gì.\""
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6466_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Hy vọng trong linh hồn của bạn, sẽ in dấu vết của Dư?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Vậy ngươi khát khao lực lượng của ta sao?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Đừng nhìn tôi như thế này, tôi cũng từng là một cô gái đoan trang… Tôi biết thêu, biết đọc thơ Tennyson… À, tôi còn biết hát: Cô ấy giống như dòng sông không ngừng chảy, trong huyết quản của tôi chảy mãi~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pickman và tôi đang hợp tác với một số tác phẩm nghệ thuật thú vị, khám phá cách tái cấu trúc chủ nghĩa biểu hiện trừu tượng thông qua việc giải cấu trúc chủ nghĩa nguyên thủy thị giác... Ể, Ô Ryta sao lại ngất đi?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Ô Ryta"
  },
  Voice_6470_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Ô Ryta\", tính năng sẽ được mở khóa"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "Bạn có muốn tôi cười không? \n Lily, bạn có đang cười không?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về nụ cười"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Thật mới lạ, tôi lại có được một tình bạn bình đẳng. \nTuy nhiên… tôi muốn giữ quyền sử dụng bạn, như một điểm thú vị nhỏ giữa chúng ta. Tối nay hãy đến phòng ngủ của tôi, về những cảm xúc giữa con người, tôi vẫn còn rất nhiều điều cần học…"
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6472_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Bạn có biết nơi đáng yêu nhất của bạn là gì không? Đó là khi bạn nói \"không\" với tôi. Mũi bạn sẽ nhăn lại, lông mày hơi nhướn lên... Đúng rồi, như bây giờ này."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6473_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Tôi yêu những người hầu của mình. Những cậu bé đáng yêu này, bị rỗng rỗng dọa sợ đến run rẩy, trốn sau lưng tôi với dáng vẻ nhỏ bé thật đáng thương. Nước mắt của người đẹp luôn khiến lòng người say đắm. Còn bạn, bạn có sợ rỗng rỗng không?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6474_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Người giữ bí mật, có ai đó mà anh ghét không? Để đáp lại, tôi có thể thay mặt anh dạy dỗ họ. Không quá một tuần, tôi sẽ khiến họ thay đổi suy nghĩ, ngoan ngoãn phục tùng anh."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6475_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = "Ừ… ngươi tuy chậm hiểu, nhưng không đến mức khiến người khác ghét bỏ. Từ ngày mai ngươi sẽ hầu hạ ta. \nNgươi không muốn…? Đây không phải là hỏi ý kiến, mà là mệnh lệnh."
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6476_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Đã lâu không có tâm trạng như vậy, tôi sẽ bước lên sân khấu với tư thế hoàn hảo nhất, dâng tặng quý vị luồng âm thanh mạnh mẽ xuyên suốt vũ trụ."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6477_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Bạn cần biết rằng, điều này không có ý nghĩa"
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6478_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Sau khi hái hoa chiến thắng, tôi muốn xin một chút quà nhỏ…"
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6480_AwakerVoiceContent = {Text = "À"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Bị đánh·phiền muộn·ba"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "Chiếc tàu bay chật hẹp, giống như một quan tài kim loại trôi nổi trong vũ trụ. Tôi đang chờ đợi sao Khởi Minh của mình, cho đến khi ngài xuất hiện."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6481_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Sao vậy!?"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Bị đánh·cuồng nộ·một"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh…"},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Đánh trúng·buồn bã·một"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Đau……"},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Bị đánh·u uất·2"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Trời phạt!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Trời phạt!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6487_AwakerVoiceContent = {Text = "Chán."},
  Voice_6487_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6488_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6488_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Còn có thể cố gắng."
  },
  Voice_6489_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6490_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6490_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6491_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6491_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Hỡi kẻ bất kính, hãy tan biến trong sự tĩnh lặng cháy bỏng."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Cẩn thận một chút, nếu đưa tay vào không gian chiều khác, thì sẽ không lấy lại được đâu!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Một đám đồ vô tích sự, nếu không muốn bị làm thành hộp thịt băm thì lần sau phải cẩn thận hơn."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Ôi trời ơi, đang làm nũng với tôi sao? \nThật khó xử như thế này, tôi không thể chờ đến khi Người Giữ Gìn hoàn toàn trưởng thành được…"
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Hãy dấn thân vào ý chí tự do!"
  },
  Voice_6496_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6497_AwakerVoiceContent = {
    Text = "Thứ thật sự khiến người ta khó chịu… Quả nhiên, vẫn là người mà cứ bỏ dở việc giữa chừng. Chỉ cần nghĩ đến loại người đó, bữa tối hôm qua muốn nôn hết ra."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Đầu lâu vô tận! Hãy để ta chiêm ngưỡng dung mạo của ngươi!"
  },
  Voice_6498_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6499_AwakerVoiceContent = {
    Text = "Đầu lâu vô tận! Hãy để ta chiêm ngưỡng dung mạo của ngươi!"
  },
  Voice_6499_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6500_AwakerVoiceContent = {Text = "Uống!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Uống!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Bạn thực sự tin tưởng tôi đến vậy sao?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6502_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "Quay lại đi."
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Được!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Tất nhiên tôi biết, đó là một khía cạnh khác của tôi. Nhưng tại sao cô ấy lại phản kháng? Chấp nhận số phận trở thành người được chọn, điều mong muốn chẳng phải trong tầm tay sao?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về \"Muphí\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Xin chào, tôi tên là Đào Đen Đá. Tôi đã từng có một giao dịch với vị khách nào đó, người đó yêu cầu tôi đến hỗ trợ bạn. Vậy, hãy để tôi nghe xem bạn cần gì nhé. \nÔi… vật phẩm mà bạn mong muốn có giá không hề rẻ đâu nhỉ?"
  },
  Voice_6506_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6507_AwakerVoiceContent = {
    Text = "*tiếng im lặng* Làm gì vậy! Tin không, tôi sẽ chặt tay của bạn xuống!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Hồng gai vô ý rạch lòng, vần thơ tuôn chảy như dòng suối trong."
  },
  Voice_6510_AwakerVoiceTitle = {Text = "Nộ"},
  Voice_6511_AwakerVoiceContent = {
    Text = "Hồng gai vô ý rạch lòng, vần thơ tuôn chảy như dòng suối trong."
  },
  Voice_6511_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6512_AwakerVoiceContent = {
    Text = "Xem của tôi…!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6513_AwakerVoiceContent = {Text = "Ừm…!"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Thảm họa đến!"
  },
  Voice_6514_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6515_AwakerVoiceContent = {
    Text = "Cho tôi nhé."
  },
  Voice_6515_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6516_AwakerVoiceContent = {
    Text = "... tên, ứ, tôi không thể nhớ nổi. \nĐúng rồi, \"24\", họ đều gọi tôi như vậy... Không! Không được ra! Bạn không thể, bây giờ không thể..."
  },
  Voice_6516_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6517_AwakerVoiceContent = {
    Text = "Lối mực lưu dấu……"
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Xuất hiện……"
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Tôi không xứng đáng với danh hiệu giọng hát thiên thần như vậy…… Chỉ cần bạn thích giọng hát của tôi là đủ."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về ca hát"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Quần áo bẩn phải thay trước khi đến salon tiếp theo."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Nó đang bám sát tôi, bóng tối vĩnh cửu, không ai có thể trốn thoát…"
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Mỗi lần nhìn thấy bạn, tôi lại nghĩ đến những xiềng xích vô hình mà bạn đã áp đặt lên tôi. Để bạn sống đã là sự nhượng bộ lớn nhất của tôi."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Dù phải bắt đầu lại bao nhiêu lần, tôi luôn bên bạn mà tiến tới."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Nguyện tình yêu nhân từ của Chúa sưởi ấm linh hồn bạn."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Tôi thích dạo chơi. Dạo chơi mà không có mục đích cụ thể. Vùng đầm lầy, nghĩa trang, phòng bệnh, lâu đài bỏ hoang...... Ở những nơi này, tôi luôn tìm thấy những bất ngờ thú vị."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Hãy cảm thấy vinh dự, cánh cửa của Quốc gia Vĩnh hằng ngay tại đây."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Gáy gáy—— thật ngứa thật ngứa! Ô Ryta cũng sẽ gãi lại!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "\"Cái chết của thiên nga\", vũ công diễn giải niềm khát vọng và sự giằng xé của sự sống thông qua ngôn ngữ cơ thể. Thân hình vặn vẹo trong ngọn lửa ấy cũng vậy thôi."
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Cắt ra, cắt ra, xé nát. Giống như những người trước đây đã làm với tôi… he he… he he he!!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Bạn vẫn nên tránh gần cô Thái Di Sơ…… không, tôi không ghen, tôi chỉ sợ có người sẽ bị phụ nữ dụ dỗ."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Lời nói phiếm - Về Thái Di Sơ"
  },
  Voice_6530_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Thái Di Sơ\""
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "……cảm ơn nhiều."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6531_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Rất tốt... bạn có một đôi mắt tinh tường để nhận biết con người."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6532_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "Quê hương của Gia Lân rất đẹp! Đó là một thành phố đá nằm trên hồ. \n Mỗi khi trăng tròn hơn, chúng tôi nhảy múa im lặng trong ngọn lửa để tế lễ…... \n Thú thực, khi Gia Lân mới đến đại học, mỗi tối đều rất nhớ nhà, còn khóc thầm trong chăn nữa. Nhưng bây giờ, Gia Lân đã có một ngôi nhà mới, những người thân mới, mọi thứ đều tốt đẹp hơn!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6533_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Ya~ vẫn chưa thỏa mãn sao? Đến đây, để tôi nhanh chóng huấn luyện bạn một chút~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Cơ bắp yếu ớt, khuôn mặt tiều tụy, chỉ có đôi mắt như của người chết còn có chút giá trị—— moi ra cho nhện ăn vừa đủ."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Cảm ơn, cảm ơn ngài đã làm tất cả cho Ai Jī Sī. Ai Jī Sī sẽ cố gắng không phụ lòng ngài!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(tiếng kêu sợ hãi)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6538_AwakerVoiceContent = {Text = "Đừng!"},
  Voice_6538_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6539_AwakerVoiceContent = {
    Text = "Thả tôi ra.."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(tiếng kêu sợ hãi)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "Kiếm thuật của cô Ramona rất khác biệt so với những kỹ năng tôi nắm được. Nếu chủ nhân cho phép, thật sự muốn được giao lưu với cô ấy… Đương nhiên, đương nhiên rồi! Chỉ là để nâng cao bản thân!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6541_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Anh hỏi em, tại sao không chơi với những đứa trẻ khác? Thật khó để nói ra… Khi còn sống, em hầu như không có cơ hội vui chơi, người bạn duy nhất của em là công chúa mà em từng phục vụ… Trời ạ! Em lại nhắc tới chủ cũ trước mặt ngài, xin hãy lượng thứ cho sự lỡ lời này…"
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6542_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Bạn là người được Đại học Misag công nhận là Người Giữ Gìn, vì vậy, tôi sẽ cấp cho bạn quyền truy cập vào các chức năng tương ứng."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về \"Nhân Vật Chính\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Chủ quân có hứng thú với \"Bảy kỹ năng của Hiệp sĩ\" mà tôi đã học không? Thật tuyệt vời! À… ừm… Vừa rồi thất lễ rồi, ý tôi là, nếu ngài muốn luyện tập cưỡi ngựa bắn cung, tôi rất vinh hạnh được làm người cùng luyện tập với ngài!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6544_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Tôi không phải là một hiệp sĩ đủ tư cách. Dù là trước dịch bệnh tà ác hay kẻ thù xâm lược, tôi đều không thể bảo vệ được chủ nhân xưa kia. Nay ngài nguyện trao cho tôi niềm tin như thế này, đó quả là vinh hạnh to lớn đối với tôi… Với vinh quang của một hiệp sĩ và mạng sống nhỏ bé này, tôi thề sẽ mãi bảo vệ con đường phía trước của ngài."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6545_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Đừng gây thương."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6547_AwakerVoiceContent = {
    Text = "Đừng nhé~"
  },
  Voice_6547_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Đập!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Đừng giết người."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "Thoải mái~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Bây giờ, chúng ta giống như nước và dầu không hòa tan."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Tôi không có gì đặc biệt thích. Nếu buộc phải nói, cảm giác khi ra ngoài thực hiện nhiệm vụ khá thú vị."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Tại sao, tại sao lại giam tôi ở đây? Hừ hừ…… Tôi sẽ không để cho kế hoạch của cậu thành công! Hãy để tôi xé nát tất cả ràng buộc và nhà tù này thành phân mảnh!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Bảo vệ mọi người."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Các cậu, lần nào cũng đến xem biểu diễn ảo thuật, chẳng thấy chán sao? Phải ngồi ngoan đấy nhé! Nếu còn chạy lên sân khấu, tôi sẽ ném các cậu vào không gian khác ngay!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về những đứa trẻ"
  },
  Voice_6555_UnlockDesc = {
    Text = "Sau khi nhận được một trong các thân thể được đánh thức \"Ai Jī Sī\"\"Jenkin\"\"Lily\"\"Muphí\"\"Gia Lân\"\"Ô Ryta\", tính năng sẽ được mở khóa"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Quà tặng của bạn, tôi xin nhận với lòng kính trọng."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Làm sao để món quà xứng đáng với sự đóng góp của quý vị?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Bao nhiêu diễm lệ…"
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Phát hiện dòng điện mạnh, sắp tiến hành bảo trì cơ thể…… sửa lại, tại sao không quá nhiệt?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6559_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Từ sau buổi lễ khởi linh lần trước, khi tôi ở trong trạng thái ngủ say, tôi thường nhìn thấy những hình ảnh tan vỡ. Trong đó, tôi có một thân thể bằng thịt và máu như bạn, và cũng sẽ rơi lệ. Điều này, có phải là một giấc mơ không?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6560_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Sau mỗi nghi lễ, vị trí ngực đều ghi nhận nhiệt độ cao, nhưng ở đó không có bất kỳ bộ phận liên quan đến năng lượng. Bạn biết tại sao không?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6561_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Tôi đã thấy, mọi thứ <Del:nên chết trong dòng điện vĩnh cửu> xin lỗi, xin lỗi, mô-đun dường như — cảnh báo, cảnh báo, hoạt động ý thức không phải của Erika tăng cường, hãy tiêu hủy tiêu hủy tiêu... Chào bạn, có gì cần tôi giúp đỡ không?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6562_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Sau khi phân tích kỹ lưỡng, tôi kết luận rằng những gì tôi thấy trong trạng thái ngủ say không phải là những giấc mơ theo nghĩa truyền thống, mà là ký ức của tôi<Del:thân thể thịt máu đáng thương này lẽ ra nên bị hủy diệt>. Còn cái nóng rát như bị quá tải có lẽ là cảm xúc được gọi là \"không cam lòng\"."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6563_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Muốn xem biểu diễn, hãy ngồi yên nào trên khán đài!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6564_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Lửa hận thù bùng cháy mãnh liệt, không bao giờ tắt."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "Ý chí mà tôi hòa nhập là một kẻ ồn ào, càng nâng cao, \"Ngài\" càng rõ ràng... giống như tiếng ồn ào của chợ búa, khá phiền phức."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6567_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Tôi sẽ dùng lực lượng này để nuốt chửng kẻ bội phản."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "……cảm ơn nhiều."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Người giữ bí mật? Thật là buồn cười, đã đến lúc tỉnh dậy từ giấc mơ không thực tế này."
  },
  Voice_6570_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6571_AwakerVoiceContent = {
    Text = "Máu trả thù, đang sôi sục.."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Động lên đi, đồ nô lệ!"
  },
  Voice_6572_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6573_AwakerVoiceContent = {
    Text = "Đừng để bị chết đuối!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Xìu xìu!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Tôi đã vứt cái bẫy chuột ở cửa sau nhà ăn, quá nguy hiểm, nếu brun con vụng về đó dẫm phải thì sao!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Cảm giác thật kỳ lạ... Tôi có phải sắp chết không? Không, cứu tôi! Đừng mà!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6576_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Tôi muốn một chiếc đèn không bao giờ tắt, cô ấy lại bảo dùng \"mẫu vật của loài sứa biết bay mà không có cánh\" để đổi chỗ. Tôi đi đâu tìm loài sinh vật kỳ quái như vậy!"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Đào Đen Đá"
  },
  Voice_6579_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Đào Đen Đá\", tính năng sẽ được mở khóa"
  },
  Voice_6582_AwakerVoiceContent = {
    Text = "Nguy hiểm."
  },
  Voice_6582_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6583_AwakerVoiceContent = {
    Text = "Cảnh báo."
  },
  Voice_6583_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6584_AwakerVoiceContent = {
    Text = "Bị đánh."
  },
  Voice_6584_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6585_AwakerVoiceContent = {
    Text = "Báu vật lấp lánh như giấy kẹo… Ai Jī Sī sẽ cất giữ kỹ lưỡng."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Chịu sát thương."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Cửa hàng nhỏ của tôi có thể tồn tại ở bất kỳ chiều nào, bất kỳ vị trí nào trong vũ trụ, đương nhiên cũng có thể tồn tại ở đây. Huống chi, tôi rất thích những đứa trẻ hơi thiếu cẩn thận của Misaque?"
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Ghét thật… ớt xanh ăn không ngon chút nào."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Mối quan hệ giữa tôi và bạn giống như mối quan hệ giữa buồm và thuyền. Không có thuyền, buồm không thể tồn tại; không có buồm, thuyền khó có thể đi xa. Đúng không nhỉ?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "Những người thành tâm với điệu múa đã chết, những kẻ sỉ nhục nghệ thuật cũng chết, chết trong ngọn lửa ngập tràn mùi nhựa đường. Cái chết không phải là kết thúc, mà là khởi đầu, vì chỉ có con người mới chết, còn điệu múa và nghệ thuật thì vĩnh cửu."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6590_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Cảm ơn sự hiểu biết của bạn, có lẽ đây là thời khắc để hòa giải với bản thân quá khứ… Tôi tin rằng những gì tôi làm là đúng đắn, chưa từng làm xấu mặt gia đình vũ đạo. Tôi sẽ bước lên sân khấu mà bạn đã chuẩn bị, và như mong muốn của bạn, tỏa sáng thật rực rỡ."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6591_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Cẩn thận nhé."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Bạn muốn tôi bước lên sân khấu, tỏa sáng trên đó? \nĐiều này đã không còn thực hiện được nữa, đôi mắt này đã bị sự thù hận nuốt chửng, ngoài việc đốt cháy mọi thứ, tôi không thể làm gì khác."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6593_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Bạn có hiểu cảm giác đó không? Quay, quay, quay, không bao giờ ngừng lại. Đầu gối căng thẳng đến mức mỏi mệt, máu đen từ đầu ngón chân thấm ướt giày ballet, nhưng vẫn không dừng lại một chút nào. Chỉ vì tôi không muốn chấp nhận số phận trở thành một đồ chơi…"
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6594_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Tôi thiêu chết không phải là những vũ công cung đình tài hoa, không phải là những người chủ trì tao nhã của ballet, không phải là những quý tộc biết thưởng thức cái cao quý và đẹp đẽ, mà là những kẻ vô năng bán thân thể, những kẻ xu nịnh bất chấp người khác, những kẻ dâm dục bẩn thỉu… Bạn sẽ hiểu tôi, phải không?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6595_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Tôi không thích những người có xúc tu dính nhớt, cũng không thích đáy biển… Đừng có lộ ra biểu cảm như thể đã hiểu rõ rồi nhé! Tôi đâu phải là đứa trẻ sợ phụ huynh!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6596_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Quý vị thật hào phóng, tôi không biết nói gì ngoài cảm kích…"
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Biến mất đi!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Biến mất đi!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Nhanh lên, đưa Brun đi!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "Đừng ..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "Phòng thủ·phiền muộn"
  },
  Voice_6602_AwakerVoiceContent = {Text = "Đi đi!"},
  Voice_6602_AwakerVoiceTitle = {
    Text = "Phòng thủ·cuồng nộ"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Reia là ai? À, người phụ nữ cầu xin tôi đánh cô ấy. Haha, khá thú vị... Nơi này cũng không đến nỗi quá buồn chán."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Reia"
  },
  Voice_6603_UnlockDesc = {
    Text = "Mở khóa sau khi có thân thể được đánh thức \"Reia\""
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Đồi thoai thoải nơi mặt trời lặn thường khiến tôi nhớ đến những ngày ở Cleveland… Cleveland, tôi vẫn còn nhớ được cái tên này, nơi đã để lại cho tôi những vết sẹo này…"
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về hoàng hôn"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "À……tinh tú……từ đây sa ngã……"
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Chắc chắn là con người. Có sinh vật nào bẩn thỉu hơn con người chăng?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "Đúng bây giờ!"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6608_AwakerVoiceContent = {Text = "Ê!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Rỗng rỗng? Ừ… đúng rồi! Kem sẽ tan chảy! Nhưng chỉ cần mọi người cùng chia sẻ, thì có thể ăn nó trước khi nó hoàn toàn biến thành kem lỏng!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Tôi sẽ dùng lực lượng này để bảo vệ bạn."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6610_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Ôi, cửa hàng này bán hàng không đổi trả nhé? Muốn lặn xuống biển sâu, đúng là cần có tàu lặn phải không?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Kẻ khắc sét"
  },
  Voice_6611_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Kẻ khắc sét\""
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Sân khấu tuyệt vời nhất! Cả giáo viên và sinh viên tại Đại học Misag đều có thể hiểu rằng tôi đang biểu diễn phép thuật thực sự! Đây chính là tri kỷ của một nhà ảo thuật, phải không?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "Trật tự của vũ trụ đang thay đổi tại đây; tương lai bị hủy diệt chính là niềm tin của nhà ảo thuật!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6613_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Có thể để Ai Jī Sī ở đây thêm một lúc không? Tôi sẽ im lặng, không phát ra bất kỳ tiếng động nào, cố gắng không gây phiền phức cho bạn…"
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6614_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Bằng trí tuệ của nhân loại…… giải mã bản chất của thế giới!"
  },
  Voice_6615_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6616_AwakerVoiceContent = {
    Text = "Trong giấc mơ của tôi, thường xuyên xuất hiện tiếng sóng biển, tiếng đó càng lúc càng xa, càng lúc càng xa. Tôi biết, có lẽ tôi sẽ mãi mãi ở lại đây, con người."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về biển sâu"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Nhiều ký ức hơn, nhiều cảm xúc hơn, nhiều giấc mơ hơn ——"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6617_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Bắt đầu thay đổi!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Đừng nháy mắt nhé!!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Đợi Người được sinh ra... tôi sẽ không còn phải chịu đựng nỗi nhục này nữa.."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Chọn tôi, chọn tôi! Nơi nào có tiệc tùng thì nơi đó có Gia Lân!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Ừ? Có hứng thú với tôi sao? Tưởng rằng… bạn đã chuẩn bị sẵn sàng để trả giá rồi?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Không tha thứ, không tha thứ…!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Vẫn ca ngợi, màu sắc đến từ các vì sao ."
  },
  Voice_6624_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6625_AwakerVoiceContent = {
    Text = "Hãy hát lên, hãy hát lên!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Thích mẹ!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6627_AwakerVoiceContent = {
    Text = "Đến đây nào."
  },
  Voice_6627_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Cẩn thận nhé."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Các thân thể được đánh thức có thể ăn vì tò mò, nhưng thức ăn không phải là vật cần thiết để duy trì sự tồn tại của chúng ta. Vì vậy, không cần phải gọi tôi mỗi lần thưởng trà chiều, việc hấp thụ đường sẽ chỉ làm tăng tốc quá trình lão hóa của các khớp cầu của thân thể này."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về buổi trà chiều"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Xin các người nhất định phải tha cho chủ nhân, Gia Lân… Gia Lân tùy các người xử trí!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Những thứ này, Lily đều có thể ăn được phải không?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6633_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Ghét? Có thể nói không, Ai Jī Sī ghét nhất là bản thân thường xuyên cảm thấy bất lực… nhưng nếu tôi nói vậy, Jenkin sẽ cực kỳ giận dữ…"
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Hãy hóa thành tro tàn."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Hãy hóa thành tro tàn."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Làm tốt lắm, Người Giữ Gìn. Nói đi, lần này muốn tôi giết ai?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6637_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Rỗng rỗng là lý do thành lập của học viện này, cũng như nguyên nhân chúng ta gặp nhau. Để cứu lấy ngọn lửa của nhân loại khỏi rỗng rỗng, cố gắng lên nhé, bạn đồng hành!"
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Tôi có thể cảm nhận được sự thù địch từ cô ấy, chắc hẳn tình yêu của tôi dành cho ngài đã khơi dậy lòng ghen tị… Ngài nhìn xem, đến chiếc miệng của chú cá voi cánh lớn kia cũng đang há rộng vì đố kỵ rồi."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chuyện trò · Về lơ-tan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Lơ-tan\""
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Chủ nhân, chủ nhân! Gia Lân hôm nay thấy một chiếc broche cameo đẹp—— tuyệt vời ở Harrold's Department Store! Chủ nhân có thể mua nó cho Gia Lân không, đây là mong ước cả đời của tôi!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Tôi sẽ là hướng dẫn của bạn trong đêm tối, nhưng khoảng thời gian này không phải là vĩnh viễn."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mẹ ơi, đau quá... mẹ à…"
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Hãy chịu thua đi! Chiến thắng đã nằm trong tầm tay tôi!"
  },
  Voice_6643_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6644_AwakerVoiceContent = {
    Text = "Hãy chịu thua đi! Chiến thắng đã nằm trong tầm tay tôi!"
  },
  Voice_6644_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6645_AwakerVoiceContent = {
    Text = "Rỗng rỗng à... Não tôi có giới hạn, không thể hiểu nổi mấy bệnh phức tạp như thế này... Có máy móc hỏng thì cứ tìm tôi nhé!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Ya! Ô Ryta đã được tìm thấy! Là hình phạt cho việc thua cuộc, bạn có thể đưa ra một yêu cầu với Ô Ryta — nhưng đừng bắt Ô Ryta đi học, làm ơn đừng mà —"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Dọn dẹp chướng ngại cho sự tái lâm của Ngài…"
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Một ngày nào đó, chú Oern sẽ đón tôi trở lại quê hương dưới đáy biển. Trước khi đó, tạm thời có thể kết bạn với bạn."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6648_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Trong gia tộc chúng tôi có dòng máu vĩ đại, người được chọn sẽ tận hưởng sự an lạc vĩnh cửu dưới biển sâu.\" \n Thật không ngờ, sau khi rời xa đại dương để đến học viện, tôi mới cảm nhận được loại an lạc này. Bạn khác hẳn với những kẻ từng bắt nạt tôi, vì vậy, tôi cũng sẽ không để bất kỳ ai khác bắt nạt bạn."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6649_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Chất liệu đặc biệt siêu cứng!"
  },
  Voice_6650_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6651_AwakerVoiceContent = {
    Text = "Bị mắc kẹt trong cái vỏ lai tạp với thành phần con người thật khiến tôi ghê tởm. Vất vả lắm mới thoát khỏi quá khứ, giờ thì hay rồi, lại phải nhớ đến chuyện đó…"
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6651_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Tôi biết, người thừa kế của dòng máu vĩ đại lại một lần nữa trở thành đầy tớ của con người. Tuy nhiên, bạn cũng đừng mong tùy tiện sai khiến tôi."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6652_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hừ, ngươi là một kẻ yếu đuối nhưng lại có chút tài năng trong việc chỉ huy. Chỉ tiếc rằng thân thể kém cỏi này khiến ta không thể phát huy hết khả năng."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6653_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Thân thể ngày càng ấm lên."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Trốn… phải trốn! phải trốn khỏi đây!"
  },
  Voice_6655_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6656_AwakerVoiceContent = {
    Text = "Trốn… phải trốn! phải trốn khỏi đây!"
  },
  Voice_6656_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6657_AwakerVoiceContent = {
    Text = "Cảm ơn sự nỗ lực của bạn, vậy để tôi tặng bạn phần thưởng xứng đáng."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Không sao."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(tiếng rên khẽ vì đau đớn)"
  },
  Voice_6659_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6660_AwakerVoiceContent = {
    Text = "Con người, dù ngươi yếu ớt, nhưng niềm tin của ngươi đã lay động ta. Ta nguyện trở thành vũ khí của ngươi, cùng nhau quậy tưng bừng đi!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6660_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Đây là phòng họp của tôi."
  },
  Voice_6662_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6664_AwakerVoiceContent = {
    Text = "Trường học bình đẳng cho mọi người... Ta không biết các ngươi đang ấp ủ những ảo tưởng ngây thơ nào. Dù ngươi không phạm phải bất kỳ sai lầm nào, họ vẫn sẽ giẫm đạp lên ngươi. Ta hiểu cảm giác đó."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Đây là nguồn gốc của mọi sự ô uế.."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Cơn thịnh nộ bùng phát·trầm cảm"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Tôi đã chịu hình phạt vì không thể bảo vệ các thuyền viên. Họ nói rằng, do sự thiếu trách nhiệm của tôi, những thuyền viên mất tích sẽ không bao giờ có thể đoàn tụ với gia đình… rỗng rỗng, có phải là như vậy không?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Đã đến gần chủ nhân hơn một chút.."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Tại sao? Tại sao bạn... không chịu tỉnh lại?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Tôi là Ôrla từ Tây Đài, bút danh… Tôi đã hứa với ai đó không tiết lộ bút danh, rất xin lỗi vì điều này, nhưng mọi người có thể gọi tôi là Ôrla."
  },
  Voice_6669_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6670_AwakerVoiceContent = {
    Text = "Tôi phản đối mọi hành vi phi chính nghĩa, nghiêm trọng nhất là bội phản. Trong quân đội, nếu không thể, không dám giao lưng cho đồng đội, toàn bộ đơn vị sẽ trở thành một đống cát rời rạc."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Tại sao bạn lại trông tối om mà lại rất sáng như vậy? …Không, không sao, hãy coi như tôi đang nói nhảm nhé."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_6672_AwakerVoiceContent = {
    Text = "(kêu đau)"
  },
  Voice_6672_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6673_AwakerVoiceContent = {
    Text = "(kiên trì rên khẽ)"
  },
  Voice_6673_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6674_AwakerVoiceContent = {
    Text = "Gì vậy?!"
  },
  Voice_6674_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Tôi thích sức sống, thích ánh sáng. Muốn cho Phiệt bước ra khỏi vỏ bọc u tối, dùng trái tim và đôi mắt để cảm nhận và nhìn thế giới này."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Không thấy tôi!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Công việc bảo trì cần tiếp tục không ?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Linh kiện đã được chuẩn bị xong."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Con người có thể có lòng bội phản, nhưng công cụ thì không. Chỉ cần sử dụng đúng cách, dung hợp cũng có thể trở thành công cụ của sự trả thù."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Sự chờ đợi nghìn năm, cuối cùng đã đến lúc... Tôi mới là người duy nhất thống trị Phi-li-tin!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_6680_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "Vừa rồi đi qua, có phải là giống lai biển sâu không? Ừ... Hãy nhìn cái lưng thẳng này, đêm nay ta sẽ thấy hắn quỳ gối bò sụp xuống."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Kẻ khắc sét"
  },
  Voice_6681_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Kẻ khắc sét\""
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Lực lượng dần trở lại trong tay… bước tiếp theo, chiếm lấy quyền lực thuộc về tôi!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6682_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Cũng không tệ, đã tiến thêm một bước đến việc lột bỏ lớp mặt nạ giả dối của người phụ nữ kia."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_6683_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Bình tĩnh, bình tĩnh nào……"
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Không cần kiêng kỵ. Mức chịu đau của tôi có thể xa vượt quá sự tưởng tượng của các bạn."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6685_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Theo tôi, những thứ đẹp đẽ nhưng ngốc nghếch mới là tuyệt nhất. Tiếc rằng, nơi này lại đầy rẫy những bộ óc thông thái nhưng chẳng hề hữu ích."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Sử dụng phản ứng tổng hợp hạt nhân của sao đỏ khổng lồ làm động lực, kết hợp với năng lượng khi ngôi sao sụp đổ, có thể khởi động máy vĩnh cửu, thắp sáng một ngọn đèn vĩnh cửu… Ể? Bạn nói rằng, không có điều kiện để chế tạo máy vĩnh cửu, cũng không có sao đỏ khổng lồ? Ừm…"
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Máu của kẻ địch chưa chảy hết."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Giao tất cả chúng… cho tôi!"
  },
  Voice_6689_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6690_AwakerVoiceContent = {
    Text = "Giao tất cả chúng… cho tôi!"
  },
  Voice_6690_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6691_AwakerVoiceContent = {
    Text = "Đến lúc ra chiến trường rồi."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Đã đến lúc rồi!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Khi ta đang ngủ, giấc mơ tràn ngập sẽ khiến linh hồn sôi trào. Vì vậy, đừng lại gần khi ta đang say giấc, càng không được tùy tiện thức tỉnh ta."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Lời rỗi · về trạng thái ngủ sâu"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Đã đến lúc rồi!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Dù Herbert là một người rất đáng sợ, nhưng con mèo của anh ta lại rất hiền lành…… không, chính xác hơn, đó phải là hai con mèo đúng không?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Hoàn thành Chương 2 của \"Điều tra Hành động\"để mở khóa"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Người phụ nữ tên Muphí kia ăn mặc cũng quá lòe loẹt… Không được, Gia Lân không thể thua cô ta!\nHoặc là, cứ giết chết cô ta đi…"
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Muphí"
  },
  Voice_6696_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_6697_AwakerVoiceContent = {Text = "Á~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "Có thoải mái không?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Khi hợp tác với Đại học Misag, rõ ràng đã nói là không để tôi tham gia chiến đấu……"
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6699_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Đừng quá tự mãn. Đôi khi, từ cao quý đến hèn mọn chỉ cách nhau một bước."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6700_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Pháp Luân Tư chào bạn. Việc gọi tôi đến đây chắc hẳn là đã chuẩn bị sẵn sàng cho việc khởi hành."
  },
  Voice_6701_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_6702_AwakerVoiceContent = {
    Text = "Ya hū—— rất mệt rất mệt, có thể đi chơi được rồi không!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "À à… ánh sáng của anh ta quá chói lọi, không thể làm ngơ, là sự mù quáng điên cuồng đã che mờ giác quan tôi… không, tôi không thể tìm bất kỳ lý do nào cho sự ngu dốt của mình…"
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Chuyện vặt · về tulô"
  },
  Voice_6703_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thức tỉnh thể \"tulô\""
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Những ngôi sao chìm trong giấc mơ, đi đến nơi định mệnh chỉ lối, hướng về thần quốc!"
  },
  Voice_6705_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6706_AwakerVoiceContent = {
    Text = "Bạn không thấy rằng, thúc đẩy vạn vật đi đến kết thúc, khiến quy tắc của thế giới ngừng chuyển động, là một việc rất thú vị sao?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6707_AwakerVoiceContent = {
    Text = "Uống đi!"
  },
  Voice_6707_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "Sung sướng!"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Hãy nhập lệnh chiến đấu."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Trong những ngày tôi trôi dạt giữa các vì sao, tôi đã mơ về ngày này vô số lần… Cảm ơn bạn, đã giúp tôi và tinkerer đoàn tụ."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chuyện trò·về tinkerer"
  },
  Voice_6710_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"tinkerer\""
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "Đại học Misaque là một nơi tốt, đặc biệt là sòng bạc ngầm được tổ chức hàng tuần…\nÀ, hóa ra ông không biết à? Ui chao, nói lộ miệng rồi sao…"
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Kháng cự sự xâm thực khủng hoảng\", ha, sự tự mãn của loài người, thật là cười chết được."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·Về Đại học Misag"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Dù sao đi nữa, con người cũng chỉ là một loài động vật nông cạn mà thôi. Chỉ cần vài lời nói, một chút gợi ý, có thể khơi dậy sự tranh đấu lẫn nhau… Ôi, mức độ này không thể khiến người ta phấn chấn tinh thần được."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Lời rỗi·về loài người"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Perhaps, viewing you as an ordinary human was due to my shortsightedness and preconceived notions. I am curious, how does someone like you, who lacks faith, manage to defend your stronghold? This is not a question from the Sea Mother, but Miriam's doubt. Can you... answer this question for me?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6714_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "Với sự đặc biệt của bạn, liệu bạn có cảm thấy chán với thế gian này không? Tôi thực tâm tin rằng, thần quốc vĩnh cửu mới là nơi thuộc về bạn. Bạn sẽ bước đi trên đất của thần linh. Bạn sẽ du ngoạn trong hồ thánh linh. Bạn sẽ bám rễ trên mảnh đất màu mỡ rộng lớn... Hãy tham gia vào thánh hành của tôi, cùng tôi vượt lên trên trần thế. Khi đó, chúng ta sẽ cùng đứng bên cạnh ngai vàng, chia sẻ niềm vui tái tạo thần quốc.."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_6715_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Chúng ta đều là kẻ vô năng bò lê trong trần thế, nhưng vị Thánh nhân kia lại phi phàm. Ông ấy là Đại hành giả, là hiện thân của thần linh nơi nhân gian. Lời giáo huấn của ông như tiếng nói tỉnh thức từ thần linh, dẫn dắt nền văn minh tiến tới bất tử… Tôi không kỳ vọng bạn có thể hiểu ngay lập tức niềm tin vào ông ấy, nhưng rồi sẽ đến ngày bạn phải quy phục dưới ngai vàng của ông."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6716_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Người được triệu tập là hạnh phúc, anh không nghĩ vậy sao? Họ được ban sức mạnh thần thánh và sở hữu tuổi thọ dài hơn. Khi vương quốc của thần đến, ý muốn của Ngài được thực hiện trên mặt đất, họ sẽ trở thành những tín đồ vinh quang. Đối với con người yếu đuối, đây chẳng phải là niềm may mắn và hạnh phúc to lớn hay sao?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6717_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "Sự vui mừng khi được tắm trong ánh sáng thần thánh, những người không có đức tin như ngươi sẽ không bao giờ hiểu được... Nguyện thần linh của ta tha thứ cho ngươi, tha thứ cho sự thiếu hiểu biết và hành vi thiếu tôn trọng của ngươi."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6718_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Hãy kết thúc nhanh chóng, Người Giữ Gìn."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6720_AwakerVoiceContent = {
    Text = "Ê hey——"
  },
  Voice_6720_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_6720_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Chết đi, đồ sâu bọ Spartan dơ bẩn."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Cô đóa nói rằng tôi có thể tạm thời trốn tránh sự rỗng rỗng bằng cách từ bỏ cơ thể… Không thể nào, không thể nào, không thể nào, khi tiến hành phẫu thuật sẽ mất ý thức, bóng tối sẽ xâm nhập vào tâm trí tôi…"
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chuyện trò · về đóa"
  },
  Voice_6722_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"đóa\""
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hừ… sao? Chẳng lẽ muốn tìm kiếm số phận bị hủy diệt rồi sao?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Chủ nhân còn bị mất ngủ không? Gia Lân đã chuẩn bị thuốc an thần Dobby cho bạn nha~! Mặc dù liều lượng có hơi vượt quá, nhưng giấc ngủ tốt mới là quan trọng nhất!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_6724_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Lúc đó chúng tôi đang uống chút rượu vui vẻ, hát hò, bỗng nhiên bị biến thành quái vật! Nhưng không sao cả, làn da xanh tươi cũng rất thú vị!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_6725_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Giấc mơ của Gia Lân? Ừm… mua được một chiếc vòng cổ ngọc trai đẹp, rồi đeo nó đi dự vũ hội, trở thành ngôi sao rực rỡ nhất!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_6726_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Bản chất của khát vọng - Tifrayesod, cô ấy cũng đã tìm ra con đường sống sót của mình. Trước những điều chưa biết, không ai có thể đánh giá sự cao thượng hay thấp kém của phương pháp."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Chất Thể Dục Vọng"
  },
  Voice_67276_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Thái Di Sơ\""
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Đi xuyên qua cánh cửa khóa bạc, đến ngai vàng của Ngài."
  },
  Voice_67277_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_67278_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Đừng phụ lòng học thức và ký ức của Ngài."
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Bên trái lau lau, bên phải lau lau, bụi bẩn và phiền não biến mất ——"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_6727_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Tôi không ở đây."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Một mảnh vỡ từ dòng chảy không-thời gian vô tận đã xuất hiện trong linh thức của tôi."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Tôi đã biết được toàn bộ."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Mọi thứ đều nằm trong hư không."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Bạn đã đi rất sâu và xa rồi. Chẳng bao lâu nữa, bạn sẽ chạm vào điều kỳ diệu phi thường đó, hy vọng bạn vẫn giữ được bình tĩnh và lý trí như bây giờ."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_67284_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"vô tri\". Không, việc tìm tòi không mệt mỏi về bản chất không phải là vô tri. Người thực sự vô tri sống trong mờ ám, thậm chí không nhận biết được rằng mình không biết điều gì."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Tôi sẽ cho bạn xem giấc mơ của tôi. Mọi điều kỳ quái và hỗn độn bạn thấy trong giấc mơ đều gần với bản chất của thế giới hơn so với thực tế mà bạn biết."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_67286_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Đây là lời khuyên cho bạn: đừng vội vàng. Khi bạn cảm thấy mệt mỏi, hãy ngừng suy nghĩ ngay lập tức, giữ gìn sức lực và năng lượng. Nếu không, bạn sẽ mãi mãi lạc trong giấc mơ."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_67287_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "Vũ trụ tuần hoàn không ngừng."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "Sự cộng hưởng giữa chúng ta không cần mất nhiều thời gian để điều chỉnh, tuy nhiên, để bảo vệ trí tuệ của bạn khỏi sự xâm hại của ảo ảnh, tôi sẽ làm từng bước một."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_67289_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Rỗng rỗng… Tôi cũng tình cờ nhận một vụ án liên quan đến nó, nhưng nói chung, tôi nghĩ việc biến mất cũng là điều tự nhiên mà. Cuối cùng thì, mỗi người đều sẽ biến mất mà."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Cánh cửa đầu tiên. Vũ trụ vô hạn sinh ra từ một điểm."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_67290_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "Cánh cửa thứ hai. Điểm kéo dài thành lối, dẫn đến hai cực vô tận."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_67291_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Cửa thứ tư. Nguyên mẫu vĩnh cửu đóng băng trong một không gian của chiều."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_67292_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Cửa thứ ba. Mặt phẳng mang tính chất cục bộ và giới hạn về phạm vi."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_67293_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Cánh cửa Tột cùng. Liên kết muôn vàn vũ trụ với hư vô cuối cùng, xuyên qua cánh cửa Tột cùng, bí ẩn tối thượng của thế giới sẽ mở ra trước bạn."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_67294_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "Cửa thứ năm. Sự thay đổi của thời gian chỉ là ảo giác của bạn, thế gian này chưa bao giờ có điểm bắt đầu, tự nhiên cũng không có điểm kết thúc."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_67295_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Tôi chỉ nên là người khai sáng của bạn, dẫn dắt bạn bước trên hành trình này rồi chìm vào giấc ngủ trong hồ nước ảo tưởng. Nay bạn là liên kết của tôi, mối liên kết giữa chúng ta đã trở nên phức tạp, khó có thể cắt đứt……"
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Bạn muốn xác nhận điều gì? Đáng tiếc, thân thể này bị giới hạn và ràng buộc rất nhiều, nếu chúng ta gặp nhau ở hố sâu, tôi có thể dẫn bạn khám phá nhiều hơn…"
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Cô ấy cũng là phân mảnh của tôi, đến từ một chiều khác, một thế giới đã bị hủy diệt vĩnh viễn. Thật đáng tiếc, dù cô ấy đã nắm được phương thức quay ngược thời gian, nhưng lại không thể hiểu thấu chân lý vượt qua không gian và thời gian, chỉ có thể liên tục chìm đắm trong đau khổ. Đây là sai lầm của tôi."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về hành trình vòng quanh Ramona"
  },
  Voice_67298_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Vòng tròn · Ramona\""
  },
  Voice_67299_AwakerVoiceContent = {
    Text = "Tôi biết"
  },
  Voice_67299_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_6729_AwakerVoiceContent = {
    Text = "Có phải ngươi rất quan tâm đến hình dạng thân thể này? Đừng lo lắng quá, khi ta sinh ra, ta có một khuôn mặt của loài người."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_67300_AwakerVoiceContent = {
    Text = "Tôi thấy."
  },
  Voice_67300_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "Thật là nhỏ bé."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Giữ bình tĩnh."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Liên kết trực tiếp với chất thể sẽ gây tổn thương nghiêm trọng đến trí tuệ của bạn…… Tuy nhiên, vì bạn quyết tâm như vậy, tôi nhất định sẽ đáp lại lời gọi của bạn."
  },
  Voice_67303_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_67304_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Đứa trẻ đó, vì phân mảnh ý thức của tôi, đã phải chịu đựng quá nhiều thứ mà cô ấy không nên phải gánh chịu. May mắn thay, linh hồn của cô ấy vẫn trong sáng như dòng bạc chảy…"
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Ramona\"để mở khóa"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Thăm giấc mơ của Ngài, khám phá bí ẩn của những bí mật vũ trụ tối cao và cấm kỵ."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Ừm."},
  Voice_67307_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_67308_AwakerVoiceContent = {
    Text = "Cánh cửa tận cùng đã mở ra cho bạn. Hãy đón nhận thế giới chết lặng sau cánh cửa đó."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_67308_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Mục đích của tôi khi thành lập trường này là để \"lưu trữ\". Các bạn đã làm được nhiều hơn tôi dự kiến."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Rỗng rỗng là món quà của thần. Nó mang lại vừa đủ nỗi đau để làm tê liệt tâm trí chúng ta, khiến chúng ta tập trung vào ẩm thực và rượu vang, rồi cùng nhau điên cuồng tiến tới sự diệt vong."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Rỗng Rỗng"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Quá khứ, hiện tại, tương lai, hàng tỷ tia sáng đều hội tụ tại đây!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Quá khứ, hiện tại, tương lai, hàng tỷ tia sáng đều hội tụ tại đây!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "Cánh cửa cực hạn đã được mở ra. Ở đây, vạn vật quy về một!"
  },
  Voice_67312_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_67313_AwakerVoiceContent = {
    Text = "Cánh cửa cực hạn đã được mở ra. Ở đây, vạn vật quy về một!"
  },
  Voice_67313_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_67314_AwakerVoiceContent = {
    Text = "Lắng nghe tiếng khôn ngoan."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Vô tận, vô cùng, vô hạn, vô bờ."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt·số ba"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Đó là ý chí của Ngài… Không, thay vì gọi là ý chí, thì đúng hơn là vô thức, ánh nhìn vô thức của Ngài khiến vạn vật hòa vào hơi thở của Ngài."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Chưa thể điều tra kỹ lưỡng……những dấu hiệu nhỏ nhặt……"
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Tôi sẽ thể hiện sự thật."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Câu trả lời\". Tôi canh gác cánh cửa này vì sự yêu thích, và cũng vì sự yêu thích mà trao chìa khóa của cửa vào tay bạn."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Phải……trở về……"
  },
  Voice_6731_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_6732_AwakerVoiceContent = {
    Text = "Vạn vật thiên địa, luân hồi nhân quả!"
  },
  Voice_6732_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6733_AwakerVoiceContent = {
    Text = "Vạn vật thiên địa, luân hồi nhân quả!"
  },
  Voice_6733_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6734_AwakerVoiceContent = {
    Text = "Lưỡi dao này vẫn chưa mòn."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "Rèn luyện cũng không được lơi lỏng."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Linh hoạt hơn."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Vật vô hình, sẽ nằm dưới sự điều khiển của bạn."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_6737_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Cảm nhận hơi thở nóng bỏng này ——"
  },
  Voice_6738_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6739_AwakerVoiceContent = {
    Text = "Chúng ta đều sẽ trở thành……một phần của ngọn lửa lục……"
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Lá chắn của tôi sẽ tỏa sáng vì ngài, chúa công."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_6740_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Lại, thêm một chút tiến bộ nữa, thật sự không biết nói lời cảm ơn thế nào cho đủ!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_6741_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Hừ"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(khinh thường nhưng cố nhịn)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(khinh thường nhưng cố nhịn)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(khinh thường nhưng cố nhịn)"
  },
  Voice_6746_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6747_AwakerVoiceContent = {
    Text = "Thời gian ở bên mọi người, luôn khiến người ta cảm thấy thư thái…"
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Chuỗi huyết của kẻ giết chóc, sứ giả của Tisiphone, lưỡi đao của sự thù hận… Họ đã trao cho tôi những danh hiệu này. Dù sao, tôi cũng chẳng ngại trở thành con người như thế."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Lời nói dạo · Về bản thân"
  },
  Voice_6749_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6749_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_6750_AwakerVoiceContent = {Text = "ALL-IN!"},
  Voice_6750_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_6751_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6751_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_6752_AwakerVoiceContent = {
    Text = "(kêu lên ngạc nhiên)"
  },
  Voice_6752_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Có thể đi chơi xa hơn được không? Đi đến biển nhé!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow——cảm ơn bạn nhé~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Người bạn~nhiều người bạn hơn~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Yu U Hahi… Anh ta rất đặc biệt. Cô nghĩ những ngày thịnh vượng của gia đình tôi đến từ đâu? Toàn bộ là nhờ anh ta giết người trong đấu trường như một chiến binh điên cuồng. Anh ta mới là nguồn thu nhập chính của gia đình tôi."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·về Yu U Hahi（Yu U Hahi）"
  },
  Voice_6757_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Yu U Hahi\""
  },
  Voice_6758_AwakerVoiceContent = {
    Text = "Ngu ngốc!"
  },
  Voice_6758_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Hừ."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Lên nào! Ra lệnh chiến đấu!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Trong hố sâu… sẽ có ánh sáng của công lý."
  },
  Voice_6761_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_6762_AwakerVoiceContent = {
    Text = "Ánh sáng của công lý giờ đây đã bừng sáng tại đây!"
  },
  Voice_6762_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6763_AwakerVoiceContent = {
    Text = "Cảm xúc của con người là thứ vừa yếu đuối vừa quý giá như hoa…"
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_67754_AwakerVoiceContent = {
    Text = "Đừng kháng cự, đừng khóc, đừng sống!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Đừng kháng cự, đừng khóc, đừng sống!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Cánh cửa ơi, hãy mở ra."
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Ồ."},
  Voice_79297_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_79298_AwakerVoiceContent = {Text = "Hả…?"},
  Voice_79298_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_80092_AwakerVoiceContent = {
    Text = "Liệu pháp tắm, liệu pháp sốc điện, liệu pháp giam giữ, những thứ này không phải là điều trị mà là ngược đãi, vì vậy trong thời gian khám bệnh, tôi sẽ dùng cách của mình để điều trị cho bệnh nhân trong bệnh viện tâm thần, cuối cùng họ đều đã chữa khỏi và tìm thấy tự do thực sự."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_80092_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Tội nghiệp White, vì viện dưỡng lão gần đó đã đầy, nên anh ta bị gia đình nhốt trong chuồng heo. Tôi đã miễn phí chữa trị cho anh ta, sau đó, anh ấy cuối cùng đã nhận ra mình là người chứ không phải gia súc, và đã tự tìm lại được phẩm giá của con người."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_80093_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Công nhân dệt, luật sư, bá tước... Tôi tuyệt đối không từ chối bệnh nhân vì chi phí, đối với tôi, họ chỉ đơn giản là những bệnh nhân cần được chữa trị mà thôi."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_80094_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Tôi thừa nhận mình đã đánh giá thấp bạn, sự tồn tại của bạn chính là nỗi đau. Lần này không cần phỏng vấn lại, tôi muốn ở bên bạn, trực tiếp chứng kiến sự đến của kết quả."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_80095_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Những bệnh nhân này đã mang đến cho tôi những ký ức đẹp. Tiếp theo, đến lượt bạn, Người giữ gìn, tôi đã chọn cho bạn một cái kết. Đó sẽ là một buổi tư vấn đáng giá nhất trong sự nghiệp của tôi mà tôi sẽ phải thưởng thức nhiều lần."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_80096_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Từ chối sự giúp đỡ của bác sĩ không mang lại lợi ích gì cho bạn. Có lẽ lần sau, chúng ta cần thử thôi miên sâu."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "Trong căn phòng tối tăm, chỉ có một mình, cộng thêm những lời thì thầm đau khổ lặp đi lặp lại trong tâm trí, đó chính là cách tốt nhất để tận hưởng thời gian."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Mặc dù nói như vậy có chút bất lịch sự, nhưng nói chuyện với đứa trẻ đó chỉ khiến tôi cảm thấy nhàm chán - bạn sẽ luôn chỉ thấy một biểu cảm, đó là nụ cười."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Ô Ryta"
  },
  Voice_81140_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Ô Ryta\", tính năng sẽ được mở khóa"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Xin lỗi vì tôi đã đến mà không được mời, tôi chỉ nhận thấy năng lượng tâm lý của bạn đang suy giảm, nên đến để quan tâm. Bây giờ, người giữ gìn, có muốn bắt đầu một hành trình tâm linh không?"
  },
  Voice_81141_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_81143_AwakerVoiceContent = {
    Text = "Phương pháp của bác sĩ tâm thần để chữa trị bệnh nhân là khoan hộp sọ bệnh nhân với phương pháp khoan vòng—Hãy thư giãn, điều đó đã xảy ra từ lâu lắm rồi, bây giờ chúng ta có nhiều cách để đo lường và khám phá tâm trí của bệnh nhân."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_81143_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Để hiểu nhau, chỉ có thể mở lòng——sờ vào đây, trái tim bạc của tôi sẽ mở ra cho bạn."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Nếu bạn muốn nghe tôi có ý kiến gì, thì bạn có thể sẽ thất vọng. So với việc thổ lộ, tôi giỏi hơn ở việc lắng nghe."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "À, tôi đã nghe thấy tiếng của Ngài, những lời thì thầm, mỗi âm tiết đều tràn đầy đau đớn cực độ!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Tôi sẽ ghi nhớ nỗi đau của khoảnh khắc này trong lòng, hồi tưởng và thưởng thức……"
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Với tư cách là một mảnh vỡ của sự tồn tại đó, bạn mang hơi thở của Ngài, hơi thở tràn đầy đau khổ, điều này khiến bất kỳ ký ức nào của bạn đều vô cùng ngon miệng."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Nhớ lại những nỗi sợ hãi, mô tả chi tiết cảm giác đau đớn của bản thân, nguyên lý của liệu pháp chấn động cảm xúc chính là đối mặt với nỗi đau, vượt qua nỗi đau. Đến đây, lau khô nước mắt, chậm rãi kể cho tôi nghe những ký ức đó..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_81149_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Chúc mừng bạn, bạn đã hồi phục——đúng, ảo giác, ảo ảnh là hiện tượng bình thường, chúng chính là bằng chứng cho sự hồi phục của bạn."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_81150_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Đầu bạn chắc chắn đầy những hình ảnh kỳ quái, không sao cả, điều này hoàn toàn bình thường. Hãy vẽ chúng ra, tiềm thức và bản năng của bạn sẽ tiết lộ mọi thứ cho bạn."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_81151_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Tiếp theo là liệu pháp đạo đức của Philippe Pinel. Bạn cần nói ra những khát vọng và nỗi sợ hãi sâu thẳm nhất, đó là quy trình cần thiết để tháo bỏ gông cùm tâm hồn, phục hồi nhân tính đã ngủ quên."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_81152_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Người giữ gìn, có thể giúp tôi hoàn thành một bài kiểm tra nhỏ không? Chỉ là bài kiểm tra mực Rorschach mà thôi, thông qua nó, tôi sẽ thấy sâu thẳm bên trong bạn những điều chưa ai biết, trở thành người đánh thức duy nhất tiết lộ bí ẩn trong lòng người giữ gìn."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Hàn huyên·Về phân tích tâm lý"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Đầu tiên, hãy cùng lắng nghe một bản nhạc. Nghe thấy chưa, âm nhạc nhẹ nhàng du dương. Giờ hãy để cơ thể và tâm hồn của mình hòa quyện với âm nhạc, bước vào sự thư giãn của tinh thần……"
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_81154_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Nhìn cái quả lắc, đôi mắt theo dõi nó xoay chuyển..."
  },
  Voice_81155_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_81156_AwakerVoiceContent = {
    Text = "Suỵt—Im lặng, rồi tiến về hướng kết cục mà tôi dẫn dắt."
  },
  Voice_81156_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_81157_AwakerVoiceContent = {
    Text = "Tâm hồn tê liệt sẽ không đánh thức bất kỳ sự quan tâm nào từ tôi. Linh hồn của họ đã chết, cho dù có khiêu khích thế nào đi nữa, cũng sẽ không có một gợn sóng nhỏ nào."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Tôi đang nghe, xin tiếp tục."
  },
  Voice_81159_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_81160_AwakerVoiceContent = {
    Text = "Xin hãy giữ im lặng."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Hãy tin tưởng tôi nhiều hơn một chút."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Hãy để mọi nỗi đau bộc lộ ra nhiều hơn nữa!"
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Không cần giấu diếm, không cần ngại ngùng, tôi là người nghe bạn tin tưởng nhất. Hãy đến đây, chia sẻ với tôi nỗi đau sâu nặng nhất của bạn..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Giờ đây Aigis trông có vẻ vui vẻ hơn nhiều. Tất nhiên, nếu vị khách nhỏ của tôi có cần, tôi rất vui lòng hỗ trợ. Ý tôi là, hỗ trợ thực sự."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Ai Jī Sī"
  },
  Voice_81165_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Ai Jī Sī\", sẽ mở khóa"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Hãy bộc lộ mặt thật nhất của bạn với tôi."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Tôi sẽ từ từ thưởng thức nỗi đau ngọt ngào này."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Không cần giấu diếm, không cần ngại ngùng, tôi là người nghe bạn tin tưởng nhất. Hãy đến đây, chia sẻ với tôi nỗi đau sâu nặng nhất của bạn..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Bệnh tâm thần không phải là đặc quyền của thời đại này, nó vượt ra ngoài thời gian và không gian, sự phân rã cũng vậy. Cả hai đều vượt ra ngoài giới hạn nhận thức của con người, đúng không?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Suỵt—Im lặng, rồi tiến về hướng kết cục mà tôi dẫn dắt."
  },
  Voice_81171_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_81172_AwakerVoiceContent = {
    Text = "Nơi này tràn ngập dấu vết của lịch sử, và ở một mức độ nào đó, lịch sử đại diện cho ký ức - những ký ức đau đớn của những người đã qua đời."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Hít thở sâu……"
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Đau khổ, tuyệt vọng, cái chết... những ký ức này, khi nếm trải, giống như món tráng miệng sau bữa ăn."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Không cần quá căng thẳng, chỉ là một buổi tư vấn tâm lý bình thường thôi."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Lắng nghe sự chỉ dẫn của tôi."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Nghi thức xảy ra sự cố không xác định. Xin lỗi vì đã dùng cờ gõ vào tay bạn, tôi phải giữ cho bạn tỉnh táo."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_84185_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Ở đây có thể nhìn thấy các mô hình tàu khác nhau, tiếp xúc với thiết bị định vị tiên tiến hơn, tôi rất thích. Điều quan trọng nhất là, tôi tin rằng con \"tàu\" này đang đi đúng con đường lịch sử của con người."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Nghi thức đã diễn ra thành công, cảm ơn sự hợp tác của bạn. Lần sau tôi sẽ tạo ra một số tín hiệu cờ riêng biệt, giúp chúng ta hoàn thành nghi thức an toàn và suôn sẻ hơn."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_84187_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Tôi không rõ tại sao nó tồn tại, chỉ rõ một điều: Tôi phải thành công trong việc điều hướng, đưa an toàn tất cả thủy thủ và hành khách trở về từ biển."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Hãy yên tâm, tôi sẽ sử dụng sức mạnh này để hướng dẫn an toàn cho tàu, tuyệt đối không lạm dụng."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Hãy ngừng kháng cự."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Tôi chỉ có sự tôn trọng dành cho bạn và sẽ quyết tâm hoàn thành mọi mệnh lệnh bạn giao cho."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Xin lỗi, tôi không hiểu người, chỉ biết về tàu, hãy tha lỗi cho tôi vì đã dùng phép so sánh này: Đường sống của bạn không phải gỗ hay sắt, mà là thép, mạnh mẽ và kiên định, thật đáng ngưỡng mộ."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_84192_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "Hãy đầu hàng đi."
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "So với việc thích, tôi nghiêng về từ \"Trở về\". Khi nhìn thẳng vào vị thần không thể hình dung đó, bộ não tôi mất lý trí và rơi vào hoan hỉ, đúng, tôi nên sợ hãi Ngài, nhưng tôi không thể kiểm soát bản thân."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Tôi sẽ không bị bão cuốn trôi."
  },
  Voice_84195_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_84196_AwakerVoiceContent = {
    Text = "Nếu không có trật tự, thế giới này còn lại gì? Chỉ có hỗn loạn và rối rắm mà thôi."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Chuyến đi tiếp theo, tôi muốn lên thuyền với tư cách khác ngoài người dẫn đường. Cái đó... có nghĩa là, tôi sẵn sàng và chấp nhận hành động dưới sự chỉ dẫn của bạn. Bạn hoàn toàn xứng đáng với lòng tin tuyệt đối của tôi."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_84197_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Tôi chỉ đang thực hiện trách nhiệm của mình với tư cách là hoa tiêu, không cần phải thông báo khen thưởng."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Hệ thống hải đăng có thể giảm nhẹ đáng kể áp lực của người lái tàu, và ánh sáng của nó đặc biệt rực rỡ, tôi rất vui được ra khơi cùng Faros."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Pháp Luân Tư"
  },
  Voice_84199_UnlockDesc = {
    Text = "Mở khóa sau khi nhận người đánh thức \"Pharos\""
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Các thủy thủ, hãy theo sự chỉ dẫn của tôi, chúng ta chắc chắn sẽ an toàn đến cảng."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Liên kết linh hồn thành công, tôi đã cảm nhận được ý thức của bạn... Đây là lần đầu tiên tôi dẫn đường trong hư không, nếu có vấn đề lệch hướng, xin bạn hãy chỉ dẫn kịp thời."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_84201_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Đã quan sát thấy mây xoắn và thủy ngân trong áp kế giảm liên tục, mọi người chú ý, tàu sắp gặp cơn bão."
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Sự hỗn loạn này toàn bộ là do tôi sai lầm trong lập kế hoạch lộ trình, tôi sẵn lòng chấp nhận hình phạt theo quy tắc."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Đo độ cao góc thiên thể."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Cảm giác chóng mặt này giống như say sóng. Vui lòng nhắm mắt, nắm tay tôi dựa vào bên cạnh tôi, như vậy sẽ cảm thấy tốt hơn một chút."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_84205_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Kéo buồm trước và hạ xuống sóng bên trái, thuyền trưởng điều chỉnh lại lộ trình theo tính toán của tôi."
  },
  Voice_84206_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_84207_AwakerVoiceContent = {
    Text = "Những kinh nghiệm này là vô cùng quý giá, tôi sẽ ghi lại chi tiết chúng vào nhật ký hàng hải, để lại cho thủy thủ sau này."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Nghi thức làm sâu thêm liên kết tồn tại rủi ro và kết quả không xác định, nhưng xin bạn yên tâm, tôi sẽ dẫn đường cho bạn, để nghi thức hoàn thành suôn sẻ."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_84208_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Điều chỉnh lại trọng tâm."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Hãy chú ý bảo vệ tàu."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Có người là tàu hơi nước, phản ứng chậm nhưng có thể vận hành nhanh chóng, có người là tàu diesel, khởi động nhanh nhưng công suất hạn chế. Còn bạn thì sao, Người giữ gìn?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_84211_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Tôi tin chắc rằng việc chăm chút ắt sẽ được đền đáp, sau này tôi sẽ cố gắng hơn nữa."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Trong nhiều nhiệm vụ khác nhau, bạn đã chứng minh bản thân. Tôi nghĩ bạn là một người dẫn đường xuất sắc như tôi, không, có lẽ bạn còn xuất sắc hơn tôi rất nhiều."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_84213_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Chỉ cần bạn cần, Cỏ Sanga luôn sẵn sàng."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_84215_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Các thủy thủ, hãy theo sự chỉ dẫn của tôi, chúng ta chắc chắn sẽ an toàn đến cảng."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Người dẫn dắt Kè Phan Điện đến báo cáo! Cờ hiệu đã được chuẩn bị hoàn chỉnh, trạng thái cá nhân tốt, xin Người giữ gìn ra lệnh khởi hành."
  },
  Voice_84218_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_84219_AwakerVoiceContent = {
    Text = "Tôi nhất định sẽ dẫn tàu, hướng đến con đường đúng đắn."
  },
  Voice_84219_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_84220_AwakerVoiceContent = {
    Text = "Có phải mũ che bị nghiêng? Xin lỗi, tôi không hiểu ý định của bạn khi làm như vậy, hãy cho tôi chỉ dẫn rõ ràng."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Cờ hiệu là ngôn ngữ của người dẫn đường, cũng là bia mộ của người dẫn đường. Khi con tàu chìm, người trục vớt sẽ từ những mảnh vụn của cờ, giải mã thông điệp cuối cùng mà tôi để lại."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Hàn huyên·Về cờ hiệu"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Cảm nhận điểm cân bằng của thân tàu."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Kéo buồm trước và hạ xuống sóng bên trái, thuyền trưởng điều chỉnh lại lộ trình theo tính toán của tôi."
  },
  Voice_84223_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_84224_AwakerVoiceContent = {
    Text = "Cờ E truyền đạt lệnh."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "Trong thời khắc cần thiết, một hoa tiêu đã học cách cộng tác trong buồng máy cũng có thể đảm nhận vai trò thuyền trưởng, nhưng để đảm bảo tàu an toàn, tôi vẫn hy vọng có thể giao nhiệm vụ này cho người giỏi hơn."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Hilaster"
  },
  Voice_84225_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Hilaster\""
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Xuất hiện cảm giác mất trọng lực, tiếp theo là cảm giác lắc lư như tàu bị rung lắc mạnh. Cảm nhận trọng tâm cơ thể theo hành động của tôi, giữ thăng bằng."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_84226_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Bắt đầu hiệu chỉnh hải đồ."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt·số ba"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C lệnh phản hồi cờ."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt·số ba"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Đừng hòng vượt qua tôi."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Nên đối xử thế nào giữa những người bạn nhỉ? Pollux thích sai tôi làm nhiều việc, dù anh ta có thể tự làm được. Và tôi cũng sẵn lòng giúp anh ta làm những việc đó, đó là sự trao đổi giữa chúng tôi. Nếu bạn muốn, tôi cũng sẽ làm gì đó cho bạn."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_90334_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Với thân thể bất diệt này, chống lại mọi clades!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Ngay cả trước khi đọc cuốn sách đó, chúng ta không phải chưa từng tò mò về thế giới bên ngoài, tò mò về cảnh quan bên ngoài hòn đảo đơn côi trong hồ, bên ngoài bức tường đỏ sậm. Nhưng khi Pollux bị tra tấn, tôi cũng chưa từng nghĩ đến phản kháng, so với Pollux, tôi thật sự yếu đuối nhiều, vụng về nhiều."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_90336_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Tôi giống như một gã ngốc? Xin lỗi, xin thứ lỗi cho sự thiếu hiểu biết của tôi, ngoài kiến thức về thần mà đèn lồng truyền dạy, tôi biết rất ít về mọi thứ khác. Tôi sẽ học nhanh hơn, bạn thích gì, ghét gì, xin hãy cho tôi biết, tôi chắc chắn sẽ ghi nhớ kỹ."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_90337_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Hãy chứng kiến, ý chí theo đuổi tự do này."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Có thể chạm tới bất kỳ ước nguyện nào cửa hàng, đủ loại hàng hóa, thực sự làm người ta cảm thấy kính sợ... không, tôi không nghi ngờ sức mạnh của cô gái ấy, nhưng, \"muốn có một thứ gì đó, phải trả giá xứng đáng\", lý lẽ này, tôi và Pollux đã trải nghiệm quá nhiều lần."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · Về Đào Đen Đá"
  },
  Voice_90339_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Đào Đen Đá\", tính năng sẽ được mở khóa"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Đôi cánh bị nguyền rủa này, liệu có thể bay cao trên không trung không?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Các ngươi không thể phá hủy ta!"
  },
  Voice_90341_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_90342_AwakerVoiceContent = {
    Text = "Ngài có muốn chạm vào những chiếc lông vũ này không? Xin mời, tôi có cần dang rộng cánh thêm một chút không?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Khi được người khác giúp đỡ, tôi thường nghĩ, liệu những sự chăm sóc đặc biệt đó, những cuốn sách quý báu mà ngài tặng, những tinh thể thiên thạch tuyệt đẹp, có phải đều có cái giá nào khác không? Xin lỗi, tôi không nên suy đoán ngài như vậy."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_90343_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Chú chim sớm muộn cũng sẽ bay cao trên bầu trời."
  },
  Voice_90344_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_90345_AwakerVoiceContent = {
    Text = "Người là bậc thầy nấu ăn nhỉ... Kiến thức chế biến thực phẩm quả nhiên rất cần thiết, mặc dù tôi không đòi hỏi nhiều về ăn uống, nhưng Pollux thực sự rất kén chọn. Có lẽ nên tìm một lúc để học hỏi nghiêm túc... Không nên đi? Tại sao, nhưng món ăn của vị tiên sinh đó trông rất ngon mà?"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Chuyện vặt·Về Dulezain"
  },
  Voice_90345_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được người đánh thức \"Dule-Sain\""
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Nghĩ lại, những hầu gái lúc thắp đèn không có gì khác so với tôi và Pollux, tất cả chúng tôi đều sống với chuỗi dây xích, còn họ thì luôn Chịu đựng. Tuy nhiên, nữ hầu xanh đó có vẻ khác, cô ấy... rất năng động, như thể bẩm sinh yêu thích làm những việc này, có lẽ cô ấy đã có tự do quý giá nhất."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Lời nói phiếm · về Gia Lân"
  },
  Voice_90346_UnlockDesc = {
    Text = "Sau khi mở khóa, nhận được thân thể được đánh thức \"Gia Lân\""
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Các ngươi không thể phá hủy ta!"
  },
  Voice_90347_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_90348_AwakerVoiceContent = {
    Text = "Vẫn không thể... bay ra ngoài sao..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Phân tán theo gió đi!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · 2"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Chào ngài, lần đầu gặp mặt, tôi là Castor... còn cần nói thêm điều gì không? Xin lỗi, tôi hơi vụng về trong lời nói, nếu ngài cần tôi biết gì, hãy gọi tôi bất cứ lúc nào."
  },
  Voice_90351_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_90352_AwakerVoiceContent = {
    Text = "Chỉ thế thôi..."
  },
  Voice_90352_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_90353_AwakerVoiceContent = {
    Text = "Rơi xuống đi!"
  },
  Voice_90353_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Tôi có rất nhiều thứ chưa từng thấy, chưa từng làm, những hồ nước xanh ngắt, sương mù dày đặc kéo dài sẽ không bao giờ giam giữ chúng tôi nữa. Đại dương, đô thị lớn, nông trang, những nơi mà cuốn bản thảo nhắc đến, tôi đều muốn đi xem cùng với Polydeuces và ngài."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_90354_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Khi bạn nghe tiếng lá trên cây xào xạc, bạn sẽ biết rằng tôi đã ở bên bạn."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_90355_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Những chiếc lông vũ đen này, trở nên sâu thẳm hơn."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Thực ra điều tôi ngưỡng mộ nhất chính là sự không có nghi ngờ, tin tưởng lẫn nhau của ngài và đồng đội của ngài. Cảm giác bị lãng quên, bị phản bội... thực sự rất đau khổ."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Tên trộm thần bí đã nói với tôi rằng, cô ấy có thể dạy tôi kỹ năng sinh tồn đường phố mạnh nhất, chỉ cần trả cho cô ấy năm trăm Răng nanh Leô... Tôi bị lừa? Không, tôi nghĩ đó là kiến thức rất đáng học, đó chính là điều tôi và Polyx cần thiết... Là vấn đề tiền bạc? Tôi đã hiểu, vậy, tôi sẽ bàn bạc với cô ấy, trả bốn trăm năm mươi Răng nanh Leô thì sao?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Chuyện phiếm · Về Jenkin"
  },
  Voice_90358_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Jenkin\", tính năng sẽ được mở khóa"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Tôi vẫn có thể chịu đựng được..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Khi còn nhỏ, việc kiểm soát đèn lồng với chúng ta chưa nghiêm ngặt như vậy, có đôi khi Polydeuces không biết đã nói gì mà có thể kỳ diệu xin được một ít kẹo ngọt. Cảm giác thưởng thức những viên kẹo đó... cũng giống như bây giờ."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_90360_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Với thân thể bất diệt này, chống lại mọi clades!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Ngài có thể dạy tôi một chút, kiến thức về giao dịch với người khác không? Cách trao đổi hàng hóa, cách quản lý tiền tệ kiếm được, thực sự là một môn học sâu sắc. Đạt được tự do chỉ là khởi đầu, để sống độc lập, tôi và Polydeuces còn rất nhiều điều cần phải học, sau này sẽ phải làm phiền ngài nhiều hơn rồi."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Phân tán theo gió đi!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Gió, hãy thổi nó vào miệng tử thần!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux anh ấy... mặc dù bị người cầm đèn gieo vào nhiều ý nghĩ không tốt, nhưng bản chất anh ấy không xấu. Anh ấy chỉ cấp bách muốn nhận được sự chấp nhận của người cầm đèn, sự chấp nhận của giáo đoàn, vì vậy quá quan tâm đến nhu cầu của họ. Thay vì nói anh ấy quá tự mãn, hãy nói, anh ấy luôn sợ mất đi \"cái tôi\" đó."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Tán gẫu· Về Polyx"
  },
  Voice_90365_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Polyxena\""
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Xin lỗi, tôi không cố ý lơ đãng... Bạn hỏi tôi chiếc lông vũ này là gì? Đó là... thứ quan trọng nhất của anh ấy, cũng là thứ quan trọng nhất của tôi. Nó đẹp, phải không?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Lúc đó chúng tôi học thần học dưới sự hướng dẫn của Giáo hoàng hoặc người giữ đèn mỗi ngày, ước mơ lớn nhất của tôi khi đó là một ngày nào đó những kinh văn có thể được biên soạn lại, trở nên ngắn và ít. Như vậy tôi sẽ không bị chóng mặt vì học thuộc lòng và bị người giữ đèn nghiêm khắc chỉ trích."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_90367_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Cảm ơn ngài, ban cho tôi chiếc chìa khóa để nắm giữ tự do."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Đôi cánh này cuối cùng đã trưởng thành hoàn toàn, rất cứng cáp, rất mạnh mẽ. Bây giờ tôi có thể đưa bạn và Pollux cùng bay, khi bạn muốn bay lên bầu trời, hãy gọi to tôi nhé."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_90369_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Trốn đằng sau cánh đi!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Cuối cùng đã thấy được bầu trời sao kỳ vĩ được viết trong cuốn sách đó."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Lãnh tụ ngày xưa... Juliette cũng thường có những khoảnh khắc ân cần với chúng ta, cô ấy luôn không tiếc nở nụ cười ấm áp với mọi người, khiến người ta sợ phụ lòng kỳ vọng của cô ấy. Chỉ cần cô ấy cười và xoa đầu bạn, không câu từ chối nào có thể thốt ra. Ừ, giờ không còn nữa, bạn có thể xoa đầu tôi bất kỳ lúc nào."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_90372_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Tôi từng bị ngâm trong lớp nhầy đen đó rất lâu, lâu đến mức tôi đã quên cả thời gian, lâu đến... cả Polydeuces cũng quên tôi. Nó mang đến cho người ta không phải là nỗi đau thể xác, mà là nỗi sợ hãi linh hồn nhìn thấy bản thân tan biến."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Từ nhỏ, chúng tôi không được phép có quá nhiều giao tiếp với người khác, từ \"bạn bè\", cũng rất lâu sau mới biết đến. Tôi và Polydeuces, ngoài nhau ra không có gì cả, anh em, bạn bè, tù nhân trong cùng một nhà giam, đều là chúng tôi, chỉ có chúng tôi. Bây giờ, đã đến lúc kết bạn mới rồi."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_90374_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_90375_AwakerVoiceContent = {
    Text = "Lùi lại!"
  },
  Voice_90375_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Một ngôi trường mà ai cũng có thể tự do trao đổi, kết bạn tùy ý sao? Bạn nói rằng ở đây không học thần học mà còn có thể chọn các khóa học khác nhau... thậm chí có thể trốn học? Vâng, thật là một nơi tuyệt vời."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_90378_AwakerVoiceContent = {Text = "Tránh ra!"},
  Voice_90378_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Kẻ bất kính… sẽ phải nhận lấy sự trừng phạt…"
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Trái tim của ta đã được thắp sáng!"
  },
  Voice_95051_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_95052_AwakerVoiceContent = {
    Text = "Vật bẩn thỉu."
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Một tín đồ quá khích, có lẽ trong mắt thế gian chỉ là kẻ điên dại không thể hiểu nổi, mặc dù cô cũng từng lạc lối, nhưng quyết tâm hy sinh tất cả vì thần thánh như vậy, chính là sự kiên trì mà hầu hết những kẻ tầm thường không thể làm được, đối với cô ấy… tôi chỉ có chút buồn bã khi thấy người đồng loại."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Nhận được thân thể được đánh thức \"Miriam\"để mở khóa"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Tôi sẽ mang đến sự dẫn dắt và phán xét, ánh sáng trắng sẽ xua tan tội ác của các bạn!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Ha... Trôi qua bao lâu, anh ấy vẫn không thay đổi chút nào. Có lẽ tôi thời thơ ấu chưa bao giờ nghĩ rằng, có một ngày tôi sẽ tổn thương, nợ nần anh trai một cách nhiều đến mức khiến tôi xấu hổ, dù số phận bi thảm này không nằm trong sự kiểm soát của bất kỳ ai trong chúng tôi. Chúng tôi đã trải qua rất nhiều cuộc chia ly, nhưng, vì tôi đã quay trở lại, từ giờ trở đi, sẽ không có điều gì có thể chia cắt chúng tôi, ngay cả cái chết."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Lệch lạc: Về Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Cas-tơ-lơ\", tính năng sẽ được mở khóa"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Trước đây tôi ghét rất nhiều thứ. Những người hầu không tuân thủ quy tắc, những người hầu không biết tôn trọng, những kẻ dị giáo xúc phạm thần linh... nhưng bây giờ, chỉ có đèn lồng, chỉ có đèn lồng! Juliette và giáo phái của cô ấy mang đến nỗi đau không thể bù đắp cho tôi và anh trai tôi. Nhân danh con trai thánh, nỗi đau này, tôi sẽ không để nó xảy ra với người khác nữa!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Tôi sẽ thực hiện con đường ánh sáng, cho đến khi tận cùng cuộc đời mình."
  },
  Voice_95057_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_95058_AwakerVoiceContent = {
    Text = "Nguyện cho ánh sáng Minh Quang xuyên qua màn đêm bất tận!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Ngài luôn hào phóng và nhân từ như vậy, tôi sẽ cảm nhận thật tốt cái nhiệt độ ánh sáng này."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Sứ giả của người giữ đèn, sinh ra từ người ban ngày, xua tan bóng tối, Thánh tử Thánh tâm, tôi, Polyx, đã tới theo lời gọi của bạn, mang đến cho bạn sức mạnh bóng tối và linh hồn ánh sáng của tôi."
  },
  Voice_95060_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_95061_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Rửa sạch tội lỗi của bạn!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Trước đây mọi người đều nói với tôi, màu đen như vực thẳm này là tín ngưỡng của tôi, là phước lành mà tôi sẽ mang đến cho các tín đồ. Giờ đây, bóng tối này đã ăn mòn tôi, hòa làm một với tôi... nhưng trái tim đang đập trong cơ thể tội lỗi này là nơi không thể nào bị xâm chiếm. Hãy yên tâm, tôi nhất định sẽ dùng sức mạnh mà màu đen ban cho tôi, mang phúc lợi thực sự đến cho nhân loại!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Tôi sẽ truyền bá danh tiếng vĩ đại của bạn, mọi thứ không sạch sẽ sẽ sớm được ánh sáng thanh tẩy."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Tất cả những tội lỗi trong quá khứ đã gây ra, không nên tiếp tục tránh né. Tôi còn phải sửa chữa những sai lầm của cây đèn, dẫn dắt những người lạc lối về con đường chính. Hãy để tôi gánh chịu tội lỗi của mình. Sau đó, tôi sẽ đáp lại ánh sáng này, đáp lại lời triệu hồi của bạn, bước lên con đường thực sự, thuộc về thánh tử."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_95065_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Ôi, một linh hồn từ bi biết bao, bạn thực sự sẵn sàng tha thứ cho một người đầy tội lỗi, tôi cảm nhận được ánh sáng thuần khiết trong linh hồn bạn, sáng hơn cả ngọn đèn, có lẽ bạn có thể dẫn dắt trái tim lạc lối của tôi..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_95066_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Bóng tối đó, bóng tối lan tỏa từ lời nguyền của Juliette, luôn bao trùm trong tâm trí tôi... nhưng bây giờ, trong bóng tối đó lại xuất hiện một tia sáng! Tia sáng nhạt nhòa đó, có phải đang muốn báo cho tôi điều gì không?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_95067_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Nghe nói cô ấy từng là một thánh nữ, nhưng, thái độ thô lỗ thế này, hành động thô bạo như vậy... Cái gì? Cô ấy thậm chí không thể thuộc một câu kinh cầu nguyện? Hình dạng vô cùng thiếu thành kính như vậy thật khiến người khác phải xấu hổ vì thần linh của cô ấy."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Lệch lạc: Về Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Muphí\", sẽ mở khóa"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Người có thể dẫn dắt mọi người ra khỏi sương mù, mới thật sự là người cầm đèn được tạo hình bằng bạc nguyên chất. Vùng đất vô tội mà Juliette nhắc đến, lại được xây dựng từ những xác chết chồng chất của các tín đồ. Là con cái thánh thần, tôi sẽ gieo rắc phúc âm mới đến tất cả những ai xứng đáng được cứu rỗi."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Người dẫn dắt tôi, đem đến ánh sáng cho tôi, từng bị che mắt bởi những ý nghĩa giả dối, giờ đây dưới sự dẫn dắt của bạn, tôi đã tìm lại được sứ mệnh thực sự của mình - chỉnh sửa những tín đồ mù quáng và méo mó, mang đến ánh sáng vĩnh cửu cho thế gian. Tôi biết đến sự vị tha của bạn, bạn không cần lòng thành kính và sự cống hiến của tôi, vậy hãy cho phép tôi ở bên cạnh bạn, ghi lại mỗi lời và hành động thánh thiện của bạn, để dẫn dắt con đường của tôi trong đêm tối."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_95070_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Tôi muốn biết rằng, mang xiềng xích, tắm trong bóng tối, tiến về ánh sáng đó, một cách kiên định… đó có phải là điều bạn muốn nói với tôi không?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_95071_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Một người hầu sáng tỏ đã mất đèn trong tay, nỗi đau đớn mù quáng này làm tôi rất lo lắng, tôi chân thành cầu xin bạn cứu lấy linh hồn lạc lối này, xin hãy nắm tay tôi, gần gũi với trái tim thánh thiện này, xin hãy ban cho tôi, sự dẫn dắt đến ánh sáng..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_95072_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Đứa trẻ bất hạnh, nhưng một khi cô đã dấn thân vào công việc theo đuổi Ngài, thì chắc chắn sẽ đạt được sự cứu rỗi cuối cùng. Nhưng tại sao người bạn như khỉ của cô ấy cũng nhận được sự thương xót của Ngài? Đứa trẻ ác độc đó thậm chí còn đánh cắp pháp khí của tôi khi cầu nguyện! Linh hồn của cô ấy nhất định chứa đựng tội lỗi như dòng lũ, thật là đại bất kính!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Aigis và Jenki"
  },
  Voice_95073_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được người đánh thức \"Aigis\", người đánh thức \"Jenkin\""
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Nhanh chóng rời đi."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "Nguyện cho ánh sáng Minh Quang xuyên qua màn đêm bất tận!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... tôi đã thấy, sức mạnh vĩ đại, sự thật của thế giới... Tôi đã nhận ra con đường sai lầm trong quá khứ, bạn mới là người cầm đèn thực sự! Xin cho phép tôi trở thành sứ giả trung thành của bạn, trái tim sinh ra cho người cầm đèn này sẽ nhảy múa, run rẩy và phục tùng vì bạn..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_95076_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Hành động cứu chuộc mù quáng của vị linh mục đó thực sự là sự ngu dốt không thể chấp nhận, phúc âm của Thần chỉ có thể ban cho những người công chính. Nếu ngay cả sứ giả của Thần cũng không có đôi mắt thấu đáo, thưởng cho những ác nhân không biết ăn năn, ô nhiễm vương quốc trong sạch của Thần, thì đó chẳng phải là sự phản bội đối với Thần và những người công chính đó sao?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Mở khóa sau khi nhận thân thể được đánh thức \"Salvador\""
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Trái tim của ta đã được thắp sáng!"
  },
  Voice_95078_AwakerVoiceTitle = {Text = "Nộ"},
  Voice_95079_AwakerVoiceContent = {Text = "Uống!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_95080_AwakerVoiceContent = {
    Text = "Khi còn nhỏ, tôi đã rất muốn bay ra khỏi cái lồng giam, lúc đó tôi luôn nghĩ rằng nơi chỉ mang lại đau khổ này chẳng đáng để lưu luyến. Nhưng giờ đây, sau hai lần trải nghiệm cuộc sống, tôi mới phát hiện ra rằng tự do không phải là điều duy nhất tôi khát khao, mà khi thấy những tín đồ biết rằng sẽ được cứu rỗi, với vẻ chân thành, hy vọng và biết ơn, đó mới là ý nghĩa thực sự của danh tính Thánh Tử."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "Trong khoảng thời gian theo cùng Juliette, tôi đã làm sai rất nhiều điều, không đáng để nhận được sự tin tưởng này. Nhưng bạn vẫn chọn tôi... xin hãy yên tâm, tôi sẽ tìm lại niềm tin thuộc về mình. Thánh tử sẽ không để các thần dân thất vọng, cũng không làm bạn thất vọng."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_95081_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Vật quà của bạn, tôi sẽ sử dụng với lòng biết ơn."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_95083_AwakerVoiceContent = {Text = "Vô lễ!"},
  Voice_95083_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "Khốn kiếp."
  },
  Voice_95084_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_95085_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "Nhân danh của tôi!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Tôi nhìn thấy rồi! Ánh sáng ấy, ánh sáng tỏa ra từ tận sâu trong ý thức, nó ngày càng trở nên sáng chói! Nó đang gọi tôi…"
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_95087_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "Trong thời thơ ấu, Castor và tôi cùng giữ chức vụ Thánh Tử. Khi đó, tôi luôn nghĩ rằng anh ấy quá vụng về, chậm chạp, cần tôi dẫn dắt con đường tương lai. Nay hiểu được con đường mà bạn đã trải qua, tôi mới nhận ra, nền tảng của thế giới này được xây dựng và mở rộng bởi những người chính trực như bạn và anh ấy."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_95088_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Ngọn đèn của tôi, từ khi nhận được sự hướng dẫn của ngài, tôi nghĩ mình đã đi đúng con đường hoàn toàn. Tại đây, tín đồ ngu ngốc của ngài vẫn còn một thắc mắc, rằng mảnh đất vô tội huyền thoại, có phải cũng nằm trong sự cai quản của ngài? Không có thứ này sao? Ý ngài là… mảnh đất vô tội nằm giữa nhân gian, trong tâm hồn thuần khiết của những người hiền lành sao?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Trái tim nghe theo ý trời này, giờ đã gần gũi hơn với bạn."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Ngài… Ngài có điều gì muốn truyền đạt với tôi không? Sứ giả của Ngài luôn sẵn sàng lắng nghe lời dạy của Ngài."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Hãy soi sáng tôi, người dẫn đường lạc lối! Với ánh sáng của ngài, tôi đã nhìn thấy rõ những gì mình cần nhìn thấy... Tôi sẽ dùng thân thể bị nguyền rủa này, để thanh tẩy mọi quá khứ, để mọi tương lai đều được tắm mát dưới ánh sáng này!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_95092_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Hát lên ánh sáng!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Theo đuổi sự cứu rỗi trong một thế giới tàn khốc sao? Cố lên nhé, chú nhóc đầy hy vọng."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_95391_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Đến đây, cầm lấy những món này đi chơi đi, nghe nói là những vật phẩm cấm bị đào từ di tích nào đó. Tôi không quan tâm đến những thứ bị ảnh hưởng bởi khí tức của họ, ban đầu định trực tiếp thiêu hủy, nhưng nghĩ rằng có thể nó sẽ hữu ích cho bạn, nên đã mang đến cho bạn.\nBạn hỏi tôi đã đến đây bằng cách nào? Tất nhiên là một số người đã \"tình nguyện\" gửi cho tôi, đừng lo, đảm bảo nguồn gốc \"sạch\" đấy."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_95392_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Săn bắn hoàn thành, thưởng sẽ được trả bằng nụ cười của tiểu thú."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Có biết không, nhóc con, thứ bắn ra từ hai khẩu súng này không phải là đạn, mà là sự kết hợp giữa khát vọng và ác ý.\nNhững hỗn loạn vô trật tự này tạo thành ngọn lửa như máu thịt, vào lúc tiếng súng thứ bảy vang lên ở bên kia, nó sẽ kéo tất cả vào luyện ngục để thiêu đốt."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về súng"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Không cần phải ép mình quá, người giữ gìn của tôi. Mặc dù tôi biết đây là con đường gian nan gấp bách, chỉ cần sơ suất sẽ rất khó khăn. Nhưng nếu tiếp tục như vậy, đến một ngày nào đó bạn sẽ kiệt sức mà ngã. Nếu cần, hãy tìm tôi nói chuyện, với tư cách là một người trong gia đình."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_95395_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Thiêu đốt, hủy diệt, than khóc đi!"
  },
  Voice_95396_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_95397_AwakerVoiceContent = {
    Text = "Biến mất đi."
  },
  Voice_95397_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Tầm nhìn của ta đã rõ ràng hơn, ta đã thấy những thứ ẩn giấu dưới vực thẳm... Để vì các ngươi, ta cần phải có sức mạnh mạnh mẽ hơn..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_95398_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Hãy đến, người giữ gìn, ngồi lại một chút nào, giờ đây chúng ta thật xa lạ.\nBạn có biết không, khi lần đầu tiên gặp bạn, tôi chưa bao giờ nghĩ rằng một ngày nào đó, tôi có thể tháo gỡ lớp vỏ bị gọi là tàn nhẫn và lạnh lùng của mình tại đây. Thật sự là có chút buồn cười, vị chúa tể bùng nổ tiếng tăm lại khao khát có một người thân để tâm sự.\nHãy hứa với tôi, nếu ngày đó bạn không chịu nổi…… thì hãy gọi tên tôi trong tâm trí bạn, tôi sẽ dẫn bạn đến vương quốc của tôi. Mặc dù điều này chỉ có thể trì hoãn mọi thứ xảy ra, nhưng ít nhất vào khoảnh khắc cuối cùng, bạn có thể nghỉ ngơi thật tốt trong vòng tay tôi."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_95399_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Chào đón kết cục bi thảm."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_95402_AwakerVoiceContent = {
    Text = "Giữa hàng triệu khát vọng và hiểm ác, hãy thiêu đốt đi!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Sau một cuộc săn bắn thành công luôn cần một bữa tiệc mừng chiến thắng, hãy cùng nhau thưởng thức thịt lạc đà nướng của tôi và rượu tequila vừa mua được. Chờ đã, nhóc, có vẻ như cậu không thể uống rượu… Vậy hãy thử nước trái cây đặc biệt của tôi nhé ~"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_95403_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Có chuyện gì vậy, nhóc con? Có muốn một cái ôm không? Đến đi, lòng ngực nóng bỏng của tôi luôn mở ra cho bạn… haha, đừng xấu hổ, là một người chị quan tâm đến em thì có gì là không bình thường đâu nhỉ?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "Chết tiệt."
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "Chào đón cái chết màu hổ phách."
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Trước tiên lùi lại, tôi sẽ bảo vệ cho... yên tâm, tôi sẽ sống sót trở về."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Hãy nào, hãy để chúng ta thiêu rụi mọi thứ thành tro tàn!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Ngọn lửa bùng cháy à, hãy bùng cháy trở lại tại đây!"
  },
  Voice_95410_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_95411_AwakerVoiceContent = {
    Text = "Ngọn lửa ngày càng mạnh, nhóc con có muốn nhìn màn pháo hoa hoành tráng không?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Những kẻ đó, những kẻ dẫm đạp lên nhân nghĩa, ẩn mình trong bóng tối, sử dụng @1 làm vật liệu cho các nghi lễ và nghiên cứu bẩn thỉu của họ... sớm hay muộn, tôi sẽ tiêu diệt tất cả bọn chúng."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Bùng!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "Tôi sẽ tìm thấy hắn, dù hắn ẩn nấp ở bất kỳ góc nào của vũ trụ, tôi chắc chắn sẽ tìm thấy hắn.\nTôi sẽ để con chuột bẩn thỉu này phải trả giá bằng mọi thứ, khi tôi tìm thấy hắn, mọi niềm vui và hài lòng trên thế gian sẽ bị thiêu rụi trong hoả ngục.\nYên tâm, khi đó tôi sẽ dành một chỗ đặc biệt cho bạn tại tang lễ của hắn, để chúng ta cùng nhau thưởng thức tiếng kêu gào cuối cùng của hắn."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Lệch lạc: Về N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Hãy lắng nghe, tiếng khóc than của những vì sao tan chảy."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_95415_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Chào đón kết cục bi thảm."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Cậu là người mà tôi tự hào, hãy tự tin lên, người giữ gìn của tôi! Dù có chuyện gì xảy ra, tôi vẫn là điểm tựa vững chắc nhất của cậu."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Những tồn tại khó thể diễn tả đó đang ăn mòn thế giới này, bạn sẽ không tránh khỏi việc trở thành kẻ thù của chúng. Nhưng điều đó không quan trọng, vì tôi sẽ đứng sau lưng bạn."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_95418_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Thiêu đốt, hủy diệt, than khóc đi!"
  },
  Voice_95420_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_95421_AwakerVoiceContent = {
    Text = "Giữ bình tĩnh."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_95422_AwakerVoiceContent = {
    Text = "Lùi lại."
  },
  Voice_95422_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Bạn hỏi tôi nhìn nhận về Phân rã như thế nào? Điều đó giống như hỏi một con chuột nhỏ lang thang trong cống rãnh suy nghĩ về vị lãnh chúa cách xa. Câu trả lời của tôi chỉ có một: sự ghê tởm từ bản năng của cơ thể. Nếu có thể, tôi sẽ vừa uống rượu sữa lạc đà thơm ngon, vừa thưởng thức tiếng thét khi chúng chết dưới nòng súng của tôi."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Bạn có muốn ngọn lửa nóng rực hơn một chút không?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_95424_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Tôi chỉ đến đây khi nhận được nhiệm vụ, nếu cậu nhóc muốn tìm tôi, hãy dùng câu thần chú này. Nào, hãy cùng tôi niệm:……………… Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Đã từng có lúc, chúng tôi còn ở trong cái thị trấn cũ kĩ đó, sống sót nhờ sự ác độc và xảo trá. Ngay cả khi trở thành cái gọi là \"thế lực lớn\", đối mặt với lão đại, đội bảo vệ và \"quý tộc\" không chịu rời khỏi sân khấu lịch sử, chúng tôi vẫn phải tỉnh táo mười phần. Nhưng bây giờ thì khác, mọi người đã trở thành \"gia tộc\" của tôi, không cần phải để ý đến sắc mặt của người khác. Hừ, dù còn một tiểu giai ở bên ngoài, nhưng tôi tin rằng gã đó sẽ ổn thôi, dù sao mỗi khi tôi bận rộn bên ngoài, chính gã đó là người chăm sóc cho những người khác."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Lệch lạc: Về gia đình"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Đây chính là kẻ thù của nhóc con à? Vậy thì—bắt đầu cuộc săn thôi."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Ta chính là chúa tể của ngọn lửa không bao giờ quên! Tuyên bố! Mọi vật sẽ diệt vong!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Giữa ngọn lửa và sự hủy diệt là tất cả của tôi, tôi say mê cái chết từ sự săn bắn... Bạn nghĩ tôi sẽ nói như vậy sao?  \nHaha, chỉ là đùa thôi, với tôi, điều quan trọng nhất đương nhiên là mọi người xung quanh. Không có gì quan trọng hơn mọi người, ngay cả... bản thân tôi cũng không được."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Cậu bé nhỏ gặp rắc rối sao? Thì hãy tuân theo triệu hồi, Katie Gura sẽ đến với sự hủy diệt. Hãy làm cho tất cả rắc rối biến mất trong khói bụi."
  },
  Voice_95430_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_95431_AwakerVoiceContent = {
    Text = "Mùi vị của sức mạnh, có muốn tìm một số xui xẻo để thử tay không?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_95431_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Ta chính là chúa tể của ngọn lửa không bao giờ quên! Tuyên bố! Mọi vật sẽ diệt vong!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "Nữ hoàng Alans huyền thoại, thể chất ham muốn vĩ đại Tifreyasod, tôi đã gặp cô một lần khi đang truy sát N. Mặc dù tôi không công nhận những gì cô ấy đã làm, nhưng thực lòng mà nói, nếu đó là cách duy nhất tôi có thể khiến mọi người sống sót trong cái nhìn của \"Ngài\"... tôi cũng sẽ chọn làm như vậy. Từ góc độ này, tôi và cô ấy không có gì khác biệt."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Chuyện phiếm: Về Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Mở khóa sau khi nhận được thân thể được đánh thức \"Thái Di Sơ\""
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Cảm giác rất tốt, vũ khí bảo trì rất tốt mà."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Ta là lửa, là ngọn lửa, là hỗn loạn không bao giờ tắt... Ta sẽ đưa mọi người... về nhà..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_95435_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Chiếc tháp chuông Gothic ở đây mang vẻ cổ điển, và người đánh thức ở đây cũng có một mùi hương mà tôi chưa bao giờ thưởng thức qua, vừa có hương thơm của linh hồn chết, vừa có một chút hương vị của người sống, thật sự... khiến người ta muốn thử nghiệm một chút."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về Misaque"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Tìm kiếm cái chết, tôi sẽ thỏa mãn ước nguyện của bạn."
  },
  Voice_96362_AwakerVoiceTitle = {Text = "Nộ 2"},
  Voice_96363_AwakerVoiceContent = {
    Text = "Tôi đã không thể đợi thêm để bắt đầu."
  },
  Voice_96363_AwakerVoiceTitle = {
    Text = "Khai mở linh trí"
  },
  Voice_96364_AwakerVoiceContent = {
    Text = "Tim bạn đã động, đúng không? Hãy đến đây, vị khách yêu quý, hãy trở thành khách quý của tôi, cùng nhau thưởng thức bữa tiệc này. Hãy để tôi dẫn dắt bạn, cùng nhau nhấm nháp từng dư âm tinh tế của mỗi linh hồn."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Khởi linh · nở rộ"
  },
  Voice_96364_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 15 để mở khóa"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Suỵt, xin đừng nói, hãy để chúng ta cùng lắng nghe âm thanh của những linh hồn."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·một"
  },
  Voice_96365_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 2 tỷ lệ đồng điều"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Vẻ đẹp vĩnh cửu là niềm tin của chúng ta. Đẩy chậm rãi sự lãng quên đến với người sống, xóa bỏ mọi dấu ấn tồn tại… điều này là sự tra tấn thuần khiết và tàn nhẫn với sự sống."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Lời nói phiếm, Về cuộc khủng hoảng"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Giống như tôi, Pikman cũng đang theo đuổi nghệ thuật vĩnh cửu, chúng tôi đáng lẽ nên trở thành những người bạn tốt hơn. Nhưng anh ta lại cho rằng việc ăn uống là một hành vi phá hoại vĩnh cửu, quan niệm nghệ thuật của anh ta thì thật quá hẹp hòi."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Nói chuyện tản mạn·Về Pikman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Sau khi nhận được thân thể được đánh thức \"Pikeman\", tính năng sẽ được mở khóa"
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Đánh · một"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Không có bất kỳ tính từ nào có thể mô tả hương thơm mê hoặc trên cơ thể bạn, nó vừa có vị chua chát và phong phú như rượu vang Bordeaux, vừa giàu có và thơm tho như bánh kem, ah... sự mong đợi đến ngày bạn qua đời có lẽ sẽ trở thành điều quan trọng nhất trong phần đời còn lại của tôi."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Lời nói dạo·Về Người Giữ Gìn"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Tôi từng thấy một hiện trường phạm tội, một người đàn ông đang từng chút một cắt xẻ da thịt, móng tay, tay và chân của một cô gái trẻ, nhưng lại không ngừng chữa lành cho cô ấy. Anh ta không muốn cô chết, cũng không phải muốn cô sống. Tôi dĩ nhiên sẽ không ban cho anh ta cái chết an yên, chỉ để cho anh ta trải nghiệm những gì mà cô gái ấy đã trải qua, có vẻ như đã vài năm… Điều này thì công bằng đối với những kẻ xúc phạm cái chết, phải không?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·điều không thích"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Tôi là thần của cái chết, nhưng xin đừng hiểu lầm, tôi không tạo ra cái chết. Tôi chỉ đi theo bước chân của cái chết, hái trái cây chín mọng."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Khởi linh·nhìn xa"
  },
  Voice_96371_UnlockDesc = {
    Text = "Cấp độ khởi linh 1 mở khóa"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Bạn có phải cũng khát khao mùi hương của tôi, thưa người giữ gìn?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Lời nói phiếm·chạm vào"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Hôm nay nên mời ai lên bàn ăn nhỉ?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Bắt đầu điều tra"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Tôi sẽ ban tặng cho các ngươi, trở thành vinh quang của bữa tiệc hôm nay."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Điều tra thành công"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Quá thiếu duyên dáng."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Bị tấn công·3"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Tôi sẽ mang đến một giấc nghỉ ngơi sạch sẽ."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Kỹ năng·1"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Trước mỗi bữa ăn, tôi sẽ trò chuyện với linh hồn. Đối với họ, việc bị con người tiêu thụ một cách nghiêm túc, thưởng thức là sự kéo dài cuộc sống và sự vinh quang cuối cùng. Giống như chúng tôi khao khát họ, họ cũng đang khao khát chúng tôi."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·ba"
  },
  Voice_96377_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở ở cấp 6"
  },
  Voice_96378_AwakerVoiceContent = {
    Text = "Yên lặng một chút."
  },
  Voice_96378_AwakerVoiceTitle = {
    Text = "Bị đánh·bốn"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Hãy tan biến trong bóng tối!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Chúng ta vẫn giữ khoảng cách thì tốt hơn."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Phòng thủ·I"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Hãy tan biến trong bóng tối!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Kỹ năng·4"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Tại sao lại đề phòng tôi như vậy? Bạn không nên cũng không cần phải hoảng loạn, việc ăn thịt người sống đi ngược lại thẩm mỹ của tôi."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Nói chuyện tản mạn·Về đồ ăn"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Tìm kiếm cái chết, tôi sẽ thỏa mãn ước nguyện của bạn."
  },
  Voice_96383_AwakerVoiceTitle = {Text = "Bùng nổ"},
  Voice_96384_AwakerVoiceContent = {
    Text = "Quá thiếu duyên dáng."
  },
  Voice_96384_AwakerVoiceTitle = {
    Text = "Bị đánh·một"
  },
  Voice_96385_AwakerVoiceContent = {
    Text = "Cẩn thận nhé."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "Phòng thủ·2"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Xong, mặc dù sự nhiệt tình của cô tiểu thư thật khiến người ta cảm động, nhưng mùi của cô ta có mùi ẩm ướt như đã lên men quá mức. Dù cô ta không ngừng cầu xin tôi thử, nhưng điều đó thực sự không hợp khẩu vị của tôi, thật khó xử."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chuyện vặt · Về Reia"
  },
  Voice_96386_UnlockDesc = {
    Text = "Mở khóa sau khi có thân thể được đánh thức \"Reia\""
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Bạn có biết không? Khi tất cả sinh mạng ra đi, đều có những âm vang dài lâu. Chúng có âm sắc cao thấp khác nhau, sẽ từ khoảnh khắc cái chết đến từ từ kéo dài, cho đến khi từ từ phân tán giữa đất trời, giống như một tiếng thở dài."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·2"
  },
  Voice_96387_UnlockDesc = {
    Text = "Tỷ lệ đồng điều mở khóa ở cấp 4"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Xin hãy yên tâm, người giữ gìn, tôi sẽ luôn ở bên bạn, cho đến ngày sinh mệnh của bạn bước đến cái chết không thể cản lại. Đến lúc đó, tôi chắc chắn sẽ dùng nghi thức trang trọng nhất để nuốt từng phần thể xác của bạn. Tôi sẽ giữ linh hồn của bạn mãi mãi trong cơ thể của tôi."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·năm"
  },
  Voice_96388_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp 10"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Bạn không ngửi thấy mùi hương của chính mình sao? Thật tiếc, bạn đã bỏ lỡ cái ngọt ngào nhất trên thế giới, nhất là… ôi, sao phải lẩn tránh vậy."
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Tỷ lệ đồng điều·4"
  },
  Voice_96389_UnlockDesc = {
    Text = "Tỷ lệ đồng điều đạt cấp 8 sẽ mở khóa"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Tôi có thể thấy nhiều cái chết hơn, cảnh đẹp bên kia đang ngày càng rõ ràng…"
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp·ba"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Hãy giao phó cơ thể cho tôi, để tôi có thể tỉ mỉ thưởng thức bạn, mỗi giọt máu, mỗi miếng thịt, mỗi chiếc xương."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Siêu Cuồng Nộ"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Các nguyên liệu khác nhau cần phải qua những cách chế biến khác nhau. Nội tạng cần ướp muối, gân chân thì tốt hơn nên hầm, các phần giàu mỡ thích hợp để lên men chín, những phần có cảm giác đặc biệt có thể chiên, nướng hoặc làm thành những món thịt đông có tạo hình đẹp, tất cả đều cần lựa chọn kỹ càng. Tất nhiên, việc giữ gìn và tôn vinh hương vị gốc của nguyên liệu là một sự tôn trọng cần thiết."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Khởi linh thể ngộ"
  },
  Voice_96392_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 7 để mở khóa"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Điều này sẽ hơi lạnh."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Đánh·2"},
  Voice_96394_AwakerVoiceContent = {
    Text = "Việc phối hợp món ăn cũng có nhiều điều phải lưu ý, chua và ngọt, giòn và mềm, tươi mát và nặng nề, tinh tế và thô ráp, hương vị lồng ghép nhau và cảm giác đối lập va chạm với nhau, khi vào miệng, nhai, hồi vị đều có cảm nhận khác nhau, đó mới là niềm vui vô tận và kỳ diệu mà món ăn đủ tiêu chuẩn mang lại."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Khởi linh·cấu trúc"
  },
  Voice_96394_UnlockDesc = {
    Text = "Mở khóa khi đạt cấp độ khởi linh 11"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Cảm ơn lòng nhiệt tình của bạn, tôi rất vinh dự."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Nhận nâng cấp hai"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Thức ăn ngon luôn đáng để chờ đợi lâu hơn."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Việc điều tra đã bị dừng"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Tôi chắc chắn không phải là một quái vật ăn tươi nuốt sống, quá trình tận hưởng cái chết là trang nghiêm và thanh lịch, ngươi cần phải giao tiếp và hiểu từng hương vị độc nhất của nguyên liệu với lòng tôn kính."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Khởi linh · độ tập trung"
  },
  Voice_96397_UnlockDesc = {
    Text = "Cấp độ khởi linh đạt 2 mở khóa"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Những người chết đã tìm được sự tĩnh lặng thật đẹp và thơm ngát, không phải vì cơ thể họ sẽ có nhiều khác biệt giữa sống và chết, mà là vì linh hồn của họ - những linh hồn hiểu biết về cái chết, quyến luyến cuộc sống, khao khát được ghi nhớ chính là những món ăn quý giá tôi hằng mong ước."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Chuyện vặt·đồ vật yêu thích"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Không có loại nước hoa nào có thể so sánh với hương thơm tự nhiên của cơ thể con người, ngửi được hương thơm rồi nhận diện con người, đó là điều tuyệt diệu nhất."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Khởi linh·suy ngẫm"
  },
  Voice_96399_UnlockDesc = {
    Text = "Đạt cấp độ khởi linh 3 để mở khóa"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, mùi hương thật sâu sắc và khó quên... Tôi không thể chờ thêm nữa để đón chào bạn vào đền thờ của tôi."
  },
  Voice_96400_AwakerVoiceTitle = {
    Text = "Hoán tỉnh"
  },
  Voice_96401_AwakerVoiceContent = {
    Text = "Hãy giao phó cơ thể cho tôi, để tôi có thể tỉ mỉ thưởng thức bạn, mỗi giọt máu, mỗi miếng thịt, mỗi chiếc xương."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Siêu hạn cơn thịnh nộ bùng phát·hai"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Tôi sẽ mang đến một giấc nghỉ ngơi sạch sẽ."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Kỹ năng·2"
  },
  Voice_96403_AwakerVoiceContent = {
    Text = "Yên lặng một chút."
  },
  Voice_96403_AwakerVoiceTitle = {
    Text = "Bị đánh·2"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Mùi hương thơm ngát của bạn thật sự khiến người ta say mê."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Nhận được nâng cấp·một"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "Giữa hàng triệu khát vọng và hiểm ác, hãy thiêu đốt đi!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Kỹ năng đặc biệt · Một"
  }
})
return Text_Voice
